def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def _rating_to_int(value, default: int = 50) -> int:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    if number <= 1.0:
        number *= 100.0
    return int(round(max(0.0, min(99.0, number))))


