def set_ruleset(name: str):
    global CURRENT_RULESET
    CURRENT_RULESET = name if name in RULESETS else "NBA"


def current_rules() -> Dict:
    return RULESETS.get(CURRENT_RULESET, RULESETS["NBA"])


def is_fiba_rules() -> bool:
    return CURRENT_RULESET == "FIBA"


def rules_quarter_seconds() -> int:
    return int(current_rules().get("quarter_seconds", GAME_SECONDS // 4))


def rules_game_seconds() -> int:
    return rules_quarter_seconds() * 4


def rules_ot_seconds() -> int:
    return int(current_rules().get("ot_seconds", 5 * 60))


def rules_timeout_count() -> int:
    return int(current_rules().get("timeouts", 7))


def rules_bonus_fouls() -> int:
    return int(current_rules().get("bonus_fouls", 5))


def is_olympic_team_name(name: str) -> bool:
    return name.startswith(OLYMPIC_TEAM_PREFIX)


def is_olympic_team(team) -> bool:
    return is_olympic_team_name(getattr(team, "name", ""))

