def enable_keyboard_controls(teamA=None, teamB=None):
    global SIM_CONTROL_ENABLED, SIM_TERMINAL_SETTINGS
    if teamA is not None:
        SIM_CONTEXT["teamA"] = teamA
    if teamB is not None:
        SIM_CONTEXT["teamB"] = teamB
    if SIM_CONTROL_ENABLED or not sys.stdin.isatty() or termios is None or tty is None:
        return
    SIM_TERMINAL_SETTINGS = termios.tcgetattr(sys.stdin)
    tty.setcbreak(sys.stdin.fileno())
    SIM_CONTROL_ENABLED = True


def disable_keyboard_controls():
    global SIM_CONTROL_ENABLED, SIM_TERMINAL_SETTINGS
    if SIM_CONTROL_ENABLED and SIM_TERMINAL_SETTINGS is not None and termios is not None:
        termios.tcsetattr(sys.stdin, termios.TCSADRAIN, SIM_TERMINAL_SETTINGS)
    SIM_CONTROL_ENABLED = False


atexit.register(disable_keyboard_controls)


def wait_for_enter(prompt: str = ""):
    if SIM_FAST_FORWARD:
        return ""
    was_enabled = SIM_CONTROL_ENABLED
    if was_enabled:
        disable_keyboard_controls()
    try:
        return input(prompt)
    finally:
        if was_enabled:
            enable_keyboard_controls(SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB"))


def fantasy_controls_active() -> bool:
    return bool(SIM_CONTEXT.get("fantasy_control_enabled")) and not SIM_FAST_FORWARD


def user_control_team() -> "Team | None":
    team = SIM_CONTEXT.get("user_control_team")
    if team is not None:
        return team
    for candidate in (SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB")):
        if candidate is not None and is_user_controlled_team(candidate):
            return candidate
    return None


def is_user_controlled_team(team: "Team | None") -> bool:
    return bool(team is not None and (team.name == "User Fantasy Team" or getattr(team, "user_controlled", False)))


def handle_live_keypress(key: str):
    global SIM_FAST_FORWARD, SIM_JUMP_TARGET
    if key == "\x03":
        raise KeyboardInterrupt
    raw_key = key
    key = key.lower()
    if raw_key == "S" and fantasy_controls_active():
        team = user_control_team()
        if team is not None:
            team.manual_sub_request = True
            print(f"\nManual substitution queued for {team.name}. It will open at the next dead ball.")
        return
    if key == "t" and fantasy_controls_active():
        team = user_control_team()
        possession = SIM_CONTEXT.get("possession")
        if team is not None and possession is team:
            team.manual_timeout_requested = True
            teamA = SIM_CONTEXT.get("teamA")
            teamB = SIM_CONTEXT.get("teamB")
            period = SIM_CONTEXT.get("period", 1)
            period_time = SIM_CONTEXT.get("period_time", GAME_SECONDS // 4)
            if teamA is not None and teamB is not None:
                maybe_apply_manual_timeout(team, teamA, teamB, period, period_time)
            else:
                print(f"\nTimeout requested for {team.name}. It will be called before the next possession starts.")
        elif team is not None:
            print(f"\n{team.name} can only call timeout when they have possession.")
        return
    if key == "s":
        SIM_FAST_FORWARD = True
        SIM_JUMP_TARGET = None
        print("\nFast-sim enabled. The rest of the game will run without pauses.")
    elif key == "1":
        SIM_FAST_FORWARD = True
        SIM_JUMP_TARGET = "end1"
        print("\nFast-sim enabled until the end of the 1st quarter.")
    elif key == "2":
        SIM_FAST_FORWARD = True
        SIM_JUMP_TARGET = "half"
        print("\nFast-sim enabled until halftime.")
    elif key == "3":
        SIM_FAST_FORWARD = True
        SIM_JUMP_TARGET = "end3"
        print("\nFast-sim enabled until the end of the 3rd quarter.")
    elif key == "4":
        SIM_FAST_FORWARD = True
        SIM_JUMP_TARGET = "half4"
        print("\nFast-sim enabled until halfway through the 4th quarter.")
    elif key == "5":
        SIM_FAST_FORWARD = True
        SIM_JUMP_TARGET = "last5"
        print("\nFast-sim enabled until the final 5 minutes.")
    elif key == "b":
        teamA = SIM_CONTEXT.get("teamA")
        teamB = SIM_CONTEXT.get("teamB")
        if teamA is None or teamB is None:
            return
        disable_keyboard_controls()
        print_box_score(teamA, teamB, "LIVE")
        input("Press Enter to resume...")
        enable_keyboard_controls(teamA, teamB)


def update_sim_clock_context(period: int, period_time: int):
    SIM_CONTEXT["period"] = period
    SIM_CONTEXT["period_time"] = period_time


def update_possession_context(possession: "Team | None"):
    SIM_CONTEXT["possession"] = possession


def maybe_stop_jump_sim(period: int, period_time: int):
    global SIM_FAST_FORWARD, SIM_JUMP_TARGET
    if SIM_JUMP_TARGET == "end1" and ((period == 1 and period_time <= 0) or period > 1):
        SIM_FAST_FORWARD = False
        SIM_JUMP_TARGET = None
        print("\nReached the end of the 1st quarter. Live pacing resumes.")
    elif SIM_JUMP_TARGET == "half" and ((period == 2 and period_time <= 0) or period > 2):
        SIM_FAST_FORWARD = False
        SIM_JUMP_TARGET = None
        print("\nReached halftime. Live pacing resumes.")
    elif SIM_JUMP_TARGET == "end3" and ((period == 3 and period_time <= 0) or period > 3):
        SIM_FAST_FORWARD = False
        SIM_JUMP_TARGET = None
        print("\nReached the end of the 3rd quarter. Live pacing resumes.")
    elif SIM_JUMP_TARGET == "half4" and period >= 4 and period_time <= 6 * 60:
        SIM_FAST_FORWARD = False
        SIM_JUMP_TARGET = None
        print("\nReached halfway through the 4th quarter. Live pacing resumes.")
    elif SIM_JUMP_TARGET == "last5" and period >= 4 and period_time <= 5 * 60:
        SIM_FAST_FORWARD = False
        SIM_JUMP_TARGET = None
        print("\nReached the final 5 minutes. Live pacing resumes.")
    elif SIM_JUMP_TARGET == "last2" and period >= 4 and period_time <= 2 * 60:
        SIM_FAST_FORWARD = False
        SIM_JUMP_TARGET = None
        print("\nReached the final 2 minutes. Live pacing resumes.")


def controlled_sleep(seconds: float):
    # Pause must take priority over fast-forward; otherwise fast-sim bypasses
    # this function before the pause flag can be observed.
    while SIM_PAUSED:
        _REAL_SLEEP(0.05)
    if SIM_FAST_FORWARD or seconds <= 0:
        return
    seconds *= SIM_SLEEP_SCALE
    if seconds <= 0:
        return
    while SIM_PAUSED:
        _REAL_SLEEP(0.05)
    if not SIM_CONTROL_ENABLED or not sys.stdin.isatty():
        _REAL_SLEEP(seconds)
        return

    remaining = seconds
    while remaining > 0:
        while SIM_PAUSED:
            _REAL_SLEEP(0.05)
        if SIM_FAST_FORWARD:
            return
        step = min(0.05, remaining)
        ready, _, _ = select.select([sys.stdin], [], [], step)
        if ready:
            handle_live_keypress(sys.stdin.read(1))
            if SIM_FAST_FORWARD:
                return
        remaining -= step


time.sleep = controlled_sleep

