def dribble_chain_pass_line(handler, receiver, next_shot_type: str) -> str:
    lines = dribble_combo_pass_finishes_by_result.get(next_shot_type, dribble_combo_pass_finishes)
    return random.choice(lines).format(
        shooter=handler.name,
        receiver=receiver.name
    )

