def default_player_go_to_shot(player_or_name, position: str = "") -> str:
    name = getattr(player_or_name, "name", player_or_name)
    key = str(name or "").strip().lower()
    if key in DEFAULT_GO_TO_SHOTS:
        return DEFAULT_GO_TO_SHOTS[key]
    pos = str(getattr(player_or_name, "position", position) or position).upper()
    if pos in ("PG", "SG"):
        return "midrange_pullup"
    if pos == "SF":
        return "downhill_finish"
    if pos == "PF":
        return "jump_hook"
    if pos == "C":
        return "drop_step"
    return ""


def go_to_shot_label(style: str) -> str:
    pack = GO_TO_SHOT_PACKS.get(str(style or ""))
    return pack["label"] if pack else "None"


def go_to_shot_sequence(player, shot_type: str, context: str | None = None):
    style = getattr(player, "go_to_shot", "") or default_player_go_to_shot(player)
    pack = GO_TO_SHOT_PACKS.get(style)
    if not pack or shot_type not in pack.get("types", ()):
        return None
    if context in ("pnr_catch_shoot", "double_wide_open", "extra_pass_open", "alley_oop"):
        return None
    if style == "relocation_three" and context in ("iso", "pressure_pullup", "mismatch_hunt", "clear_side", "double_split", "foul_hunt"):
        return None
    trigger = 0.14 + getattr(player, "shot_tendency", 0.40) * 0.12 + getattr(player, "iso_tendency", 0.30) * 0.10
    if context in ("iso", "isolation", "late_quick", "mismatch_hunt", "clear_side", "pressure_pullup", "double_split"):
        trigger += 0.10
    if getattr(player, "usage", 0.0) >= 0.28:
        trigger += 0.06
    if random.random() > min(0.48, trigger):
        return None
    return random.choice(pack["lines"])


