def shot_family(shot_type: str) -> str:
    if shot_type == "three":
        return "three"
    if shot_type in ("mid", "post_fade"):
        return "mid"
    return "paint"


def shot_diet_type(shot_type: str) -> str:
    return "post" if shot_type == "post_fade" else shot_type


def is_post_family_shot(shot_type: str) -> bool:
    return shot_type in ("post", "post_fade")


def is_paint_shot(shot_type: str) -> bool:
    return shot_type in ("rim", "dunk", "post", "post_fade")


def commentator_make(shooter: str, defender: str, shot_type: str, defense_line: str) -> str:
    return random.choice(broadcast_make_lines[shot_family(shot_type)]).format(
        shooter=shooter,
        defender=defender,
        defense=defense_line
    )


def commentator_miss(shooter: str, defender: str, shot_type: str, defense_line: str) -> str:
    return random.choice(broadcast_miss_lines[shot_family(shot_type)]).format(
        shooter=shooter,
        defender=defender,
        defense=defense_line
    )


def screen_action_context(context: str | None) -> bool:
    if not context:
        return False
    return context in {
        "high_pnr", "empty_corner_pnr", "spain_pnr", "floppy", "elevator",
        "handoff", "sideline_curl_three", "ghost_screen_three",
        "pnr_catch_shoot", "roller", "popper", "alley_oop",
    } or "screen" in context or "pnr" in context or "pindown" in context


def context_defense_line(shot_type: str, quality_label: str, made: bool, context: str | None,
                         defender: "Player | None" = None) -> str:
    if quality_label == "wide open" and not is_paint_shot(shot_type):
        return random.choice(def_open_make if made else def_open_miss)

    if is_paint_shot(shot_type):
        # Crediting the defender for "walling up" or "meeting him at the
        # rim" only makes sense if he's actually a real interior defender.
        # A weak rim protector standing nearby isn't the reason for a make
        # or miss -- treat that the same as a defender who just wasn't a
        # factor, rather than praising a contest that wasn't really there.
        if defender is not None and defender.interior_def < 0.55:
            return random.choice(def_open_make if made else def_open_miss)
        return random.choice(def_int_make if made else def_int_miss)

    # Same idea on the perimeter: a below-average on-ball defender standing
    # in the vicinity of a jumper isn't "forcing a tough shot" or "staying
    # attached" -- he's just there. Only hand out defensive credit when the
    # defender's rating actually backs it up.
    if defender is not None and defender.perimeter_def < 0.55:
        return random.choice(def_open_make if made else def_open_miss)

    pool = list(def_per_make if made else def_per_miss)
    if not screen_action_context(context):
        screen_words = ("screen", "top-lock", "action")
        filtered = [line for line in pool if not any(word in line for word in screen_words)]
        if filtered:
            pool = filtered
    return random.choice(pool)


