def time_left_phrase(seconds_left: int) -> str:
    # Every template that uses {time_left} appends its own trailing word
    # ("left", "remaining", "showing") right after this -- returning the
    # literal phrase "no time left" produced "...with no time left left."
    # "0 seconds" reads correctly no matter which word follows it.
    if seconds_left <= 0:
        return "0 seconds"
    return f"{seconds_left} second" + ("" if seconds_left == 1 else "s")


def is_late_go_ahead_make(score_before: int, opp_score: int, pts: int, period: int, score_time: int) -> bool:
    return period >= 4 and score_time <= 5 and score_before <= opp_score and score_before + pts > opp_score


