def dribble_chain_count_for_player(player) -> int:
    handle = getattr(player, "ball_handle", 0.0)
    if handle < 0.70:
        return 0
    if handle < 0.85:
        return 1
    if handle < 0.92:
        return random.randint(1, 3)
    return random.randint(1, 4)


def should_print_dribble_chain(shooter, shot_type: str, context: str | None) -> bool:
    if shot_type not in ("three", "mid", "rim"):
        return False
    if getattr(shooter, "ball_handle", 0.0) < 0.70:
        return False
    if context in (
        "catch_shoot", "pnr_catch_shoot", "double_wide_open", "extra_pass_open",
        "handle_combo_pass", "late_catch_shoot", "late_oreb_kickout", "dump_off",
        "dump_off_elite_help", "roller", "popper", "alley_oop", "deep_paint_touch",
        "post_split", "post_touch", "putback"
    ):
        return False
    return True


