# ============================================================
# DATA STRUCTURES
# ============================================================

from dataclasses import dataclass, field

@dataclass(eq=True, unsafe_hash=True)
class Player:
    name: str
    position: str

    # Tendencies (0-1): how often they try each type of action
    three_tendency: float
    mid_tendency: float
    drive_tendency: float
    post_tendency: float
    dunk_tendency: float   # how often they try to dunk on rim attacks
    shot_tendency: float   # overall "shoot now" tendency for this exact player version

    # Scoring ratings (0-1): base efficiency at each level
    three_rating: float
    mid_rating: float
    rim_rating: float
    dunk_rating: float
    ft_rating: float

    # Offensive role / skill (0-1)
    usage: float
    playmaking: float
    ball_handle: float

    # Misc ratings (0-1)
    steal: float
    block: float
    oreb: float
    dreb: float
    foul_draw: float
    foul_rate: float

    # Defense (0-1)
    perimeter_def: float
    interior_def: float
    clutchness: float = 0.50
    secondary_positions: Tuple[str, ...] = field(default_factory=tuple, compare=False, hash=False)
    badges: Tuple[str, ...] = field(default_factory=tuple, compare=False, hash=False)
    height: int = field(default=0, compare=False, hash=False)  # inches
    speed: float = field(default=0.0, compare=False, hash=False)
    # Conditioning / endurance (0-1): how well this player holds up as
    # minutes and possessions pile up in a game. Every roster entry sets
    # this explicitly (players_data.py) rather than deriving it from other
    # ratings -- it's a real, individually-judged scouting call per player,
    # not a formula. 0.0 is only a load-time placeholder; __post_init__
    # does NOT backfill it the way speed/shot_iq get defaulted.
    stamina: float = field(default=0.0, compare=False, hash=False)
    shot_iq: float = field(default=0.0, compare=False, hash=False)
    iso_tendency: float = field(default=0.0, compare=False, hash=False)
    archetype: str = field(default="", compare=False, hash=False)
    go_to_shot: str = field(default="", compare=False, hash=False)


    # box score / state
    pts: int = 0
    reb: int = 0
    ast: int = 0
    assist_pts_created: int = 0
    stl: int = 0
    blk_stat: int = 0
    tov: int = 0
    pf: int = 0
    fgm: int = 0
    fga: int = 0
    tpm: int = 0
    tpa: int = 0
    ftm: int = 0
    fta: int = 0
    minutes: int = 0
    fouled_out: bool = False
    plus_minus: int = 0
    oreb_stat: int = 0
    dreb_stat: int = 0
    fouls_drawn: int = 0
    double_teams_faced: int = 0
    is_starter: bool = field(default=False, compare=False, hash=False)
    shot_diet: Dict[str, int] = field(default_factory=dict, compare=False, hash=False)
    defended_diet: Dict[str, int] = field(default_factory=dict, compare=False, hash=False)
    defended_matchup_diet: Dict[str, Dict[str, int]] = field(default_factory=dict, compare=False, hash=False)

    def __post_init__(self):
        valid_positions = {"PG", "SG", "SF", "PF", "C"}
        secondary = self.secondary_positions
        if isinstance(secondary, str):
            secondary = tuple(pos.strip().upper() for pos in secondary.replace("/", ",").split(","))
        else:
            try:
                secondary = tuple(str(pos).strip().upper() for pos in secondary)
            except TypeError:
                secondary = ()
        secondary = tuple(pos for pos in secondary if pos in valid_positions)
        self.secondary_positions = secondary or default_secondary_positions(self.position)

        if isinstance(self.badges, str):
            self.badges = tuple(badge.strip() for badge in self.badges.split(",") if badge.strip())
        else:
            try:
                self.badges = tuple(str(badge).strip() for badge in self.badges if str(badge).strip())
            except TypeError:
                self.badges = ()

        if self.height <= 0:
            self.height = default_player_height(self.name, self.position)
        if self.speed <= 0:
            self.speed = default_player_speed(self.name, self.position)
        if self.shot_iq <= 0:
            self.shot_iq = default_player_shot_iq(self)
        if self.iso_tendency <= 0:
            self.iso_tendency = default_player_iso_tendency(self)
        if not self.archetype:
            self.archetype = infer_player_archetype(self)
        if not self.go_to_shot:
            self.go_to_shot = default_player_go_to_shot(self)


def foul_draw_sim(player: "Player | None") -> float:
    if player is None:
        return 0.0
    # Compress the curve a bit rather than a straight multiple of the rating:
    # elite foul-drawers pull a little less free-throw rate than pure linear
    # scaling would give them, low-foul-draw players keep a little more.
    x = clamp(getattr(player, "foul_draw", 0.0), 0.0, 0.99)
    # Below the midpoint, leave the rate exactly where it was. Only above the
    # midpoint does the slope ease off, so a low-rated free-throw drawer sees
    # no change at all, while a high-rated one gets pulled down a bit instead
    # of scaling all the way up linearly.
    if x <= 0.50:
        return 0.04 + x * 0.23
    mid = 0.04 + 0.50 * 0.23
    if x <= 0.85:
        return mid + (x - 0.50) * 0.23 * 0.75
    # A genuinely maxed-out (0.99) foul-draw rating on a high-usage player
    # should land a heavy-minutes star around 10 FTA/game, not just a bit
    # above average -- steepen sharply only in the true elite tier so this
    # doesn't drag up the ~140 players sitting at 0.90+ across the whole
    # league average, just the very top of it.
    top = mid + (0.85 - 0.50) * 0.23 * 0.75
    return top + (x - 0.85) * 0.57


def usage_foul_weight(player: "Player | None") -> float:
    # Shooting-foul chance used to scale with raw usage, which meant a
    # 0.70-usage star drew fouls at ~9x the rate of a 0.08-usage bench
    # player -- free throws piled up on one guy. Compress it so role
    # players still draw a meaningful share while the star still leads.
    if player is None:
        return 0.0
    base = max(0.0, getattr(player, "usage", 0.0)) ** 0.6
    # Diminishing returns as the player's own FTA total climbs in this
    # game. A flat per-shot rate compounding over 30+ shot attempts could
    # produce 20+ FTA nights far more often than real basketball ever
    # sees -- taper the rate once he's already had a big free-throw game,
    # leaving a normal night (well under a dozen) untouched.
    fta_so_far = getattr(player, "fta", 0)
    if fta_so_far > 10:
        base *= 1.0 / (1.0 + (fta_so_far - 10) * 0.35)
    return base


def foul_rate_sim(player: "Player | None") -> float:
    if player is None:
        return 0.0
    return clamp(getattr(player, "foul_rate", 0.0), 0.0, 0.99) * 0.30


@dataclass
class Team:
    name: str
    roster: List[Player]
    on_floor: List[Player] = field(default_factory=list)
    bench: List[Player] = field(default_factory=list)
    score: int = 0
    timeouts: int = 7

    team_reb: int = 0
    team_ast: int = 0
    team_stl: int = 0
    team_blk: int = 0
    team_tov: int = 0
    team_pf: int = 0
    points_paint: int = 0
    fastbreak_pts: int = 0
    second_chance_pts: int = 0
    fouls_drawn: int = 0
    shot_diet: Dict[str, int] = field(default_factory=dict)

    def init_lineup(self):
        # First 5 in roster are starters
        self.on_floor = self.roster[:5]
        self.bench = self.roster[5:]
        for i, p in enumerate(self.roster):


            p.is_starter = i < 5
        if getattr(self, "lock_custom_starting_positions", False):
            return
        balance_lineup_positions(self)


# ============================================================
# UTIL / MATCHUPS / SUBS
# ============================================================

# UPDATED: SG and SF are now grouped together as "W" (wings),
# so they will naturally guard each other in matchups.
def default_secondary_positions(pos: str) -> Tuple[str, ...]:
    pos = pos.upper()
    defaults = {
        "PG": ("SG",),
        "SG": ("PG", "SF"),
        "SF": ("SG", "PF"),
        "PF": ("SF", "C"),
        "C": ("PF",),
    }
    return defaults.get(pos, tuple())


