def series_pressure_bonus(player: Player, team: Team, opponent: Team) -> float:
    bonus = 0.0
    if getattr(opponent, "series_wins", 0) >= 3:
        bonus += badge_tier(player, "elimination") * 0.050
    if getattr(team, "series_wins", 0) >= 3:
        bonus += badge_tier(player, "closer") * 0.045
    return min(0.32, bonus)


def limitless_range_tier(player: Player) -> int:
    return badge_tier(player, "limitless_range")


def limitless_range_badge_tier(player: Player) -> str | None:
    if player.three_rating >= 0.97 and player.three_tendency >= 0.50:
        return "plat"
    if player.three_rating >= 0.92 and player.three_tendency >= 0.42:
        return "gold"
    if player.three_rating >= 0.88 and player.three_tendency >= 0.34:
        return "silver"
    if player.three_rating >= 0.84 and player.three_tendency >= 0.28:
        return "bronze"
    return None


def limitless_range_quality_multiplier(player: Player, heat_check: bool = False) -> float:
    tier = limitless_range_tier(player)
    if heat_check:
        return 0.72 + tier * 0.060
    return 0.76 + tier * 0.055


def limitless_range_make_bonus(player: Player) -> float:
    tier = limitless_range_tier(player)
    if tier <= 0:
        return 0.94
    return 0.96 + tier * 0.025


def is_late_close_game(team: Team, opponent: Team | None, period: int, period_time: int) -> bool:
    if opponent is None:
        return False
    return period >= 4 and period_time <= 6 * 60 and abs(team.score - opponent.score) <= 10


def maybe_limitless_range_three(player: Player, team: Team, period: int, period_time: int,
                                opponent: Team | None = None) -> str | None:
    if player.three_tendency <= 0 or player.three_rating < 0.78:
        return None

    if is_late_close_game(team, opponent, period, period_time):
        return None

    tier = limitless_range_tier(player)
    jumper_streak = getattr(player, "jumper_make_streak", 0)
    if jumper_streak >= 3:
        player.jumper_make_streak = 0
        return "heat_check"

    if tier <= 0:
        return None

    base = {
        1: 0.006,
        2: 0.012,
        3: 0.020,
        4: 0.032,
    }.get(tier, 0.0)
    chance = base + max(0.0, player.three_tendency - 0.38) * 0.030
    if getattr(team, "momentum", 0.0) >= 6:
        chance += 0.006
    return "limitless" if random.random() < min(0.055, chance) else None


def assign_player_badges(team: Team):
    for p in team.roster:
        # Normalize any manually entered badges first so old raw strings like
        # "posterizer" still display and behave as bronze-level badges.
        original_badges = tuple(getattr(p, "badges", ()))
        p.badges = tuple()
        for badge in original_badges:
            add_badge(p, str(badge))

        for badge_name, tier in PLAYOFF_MOMENT_BADGES.get(p.name, {}).items():
            add_badge(p, badge_name, tier)

        movement_level = badge_level_from_rating(
            p.three_rating * 0.68 + p.three_tendency * 0.32,
            0.70, 0.76, 0.82, 0.90
        )
        if movement_level and p.three_tendency >= 0.38:
            add_badge(p, "movement_shooter", movement_level)

        limitless_tier = limitless_range_badge_tier(p)
        if limitless_tier:
            add_badge(p, "limitless_range", limitless_tier)

        catch_score = p.three_rating * 0.76 + p.shot_iq * 0.16 + p.three_tendency * 0.08
        catch_level = badge_level_from_rating(catch_score, 0.76, 0.82, 0.88, 0.94)
        if catch_level and p.three_tendency >= 0.24 and p.iso_tendency < 0.82:
            add_badge(p, "catch_shoot", catch_level)

        iso_score = p.usage * 0.34 + max(p.mid_rating, p.three_rating) * 0.46 + p.ball_handle * 0.20
        iso_level = badge_level_from_rating(iso_score, 0.66, 0.74, 0.82, 0.90)
        if iso_level and p.usage >= 0.24:
            add_badge(p, "iso_scorer", iso_level)

        creator_score = p.ball_handle * 0.46 + max(p.mid_rating, p.three_rating) * 0.34 + p.shot_iq * 0.20
        creator_level = badge_level_from_rating(creator_score, 0.78, 0.84, 0.90, 0.96)
        if creator_level and p.ball_handle >= 0.78 and p.usage >= 0.18:
            add_badge(p, "shot_creator", creator_level)

        ankle_score = p.ball_handle * 0.72 + p.iso_tendency * 0.18 + p.usage * 0.10
        ankle_level = badge_level_from_rating(ankle_score, 0.76, 0.84, 0.91, 0.97)
        if ankle_level and p.ball_handle >= 0.82:
            add_badge(p, "ankle_breaker", ankle_level)

        poster_score = p.dunk_rating * 0.62 + p.dunk_tendency * 0.28 + p.rim_rating * 0.10
        poster_level = badge_level_from_rating(poster_score, 0.66, 0.76, 0.86, 0.94)
        if poster_level and p.dunk_tendency >= 0.30:
            add_badge(p, "posterizer", poster_level)

        play_score = p.playmaking * 0.72 + p.ball_handle * 0.18 + p.shot_iq * 0.10
        play_level = badge_level_from_rating(play_score, 0.72, 0.80, 0.88, 0.96)
        if play_level:
            add_badge(p, "post_hub" if can_play_position(p, "C") else "transition_engine", play_level)
            if p.playmaking >= 0.82:
                add_badge(p, "floor_general", play_level)

        lob_score = p.dunk_rating * 0.56 + p.dunk_tendency * 0.34 + p.rim_rating * 0.10
        lob_level = badge_level_from_rating(lob_score, 0.68, 0.78, 0.88, 0.95)
        if lob_level and p.dunk_tendency >= 0.42:
            add_badge(p, "lob_threat", lob_level)

        lock_score = max(p.perimeter_def, p.interior_def)
        lock_level = badge_level_from_rating(lock_score, 0.74, 0.82, 0.90, 0.97)
        if lock_level:
            add_badge(p, "lockdown", lock_level)
        if p.interior_def >= 0.78 or p.block >= 0.62:
            rim_level = badge_level_from_rating(max(p.interior_def, p.block), 0.72, 0.80, 0.88, 0.96)
            if rim_level:
                add_badge(p, "rim_protector", rim_level)
                add_badge(p, "defensive_anchor", rim_level)

        reb_score = max(p.oreb, p.dreb)
        reb_level = badge_level_from_rating(reb_score, 0.62, 0.74, 0.86, 0.96)
        if reb_level:
            add_badge(p, "rebounder", reb_level)

        if badge_tier(p, "chasedown") == 0 and p.block >= 0.42 and p.speed >= 0.72:
            tier = "gold" if p.block >= 0.64 and p.speed >= 0.80 else "silver" if p.block >= 0.52 else "bronze"
            add_badge(p, "chasedown", tier)


def infer_coach_style(team: Team):
    three_rate = sum(p.three_tendency for p in team.roster) / max(1, len(team.roster))
    playmaking = sum(p.playmaking for p in team.roster) / max(1, len(team.roster))
    defense = sum(0.5 * p.perimeter_def + 0.5 * p.interior_def for p in team.roster) / max(1, len(team.roster))
    bench_quality = sum(overall_rating(p) for p in team.roster[5:]) / max(1, len(team.roster[5:]))
    top_defense = max((0.5 * p.perimeter_def + 0.5 * p.interior_def for p in team.roster), default=0.60)
    coach_iq = 0.50 + playmaking * 0.18 + defense * 0.22 + bench_quality * 0.10
    if any(p.playmaking >= 0.82 for p in team.roster):
        coach_iq += 0.04
    if top_defense >= 0.82:
        coach_iq += 0.04

    return {
        "pace": 1.05 if playmaking >= 0.66 else 0.98,
        "three_preference": 1.10 if three_rate >= 0.32 else 0.94,
        "ball_movement": 1.18 if playmaking >= 0.66 else 1.02,
        "timeout_aggression": 1.15 if defense < 0.62 else 0.95,
        "rotation_depth": 10 if bench_quality >= 0.62 else 8,
        "coach_iq": max(0.45, min(0.92, coach_iq)),
        "help_aggression": 1.12 if defense >= 0.68 else 0.92,
        "matchup_adjustment": 1.15 if top_defense >= 0.82 else 0.95,
        "def_scheme": "switch" if defense >= 0.70 else ("drop" if any(can_play_position(p, "C") and p.interior_def >= 0.82 for p in team.roster) else "standard"),
    }


