def coach_profile_name(team: Team) -> str:
    name = team.name
    if "Warriors" in name:
        return "motion_split"
    if "Heat" in name:
        return "ball_movement" if name in ("2020 Miami Heat", "2023 Miami Heat") else "rim_pressure"
    if "Spurs" in name:
        return "ball_movement"
    if name in ("2024 Boston Celtics", "2021 Utah Jazz"):
        return "five_out"
    if name in ("2020 Boston Celtics", "2022 Boston Celtics", "2013 Indiana Pacers"):
        return "defensive_grind"
    if name in ("1987 Boston Celtics", "2015 Atlanta Hawks", "2025 Indiana Pacers", "2023 Sacramento Kings", "2005 Phoenix Suns"):
        return "ball_movement"
    if name in ("2018 Houston Rockets", "2020 Houston Rockets", "2022 Dallas Mavericks", "2021 Brooklyn Nets", "2022 Brooklyn Nets", "2021 Portland Trail Blazers", "2026 Los Angeles Lakers", "2027 Los Angeles Lakers"):
        return "heliocentric_spread"
    if name == "2026 Dallas Mavericks":
        return "balanced"
    if name in ("2016 Cleveland Cavaliers", "2018 Cleveland Cavaliers", "2009 Cleveland Cavaliers", "2021 Atlanta Hawks"):
        return "heliocentric_spread"
    if "Knicks" in name or name == "2011 Chicago Bulls":
        return "defensive_grind"
    if name in ("2013 Memphis Grizzlies", "2004 Detroit Pistons"):
        return "post_hub"
    if name in ("2021 Milwaukee Bucks", "2022 Memphis Grizzlies", "2024 Orlando Magic", "2024 Minnesota Timberwolves"):
        return "rim_pressure"
    if name in ("1996 Chicago Bulls", "2001 Los Angeles Lakers"):
        return "triangle"
    if name == "1987 Los Angeles Lakers":
        return "showtime"
    if name in ("1994 Houston Rockets", "2023 Denver Nuggets", "2024 Denver Nuggets", "2027 Denver Nuggets", "2026 Houston Rockets"):
        return "post_hub"
    if name in ("2015 Los Angeles Clippers", "2014 Los Angeles Clippers", "2024 Los Angeles Clippers", "2017 Washington Wizards", "2018 New Orleans Pelicans"):
        return "pace_motion"
    return "balanced"


def apply_coach_profile(team: Team):
    profile_name = coach_profile_name(team)
    profile = COACH_PROFILES.get(profile_name, COACH_PROFILES["balanced"])
    team.coach_profile = profile_name
    for key, value in profile.items():
        if isinstance(value, (int, float)):
            current = team.coach_style.get(key, value)
            team.coach_style[key] = (current + value) / 2
        else:
            team.coach_style[key] = value


DEFENSIVE_SCHEME_OVERRIDES: Dict[str, str] = {}
OFFENSIVE_SET_OVERRIDES: Dict[str, str] = {}


def star_scoring_pressure(player: Player) -> float:
    shot_skill = max(player.three_rating, player.mid_rating, player.rim_rating, player.dunk_rating)
    shot_mix = max(player.three_tendency, player.mid_tendency, player.drive_tendency, player.post_tendency)
    return (
        0.34 * player.usage
        + 0.26 * player.shot_tendency
        + 0.22 * shot_skill
        + 0.10 * shot_mix
        + 0.08 * player.clutchness
    )


def coverage_plan_for_star(player: Player) -> str:
    pressure = star_scoring_pressure(player)
    if pressure < 0.54:
        return "shade_help"
    if player.playmaking < 0.64:
        return "trap_force_pass"
    if player.playmaking < 0.82:
        return "early_double"
    return "late_double_rotate"


def choose_coach_game_plan(team: Team, opponent: Team):
    style = getattr(team, "coach_style", {})
    opponent_rim = max((p.rim_rating + p.drive_tendency for p in opponent.roster), default=1.0)
    opponent_three = sum(p.three_tendency for p in opponent.roster) / max(1, len(opponent.roster))
    team_three = sum(p.three_tendency for p in team.roster) / max(1, len(team.roster))
    team_rim = max((p.rim_rating + p.drive_tendency for p in team.roster), default=1.0)
    opponent_stars = sorted(opponent.roster, key=star_scoring_pressure, reverse=True)
    star_target = opponent_stars[0] if opponent_stars else None
    star_coverage = coverage_plan_for_star(star_target) if star_target else "standard"

    offense_focus = "balanced"
    if getattr(team, "series_game_plan_adjustment", None):
        offense_focus = team.series_game_plan_adjustment
    elif lineup_can_five_out(team):
        offense_focus = "five_out"
    elif style.get("heliocentric", 0.50) >= 0.95:
        offense_focus = "star_spread"
    elif style.get("offensive_style") in ("ball movement", "motion split", "pace motion", "showtime") and style.get("ball_movement", 1.0) >= 1.24:
        offense_focus = "motion"
    elif style.get("three_preference", 1.0) >= 1.16 or team_three >= 0.36:
        offense_focus = "hunt_threes"
    elif team_rim >= 1.22:
        offense_focus = "attack_paint"
    elif style.get("ball_movement", 1.0) >= 1.20:
        offense_focus = "motion"

    defensive_plan = "standard"
    elite_rim_anchor = max((p.interior_def + p.block for p in team.roster), default=0.0) >= 1.45
    weak_perimeter_group = sum(p.perimeter_def for p in team.roster) / max(1, len(team.roster)) < 0.58
    high_creation_star = star_target and star_target.playmaking >= 0.82 and star_target.ball_handle >= 0.82
    scoring_star_low_playmaking = star_target and star_target.usage >= 0.30 and star_target.playmaking < 0.72

    if opponent_three >= 0.38:
        defensive_plan = "stay_home"
    elif high_creation_star and style.get("coach_iq", 0.62) >= 0.78 and random.random() < 0.45:
        defensive_plan = "show_recover"
    elif scoring_star_low_playmaking:
        defensive_plan = "blitz"
    elif opponent_rim >= 1.26:
        defensive_plan = "drop" if elite_rim_anchor else "wall_paint"
    elif weak_perimeter_group and style.get("help_aggression", 1.0) >= 1.10:
        defensive_plan = "zone"
    elif style.get("def_scheme") == "switch":
        defensive_plan = "switch"
    if star_coverage in ("trap_force_pass", "early_double", "late_double_rotate"):
        defensive_plan = "load_star"
        if getattr(team, "defensive_focus", None) is None and star_target is not None:
            team.defensive_focus = star_target.name

    foul_strategy = "normal"
    if any(p.ft_rating < 0.62 and p.usage >= 0.10 for p in opponent.on_floor):
        foul_strategy = "selective_hack"
    elif any(p.pf >= 3 and p in opponent.on_floor for p in opponent.roster):
        foul_strategy = "attack_foul_trouble"
    elif sum(p.pf for p in team.on_floor) >= 10:
        foul_strategy = "avoid_fouls"

    team.game_plan = {
        "offense": offense_focus,
        "defense": defensive_plan,
        "foul_strategy": foul_strategy,
        "star_target": star_target.name if star_target else None,
        "star_coverage": star_coverage,
    }
    apply_offensive_set_override(team)
    apply_defensive_scheme_override(team)


def apply_defensive_scheme_override(team: Team):
    override = DEFENSIVE_SCHEME_OVERRIDES.get(team.name)
    if not override or override == "auto":
        return
    plan = getattr(team, "game_plan", {})
    if override == "top_lock":
        plan["defense"] = "stay_home"
        plan["top_lock_shooters"] = True
        plan["limit_threes"] = True
    else:
        plan["defense"] = override
        if override in ("stay_home", "show_recover"):
            plan["limit_threes"] = True
        if override in ("pack_paint", "wall_paint", "zone", "drop"):
            plan["limit_paint"] = True
    team.game_plan = plan


def apply_offensive_set_override(team: Team):
    override = OFFENSIVE_SET_OVERRIDES.get(team.name)
    if not override or override == "auto":
        return

    plan = getattr(team, "game_plan", {})
    plan["offense"] = override

    if override == "five_out":
        plan["spacing_priority"] = True
        plan["paint_space"] = "wide"
        plan["glass_priority"] = "low"
    elif override == "four_out_one_in":
        plan["spacing_priority"] = True
        plan["paint_space"] = "balanced"
        plan["glass_priority"] = "normal"
    elif override == "three_out_two_in":
        plan["paint_space"] = "crowded"
        plan["glass_priority"] = "high"
        plan["two_big_actions"] = True
    elif override == "post_heavy":
        plan["paint_space"] = "post"
        plan["glass_priority"] = "high"
        plan["post_priority"] = True
    elif override == "motion":
        plan["ball_movement_priority"] = True
        plan["paint_space"] = "balanced"
    elif override == "star_spread":
        plan["star_touch_priority"] = True
        plan["paint_space"] = "spread"

    team.game_plan = plan


def lineup_can_five_out(team: Team) -> bool:
    players = getattr(team, "on_floor", [])
    if len(players) < 5:
        return False
    for p in players:
        if p.three_rating < 0.72 or p.three_tendency < 0.16:
            return False
    return True


