def position_group(pos: str) -> str:
    pos = pos.upper()
    if pos == "PG":
        return "PG"      # primary ball-handlers
    if pos in ("SG", "SF"):
        return "W"       # wings – SG & SF interchangeable
    if pos in ("PF", "C"):
        return "B"       # bigs
    return pos

def player_stat_key(team: Team, player: Player) -> str:
    same_name = [p for p in getattr(team, "roster", []) if p.name == player.name]
    if len(same_name) <= 1:
        return player.name
    for idx, candidate in enumerate(same_name, start=1):
        if candidate is player:
            return player.name if idx == 1 else f"{player.name} #{idx}"
    return player.name


def player_from_stat_key(team: Team, key: str) -> Player | None:
    for player in getattr(team, "roster", []):
        if player_stat_key(team, player) == key:
            return player
    return next((player for player in getattr(team, "roster", []) if player.name == key), None)


def add_player_to_series_totals(series_totals: Dict, team: Team):
    if team.name not in series_totals:
        series_totals[team.name] = {}

    for p in team.roster:
        player_key = player_stat_key(team, p)
        if player_key not in series_totals[team.name]:
            series_totals[team.name][player_key] = {
                "position": p.position,
                "games": 0,
                "minutes": 0,
                "pts": 0,
                "reb": 0,
                "oreb": 0,
                "dreb": 0,
                "ast": 0,
                "assist_pts_created": 0,
                "stl": 0,
                "blk": 0,
                "tov": 0,
                "pf": 0,
                "plus_minus": 0,
                "double_teams_faced": 0,
                "fgm": 0,
                "fga": 0,
                "tpm": 0,
                "tpa": 0,
                "ftm": 0,
                "fta": 0,
                "shot_diet": {},
                "quarter_shot_diet": {},
                "defended_diet": {},
                "defended_matchup_diet": {},
                "quarter_stats": {},
            }

        s = series_totals[team.name][player_key]
        s["position"] = p.position
        s["games"] += 1
        s["minutes"] += p.minutes
        s["pts"] += p.pts
        s["reb"] += p.reb
        s["oreb"] += p.oreb_stat
        s["dreb"] += p.dreb_stat
        s["ast"] += p.ast
        s["assist_pts_created"] += getattr(p, "assist_pts_created", 0)
        s["stl"] += p.stl
        s["blk"] += p.blk_stat
        s["tov"] += p.tov
        s["pf"] += p.pf
        s["plus_minus"] += p.plus_minus
        s["double_teams_faced"] += getattr(p, "double_teams_faced", 0)
        s["fgm"] += p.fgm
        s["fga"] += p.fga
        s["tpm"] += p.tpm
        s["tpa"] += p.tpa
        s["ftm"] += p.ftm
        s["fta"] += p.fta
        for key, value in getattr(p, "shot_diet", {}).items():
            s["shot_diet"][key] = s["shot_diet"].get(key, 0) + value
        for q, q_diet in (getattr(p, "quarter_shot_diet", {}) or {}).items():
            q_bucket = s["quarter_shot_diet"].setdefault(q, {})
            for key, value in (q_diet or {}).items():
                q_bucket[key] = q_bucket.get(key, 0) + value
        for key, value in getattr(p, "defended_diet", {}).items():
            s["defended_diet"][key] = s["defended_diet"].get(key, 0) + value
        merge_nested_diet(s["defended_matchup_diet"], getattr(p, "defended_matchup_diet", {}))
        for row in getattr(team, "quarter_player_stats", {}).get(player_key, []):
            period = row.get("period")
            if period is None:
                continue
            q = s["quarter_stats"].setdefault(period, {
                "games": 0,
                "minutes": 0,
                "pts": 0,
                "reb": 0,
                "ast": 0,
                "assist_pts_created": 0,
                "stl": 0,
                "blk": 0,
                "tov": 0,
                "oreb": 0,
                "dreb": 0,
                "pf": 0,
                "fgm": 0,
                "fga": 0,
                "tpm": 0,
                "tpa": 0,
                "ftm": 0,
                "fta": 0,
                "plus_minus": 0,
            })
            q["games"] += 1
            for key in (
                "minutes", "pts", "reb", "ast", "assist_pts_created", "stl", "blk", "tov", "oreb", "dreb",
                "pf", "fgm", "fga", "tpm", "tpa", "ftm", "fta", "plus_minus"
            ):
                q[key] += row.get(key, 0)


