def snapshot_series_game(game_num: int, teamA: Team, teamB: Team, home_team: Team) -> Dict:
    return {
        "game_num": game_num,
        "home": home_team.name,
        "away": teamB.name if home_team is teamA else teamA.name,
        "teams": [snapshot_team_box(teamA), snapshot_team_box(teamB)],
        "why_won": build_why_won_summary(teamA, teamB),
    }


def team_snapshot_totals(game_team: Dict) -> Dict:
    return game_team.get("totals", {}) or {}


def build_why_won_summary(teamA: Team, teamB: Team) -> str:
    winner = teamA if teamA.score >= teamB.score else teamB
    loser = teamB if winner is teamA else teamA
    wt = accumulate_team_totals(winner)
    lt = accumulate_team_totals(loser)
    edges = []
    if winner.score - loser.score >= 8:
        edges.append(f"controlled the scoreboard by {winner.score - loser.score}")
    reb_edge = wt.get("reb", 0) - lt.get("reb", 0)
    if abs(reb_edge) >= 6:
        edges.append(f"won the glass {wt.get('reb', 0)}-{lt.get('reb', 0)}")
    ast_edge = wt.get("ast", 0) - lt.get("ast", 0)
    if ast_edge >= 5:
        edges.append(f"created cleaner looks with {wt.get('ast', 0)} assists")
    tov_edge = lt.get("tov", 0) - wt.get("tov", 0)
    if tov_edge >= 4:
        edges.append(f"took better care of the ball, forcing a {tov_edge}-turnover gap")
    three_edge = wt.get("tpm", 0) - lt.get("tpm", 0)
    if three_edge >= 4:
        edges.append(f"won the three-point math by {three_edge} makes")
    ft_edge = wt.get("ftm", 0) - lt.get("ftm", 0)
    if ft_edge >= 5:
        edges.append(f"lived at the line with a {ft_edge}-made-FT edge")
    top = max(winner.roster, key=lambda p: p.pts)
    if top.pts >= 25:
        edges.append(f"got a star punch from {top.name} ({top.pts} points)")
    if not edges:
        edges.append("made just enough late-game plays")
    return f"Game went to {winner.name}: " + "; ".join(edges[:4]) + "."


def build_postgame_recaps_text(game_logs: List[Dict]) -> str:
    if not game_logs:
        return "Postgame recaps will appear after games finish."
    lines = ["POSTGAME WHY THEY WON", "=" * 80]
    for game in game_logs:
        lines.append(f"Game {game.get('game_num', '-')}: {game.get('why_won', 'No recap available.')}")
    return "\n".join(lines)


def build_series_memory_text(game_logs: List[Dict]) -> str:
    if not game_logs:
        return "Series gameplan memory will appear after Game 1."
    lines = ["SERIES GAMEPLAN MEMORY", "=" * 80]
    for game in game_logs:
        lines.append(f"Game {game.get('game_num', '-')}")
        for team in game.get("teams", []) or []:
            players = team.get("players", []) or []
            if not players:
                continue
            top = max(players, key=lambda p: p.get("pts", 0))
            totals = team_snapshot_totals(team)
            diet = team.get("shot_diet", {}) or {}
            fga = max(1, totals.get("fga", 0))
            three_rate = diet.get("three", 0) / fga
            paint_att = diet.get("rim", 0) + diet.get("post", 0) + diet.get("dunk", 0)
            notes = []
            if top.get("pts", 0) >= 28:
                notes.append(f"load extra help toward {top.get('name')} after {top.get('pts')} points")
            if three_rate >= 0.42:
                notes.append("run shooters off the line")
            if paint_att >= fga * 0.45:
                notes.append("build a stronger paint wall")
            if totals.get("tov", 0) >= 14:
                notes.append("pressure their ball security")
            if not notes:
                notes.append("keep the base plan, no emergency adjustment")
            lines.append(f"  {team.get('name')}: " + "; ".join(notes[:3]))
    return "\n".join(lines)


def build_series_bracket_visual(game_logs: List[Dict], series_team_totals: Dict) -> str:
    if not game_logs and not series_team_totals:
        return "Series game tiles will appear here."
    names = list(series_team_totals.keys())
    if len(names) < 2 and game_logs:
        names = [team.get("name", "") for team in (game_logs[-1].get("teams", []) or [])]
    lines = ["BEST-OF-7 SERIES", "=" * 80]
    if len(names) >= 2:
        a, b = names[:2]
        aw = series_team_totals.get(a, {}).get("wins", 0)
        bw = series_team_totals.get(b, {}).get("wins", 0)
        lines.append(f"{a:<34} ({aw})")
        lines.append("        ├── " + "  ".join(f"G{g.get('game_num')}: {g.get('home')} H" for g in game_logs[-7:]))
        lines.append(f"{b:<34} ({bw})")
    lines.append("")
    for game in game_logs[-7:]:
        teams = game.get("teams", []) or []
        if len(teams) >= 2:
            winner = max(teams, key=lambda t: t.get("score", 0))
            loser = min(teams, key=lambda t: t.get("score", 0))
            lines.append(f"Game {game.get('game_num')}: {winner.get('name')} {winner.get('score')} - {loser.get('score')} {loser.get('name')} | Home: {game.get('home')}")
    return "\n".join(lines)


def is_clutch_shot_context() -> bool:
    period = SIM_CONTEXT.get("period") if isinstance(globals().get("SIM_CONTEXT"), dict) else None
    period_time = SIM_CONTEXT.get("period_time") if isinstance(globals().get("SIM_CONTEXT"), dict) else None
    teamA = SIM_CONTEXT.get("teamA") if isinstance(globals().get("SIM_CONTEXT"), dict) else None
    teamB = SIM_CONTEXT.get("teamB") if isinstance(globals().get("SIM_CONTEXT"), dict) else None
    return (
        isinstance(period, int) and period >= 4
        and isinstance(period_time, int) and period_time <= 6 * 60
        and teamA is not None and teamB is not None
        and abs(teamA.score - teamB.score) <= 10
    )





