def safe_div(a, b):
    return 0.0 if b == 0 else a / b


def clamp_value(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def format_diet_pair(diet: Dict[str, int], key: str) -> str:
    made = diet.get(key + "_made", 0)
    attempts = diet.get(key, 0)
    pct = safe_pct(made, attempts)
    return f"{made}/{attempts} {pct:.1f}%"


def format_diet_pair_compact(diet: Dict[str, int], key: str) -> str:
    made = diet.get(key + "_made", 0)
    attempts = diet.get(key, 0)
    pct = safe_pct(made, attempts)
    return f"{made}/{attempts} {pct:.0f}%"


def format_diet_group_compact(diet: Dict[str, int], keys: Tuple[str, ...]) -> str:
    made = sum(diet.get(key + "_made", 0) for key in keys)
    attempts = sum(diet.get(key, 0) for key in keys)
    pct = safe_pct(made, attempts)
    return f"{made}/{attempts} {pct:.0f}%"


def format_diet_total(diet: Dict[str, int]) -> str:
    keys = ("three", "mid", "rim", "post", "dunk")
    made = sum(diet.get(key + "_made", 0) for key in keys)
    attempts = sum(diet.get(key, 0) for key in keys)
    pct = safe_pct(made, attempts)
    return f"{made}/{attempts} {pct:.1f}%"


def format_shot_quality_avg(diet: Dict[str, int]) -> str:
    count = diet.get("shot_quality_count", 0)
    if count <= 0:
        return "0.00"
    return f"{diet.get('shot_quality_sum', 0.0) / count:.2f}"


def add_shot_quality_to_diet(diet: Dict[str, int], quality_mult: float | None):
    if quality_mult is None:
        quality_mult = 1.0
    diet["shot_quality_sum"] = diet.get("shot_quality_sum", 0.0) + quality_mult
    diet["shot_quality_count"] = diet.get("shot_quality_count", 0) + 1


def add_to_shot_diet(diet: Dict[str, int], shot_type: str, context: str = "", made: bool = False):
    shot_type = shot_diet_type(shot_type)
    contexts = set(str(context or "").split("|")) - {""}
    if made:
        diet[f"{shot_type}_made"] = diet.get(f"{shot_type}_made", 0) + 1

        if is_paint_shot(shot_type):
            diet["paint_made"] = diet.get("paint_made", 0) + 1
        if contexts & {"pnr_catch_shoot", "double_wide_open", "extra_pass_open", "drive_kick", "extra_pass", "late_catch_shoot", "fastbreak_catch_shoot"}:
            diet["catch_shoot_made"] = diet.get("catch_shoot_made", 0) + 1
        if "iso" in contexts:
            diet["iso_made"] = diet.get("iso_made", 0) + 1
        if "putback" in contexts:
            diet["putback_made"] = diet.get("putback_made", 0) + 1
        if contexts & {"fastbreak", "fastbreak_catch_shoot"}:
            diet["fastbreak_made"] = diet.get("fastbreak_made", 0) + 1
        if "wide_open" in contexts:
            diet["wide_open_made"] = diet.get("wide_open_made", 0) + 1
            diet[f"{shot_type}_open_made"] = diet.get(f"{shot_type}_open_made", 0) + 1
        if "contested" in contexts:
            diet["contested_made"] = diet.get("contested_made", 0) + 1
            diet[f"{shot_type}_contested_made"] = diet.get(f"{shot_type}_contested_made", 0) + 1

    else:
        diet[shot_type] = diet.get(shot_type, 0) + 1

        if is_paint_shot(shot_type):
            diet["paint"] = diet.get("paint", 0) + 1
        if contexts & {"pnr_catch_shoot", "double_wide_open", "extra_pass_open", "drive_kick", "extra_pass", "late_catch_shoot", "fastbreak_catch_shoot"}:
            diet["catch_shoot"] = diet.get("catch_shoot", 0) + 1
        if "iso" in contexts:
            diet["iso"] = diet.get("iso", 0) + 1
        if "putback" in contexts:
            diet["putback"] = diet.get("putback", 0) + 1
        if contexts & {"fastbreak", "fastbreak_catch_shoot"}:
            diet["fastbreak"] = diet.get("fastbreak", 0) + 1
        if "wide_open" in contexts:
            diet["wide_open"] = diet.get("wide_open", 0) + 1
            diet[f"{shot_type}_open"] = diet.get(f"{shot_type}_open", 0) + 1
        if "contested" in contexts:
            diet["contested"] = diet.get("contested", 0) + 1
            diet[f"{shot_type}_contested"] = diet.get(f"{shot_type}_contested", 0) + 1


def shot_quality_diet_context(context: str | None, quality_label: str) -> str:
    contexts = []
    if context:
        contexts.extend(str(context).split("|"))
    if quality_label == "wide open":
        contexts.append("wide_open")
    elif quality_label in ("lightly contested", "tightly contested", "smothered", "late-clock forced", "rushed role-player look"):
        contexts.append("contested")
    seen = []
    for item in contexts:
        if item and item not in seen:
            seen.append(item)
    return "|".join(seen)


def is_contested_diet_context(context: str | None) -> bool:
    return "contested" in (set(str(context or "").split("|")) - {""})


def defensive_diet_context(context: str | None) -> str:
    contexts = [
        item for item in str(context or "").split("|")
        if item and item not in ("fastbreak", "fastbreak_catch_shoot")
    ]
    if "wide_open" not in contexts and "contested" not in contexts:
        contexts.append("contested")
    return "|".join(contexts)


def record_defended_matchup_diet(defender: Player | None, shooter: Player | None,
                                 shot_type: str, context: str, made: bool):
    if defender is None or shooter is None:
        return
    if not hasattr(defender, "defended_matchup_diet") or defender.defended_matchup_diet is None:
        defender.defended_matchup_diet = {}
    guarded_bucket = defender.defended_matchup_diet.setdefault(shooter.name, {})
    add_to_shot_diet(guarded_bucket, shot_type, context, made=made)


def merge_nested_diet(target: Dict, source: Dict):
    for outer_key, diet in (source or {}).items():
        bucket = target.setdefault(outer_key, {})
        for key, value in (diet or {}).items():
            bucket[key] = bucket.get(key, 0) + value





def calc_series_advanced(p, team, opp):
    gp = max(1, p["games"])
    mp = p["minutes"] / 60
    mpg = safe_div(mp, gp)
    team_mp = 240 * gp
    team_minutes_factor = team_mp / 5
    if mp <= 0:
        return (mpg,) + (0.0,) * 26

    pts = p["pts"]
    fga = p["fga"]
    fgm = p["fgm"]
    fta = p["fta"]
    ftm = p["ftm"]
    tpa = p["tpa"]
    tpm = p["tpm"]
    ast = p["ast"]
    tov = p["tov"]
    oreb = p["oreb"]
    dreb = p["dreb"]
    reb = p["reb"]
    stl = p["stl"]
    blk = p["blk"]
    pf = p.get("pf", 0)
    plus_minus = p.get("plus_minus", 0)
    assist_pts_created = p.get("assist_pts_created", 0)

    ts = 100 * safe_div(pts, 2 * (fga + 0.44 * fta))
    efg = 100 * safe_div(fgm + 0.5 * tpm, fga)
    three_par = safe_div(tpa, fga)
    ftr = safe_div(fta, fga)

    team_poss = team["fga"] + 0.44 * team["fta"] - team["oreb"] + team["tov"]
    opp_poss = opp["fga"] + 0.44 * opp["fta"] - opp["oreb"] + opp["tov"]
    poss = 0.5 * (team_poss + opp_poss)

    orb_pct = 100 * safe_div(oreb * team_minutes_factor, mp * (team["oreb"] + opp["dreb"]))
    drb_pct = 100 * safe_div(dreb * team_minutes_factor, mp * (team["dreb"] + opp["oreb"]))
    trb_pct = 100 * safe_div(reb * team_minutes_factor, mp * (team["reb"] + opp["reb"]))
    ast_den = ((mp / team_minutes_factor) * team["fgm"]) - fgm
    ast_pct = 100 * safe_div(ast, ast_den)
    stl_pct = 100 * safe_div(stl * team_minutes_factor, mp * opp_poss)
    blk_pct = 100 * safe_div(blk * team_minutes_factor, mp * max(1, opp["fga"] - opp["tpa"]))
    tov_pct = 100 * safe_div(tov, fga + 0.44 * fta + tov)
    usg_pct = 100 * safe_div(
        (fga + 0.44 * fta + tov) * team_minutes_factor,
        mp * (team["fga"] + 0.44 * team["fta"] + team["tov"])
    )

    league_ts = 0.575
    league_ortg = 115.0
    player_ts = safe_div(pts, 2 * (fga + 0.44 * fta))
    scoring_value = pts * (player_ts - league_ts)
    play_value = ast * 1.5
    def_value = stl * 2.5 + blk * 2.0 + dreb * 0.35
    mistake_cost = tov * 1.5 + max(0, fga - fgm) * 0.35

    pos = str(p.get("position", "SF") or "SF").upper()
    if pos not in ("PG", "SG", "SF", "PF", "C"):
        pos = "SF"
    role_weights = {
        "PG": {"scoring": 14.0, "usage": 0.050, "ast": 0.072, "tov": 0.105, "three": 1.25, "orb": 0.018, "drb": 0.010, "stl": 0.070, "blk": 0.020, "dreb": 0.010},
        "SG": {"scoring": 15.5, "usage": 0.058, "ast": 0.052, "tov": 0.108, "three": 1.35, "orb": 0.016, "drb": 0.012, "stl": 0.068, "blk": 0.026, "dreb": 0.012},
        "SF": {"scoring": 15.0, "usage": 0.052, "ast": 0.044, "tov": 0.100, "three": 1.05, "orb": 0.022, "drb": 0.017, "stl": 0.064, "blk": 0.034, "dreb": 0.016},
        "PF": {"scoring": 13.2, "usage": 0.042, "ast": 0.035, "tov": 0.094, "three": 0.70, "orb": 0.034, "drb": 0.026, "stl": 0.052, "blk": 0.052, "dreb": 0.024},
        "C":  {"scoring": 12.0, "usage": 0.034, "ast": 0.030, "tov": 0.090, "three": 0.42, "orb": 0.040, "drb": 0.032, "stl": 0.044, "blk": 0.072, "dreb": 0.030},
    }
    w = role_weights[pos]
    team_ortg = 100 * safe_div(team["pts"], poss)
    opp_ortg = 100 * safe_div(opp["pts"], max(1.0, opp_poss))
    team_net_per100 = team_ortg - opp_ortg
    plus_per100 = 100 * safe_div(plus_minus, max(1.0, poss * safe_div(mp, team_mp)))
    team_off_context = (team_ortg - league_ortg) * 0.045
    team_total_context = team_net_per100 * 0.060 + plus_per100 * 0.018

    scoring_eff = player_ts - league_ts
    scoring_volume = safe_div(pts * 75, max(1.0, poss * safe_div(mp, team_mp))) - 18.0
    spacing_value = three_par * safe_div(tpm, max(1, tpa)) if tpa else 0.0
    obpm = (
        scoring_eff * w["scoring"]
        + scoring_volume * w["usage"]
        + (usg_pct - 20.0) * w["usage"]
        + ast_pct * w["ast"]
        + orb_pct * w["orb"]
        + drb_pct * w["drb"]
        + spacing_value * w["three"]
        - tov_pct * w["tov"]
        + team_off_context
        - 1.65
    )

    defensive_component = (
        stl_pct * w["stl"]
        + blk_pct * w["blk"]
        + drb_pct * w["dreb"]
        + (league_ortg - opp_ortg) * 0.035
        + plus_per100 * 0.012
        - safe_div(pf * 36, mp) * 0.070
        - 0.85
    )
    bpm = obpm + defensive_component + team_total_context
    dbpm = bpm - obpm

    per = (
        pts + reb * 1.2 + ast * 1.5 + stl * 3 + blk * 3
        - tov * 2 - (fga - fgm) - (fta - ftm) * 0.5
    )
    per = safe_div(per, max(1, mp)) * 7.5

    ows = max(0.0, (scoring_value + play_value - mistake_cost) / 10)
    dws = max(0.0, (def_value + safe_div(team["pts"] - opp["pts"], gp) * safe_div(mp, team_minutes_factor)) / 12)
    ws = ows + dws
    ws48 = safe_div(ws * 48, mp)
    vorp = safe_div((bpm - (-2.0)) * mp, 240)
    # Impact mirrors the Basketball-Reference BPM split: offensive impact is
    # the offensive box plus/minus estimate, defensive impact is BPM - OBPM,
    # and total impact is the combined BPM.
    off_impact = obpm
    def_impact = dbpm
    total_impact = bpm
    plus_minus_pg = safe_div(plus_minus, gp)
    dbl_team_pg = safe_div(p.get("double_teams_faced", 0), gp)

    return mpg, per, ts, efg, three_par, ftr, orb_pct, drb_pct, trb_pct, ast_pct, stl_pct, blk_pct, tov_pct, usg_pct, ows, dws, ws, ws48, obpm, dbpm, bpm, vorp, off_impact, def_impact, total_impact, plus_minus_pg, dbl_team_pg


