        ("three_out_two_in", "3-out, 2-in: stronger glass/post play, tighter driving lanes"),
        ("post_heavy", "Post-heavy / inside-out: more paint touches, fewer perimeter looks"),
        ("motion", "Motion / ball movement: more handoffs/cuts, fewer pure isolations"),
        ("star_spread", "Star spread / isolation: star touches, less flow, cleaner driving space"),
