def apply_manual_player_roles(team: Team):
    roles = getattr(team, "manual_player_roles", {})
    if not roles:
        return

    for player in team.roster:
        if not hasattr(player, "fantasy_role_base"):
            player.fantasy_role_base = {
                "usage": player.usage,
                "shot_tendency": player.shot_tendency,
                "iso_tendency": player.iso_tendency,
                "playmaking": player.playmaking,
                "ball_handle": player.ball_handle,
                "three_tendency": player.three_tendency,
                "drive_tendency": player.drive_tendency,
                "post_tendency": player.post_tendency,
                "perimeter_def": player.perimeter_def,
                "interior_def": player.interior_def,
                "target_minutes": getattr(player, "target_minutes", None),
            }
        base = player.fantasy_role_base
        player.usage = base["usage"]
        player.shot_tendency = base["shot_tendency"]
        player.iso_tendency = base["iso_tendency"]
        player.playmaking = base["playmaking"]
        player.ball_handle = base["ball_handle"]
        player.three_tendency = base["three_tendency"]
        player.drive_tendency = base["drive_tendency"]
        player.post_tendency = base["post_tendency"]
        player.perimeter_def = base["perimeter_def"]
        player.interior_def = base["interior_def"]
        if base["target_minutes"] is not None:
            player.target_minutes = base["target_minutes"]

        role = roles.get(player.name)
        if not role:
            player.fantasy_role = "auto"
            continue
        player.fantasy_role = role

        if role == "primary_scorer":
            player.usage = min(0.42, player.usage + 0.055)
            player.shot_tendency = min(0.64, player.shot_tendency + 0.080)
            player.iso_tendency = min(0.90, player.iso_tendency + 0.080)
            player.target_minutes = max(getattr(player, "target_minutes", 0), random.randint(38, 43))
        elif role == "secondary_scorer":
            player.usage = min(0.34, player.usage + 0.030)
            player.shot_tendency = min(0.54, player.shot_tendency + 0.050)
            player.target_minutes = max(getattr(player, "target_minutes", 0), random.randint(32, 38))
        elif role == "primary_playmaker":
            player.usage = min(0.32, player.usage + 0.018)
            player.playmaking = min(0.99, player.playmaking + 0.035)
            player.ball_handle = min(0.99, player.ball_handle + 0.020)
            player.shot_tendency = max(0.16, player.shot_tendency - 0.025)
            player.target_minutes = max(getattr(player, "target_minutes", 0), random.randint(34, 40))
        elif role == "spot_up":
            player.three_tendency = min(0.72, player.three_tendency + 0.090)
            player.shot_tendency = min(0.42, player.shot_tendency + 0.015)
            player.iso_tendency = max(0.02, player.iso_tendency - 0.070)
            player.target_minutes = max(getattr(player, "target_minutes", 0), random.randint(22, 32))
        elif role == "defensive_stopper":
            player.usage = max(0.08, player.usage - 0.025)
            player.shot_tendency = max(0.08, player.shot_tendency - 0.040)
            player.perimeter_def = min(0.99, player.perimeter_def + 0.020)
            player.interior_def = min(0.99, player.interior_def + 0.012)
            player.target_minutes = max(getattr(player, "target_minutes", 0), random.randint(26, 36))
        elif role == "rim_runner":
            player.drive_tendency = min(0.56, player.drive_tendency + 0.040)
            player.post_tendency = min(0.62, player.post_tendency + 0.030)
            player.shot_tendency = min(0.34, max(player.shot_tendency, 0.18))
            player.target_minutes = max(getattr(player, "target_minutes", 0), random.randint(22, 32))
        elif role == "sixth_man":
            player.usage = min(0.30, player.usage + 0.020)
            player.shot_tendency = min(0.48, player.shot_tendency + 0.035)
            player.target_minutes = max(getattr(player, "target_minutes", 0), random.randint(24, 32))
        elif role == "bench_depth":
            player.usage = max(0.06, player.usage - 0.035)
            player.shot_tendency = max(0.05, player.shot_tendency - 0.050)
            player.target_minutes = min(getattr(player, "target_minutes", 14), random.randint(6, 14))


def queue_manual_substitution(team: Team):
    print(f"\nManual substitution for {team.name}")
    queued = list(getattr(team, "manual_substitution", []) or [])
    projected_on_floor = list(team.on_floor)
    projected_bench = [p for p in team.bench if not p.fouled_out]

    while True:
        print("\nOn court:")
        out_player = choose_player_from_list(projected_on_floor, "Choose player to sub out, or press Enter when done: ")
        if out_player is None:
            break
        print("Bench:")
        in_player = choose_player_from_list(projected_bench, "Choose player to sub in, or press Enter to cancel this sub: ")
        if in_player is None:
            continue

        queued.append((out_player.name, in_player.name))
        projected_on_floor[projected_on_floor.index(out_player)] = in_player
        projected_on_floor = balanced_lineup_order(projected_on_floor)
        projected_bench.remove(in_player)
        projected_bench.append(out_player)
        print(f"Queued: {in_player.name} for {out_player.name}.")

        if input("Add another substitution? Enter y or press Enter: ").strip().lower() not in ("y", "yes"):
            break

    if not queued:
        return
    team.manual_substitution = queued
    team.manual_sub_request = False
    print(f"{len(queued)} manual substitution(s) queued for the next dead ball.")


def apply_manual_substitution(team: Team) -> bool:
    requests = list(getattr(team, "manual_substitution", []) or [])
    if not requests:
        return False
    applied = False
    team.manual_substitution = []
    free_throw_shooter = getattr(team, "free_throw_shooter", None)
    for out_name, in_name in requests:
        out_player = next((p for p in team.on_floor if p.name == out_name), None)
        in_player = next((p for p in team.bench if p.name == in_name and not p.fouled_out), None)
        if out_player is None or in_player is None:
            print(f"{team.name} manual sub {in_name} for {out_name} could not be applied because the lineup changed.")
            continue
        if free_throw_shooter is not None and out_player is free_throw_shooter:
            print(f"{team.name} cannot sub out {out_player.name} until his free throws are finished.")
            team.manual_substitution.append((out_name, in_name))
            continue
        idx = team.on_floor.index(out_player)
        team.on_floor[idx] = in_player
        team.bench.remove(in_player)
        team.bench.append(out_player)
        out_player.current_stint = 0
        in_player.current_stint = 0
        print(commentator_sub(team.name, in_player.name, out_player.name))
        applied = True
    if applied:
        balance_lineup_positions(team)
        time.sleep(SLEEP * 0.5)
    return applied


def handle_manual_sub_request_if_needed():
    team = user_control_team()
    if team is None or not getattr(team, "manual_sub_request", False):
        return
    team.manual_sub_request = False
    was_enabled = SIM_CONTROL_ENABLED
    if was_enabled:
        disable_keyboard_controls()
    try:
        queue_manual_substitution(team)
    finally:
        if was_enabled:
            enable_keyboard_controls(SIM_CONTEXT.get("teamA"), SIM_CONTEXT.get("teamB"))


def can_advance_after_timeout(period: int, period_time: int) -> bool:
    if period_time <= 0:
        return False
    return period > 4 or (period == 4 and period_time <= 2 * 60)


def maybe_apply_manual_timeout(possession: Team, teamA: Team, teamB: Team,
                               period: int, period_time: int) -> bool:
    if not getattr(possession, "manual_timeout_requested", False):
        return False
    possession.manual_timeout_requested = False
    if possession.timeouts <= 0:
        print(f"{possession.name} tried to call timeout, but they are out of timeouts.")
        return False

    opponent = teamB if possession is teamA else teamA
    possession.timeouts -= 1
    possession.manual_timeout_stop_possession = True
    if can_advance_after_timeout(period, period_time):
        possession.ato_pending = True
        possession.inbound_pending = True
    else:
        possession.ato_pending = False
        possession.inbound_pending = False
    possession.current_run = 0
    opponent.current_run = 0
    possession.momentum = min(2.0, getattr(possession, "momentum", 0.0))
    opponent.momentum = max(-1.0, getattr(opponent, "momentum", 0.0) * 0.35)

    print_scoreboard(period, period_time, teamA, teamB)
    print(commentator_timeout(possession.name, possession.timeouts))

    was_enabled = SIM_CONTROL_ENABLED
    if was_enabled:
        disable_keyboard_controls()
    try:
        configure_offensive_set_menu(possession)
        configure_defensive_scheme_menu(possession)
        configure_player_defensive_customization(possession, opponent)
        if is_user_controlled_team(possession):
            configure_fantasy_player_roles(possession)
            apply_manual_player_roles(possession)
        if input("Queue a substitution out of this timeout? Enter y or press Enter: ").strip().lower() in ("y", "yes"):
            queue_manual_substitution(possession)
            apply_manual_substitution(possession)
    finally:
        if was_enabled:
            enable_keyboard_controls(teamA, teamB)
    return True


def consume_manual_timeout_stop(team: Team) -> bool:
    if getattr(team, "manual_timeout_stop_possession", False):
        team.manual_timeout_stop_possession = False
        return True
    return False


def foul_trouble_defense_factor(defender: Player) -> float:
    if defender.pf >= 5:
        return 0.78
    if defender.pf >= 4:
        return 0.88
    if defender.pf >= 3:
        return 0.94
    return 1.0


def foul_trouble_foul_factor(defender: Player) -> float:
    if defender.pf >= 5:
        return 0.35
    if defender.pf >= 4:
        return 0.55
    if defender.pf >= 3:
        return 0.75
    return 1.0


def stamina_fatigue_multiplier(player: Player) -> float:
    """
    Scales how hard the accumulated-minutes/stint fatigue below actually
    bites for this specific player. Every roster entry carries its own,
    individually-judged conditioning rating (player.stamina, set in
    players_data.py) rather than everyone fatiguing on one identical curve.

    0.75 is the pivot -- a player rated right there fatigues exactly like
    the original, stamina-blind curve did. A grinder rated down near 0.55
    takes noticeably more drag for the same minutes; an iron-man up near
    0.95 gets most of it blunted away.
    """
    stamina = getattr(player, "stamina", 0.0) or 0.75
    return max(0.45, min(1.85, 1.0 + (0.75 - stamina) * 1.6))


def fatigue_factor(player: Player) -> float:
    minutes = player.minutes / 60
    stint = getattr(player, "current_stint", 0) / 60
    stint_drag = 0.0
    if stint > 9:
        stint_drag = min(0.04, (stint - 9) * 0.004)
    if minutes <= 36:
        base = 1.0
    elif minutes <= 42:
        base = max(0.97, 1.0 - (minutes - 36) * 0.004)
    else:
        base = max(0.94, 0.976 - (minutes - 42) * 0.006)
    drag = (1.0 - base + stint_drag) * stamina_fatigue_multiplier(player)
    return max(0.85, 1.0 - drag)


def fatigue_offense_factor(player: Player) -> float:
    minutes = player.minutes / 60
    stint = getattr(player, "current_stint", 0) / 60
    stint_drag = 0.0
    if stint > 9:
        stint_drag = min(0.05, (stint - 9) * 0.005)
    if minutes <= 38:
        base = 1.0
    elif minutes <= 44:
        base = max(0.97, 1.0 - (minutes - 38) * 0.004)
    else:
        base = max(0.94, 0.976 - (minutes - 44) * 0.006)
    drag = (1.0 - base + stint_drag) * stamina_fatigue_multiplier(player)
    return max(0.85, 1.0 - drag)


def effective_speed(player: Player) -> float:
    return player.speed * fatigue_factor(player)


def fatigue_touch_multiplier(player: Player) -> float:
    fatigue = fatigue_offense_factor(player)
    if fatigue >= 0.98:
        return 1.0
    star_resistance = 0.35 if player.usage >= 0.30 or player.clutchness >= 0.88 else 0.0
    penalty = (1.0 - fatigue) * (1.0 - star_resistance)
    return max(0.90, 1.0 - penalty * 0.55)


def effective_perimeter_def(defender: Player) -> float:
    return defender.perimeter_def * foul_trouble_defense_factor(defender) * fatigue_factor(defender)


def effective_interior_def(defender: Player) -> float:
    base = defender.interior_def
    high_end_bonus = max(0.0, base - 0.72) * 0.55 + max(0.0, base - 0.88) * 0.35
    boosted = min(1.12, base + high_end_bonus)
    return boosted * foul_trouble_defense_factor(defender) * fatigue_factor(defender)


def defensive_matchup_score(defender: Player, offensive_player: Player) -> float:
    size_fit = 0.08 * height_advantage(defender, offensive_player)
    off_pos = offensive_player.position.upper()
    caution = foul_trouble_defense_factor(defender)
    if off_pos in ("PG", "SG"):
        score = 0.85 * effective_perimeter_def(defender) + 0.15 * effective_interior_def(defender)
    elif off_pos == "SF":
        score = 0.6 * effective_perimeter_def(defender) + 0.4 * effective_interior_def(defender)
    else:
        score = 0.25 * effective_perimeter_def(defender) + 0.75 * effective_interior_def(defender)

    if "lockdown" in defender.badges:
        score += 0.05 * caution
    if defender.pf >= 4:
        score -= 0.06
    return score + size_fit


def build_defensive_matchups(off: Team, dff: Team) -> Dict[Player, Player]:
    """
    1-on-1 defensive matchups with hard role constraints.
    PF/C defenders never guard guards; perimeter stoppers get the best creator,
    and interior stoppers get the best forward/big rim pressure.
    """
    mapping: Dict[Player, Player] = {}
    used_defenders: set[Player] = set()

    def primary_position(player: Player) -> str:
        return player.position.upper()

    def is_guard(player: Player) -> bool:
        return primary_position(player) in ("PG", "SG")

    def is_forward(player: Player) -> bool:
        return primary_position(player) in ("SF", "PF")

    def is_big(player: Player) -> bool:
        return primary_position(player) == "C"

    def defender_can_guard(defender: Player, offensive_player: Player) -> bool:
        # Bigs and power forwards should never be assigned to guards.
        if primary_position(defender) in ("PF", "C") and is_guard(offensive_player):
            return False

        # Centers stay on true frontcourt assignments only.
        if primary_position(defender) == "C":
            return primary_position(offensive_player) in ("PF", "C")

        # Guards take guards and wings, not PF/C.
        if is_guard(defender):
            return is_guard(offensive_player) or primary_position(offensive_player) == "SF"

        # Small forwards are the flexible bridge position.
        if primary_position(defender) == "SF":
            return True

        # Power forwards can guard wings, fours, and centers.
        return is_forward(offensive_player) or is_big(offensive_player)

    def perimeter_threat_score(player: Player) -> float:
        return (
            0.38 * player.three_rating
            + 0.30 * player.playmaking
            + 0.22 * player.ball_handle
            + 0.20 * player.usage
            + 0.12 * player.three_tendency
        )

    def interior_threat_score(player: Player) -> float:
        rim_role = 1.0 if is_big(player) else (0.82 if primary_position(player) == "PF" else 0.48)
        return (
            rim_role * (
                0.34 * player.rim_rating
                + 0.24 * player.dunk_rating
                + 0.22 * player.post_tendency
                + 0.10 * player.drive_tendency
            )
            + 0.18 * player.usage
            + max(0, player.height - 78) * 0.012
        )

    def perimeter_defender_score(defender: Player, offensive_player: Player) -> float:
        return (
            0.80 * effective_perimeter_def(defender)
            + 0.12 * effective_interior_def(defender)
            + 0.06 * defender.steal
            + (0.05 if is_defensive_role_player(defender) else 0.0)
            + 0.06 * height_advantage(defender, offensive_player)
        )

    def interior_defender_score(defender: Player, offensive_player: Player) -> float:
        return (
            0.72 * effective_interior_def(defender)
            + 0.12 * effective_perimeter_def(defender)
            + 0.12 * defender.block
            + 0.08 * height_advantage(defender, offensive_player)
        )

    def preferred_candidates(candidates: List[Player], offensive_player: Player, prefer: str) -> List[Player]:
        if prefer == "guard":
            guards = [d for d in candidates if is_guard(d)]
            if guards:
                return guards
        if prefer == "wing":
            wings = [
                d for d in candidates
                if primary_position(d) in ("SG", "SF", "PF")
            ]
            if wings:
                return wings
        if prefer == "interior":
            bigs = [
                d for d in candidates
                if primary_position(d) in ("PF", "C")
            ]
            if bigs:
                return bigs
        return candidates

    def assign(offensive_player: Player, prefer: str = "balanced") -> bool:
        if offensive_player in mapping:
            return False
        candidates = [
            d for d in dff.on_floor
            if d not in used_defenders and not d.fouled_out and defender_can_guard(d, offensive_player)
        ]
        if not candidates:
            candidates = [
                d for d in dff.on_floor
                if d not in used_defenders and not d.fouled_out
                and not (primary_position(d) in ("PF", "C") and is_guard(offensive_player))
                and not (is_guard(d) and (primary_position(offensive_player) in ("PF", "C")))
                and not (primary_position(d) == "C" and primary_position(offensive_player) == "SF")
            ]
        if not candidates:
            candidates = [
                d for d in dff.on_floor
                if d not in used_defenders and not d.fouled_out
                and not (primary_position(d) == "C" and primary_position(offensive_player) == "SF")
                and not (is_guard(d) and primary_position(offensive_player) in ("PF", "C"))
            ]
        if not candidates:
            return False

        candidates = preferred_candidates(candidates, offensive_player, prefer)

        if prefer == "perimeter":
            defender = max(candidates, key=lambda d: perimeter_defender_score(d, offensive_player))
        elif prefer == "guard":
            defender = max(candidates, key=lambda d: perimeter_defender_score(d, offensive_player))
        elif prefer == "wing":
            defender = max(candidates, key=lambda d: 0.65 * perimeter_defender_score(d, offensive_player) + 0.35 * defensive_matchup_score(d, offensive_player))
        elif prefer == "interior":
            defender = max(candidates, key=lambda d: interior_defender_score(d, offensive_player))
        else:
            defender = max(candidates, key=lambda d: defensive_matchup_score(d, offensive_player))

        mapping[offensive_player] = defender
        used_defenders.add(defender)
        return True

    focus_name = getattr(dff, "defensive_focus", None)
    focused = next((p for p in off.on_floor if p.name == focus_name), None)
    if focused:
        focus_prefer = "interior" if (is_forward(focused) or is_big(focused)) and interior_threat_score(focused) > perimeter_threat_score(focused) else "perimeter"
        assign(focused, focus_prefer)

    wing_options = [
        p for p in off.on_floor
        if p not in mapping
        and primary_position(p) == "SF"
        and (p.usage >= 0.22 or perimeter_threat_score(p) >= 0.86)
    ]
    if wing_options:
        primary_wing = max(wing_options, key=lambda p: max(perimeter_threat_score(p), interior_threat_score(p)))
        assign(primary_wing, "wing")

    perimeter_options = [p for p in off.on_floor if p not in mapping and is_guard(p)]
    if not perimeter_options:
        perimeter_options = [p for p in off.on_floor if p not in mapping and primary_position(p) == "SF"]
    if perimeter_options:
        primary_perimeter = max(perimeter_options, key=perimeter_threat_score)
        assign(primary_perimeter, "guard" if is_guard(primary_perimeter) else "wing")

    interior_options = [p for p in off.on_floor if p not in mapping and (is_forward(p) or is_big(p))]
    if interior_options:
        primary_interior = max(interior_options, key=interior_threat_score)
        assign(primary_interior, "interior")

    remaining = sorted(
        [p for p in off.on_floor if p not in mapping],
        key=lambda p: (
            0 if primary_position(p) == "C" else (1 if primary_position(p) == "PF" else (2 if is_guard(p) else 3)),
            -max(perimeter_threat_score(p), interior_threat_score(p)),
        )
    )
    for offensive_player in remaining:
        prefer = "perimeter" if is_guard(offensive_player) or primary_position(offensive_player) == "SF" else "interior"
        assign(offensive_player, prefer)

    manual_matchups = getattr(dff, "manual_matchups", {})
    if manual_matchups:
        for off_name, def_name in manual_matchups.items():
            offensive_player = next((p for p in off.on_floor if p.name == off_name), None)
            defender = next((p for p in dff.on_floor if p.name == def_name and not p.fouled_out), None)
            if offensive_player is None or defender is None:
                continue
            if not defender_can_guard(defender, offensive_player):
                continue
            current_defender = mapping.get(offensive_player)
            if current_defender is defender:
                continue
            other_offensive_player = next(
                (o for o, d in mapping.items() if d is defender and o is not offensive_player),
                None
            )
            mapping[offensive_player] = defender
            if other_offensive_player is not None and current_defender is not None:
                mapping[other_offensive_player] = current_defender

    return mapping

def defensive_role_value(p: Player) -> float:
    return (
        0.58 * p.perimeter_def
        + 0.28 * p.interior_def
        + 0.08 * p.steal
        + 0.06 * p.block
    )


def is_defensive_role_player(p: Player) -> bool:
    return (
        p.name in ("Alex Caruso", "Marcus Smart")
        or defensive_role_value(p) >= 0.82
    )


def is_priority_reserve(player: Player, team: Team) -> bool:
    if player.name == "Shaun Livingston" and team.name in ("2016 Golden State Warriors", "2017 Golden State Warriors", "2019 Golden State Warriors"):
        return True
    if player.name == "Nicolas Claxton" and team.name == "2022 Brooklyn Nets":
        return True
    if player.name == "Naz Reid" and team.name == "2024 Minnesota Timberwolves":
        return True
    if player.name == "Dereck Lively II" and team.name == "2024 Dallas Mavericks":
        return True
    if player.name == "Dereck Lively II" and team.name == "2026 Dallas Mavericks":
        return True
    if player.name in ("Max Christie", "Dereck Lively II", "Santi Aldama", "Naji Marshall") and team.name == "2027 Dallas Mavericks":
        return True
    if player.name == "Kentavious Caldwell-Pope" and team.name == "2027 Philadelphia 76ers":
        return True
    if player.name == "Mitchell Robinson" and team.name == "2026 New York Knicks":
        return True
    if player.name == "Miles McBride" and team.name == "2026 New York Knicks":
        return True
    if player.name == "Jarred McCain" and team.name == "2026 Oklahoma City Thunder":
        return True
    if player.name == "Dylan Harper" and team.name == "2026 San Antonio Spurs":
        return True
    return False


def is_garbage_only_player(player: Player, team: Team) -> bool:
    return False


def closing_lineup_score(p: Player) -> float:
    role_bonus = 0.075 if is_defensive_role_player(p) else 0.0
    return (
        overall_rating(p)
        + role_bonus
        + 0.045 * defensive_role_value(p)
        + 0.025 * p.clutchness
    )


def closing_lineup_score_for_team(team: Team, p: Player) -> float:
    score = closing_lineup_score(p)
    if is_priority_reserve(p, team):
        score += 0.10
    if not is_superstar(p, team):
        remaining = target_minutes(p, team) - p.minutes / 60
        if remaining <= -1:
            score -= 0.09
        elif remaining >= 2:
            score += min(0.06, remaining * 0.012)
    return score


def mandatory_closers(team: Team) -> Tuple[str, ...]:
    if team.name == "2016 Golden State Warriors":
        return ("Stephen Curry", "Klay Thompson", "Draymond Green")
    if team.name == "2017 Golden State Warriors":
        return ("Stephen Curry", "Klay Thompson", "Kevin Durant", "Draymond Green")
    if team.name == "2019 Golden State Warriors":
        return ("Stephen Curry", "Klay Thompson", "Draymond Green")
    if team.name == "2021 Brooklyn Nets":
        return ("Kevin Durant", "Kyrie Irving", "James Harden")
    if team.name == "2026 San Antonio Spurs":
        return ("Victor Wembanyama", "De'Aaron Fox", "Stephon Castle", "Devin Vassell", "Julian Champagnie")
    if team.name == "2027 Philadelphia 76ers":
        return ("Tyrese Maxey", "Jaylen Brown", "LeBron James", "Joel Embiid")
    if team.name == "2018 Boston Celtics":
        return ("Kyrie Irving", "Jayson Tatum", "Jaylen Brown", "Al Horford")
    if team.name == "2018 New Orleans Pelicans":
        return ("Anthony Davis", "DeMarcus Cousins", "Jrue Holiday")
    if team.name == "2024 Dallas Mavericks":
        return ("Luka Doncic", "Kyrie Irving")
    return tuple()


def overall_rating(p: Player) -> float:
    scoring = (p.three_rating + p.mid_rating + p.rim_rating + p.dunk_rating) / 4.0
    interior_pf_bonus = 0.0
    if can_play_position(p, "PF") and p.position != "C":
        interior_pf_score = (
            0.32 * p.rim_rating
            + 0.22 * p.dunk_rating
            + 0.20 * p.interior_def
            + 0.12 * (0.45 * p.oreb + 0.55 * p.dreb)
            + 0.08 * p.block
            + 0.06 * p.clutchness
        )
        if p.three_rating < 0.72 and interior_pf_score >= 0.88:
            interior_pf_bonus = 0.018
        elif p.three_rating < 0.78 and interior_pf_score >= 0.84:
            interior_pf_bonus = 0.011
        elif p.three_rating < 0.82 and interior_pf_score >= 0.80:
            interior_pf_bonus = 0.006
    defense = (
        0.36 * p.perimeter_def
        + 0.34 * p.interior_def
        + 0.12 * p.steal
        + 0.10 * p.block
        + 0.04 * p.oreb
        + 0.04 * p.dreb
    )
    defensive_bonus = max(0.0, defensive_role_value(p) - 0.72) * 0.16
    rebounding_bonus = max(0.0, (0.45 * p.oreb + 0.55 * p.dreb) - 0.76) * 0.06
    return 0.38 * scoring + 0.18 * p.ft_rating + 0.19 * p.playmaking + 0.14 * defense + 0.11 * p.usage + defensive_bonus + rebounding_bonus + interior_pf_bonus
def get_rotation_tiers(team: Team):
    """
    Returns (elite, starters, bench)
    """
    sorted_players = sorted(team.roster, key=overall_rating, reverse=True)
    elite = set(sorted_players[:3])       # only THESE can hit 42–45
    starters = set(sorted_players[:5])    # normal starters
    bench = set(sorted_players[5:])
    return elite, starters, bench
def block_out_of_bounds_chance(shot_type: str) -> float:
    if shot_type in ("rim", "dunk"):
        return 0.28
    if is_post_family_shot(shot_type):
        return 0.22
    return 0.16


def get_star_players(team: Team, num: int = 3) -> List[Player]:
    sorted_players = sorted(team.roster, key=overall_rating, reverse=True)
    return sorted_players[:min(num, len(sorted_players))]


def rotation_star_players(team: Team) -> List[Player]:
    ranked = sorted([p for p in team.roster if not p.fouled_out], key=overall_rating, reverse=True)
    stars = ranked[:2]
    required_names = set(mandatory_closers(team))
    for p in ranked:
        if p.name in required_names and p not in stars:
            stars.append(p)
    if len(ranked) > 2:
        third = ranked[2]
        if third.usage >= 0.28 or overall_rating(third) >= 0.76:
            stars.append(third)
    for p in ranked[2:]:
        guard_closer = (
            can_play_position(p, "PG") or can_play_position(p, "SG")
        ) and p.usage >= 0.28 and p.clutchness >= 0.84 and p.shot_tendency >= 0.40
        if guard_closer and p not in stars:
            stars.append(p)
        if len(stars) >= 4:
            break
    return stars


