def coach_rotation_profile(team: Team) -> str:
    if is_olympic_team(team):
        return "deep national team"
    depth = getattr(team, "coach_style", {}).get("rotation_depth", 8)
    if depth >= 10:
        return "deep rotation"
    if any(p.usage >= 0.34 for p in team.roster):
        return "star-heavy playoff"
    if sum(1 for p in team.roster[:8] if p.perimeter_def + p.interior_def >= 1.45) >= 3:
        return "defense-first"
    return "balanced rotation"


def apply_rotation_profile(team: Team):
    profile = coach_rotation_profile(team)
    team.rotation_profile = profile
    style = getattr(team, "coach_style", {})
    if profile == "deep national team":
        style["rotation_depth"] = max(style.get("rotation_depth", 8), 10)
        style["ball_movement"] = max(style.get("ball_movement", 1.0), 1.28)
        style["heliocentric"] = min(style.get("heliocentric", 0.50), 0.48)
        style["pace"] = min(style.get("pace", 1.0), 1.00)
    elif profile == "deep rotation":
        style["rotation_depth"] = max(style.get("rotation_depth", 8), 10)
    elif profile == "star-heavy playoff":
        style["rotation_depth"] = min(style.get("rotation_depth", 8), 8)
    team.coach_style = style


def apply_international_chemistry(team: Team):
    if not is_olympic_team(team):
        team.international_chemistry = 0.0
        return
    continuity_map = {
        "2024 Olympic Germany": 0.12,
        "2024 Olympic Serbia": 0.10,
        "2024 Olympic France": 0.08,
        "2024 Olympic Australia": 0.08,
        "2024 Olympic Spain": 0.07,
        "2024 Olympic Canada": 0.05,
        "2024 Olympic USA": 0.04,
        "2024 Olympic Greece": 0.06,
        "2024 Olympic Brazil": 0.06,
        "2024 Olympic Japan": 0.06,
        "2024 Olympic South Sudan": 0.05,
        "2024 Olympic Puerto Rico": 0.06,
    }
    bonus = continuity_map.get(team.name, 0.05)
    team.international_chemistry = bonus
    team.coach_style["ball_movement"] = max(team.coach_style.get("ball_movement", 1.0), 1.12 + bonus)
    team.coach_style["coach_iq"] = min(0.94, team.coach_style.get("coach_iq", 0.68) + bonus * 0.35)
    team.coach_style["turnover_control"] = min(1.18, team.coach_style.get("turnover_control", 1.0) + bonus)


def tournament_game_score(team: Team) -> float:
    return team.score + getattr(team, "team_ast", 0) * 0.7 + getattr(team, "team_reb", 0) * 0.35 + getattr(team, "team_stl", 0) * 1.4 + getattr(team, "team_blk", 0) * 1.2

