def clutch_multiplier(player: Player, team: Team, opponent: Team, period: int, period_time: int) -> float:
    margin = team.score - opponent.score
    fourth_quarter = period >= 4
    late_game = fourth_quarter and period_time <= 6 * 60
    final_minutes = fourth_quarter and period_time <= 2 * 60
    trailing = margin < 0

    if not fourth_quarter:
        return 1.0

    if trailing:
        pressure = min(1.0, abs(margin) / 12)
        if late_game:
            pressure *= 1.25
        if final_minutes:
            pressure *= 1.20

        # Clutchness is centered around 0.55: great closers lift under pressure,
        # low-clutch players can tighten up instead of receiving a free boost.
        clutch_delta = player.clutchness - 0.55
        rating_effect = 0.055 + clutch_delta * 0.50 + badge_tier(player, "clutch") * 0.060
        return max(0.90, min(1.45, 1.0 + pressure * rating_effect))

    close_game = abs(margin) <= 5 and late_game
    if close_game:
        clutch_delta = player.clutchness - 0.55
        badge_effect = badge_tier(player, "clutch") * 0.040
        return max(0.96, min(1.25, 1.0 + clutch_delta * 0.13 + badge_effect))

    return 1.0


def effective_tendency(base_tendency: float, player: Player, team: Team,
                       opponent: Team, period: int, period_time: int) -> float:
    if base_tendency <= 0:
        return 0.0

    series_boost = series_pressure_bonus(player, team, opponent) * 0.45
    return min(1.0, base_tendency * (clutch_multiplier(player, team, opponent, period, period_time) + series_boost))


def three_attempt_tendency_curve(tendency: float) -> float:
    """Turn linear 3PT tendency into a smooth, stronger attempt-volume curve."""
    tendency = max(0.0, min(1.0, float(tendency)))
    if tendency <= 0.0 or tendency >= 1.0:
        return tendency
    exponent = 1.80
    high = tendency ** exponent
    low = (1.0 - tendency) ** exponent
    return high / max(1e-9, high + low)


def effective_rating(base_rating: float, player: Player, team: Team,
                     opponent: Team, period: int, period_time: int) -> float:
    momentum_boost = getattr(team, "momentum", 0.0) * 0.006
    clutch_boost = clutch_multiplier(player, team, opponent, period, period_time) - 1.0
    series_boost = series_pressure_bonus(player, team, opponent)
    fatigue_drag = max(0.0, (player.minutes / 60 - 40) * 0.002) * stamina_fatigue_multiplier(player)
    home_boost = 0.012 if getattr(team, "home_team", False) else 0.0

    if is_superstar(player, team):
        fatigue_drag *= 0.30

    if getattr(player, "injury_limited", False):
        fatigue_drag += 0.035

    return min(1.0, base_rating * (1.0 + momentum_boost + clutch_boost + series_boost + home_boost - fatigue_drag))


def effective_ft_rating(player: Player, team: Team, opponent: Team,
                        period: int, period_time: int) -> float:
    rating = player.ft_rating
    rating *= 1.0 + series_pressure_bonus(player, team, opponent) * 0.55
    if period >= 4 and team.score < opponent.score:
        pressure = min(1.0, abs(team.score - opponent.score) / 10)
        if period_time <= 2 * 60:
            pressure *= 1.25
        clutch_delta = player.clutchness - 0.55
        rating *= 1.0 + pressure * (clutch_delta * 0.16 + badge_tier(player, "clutch") * 0.032)
    elif period >= 4 and period_time <= 2 * 60 and abs(team.score - opponent.score) <= 5:
        rating *= 1.0 + (player.clutchness - 0.55) * 0.05 + badge_tier(player, "clutch") * 0.024
    return max(0.35, min(0.97, rating))


def is_blowout(teamA: Team, teamB: Team, period: int, period_time: int) -> bool:
    margin = abs(teamA.score - teamB.score)

    if period >= 4:
        if period_time <= 6 * 60 and margin >= 20:
            return True
        if period_time <= 9 * 60 and margin >= 26:
            return True

    if period == 3 and period_time <= 3 * 60 and margin >= 30:
        return True

    return False


def force_garbage_time_lineup(team: Team):
    available = [p for p in team.roster if not p.fouled_out]
    if len(available) <= 5:
        team.on_floor = available[:5]
    else:
        team.on_floor = sorted(
            available,
            key=lambda p: (
                is_superstar(p, team),
                overall_rating(p),
                p.minutes
            )
        )[:5]

    team.bench = [p for p in team.roster if not identity_contains(team.on_floor, p)]
    balance_lineup_positions(team)
    team.garbage_time_pending = False
    team.garbage_time_locked = True


def enter_garbage_time(teamA: Team, teamB: Team, period: int, period_time: int):
    force_garbage_time_lineup(teamA)
    force_garbage_time_lineup(teamB)
    print_scoreboard(period, period_time, teamA, teamB)
    print("Both teams empty the bench for garbage time. Rotations are locked from here.")
    names_a = ", ".join(p.name for p in teamA.on_floor)
    names_b = ", ".join(p.name for p in teamB.on_floor)
    print(f"{teamA.name}: {names_a}")
    print(f"{teamB.name}: {names_b}")
    time.sleep(SLEEP * 0.8)


def force_mandatory_closer_lineup(team: Team, period: int):
    closer_names = set(mandatory_closers(team))
    if not closer_names or getattr(team, "garbage_time_locked", False):
        return
    protected = getattr(team, "free_throw_shooter", None)
    available = [
        p for p in team.roster
        if not p.fouled_out
        and not is_foul_rest_locked(p, period)
        and not is_garbage_only_player(p, team)
    ]
    if len(available) < 5:
        available = [p for p in team.roster if not p.fouled_out]

    desired = [p for p in available if p.name in closer_names]
    desired.extend(
        p for p in sorted(available, key=lambda p: closing_lineup_score_for_team(team, p), reverse=True)
        if p not in desired
    )
    if protected in available and protected not in desired[:5]:
        desired = [protected] + [p for p in desired if p is not protected]
    team.on_floor = desired[:5]
    team.bench = [p for p in team.roster if p not in team.on_floor and not p.fouled_out]
    balance_lineup_positions(team)


def maybe_enter_garbage_time(teamA: Team, teamB: Team, period: int, period_time: int,
                             allow_timeout: bool = False) -> bool:
    if getattr(teamA, "garbage_time_locked", False) and getattr(teamB, "garbage_time_locked", False):
        return True

    if not is_blowout(teamA, teamB, period, period_time):
        return False

    # Some playoff teams keep their core stars on the floor longer even in
    # ugly games. Do not empty the bench too early if mandatory closers are
    # still far below their intended playoff workload.
    if period >= 4 and period_time > 3 * 60 and abs(teamA.score - teamB.score) < 40:
        for team in (teamA, teamB):
            closer_names = set(mandatory_closers(team))
            if not closer_names:
                continue
            for p in team.roster:
                if (
                    p.name in closer_names
                    and not p.fouled_out
                    and not is_foul_rest_locked(p, period)
                    and p.minutes / 60 < min(36, target_minutes(p, team) * 0.86)
                ):
                    force_mandatory_closer_lineup(team, period)
                    return False

    losing_team = teamA if teamA.score < teamB.score else teamB

    if allow_timeout and losing_team.timeouts > 0:
        losing_team.timeouts -= 1
        losing_team.timeout_cooldown = 999
        print_scoreboard(period, period_time, teamA, teamB)
        print(f"{losing_team.name} call timeout with the game out of reach. Timeouts left: {losing_team.timeouts}.")
        time.sleep(SLEEP * 0.8)
        enter_garbage_time(teamA, teamB, period, period_time)
        return True

    if not allow_timeout:
        enter_garbage_time(teamA, teamB, period, period_time)
        return True

    teamA.garbage_time_pending = True
    teamB.garbage_time_pending = True
    return False


def enforce_timeout_limits(team: Team, period: int, period_time: int):
    max_timeouts = 7
    if period == 2:
        max_timeouts = 6
    elif period == 3:
        max_timeouts = 5
    elif period >= 4:
        max_timeouts = 4
        if period_time <= 3 * 60:
            max_timeouts = 2

    if team.timeouts > max_timeouts:
        team.timeouts = max_timeouts


def timeout_management_decision(scoring_team: Team, defending_team: Team,
                                period: int, period_time: int) -> Tuple[bool, str]:
    enforce_timeout_limits(defending_team, period, period_time)

    if defending_team.timeouts <= 0:
        return False, ""

    scoring_run = getattr(scoring_team, "current_run", 0)
    scoring_momentum = getattr(scoring_team, "momentum", 0.0)
    margin = defending_team.score - scoring_team.score
    abs_margin = abs(margin)
    coach = getattr(defending_team, "coach_style", {})
    coach_iq = coach.get("coach_iq", 0.62)
    timeout_aggression = coach.get("timeout_aggression", 1.0)

    if period <= 2 and defending_team.timeouts <= 2:
        return False, ""
    if period == 3 and defending_team.timeouts <= 2 and scoring_run < 12:
        return False, ""
    if period >= 4 and period_time <= 3 * 60 and defending_team.timeouts <= 2:
        return False, ""

    if getattr(defending_team, "timeout_cooldown", 0) > 0:
        defending_team.timeout_cooldown -= 1
        if scoring_run < 10:
            return False, ""

    pressure = 0.0
    reasons = []

    if scoring_run >= 14:
        pressure += 1.25
        reasons.append(f"{scoring_run}-0 run")
    elif scoring_run >= 10:
        pressure += 0.92
        reasons.append(f"{scoring_run}-0 run")
    elif scoring_run >= 8 and period >= 3:
        pressure += 0.58
        reasons.append(f"{scoring_run}-0 run")

    if scoring_momentum >= 10:
        pressure += 0.38
        reasons.append("momentum swing")
    elif scoring_momentum >= 7:
        pressure += 0.24

    if margin < 0:
        if abs_margin >= 12:
            pressure += 0.32
            reasons.append("game slipping")
        elif abs_margin >= 6 and period >= 3:
            pressure += 0.26
            reasons.append("lead building")
    else:
        if scoring_run >= 8 and margin <= 4:
            pressure += 0.52
            reasons.append("lead nearly gone")
        elif scoring_run >= 10 and margin <= 8:
            pressure += 0.34
            reasons.append("lead shrinking")

    if period >= 4:
        if period_time <= 6 * 60 and abs_margin <= 10 and scoring_run >= 6:
            pressure += 0.45
            reasons.append("late-game control")
        elif period_time > 8 * 60 and scoring_run >= 8:
            pressure += 0.24
    elif period == 3 and period_time <= 5 * 60 and scoring_run >= 8:
        pressure += 0.20
    elif period <= 2 and scoring_run < 10:
        pressure -= 0.18

    tired_core = [
        p for p in defending_team.on_floor
        if is_superstar(p, defending_team) and p.minutes / 60 >= target_minutes(p, defending_team) * 0.72
    ]
    if tired_core and scoring_run >= 6:
        pressure += 0.22
        reasons.append("star rest reset")

    timeout_bank = defending_team.timeouts
    if timeout_bank >= 5:
        pressure += 0.16
    elif timeout_bank <= 2:
        pressure -= 0.38
    elif timeout_bank == 3 and period < 4:
        pressure -= 0.18

    pressure *= timeout_aggression
    pressure += (coach_iq - 0.62) * 0.18

    threshold = 1.0
    if period >= 4 and period_time <= 6 * 60:
        threshold = 0.88
    elif period <= 2:
        threshold = 1.10

    if pressure >= threshold:
        if not reasons:
            reasons.append("settle the game")
        return True, reasons[0]

    return False, ""


def offer_fantasy_timeout_defensive_config(team: Team, opponent: Team, teamA: Team, teamB: Team):
    if not is_user_controlled_team(team) or SIM_FAST_FORWARD:
        return
    if not SIM_CONTEXT.get("fantasy_control_enabled"):
        return
    was_enabled = SIM_CONTROL_ENABLED
    if was_enabled:
        disable_keyboard_controls()
    try:
        if input("Use this timeout to change offensive sets? Enter y or press Enter: ").strip().lower() in ("y", "yes"):
            configure_offensive_set_menu(team)
        if input("Use this timeout to make defensive adjustments? Enter y or press Enter: ").strip().lower() in ("y", "yes"):
            configure_defensive_scheme_menu(team)
            configure_player_defensive_customization(team, opponent)
    finally:
        if was_enabled:
            enable_keyboard_controls(teamA, teamB)


def maybe_call_timeout_after_score(scoring_team: Team, defending_team: Team,
                                   period: int, period_time: int, teamA: Team, teamB: Team):

    enforce_timeout_limits(scoring_team, period, period_time)
    enforce_timeout_limits(defending_team, period, period_time)

    if maybe_enter_garbage_time(teamA, teamB, period, period_time, allow_timeout=True):
        return

    should_timeout, timeout_reason = timeout_management_decision(scoring_team, defending_team, period, period_time)

    if should_timeout:
        scoring_run = getattr(scoring_team, "current_run", 0)
        defending_team.timeouts -= 1
        defending_team.timeout_cooldown = 6 if period < 4 else 4
        scoring_team.current_run = 0
        defending_team.current_run = 0

        if timeout_reason in ("lead nearly gone", "lead shrinking"):
            scoring_team.momentum = 0.0
            defending_team.momentum = 1.5
        else:
            scoring_team.momentum *= 0.45
            defending_team.momentum = min(3.0, getattr(defending_team, "momentum", 0.0) + 3.0)

        styles = getattr(defending_team, "coach_style", {})
        coach_iq = styles.get("coach_iq", 0.62)
        scoring_threats = [
            p for p in scoring_team.on_floor
            if p.pts >= 12 or getattr(p, "hot_streak", 0) >= 2 or p.usage >= 0.30
        ]
        if scoring_threats and random.random() < min(0.90, 0.28 + coach_iq * 0.55):
            focus = max(
                scoring_threats,
                key=lambda p: p.pts + getattr(p, "hot_streak", 0) * 5 + p.usage * 18
            )
            defending_team.defensive_focus = focus.name

        weak_links = [
            p for p in defending_team.on_floor
            if not p.fouled_out and (0.55 * p.perimeter_def + 0.45 * p.interior_def) <= 0.62
        ]
        if weak_links and random.random() < min(0.78, 0.25 + coach_iq * 0.38):
            target = min(weak_links, key=lambda p: 0.55 * p.perimeter_def + 0.45 * p.interior_def)
            scoring_team.offensive_hunt_target = target.name

        print_scoreboard(period, period_time, teamA, teamB)
        if scoring_run >= 8:
            print(f"{scoring_team.name} are on a {scoring_run}-0 run.")
        if timeout_reason:
            print(commentator_timeout(defending_team.name, defending_team.timeouts) + f" The issue: {timeout_reason}.")
        else:
            print(commentator_timeout(defending_team.name, defending_team.timeouts))
        focus_name = getattr(defending_team, "defensive_focus", None)
        # defensive_focus is sticky once set (by this function or by
        # maybe_defensive_adjustment) and nothing clears it when that player
        # gets subbed out. Without this check, a timeout well after the
        # target left the game would still call out a player who isn't even
        # on the floor. Only announce it while he's actually out there.
        if focus_name and any(p.name == focus_name for p in scoring_team.on_floor):
            print(f"{defending_team.name} use the timeout to shade extra help toward {focus_name}.")
        if getattr(scoring_team, "offensive_hunt_target", None):
            print(f"{scoring_team.name} come out looking to involve {scoring_team.offensive_hunt_target} in the next actions.")
        if can_advance_after_timeout(period, period_time):
            defending_team.ato_pending = True
            defending_team.inbound_pending = True
            print(f"{defending_team.name} advance the ball for a frontcourt inbound.")
        else:
            defending_team.ato_pending = False
            defending_team.inbound_pending = False
        time.sleep(SLEEP * 0.9)
        offer_fantasy_timeout_defensive_config(defending_team, scoring_team, teamA, teamB)

        if should_close_game(teamA, teamB, period, period_time):
            if auto_subs_allowed(defending_team):
                force_starter_lineup(defending_team)
            if auto_subs_allowed(scoring_team):
                force_starter_lineup(scoring_team)
        else:
            dead_ball_rotation(defending_team, period, period_time, reason="timeout", max_subs=3)
            dead_ball_rotation(scoring_team, period, period_time, reason="timeout", max_subs=3)


def lineup_key(team: Team) -> Tuple[str, ...]:
    players = list(getattr(team, "on_floor", []) or [])[:5]
    try:
        players = balanced_lineup_order(players)
    except Exception:
        pass
    return tuple(p.name for p in players)


def ensure_lineup_row(team: Team) -> Dict:
    if not hasattr(team, "lineup_plus_minus") or team.lineup_plus_minus is None:
        team.lineup_plus_minus = {}
    key = lineup_key(team)
    return team.lineup_plus_minus.setdefault(key, {"minutes": 0, "plus_minus": 0, "pts_for": 0, "pts_against": 0})


def record_lineup_plus_minus(scoring_team: Team, defending_team: Team, points: int):
    if len(getattr(scoring_team, "on_floor", []) or []) >= 5:
        row = ensure_lineup_row(scoring_team)
        row["plus_minus"] += points
        row["pts_for"] += points
    if len(getattr(defending_team, "on_floor", []) or []) >= 5:
        row = ensure_lineup_row(defending_team)
        row["plus_minus"] -= points
        row["pts_against"] += points


def record_lineup_minutes(team: Team, seconds: int):
    if seconds <= 0 or len(getattr(team, "on_floor", []) or []) < 5:
        return
    row = ensure_lineup_row(team)
    row["minutes"] += seconds


def record_score_event(scoring_team: Team, defending_team: Team, points: int,
                       period: int, period_time: int, teamA: Team, teamB: Team,
                       check_timeout: bool = True):
    scoring_team.current_run = getattr(scoring_team, "current_run", 0) + points
    defending_team.current_run = 0
    defending_team.last_announced_run = 0
    scoring_team.biggest_run = max(getattr(scoring_team, "biggest_run", 0), scoring_team.current_run)
    if scoring_team.current_run >= 10:
        scoring_team.last_turning_point = f"{scoring_team.name} built a {scoring_team.current_run}-0 run in the {period_label(period)}."

    for p in scoring_team.on_floor:
        p.plus_minus += points
    for p in defending_team.on_floor:
        p.plus_minus -= points
    record_lineup_plus_minus(scoring_team, defending_team, points)

    scoring_team.momentum = min(12.0, getattr(scoring_team, "momentum", 0.0) + points * 0.8)
    defending_team.momentum = max(-6.0, getattr(defending_team, "momentum", 0.0) - points * 0.5)

    if check_timeout:
        maybe_call_timeout_after_score(scoring_team, defending_team, period, period_time, teamA, teamB)


def is_superstar(player: Player, team: Team) -> bool:
    ranked = sorted(team.roster, key=overall_rating, reverse=True)
    return player in ranked[:2] or player.usage >= 0.30


def force_best_available_lineup(team: Team):
    if getattr(team, "garbage_time_locked", False):
        return

    current_period = getattr(team, "current_period", 0)
    available = [
        p for p in team.roster
        if not p.fouled_out
        and not is_foul_rest_locked(p, current_period)
        and not is_garbage_only_player(p, team)
    ]
    if len(available) < 5:
        available = [p for p in team.roster if not p.fouled_out and not is_garbage_only_player(p, team)]
    if len(available) < 5:
        available = [p for p in team.roster if not p.fouled_out]
    team.on_floor = sorted(
        available,
        key=lambda p: (
            is_superstar(p, team),
            overall_rating(p),
            p.usage,
            p.clutchness
        ),
        reverse=True
    )[:5]
    team.bench = [p for p in team.roster if p not in team.on_floor]
    balance_lineup_positions(team)


def target_minutes(player: Player, team: Team) -> int:
    if not hasattr(player, "target_minutes"):
        initialize_minute_targets(team)
    return player.target_minutes


def foul_rest_until_period(player: Player, period: int) -> int | None:
    if period == 1 and player.pf >= 2:
        return 2
    if period == 2 and player.pf >= 4:
        return 3
    if period == 3 and player.pf >= 5:
        return 4
    return None


def is_foul_rest_locked(player: Player, period: int) -> bool:
    return getattr(player, "foul_rest_until", 0) > period


def starter_minute_need(player: Player, team: Team) -> float:
    if not getattr(player, "is_starter", False):
        return -999.0
    return target_minutes(player, team) - player.minutes / 60


def period_length_seconds(period: int) -> int:
    return rules_quarter_seconds() if period <= 4 else rules_ot_seconds()


def should_rest_for_stint(player: Player, team: Team, period: int, period_time: int, stars: set[Player]) -> bool:
    if player.fouled_out:
        return False

    elapsed_period_minutes = (period_length_seconds(period) - period_time) / 60
    played_minutes = player.minutes / 60

    if player in stars:
        target = target_minutes(player, team)
        if period < 4:
            return elapsed_period_minutes >= 8.0 and played_minutes >= target * 0.72
        if period >= 4 and period_time > 6 * 60:
            return played_minutes >= target and elapsed_period_minutes >= 5.0
        return False

    if getattr(player, "is_starter", False):
        if played_minutes >= target_minutes(player, team):
            return True
        if period in (1, 3) and elapsed_period_minutes >= 6.5 and played_minutes >= 6.5:
            return True
        if period in (2, 4) and elapsed_period_minutes >= 5.5 and played_minutes >= 5.5:
            return True
        return False

    if played_minutes >= target_minutes(player, team):
        return True
    if is_priority_reserve(player, team):
        return elapsed_period_minutes >= 8.0 and played_minutes >= 8.0
    return elapsed_period_minutes >= 5.0 and played_minutes >= 5.0


def is_rotation_window_candidate(player: Player, team: Team, period: int, period_time: int) -> bool:
    if player.fouled_out or is_foul_rest_locked(player, period):
        return False
    if is_garbage_only_player(player, team):
        return False
    if getattr(team, "garbage_time_locked", False):
        return True
    if player.minutes <= 0:
        target = target_minutes(player, team)
        if period >= 4:
            return False
        if period == 1:
            return target >= 18 and period_time <= 6 * 60
        if period in (2, 3):
            return target >= 8
        return False
    if period < 4:
        return True
    if getattr(player, "is_starter", False):
        return True
    if player.minutes > 0:
        return True

    # Do not let unused bench players get their whole run as 4th-quarter
    # catch-up minutes unless the game has already entered garbage time.
    return False


def should_prioritize_first_stint(player: Player, team: Team, period: int, period_time: int) -> bool:
    if player.minutes > 0:
        return False
    if is_garbage_only_player(player, team) or player.fouled_out or is_foul_rest_locked(player, period):
        return False
    target = target_minutes(player, team)
    if target < 8:
        return False
    if period == 1:
        return target >= 18 and period_time <= 6 * 60
    if period == 2:
        return True
    if period == 3:
        return target >= 10
    return getattr(team, "garbage_time_locked", False)


def best_bench_replacement_for(team: Team, out_player: Player, excluded: set[Player] = None):
    excluded = excluded or set()
    current_period = getattr(team, "current_period", 0)
    available = [
        p for p in team.bench
        if p not in excluded
        and is_rotation_window_candidate(p, team, current_period, 0)
    ]
    starter_needs = [
        p for p in available
        if getattr(p, "is_starter", False) and starter_minute_need(p, team) >= 4
    ]
    same_pos_starter_needs = [
        p for p in starter_needs
        if (can_play_position(p, out_player.position) or can_play_position(out_player, p.position))
    ]
    if same_pos_starter_needs:
        return max(same_pos_starter_needs, key=lambda p: (starter_minute_need(p, team), overall_rating(p)))
    if starter_needs:
        return max(starter_needs, key=lambda p: (starter_minute_need(p, team), overall_rating(p)))

    same_pos = [
        p for p in available
        if (can_play_position(p, out_player.position) or can_play_position(out_player, p.position))
    ]
    priority_same_pos = [
        p for p in same_pos
        if is_priority_reserve(p, team) and p.minutes / 60 < target_minutes(p, team) - 2
    ]
    if priority_same_pos:
        return max(priority_same_pos, key=lambda p: (target_minutes(p, team) - p.minutes / 60, overall_rating(p)))
    if same_pos:
        return max(same_pos, key=overall_rating)

    if not available:
        return None

    priority_available = [
        p for p in available
        if is_priority_reserve(p, team) and p.minutes / 60 < target_minutes(p, team) - 2
    ]
    if priority_available:
        return max(priority_available, key=lambda p: (target_minutes(p, team) - p.minutes / 60, overall_rating(p)))

    return max(available, key=overall_rating)


def swap_players(team: Team, out_player: Player, sub_in: Player, label: str) -> bool:
    if out_player not in team.on_floor or sub_in not in team.bench:
        return False
    if out_player is getattr(team, "free_throw_shooter", None):
        return False

    idx = team.on_floor.index(out_player)
    team.on_floor[idx] = sub_in
    team.bench.remove(sub_in)
    team.bench.append(out_player)
    balance_lineup_positions(team)
    out_player.current_stint = 0
    sub_in.current_stint = 0
    print(commentator_sub(team.name, sub_in.name, out_player.name))
    time.sleep(SLEEP * 0.6)
    return True


def enforce_spurs_rotation_map(team: Team, period: int, period_time: int, protected: Player = None) -> bool:
    """Keep the 2026 Spurs close to their intended playoff minute ladder."""
    if team.name != "2026 San Antonio Spurs" or getattr(team, "garbage_time_locked", False):
        return False
    if period >= 4 and period_time <= 6 * 60:
        return False

    elapsed_game_minutes = max(
        0.0,
        ((period - 1) * rules_quarter_seconds() + (rules_quarter_seconds() - period_time)) / 60,
    )

    def expected_minutes_for(p: Player) -> float:
        return min(target_minutes(p, team), elapsed_game_minutes * (target_minutes(p, team) / 48.0) + 1.0)

    priority_order = {
        "Dylan Harper": 1.30,
        "Keldon Johnson": 1.16,
        "Luke Kornet": 1.08,
        "Harrison Barnes": 0.98,
        "Kelly Olynyk": 0.82,
    }

    bench_needs = []
    for p in team.bench:
        if not is_rotation_window_candidate(p, team, period, period_time):
            continue
        played = p.minutes / 60
        target = target_minutes(p, team)
        if played >= target - 0.5:
            continue
        if period == 1 and target < 16:
            continue
        expected = expected_minutes_for(p)
        harper_catchup = (
            p.name == "Dylan Harper"
            and period >= 3
            and period_time <= 9 * 60
            and played < target - 4
        )
        if played < expected - 0.4 or (period >= 2 and played <= 0 and target >= 8) or harper_catchup:
            bench_needs.append(p)

    if not bench_needs:
        return False

    sub_in = max(
        bench_needs,
        key=lambda p: (
            expected_minutes_for(p) - p.minutes / 60,
            priority_order.get(p.name, 0.65),
            target_minutes(p, team),
            overall_rating(p),
        ),
    )

    protected_names = {"Victor Wembanyama"} if period == 1 else set()
    candidates = [
        p for p in team.on_floor
        if p is not protected
        and p.name not in protected_names
        and not p.fouled_out
        and not is_foul_rest_locked(p, period)
    ]
    if not candidates:
        return False

    def give_up_score(p: Player) -> float:
        played = p.minutes / 60
        expected = expected_minutes_for(p)
        star_penalty = 0.55 if p.name in ("Victor Wembanyama", "De'Aaron Fox") else 0.0
        castle_penalty = 0.20 if p.name == "Stephon Castle" else 0.0
        return (played - expected) + (played - target_minutes(p, team)) * 0.35 - star_penalty - castle_penalty

    out_player = max(candidates, key=give_up_score)
    if give_up_score(out_player) < -1.2 and sub_in.minutes > 0:
        return False

    return swap_players(team, out_player, sub_in, " (rotation)")


def enforce_spurs_harper_minutes(team: Team, period: int, period_time: int, protected: Player = None) -> bool:
    if team.name != "2026 San Antonio Spurs" or getattr(team, "garbage_time_locked", False):
        return False
    harper = next((p for p in team.roster if p.name == "Dylan Harper" and not p.fouled_out), None)
    if harper is None or harper in team.on_floor or harper not in team.bench:
        return False
    if is_foul_rest_locked(harper, period) or not is_rotation_window_candidate(harper, team, period, period_time):
        return False

    played = harper.minutes / 60
    target = target_minutes(harper, team)
    elapsed_game_minutes = max(0.0, ((period - 1) * rules_quarter_seconds() + (rules_quarter_seconds() - period_time)) / 60)
    expected_minutes = min(target, elapsed_game_minutes * (target / 48.0) + 0.8)
    if played >= target - 0.5 or (period < 4 and played >= expected_minutes):
        return False

    give_up_names = {
        "Harrison Barnes": 1.20,
        "Kelly Olynyk": 1.18,
        "Luke Kornet": 1.12,
        "Keldon Johnson": 1.08,
        "Julian Champagnie": 0.96,
        "De'Aaron Fox": 0.92,
        "Devin Vassell": 0.90,
        "Stephon Castle": 0.72,
        "Victor Wembanyama": 0.20,
    }
    candidates = [
        p for p in team.on_floor
        if p is not protected
        and not p.fouled_out
        and not is_foul_rest_locked(p, period)
        and p.name != "Victor Wembanyama"
    ]
    if not candidates:
        return False

    def give_up_score(p: Player) -> float:
        over_target = p.minutes / 60 - target_minutes(p, team)
        pace_over = p.minutes / 60 - elapsed_game_minutes * (target_minutes(p, team) / 48.0)
        return give_up_names.get(p.name, 0.80) + over_target * 0.22 + pace_over * 0.16

    out_player = max(candidates, key=give_up_score)
    return swap_players(team, out_player, harper, " (rotation)")


def dead_ball_rotation(team: Team, period: int, period_time: int,
                       reason: str = "foul", protected: Player = None,
                       max_subs: int = 3):
    if getattr(team, "garbage_time_locked", False) or not team.bench:
        return
    if not auto_subs_allowed(team):
        return

    if not hasattr(team.roster[0], "target_minutes"):
        initialize_minute_targets(team)

    if enforce_spurs_rotation_map(team, period, period_time, protected):
        team.last_sub_period = period
        team.last_sub_time = period_time
        return

    if enforce_spurs_harper_minutes(team, period, period_time, protected):
        team.last_sub_period = period
        team.last_sub_time = period_time
        return

    if period >= 4 and period_time <= 6 * 60:
        # Close 4th: only foul trouble/foul-outs should alter the lineup.
        force_mandatory_closer_lineup(team, period)
        return

    last_period = getattr(team, "last_sub_period", None)
    last_time = getattr(team, "last_sub_time", None)
    if last_period == period and last_time is not None and (last_time - period_time) < 75:
        return

    changed = 0
    moved_out = set()
    moved_in = set()
    ranked = sorted([p for p in team.roster if not p.fouled_out], key=overall_rating, reverse=True)
    stars = set(rotation_star_players(team))

    while changed < max_subs:
        priority_bench = [
            p for p in team.bench
            if (is_priority_reserve(p, team) or should_prioritize_first_stint(p, team, period, period_time))
            and p not in moved_in
            and p not in moved_out
            and is_rotation_window_candidate(p, team, period, period_time)
            and p.minutes / 60 < target_minutes(p, team) - 2
        ]

        needed_starters_on_bench = [
            p for p in team.bench
            if getattr(p, "is_starter", False)
            and p not in moved_in
            and p not in moved_out
            and is_rotation_window_candidate(p, team, period, period_time)
            and starter_minute_need(p, team) >= 4
        ]

        candidates = [
            p for p in team.on_floor
            if p is not protected
            and p not in moved_out
            and p not in moved_in
            and should_rest_for_stint(p, team, period, period_time, stars)
            and not is_foul_rest_locked(p, period)
        ]

        if not candidates and needed_starters_on_bench:
            candidates = [
                p for p in team.on_floor
                if p is not protected
                and p not in moved_out
                and p not in moved_in
                and p not in stars
                and not p.fouled_out
                and not is_foul_rest_locked(p, period)
                and not (getattr(p, "is_starter", False) and starter_minute_need(p, team) > 0)
            ]

        if priority_bench:
            priority = max(priority_bench, key=lambda p: target_minutes(p, team) - p.minutes / 60)
            candidates = [
                p for p in team.on_floor
                if p is not protected
                and p not in moved_out
                and p not in moved_in
                and p not in stars
                and not is_foul_rest_locked(p, period)
                and not (getattr(p, "is_starter", False) and starter_minute_need(p, team) > 0)
            ]
            if candidates:
                out_player = max(candidates, key=lambda p: (p.minutes, -overall_rating(p)))
                if swap_players(team, out_player, priority, f" ({reason})"):
                    moved_out.add(out_player)
                    moved_in.add(priority)
                    changed += 1
                    continue

        if not candidates and period_time <= 6 * 60 and period < 4:
            candidates = [
                p for p in team.on_floor
                if p is not protected
                and p not in moved_out
                and p not in moved_in
                and should_rest_for_stint(p, team, period, period_time, stars)
                and not is_foul_rest_locked(p, period)
            ]

        if not candidates:
            break

        out_player = max(candidates, key=lambda p: p.minutes)
        sub_in = best_bench_replacement_for(team, out_player, excluded=moved_out | moved_in)
        if sub_in is None or sub_in in moved_in:
            break

        if not swap_players(team, out_player, sub_in, f" ({reason})"):
            break

        moved_out.add(out_player)
        moved_in.add(sub_in)
        changed += 1

    if changed:
        team.last_sub_period = period
        team.last_sub_time = period_time


def timed_rotation_sub(team: Team, period: int, period_time: int):
    """
    Normal rotation subs for role players.
    Top two stars keep their existing minute targets; this only gets bench
    players into the game earlier so non-star starters don't play giant stints.
    """
    dead_ball_rotation(team, period, period_time, reason="rotation", max_subs=2)


def auto_subs_allowed(team: Team) -> bool:
    if not is_user_controlled_team(team):
        return True
    if not SIM_CONTEXT.get("fantasy_control_enabled"):
        return True
    return SIM_FAST_FORWARD or SIM_JUMP_TARGET is not None


def set_quarter_lineup(team: Team, next_period: int):
    """
    Stagger quarter-opening lineups so bench players get real runs.
    The top two stars are handled separately from role-player depth.
    """
    if getattr(team, "garbage_time_locked", False):
        return
    if not auto_subs_allowed(team):
        return

    if not hasattr(team.roster[0], "target_minutes"):
        initialize_minute_targets(team)

    available = [
        p for p in team.roster
        if not p.fouled_out
        and not is_foul_rest_locked(p, next_period)
        and not is_garbage_only_player(p, team)
    ]
    if len(available) < 5:
        available = [p for p in team.roster if not p.fouled_out and not is_garbage_only_player(p, team)]
    if len(available) < 5:
        available = [p for p in team.roster if not p.fouled_out]
    if len(available) <= 5:
        team.on_floor = available[:5]
        team.bench = [p for p in team.roster if p not in team.on_floor]
        balance_lineup_positions(team)
        return

    if team.name == "2026 San Antonio Spurs" and next_period in (2, 3, 4):
        spurs_groups = {
            2: ["Dylan Harper", "Keldon Johnson", "Harrison Barnes", "Luke Kornet", "Stephon Castle"],
            3: ["De'Aaron Fox", "Stephon Castle", "Devin Vassell", "Julian Champagnie", "Victor Wembanyama"],
            4: ["De'Aaron Fox", "Dylan Harper", "Devin Vassell", "Julian Champagnie", "Victor Wembanyama"],
        }
        desired = []
        for name in spurs_groups[next_period]:
            p = next((player for player in available if player.name == name), None)
            if p is not None and p not in desired:
                desired.append(p)
        for p in sorted(available, key=lambda p: (p.minutes / max(1, target_minutes(p, team)), -target_minutes(p, team), -overall_rating(p))):
            if len(desired) >= 5:
                break
            if p not in desired:
                desired.append(p)
        team.on_floor = desired[:5]
        team.bench = [p for p in team.roster if p not in team.on_floor and not p.fouled_out]
        balance_lineup_positions(team)
        if next_period in (2, 4):
            names = ", ".join(p.name for p in team.on_floor)
            label = "closing group" if next_period == 4 else "staggered group"
            print(f"{team.name} open Q{next_period} with a {label}: {names}.")
            time.sleep(SLEEP * 0.6)
        return

    ranked = sorted(available, key=overall_rating, reverse=True)
    stars = [p for p in rotation_star_players(team) if p in available]
    if not stars:
        stars = ranked[:2]

    if next_period in (1, 3):
        desired = ranked[:5]
    elif next_period == 2:
        desired = [stars[0]]
    elif next_period == 4:
        fourth_available = [
            p for p in available
            if getattr(p, "is_starter", False) or p.minutes > 0
        ]
        if len(fourth_available) < 5:
            fourth_available = [
                p for p in available
                if getattr(p, "is_starter", False) or p.minutes > 0
            ]
        if len(fourth_available) < 5:
            fourth_available = ranked
        required_names = mandatory_closers(team)
        desired = [
            p for p in fourth_available
            if p.name in required_names
        ]
        desired.extend(
            p for p in sorted(fourth_available, key=lambda p: closing_lineup_score_for_team(team, p), reverse=True)
            if p not in desired
        )
        desired = desired[:5]
    else:
        desired = ranked[:5]

    if team.name == "2026 San Antonio Spurs" and next_period in (2, 4):
        harper = next((p for p in available if p.name == "Dylan Harper"), None)
        if harper is not None and harper not in desired and harper.minutes / 60 < target_minutes(harper, team) - 1:
            replaceable = [p for p in desired if p.name not in ("Victor Wembanyama", "Stephon Castle")]
            if replaceable:
                out_player = max(replaceable, key=lambda p: (p.minutes / 60 - target_minutes(p, team), p.minutes, -overall_rating(p)))
                desired = [harper if p is out_player else p for p in desired]

    used = set(desired)
    if next_period == 2:
        top_rotation = set(ranked[:6])
        top_rotation.update(p for p in available if is_priority_reserve(p, team))
        first_stint_reserves = sorted(
            [
                p for p in available
                if p not in used
                and target_minutes(p, team) >= 10
                and p.minutes <= 0
                and not is_garbage_only_player(p, team)
            ],
            key=lambda p: (target_minutes(p, team), overall_rating(p)),
            reverse=True
        )
        for p in first_stint_reserves:
            if len(desired) >= 5:
                break
            desired.append(p)
            used.add(p)

        priority_reserves = sorted(
            [
                p for p in available
                if p not in used
                and is_priority_reserve(p, team)
                and p.minutes / 60 < target_minutes(p, team) - 2
            ],
            key=lambda p: (target_minutes(p, team) - p.minutes / 60, overall_rating(p)),
            reverse=True
        )
        for p in priority_reserves:
            if len(desired) >= 5:
                break
            desired.append(p)
            used.add(p)

        starter_needs = sorted(
            [
                p for p in available
                if p not in used
                and getattr(p, "is_starter", False)
                and p.minutes / 60 < target_minutes(p, team) - 2
            ],
            key=lambda p: (can_play_position(p, "C"), starter_minute_need(p, team), overall_rating(p)),
            reverse=True
        )
        for p in starter_needs:
            if len(desired) >= 5:
                break
            desired.append(p)
            used.add(p)

        depth = sorted(
            [p for p in available if p not in used],
            key=lambda p: (
                not (getattr(p, "is_starter", False) and p.minutes / 60 < target_minutes(p, team)),
                not (p in top_rotation and p.minutes / 60 < target_minutes(p, team)),
                p.minutes / max(1, target_minutes(p, team)),
                p in stars,
                -overall_rating(p),
            )
        )
        for p in depth:
            if len(desired) >= 5:
                break
            desired.append(p)
            used.add(p)

    for p in ranked:
        if len(desired) >= 5:
            break
        if p not in used:
            desired.append(p)
            used.add(p)

    team.on_floor = desired[:5]
    team.bench = [p for p in team.roster if p not in team.on_floor and not p.fouled_out]
    balance_lineup_positions(team)

    if next_period in (2, 4):
        names = ", ".join(p.name for p in team.on_floor)
        label = "closing group" if next_period == 4 else "staggered group"
        print(f"{team.name} open Q{next_period} with a {label}: {names}.")
        time.sleep(SLEEP * 0.6)

def decide_isolation(shooter: Player) -> bool:
    """
    Returns True if player chooses to isolate instead of shooting immediately.
    High total shot tendency = less isolation.
    """
# Isolation probability driven by shot tendency
    iso_prob = max(0.10, 0.60 - shooter.shot_tendency * 0.50)


    return random.random() < iso_prob

def maybe_substitute(team: Team, reason: str, protected: Player = None,
                     period: int = None, period_time: int = None):
    if reason not in ("foul", "quarter", "timeout"):
        return

    if getattr(team, "garbage_time_locked", False):
        return

    if not hasattr(team.roster[0], "target_minutes"):
        initialize_minute_targets(team)

    if not team.bench:
        return

    ranked = sorted([p for p in team.roster if not p.fouled_out], key=overall_rating, reverse=True)
    superstar = ranked[0] if ranked else None
    second_star = ranked[1] if len(ranked) > 1 else None
    top_five = ranked[:5]

    def do_sub(out_player: Player, sub_in: Player, label: str):
        swap_players(team, out_player, sub_in, label)

    def best_bench_replacement(out_player: Player):
        return best_bench_replacement_for(team, out_player)

    def bring_in(player: Player):
        current_period = getattr(team, "current_period", 0)
        if player is None or player in team.on_floor or player.fouled_out or is_foul_rest_locked(player, current_period):
            return False

        candidates = [
            p for p in team.on_floor
            if p is not protected and p not in (superstar, second_star)
        ]

        if not candidates:
            candidates = [p for p in team.on_floor if p is not protected]

        if not candidates:
            return False

        out_player = min(candidates, key=overall_rating)
        do_sub(out_player, player, f" ({reason})")
        return True

    # Best player should never sit through a whole quarter unless fouled out.
    if superstar and superstar in team.bench and (superstar.minutes / 60) < target_minutes(superstar, team):
        bring_in(superstar)
        return

    # Keep at least one of the top two stars on the floor.
    if superstar and second_star:
        if superstar not in team.on_floor and second_star not in team.on_floor:
            bring_in(superstar)
            return

    # At quarter breaks, rebuild around starters/top players.
    if reason == "quarter":
        desired = []

        # Q1/Q3/Q4 starts: strongest available lineup.
        # Q2 can stagger, but still keeps the superstar involved.
        for p in top_five:
            if len(desired) < 5:
                desired.append(p)

        team.on_floor = desired[:5]
        team.bench = [p for p in team.roster if p not in team.on_floor and not p.fouled_out]
        balance_lineup_positions(team)
        return

    # Foul/timeout dead-ball subs: rest only players clearly over target.
    if period is not None and period_time is not None:
        dead_ball_rotation(team, period, period_time, reason=reason, protected=protected, max_subs=3)

def dead_ball_subs(teamA: Team, teamB: Team, period: int, period_time: int,
                   reason: str = "foul", protected_teamA: Player = None,
                   protected_teamB: Player = None, max_subs: int = 3):
    protected_teamA = protected_teamA or getattr(teamA, "free_throw_shooter", None)
    protected_teamB = protected_teamB or getattr(teamB, "free_throw_shooter", None)

    if getattr(teamA, "garbage_time_pending", False) or getattr(teamB, "garbage_time_pending", False):
        enter_garbage_time(teamA, teamB, period, period_time)
        return

    if maybe_enter_garbage_time(teamA, teamB, period, period_time, allow_timeout=False):
        return

    handle_manual_sub_request_if_needed()

    if should_close_game(teamA, teamB, period, period_time):
        if auto_subs_allowed(teamA):
            force_starter_lineup(teamA, protected=protected_teamA)
        if auto_subs_allowed(teamB):
            force_starter_lineup(teamB, protected=protected_teamB)
        apply_manual_substitution(teamA)
        apply_manual_substitution(teamB)
    elif should_restore_fourth_core(teamA, teamB, period, period_time):
        if auto_subs_allowed(teamA):
            force_closing_lineup(teamA, protected=protected_teamA)
        if auto_subs_allowed(teamB):
            force_closing_lineup(teamB, protected=protected_teamB)
        apply_manual_substitution(teamA)
        apply_manual_substitution(teamB)
    else:
        apply_manual_substitution(teamA)
        apply_manual_substitution(teamB)
        dead_ball_rotation(teamA, period, period_time, reason=reason, protected=protected_teamA, max_subs=max_subs)
        dead_ball_rotation(teamB, period, period_time, reason=reason, protected=protected_teamB, max_subs=max_subs)


def out_of_bounds_turnover_chance(passer: Player, receiver: Player) -> float:
    passer_security = 0.55 * passer.playmaking + 0.45 * passer.ball_handle
    pressure = 1.0 - passer_security
    return max(0.004, min(0.030, 0.006 + pressure * 0.020))


def deflection_out_of_bounds_chance(passer: Player, receiver: Player, defender: Player) -> float:
    defensive_activity = 0.4 * defender.steal + 0.4 * defender.perimeter_def
    passer_security = 0.55 * passer.playmaking + 0.45 * passer.ball_handle
    return max(0.004, min(0.035, 0.006 + defensive_activity * 0.030 - passer_security * 0.010))


def missed_shot_out_of_bounds_chance(shot_type: str) -> float:
    if shot_type == "three":
        return 0.025
    if shot_type == "mid":
        return 0.020
    return 0.015


def shot_clock_violation_chance(off: Team, dff: Team, period: int, period_time: int) -> float:
    # Rare, but a little more likely against strong defense.
    defense_pressure = sum(0.5 * p.perimeter_def + 0.5 * p.interior_def for p in dff.on_floor) / len(dff.on_floor)
    offense_creation = sum(0.5 * p.playmaking + 0.5 * p.ball_handle for p in off.on_floor) / len(off.on_floor)

    base = 0.006
    if period_time <= 24:
        return 0.0

    return max(0.002, min(0.025, base + defense_pressure * 0.018 - offense_creation * 0.012))


def describe_shot_clock_violation(off: Team, dff: Team,
                                  handler: Player,
                                  matchups: Dict[Player, Player]):
    teammates = [p for p in off.on_floor if p is not handler]
    first_receiver = random.choice(teammates) if teammates else handler
    second_receiver = random.choice([p for p in teammates if p is not first_receiver] or [handler])
    primary_defender = matchups.get(handler, random.choice(dff.on_floor))
    receiver_defender = matchups.get(first_receiver, random.choice(dff.on_floor))

    opening_lines = [
        f"{handler.name} works off the screen, but {primary_defender.name} stays attached and cuts off the angle.",
        f"{handler.name} probes above the break while {primary_defender.name} keeps him out of the lane.",
        f"{handler.name} tries to turn the corner, but {dff.name} load up on the ball.",
        f"{handler.name} backs it out with the clock running and cannot shake {primary_defender.name}.",
    ]
    middle_lines = [
        f"{handler.name} gives it up to {first_receiver.name}, and {receiver_defender.name} is already there on the catch.",
        f"{first_receiver.name} flashes to the elbow, but the passing lane closes before he can attack.",
        f"{off.name} reverse it to {first_receiver.name}, but the defense switches it cleanly.",
        f"{first_receiver.name} catches and immediately has to send it back out under pressure.",
    ]
    late_lines = [
        f"{second_receiver.name} tries to reset the action, but the spacing is jammed up.",
        f"{handler.name} calls for it again with the clock fading.",
        f"{off.name} swing it one more time, but nobody gets separation.",
        f"The possession stalls near the sideline as {dff.name} stay connected.",
    ]

    for line in (random.choice(opening_lines), random.choice(middle_lines), random.choice(late_lines)):
        print(line)
        time.sleep(SLEEP * 0.55)

def foul_out_sub(team: Team, player: Player):
    player.fouled_out = True
    same_pos_bench = [
        b for b in team.bench
        if (can_play_position(b, player.position) or can_play_position(player, b.position))
        and not b.fouled_out
    ]
    if same_pos_bench:
        sub_in = max(same_pos_bench, key=overall_rating)
        team.on_floor = [sub_in if p is player else p for p in team.on_floor]
        team.bench.remove(sub_in)
        balance_lineup_positions(team)
        print(f"{team.name}: {player.name} has fouled out. {sub_in.name} replaces him.")
        time.sleep(SLEEP * 0.8)
    else:
        print(f"{team.name}: {player.name} has fouled out. No same-position sub available.")
        time.sleep(SLEEP * 0.8)

def should_close_game(teamA: Team, teamB: Team, period: int, period_time: int) -> bool:
    return period >= 4 and period_time <= 6 * 60 and abs(teamA.score - teamB.score) <= 10


def should_restore_fourth_core(teamA: Team, teamB: Team, period: int, period_time: int) -> bool:
    return period >= 4 and period_time <= 9 * 60 and abs(teamA.score - teamB.score) <= 16


def force_starter_lineup(team: Team, protected: Player = None):
    if getattr(team, "garbage_time_locked", False):
        return
    protected = protected or getattr(team, "free_throw_shooter", None)

    available = [
        p for p in team.roster
        if not p.fouled_out and not is_garbage_only_player(p, team)
    ]
    if len(available) < 5:
        available = [p for p in team.roster if not p.fouled_out]

    starters = [p for p in available if getattr(p, "is_starter", False)]
    fill = [
        p for p in sorted(available, key=lambda p: closing_lineup_score_for_team(team, p), reverse=True)
        if not identity_contains(starters, p)
    ]

    lineup = (starters + fill)[:5]
    if protected in available and not identity_contains(lineup, protected):
        replaceable = [
            p for p in lineup
            if not getattr(p, "is_starter", False) and p.name not in mandatory_closers(team)
        ] or [p for p in lineup if p.name not in mandatory_closers(team)] or list(lineup)
        if replaceable:
            out_player = min(replaceable, key=lambda p: closing_lineup_score_for_team(team, p))
            lineup[lineup.index(out_player)] = protected
    team.on_floor = lineup
    team.bench = [p for p in team.roster if not identity_contains(team.on_floor, p)]
    balance_lineup_positions(team)


def force_closing_lineup(team: Team, protected: Player = None):
    if getattr(team, "garbage_time_locked", False):
        return
    protected = protected or getattr(team, "free_throw_shooter", None)

    current_period = getattr(team, "current_period", 0)
    available = [
        p for p in team.roster
        if not p.fouled_out
        and not is_foul_rest_locked(p, current_period)
        and not is_garbage_only_player(p, team)
    ]
    if len(available) < 5:
        available = [p for p in team.roster if not p.fouled_out and not is_garbage_only_player(p, team)]
    if len(available) < 5:
        available = [p for p in team.roster if not p.fouled_out]
    required_names = mandatory_closers(team)
    protected_players = [protected] if protected in available else []
    required = protected_players + [p for p in available if p.name in required_names and not identity_contains(protected_players, p)]
    closing_five = required + [
        p for p in sorted(available, key=lambda p: closing_lineup_score_for_team(team, p), reverse=True)
        if not identity_contains(required, p)
    ]
    closing_five = closing_five[:5]

    team.on_floor = closing_five
    team.bench = [p for p in team.roster if not identity_contains(team.on_floor, p)]
    balance_lineup_positions(team)


