def safe_pct(made: int, att: int) -> float:
    return 0.0 if att == 0 else round(100 * made / att, 1)


def record_assist(passer: Player, team: Team, points_created: int):
    passer.ast += 1
    passer.assist_pts_created = getattr(passer, "assist_pts_created", 0) + points_created
    team.team_ast += 1


PLAYER_NAME_COL_WIDTH = 20


def table_player_name(name: str, width: int = PLAYER_NAME_COL_WIDTH) -> str:
    if len(name) <= width:
        return name
    parts = name.split()
    if len(parts) > 1:
        shortened = " ".join([*(part[0] + "." for part in parts[:-1]), parts[-1]])
        if len(shortened) <= width:
            return shortened
    return name[:width - 1] + "."


POSITION_BOX_ORDER = {"PG": 0, "SG": 1, "SF": 2, "PF": 3, "C": 4}


def position_box_rank(pos: str) -> int:
    return POSITION_BOX_ORDER.get(pos.upper(), 9)


def is_final_box_score(label: str) -> bool:
    return label.strip().upper() == "FINAL"


def box_score_player_order(team: Team, final: bool = False) -> List[Player]:
    roster_index = {p: i for i, p in enumerate(team.roster)}
    if final:
        return sorted(
            team.roster,
            key=lambda p: (
                0 if getattr(p, "is_starter", False) else 1,
                -p.pts,
                -p.minutes,
                position_box_rank(p.position),
                roster_index.get(p, 99),
            )
        )

    on_floor = set(team.on_floor)
    return sorted(
        team.roster,
        key=lambda p: (
            0 if p in on_floor else 1,
            position_box_rank(p.position),
            0 if getattr(p, "is_starter", False) else 1,
            roster_index.get(p, 99),
        )
    )


def box_score_snapshot_order(players: List[Dict], final: bool = False) -> List[Dict]:
    if final:
        return sorted(
            players,
            key=lambda p: (
                0 if p.get("is_starter") else 1,
                -p.get("pts", 0),
                -p.get("minutes", 0),
                position_box_rank(p.get("position", "")),
                p.get("roster_index", 99),
            )
        )

    return sorted(
        players,
        key=lambda p: (
            0 if p.get("on_court") else 1,
            position_box_rank(p.get("position", "")),
            0 if p.get("is_starter") else 1,
            p.get("roster_index", 99),
        )
    )


def ts_percentage(player: Player) -> float:
    denom = 2 * (player.fga + 0.44 * player.fta)
    if denom == 0:
        return 0.0
    return round(100 * player.pts / denom, 1)


def accumulate_team_totals(team: Team) -> Dict[str, float]:
    tot = {
        "pts": 0, "reb": 0, "oreb": 0, "dreb": 0, "ast": 0, "stl": 0, "blk": 0, "tov": 0, "pf": 0,
        "fgm": 0, "fga": 0, "tpm": 0, "tpa": 0, "ftm": 0, "fta": 0
    }
    for p in team.roster:
        tot["pts"] += p.pts
        tot["reb"] += p.reb
        tot["oreb"] += p.oreb_stat
        tot["dreb"] += p.dreb_stat
        tot["ast"] += p.ast
        tot["stl"] += p.stl
        tot["blk"] += p.blk_stat
        tot["tov"] += p.tov
        tot["pf"] += p.pf
        tot["fgm"] += p.fgm
        tot["fga"] += p.fga
        tot["tpm"] += p.tpm
        tot["tpa"] += p.tpa
        tot["ftm"] += p.ftm
        tot["fta"] += p.fta
    return tot


def team_quarter_snapshot(team: Team) -> Dict[str, float]:
    totals = accumulate_team_totals(team)
    snap = dict(totals)
    snap["score"] = team.score
    snap["points_paint"] = getattr(team, "points_paint", 0)
    snap["fastbreak_pts"] = getattr(team, "fastbreak_pts", 0)
    snap["second_chance_pts"] = getattr(team, "second_chance_pts", 0)
    snap["fouls_drawn"] = getattr(team, "fouls_drawn", 0)
    return snap


def append_quarter_team_stats(team: Team, period: int, start_snapshot: Dict[str, float]):
    end_snapshot = team_quarter_snapshot(team)
    keys = (
        "score", "reb", "oreb", "dreb", "ast", "stl", "blk", "tov", "pf",
        "fgm", "fga", "tpm", "tpa", "ftm", "fta",
        "points_paint", "fastbreak_pts", "second_chance_pts", "fouls_drawn"
    )
    row = {"period": period}
    for key in keys:
        row[key] = end_snapshot.get(key, 0) - start_snapshot.get(key, 0)
    if not hasattr(team, "quarter_team_stats") or team.quarter_team_stats is None:
        team.quarter_team_stats = []
    team.quarter_team_stats.append(row)


def player_quarter_snapshot(team: Team) -> Dict[str, Dict[str, float]]:
    return {
        player_stat_key(team, p): {
            "minutes": p.minutes,
            "pts": p.pts,
            "reb": p.reb,
        "ast": p.ast,
        "assist_pts_created": getattr(p, "assist_pts_created", 0),
        "stl": p.stl,
            "blk": p.blk_stat,
            "tov": p.tov,
            "oreb": p.oreb_stat,
            "dreb": p.dreb_stat,
            "pf": p.pf,
            "fgm": p.fgm,
            "fga": p.fga,
            "tpm": p.tpm,
            "tpa": p.tpa,
            "ftm": p.ftm,
            "fta": p.fta,
            "plus_minus": p.plus_minus,
            "shot_diet": dict(getattr(p, "shot_diet", {}) or {}),
            "defended_diet": dict(getattr(p, "defended_diet", {}) or {}),
        }
        for p in team.roster
    }


def diet_snapshot_delta(end_diet: Dict, start_diet: Dict) -> Dict:
    delta = {}
    keys = set((end_diet or {}).keys()) | set((start_diet or {}).keys())
    for key in keys:
        end_value = (end_diet or {}).get(key, 0)
        start_value = (start_diet or {}).get(key, 0)
        if isinstance(end_value, (int, float)) and isinstance(start_value, (int, float)):
            value = end_value - start_value
            if value:
                delta[key] = value
    return delta

def diet_minus_completed(current_diet: Dict, completed_rows: List[Dict], key: str) -> Dict:
    result = dict(current_diet or {})
    for row in completed_rows:
        for diet_key, value in (row.get(key, {}) or {}).items():
            if isinstance(value, (int, float)):
                result[diet_key] = result.get(diet_key, 0) - value
    return {k: v for k, v in result.items() if v}

def append_quarter_player_stats(team: Team, period: int, start_snapshot: Dict[str, Dict[str, float]]):
    if not hasattr(team, "quarter_player_stats") or team.quarter_player_stats is None:
        team.quarter_player_stats = {}

    end_snapshot = player_quarter_snapshot(team)
    keys = (
        "minutes", "pts", "reb", "ast", "assist_pts_created", "stl", "blk", "tov", "oreb", "dreb",
        "pf", "fgm", "fga", "tpm", "tpa", "ftm", "fta", "plus_minus"
    )

    for p in team.roster:
        player_key = player_stat_key(team, p)
        start = start_snapshot.get(player_key, {})
        end = end_snapshot.get(player_key, {})
        row = {"period": period}
        for key in keys:
            row[key] = end.get(key, 0) - start.get(key, 0)
        row["shot_diet"] = diet_snapshot_delta(end.get("shot_diet", {}), start.get("shot_diet", {}))
        row["defended_diet"] = diet_snapshot_delta(end.get("defended_diet", {}), start.get("defended_diet", {}))
        team.quarter_player_stats.setdefault(player_key, []).append(row)


def compact_quarter_player_cell(rows: List[Dict[str, float]], period: int) -> str:
    row = next((r for r in rows if r.get("period") == period), None)
    if not row:
        return "0/0/0"
    return f"{int(row.get('pts', 0))}/{int(row.get('reb', 0))}/{int(row.get('ast', 0))}"


def print_quarter_player_stats_box(teamA: Team, teamB: Team, label: str = "REGULATION"):
    print("\n" + "=" * 120)
    print(f"{label} PLAYER QUARTER SPLITS")
    print("Quarter cells are PTS/REB/AST.")
    print("=" * 120)

    header = f"{'Player':<{PLAYER_NAME_COL_WIDTH}} POS ST  Q1       Q2       Q3       Q4       TOT      MIN   STL BLK TOV +/-"

    for team in (teamA, teamB):
        print(f"\n{team.name}")
        print("-" * 120)
        print(header)
        print("-" * len(header))
        quarter_stats = getattr(team, "quarter_player_stats", {})

        for p in box_score_player_order(team, final=True):
            player_key = player_stat_key(team, p)
            rows = quarter_stats.get(player_key, [])
            totals = {
                "minutes": sum(r.get("minutes", 0) for r in rows),
                "pts": sum(r.get("pts", 0) for r in rows),
                "reb": sum(r.get("reb", 0) for r in rows),
                "ast": sum(r.get("ast", 0) for r in rows),
                "stl": sum(r.get("stl", 0) for r in rows),
                "blk": sum(r.get("blk", 0) for r in rows),
                "tov": sum(r.get("tov", 0) for r in rows),
                "plus_minus": sum(r.get("plus_minus", 0) for r in rows),
            }
            if totals["minutes"] <= 0 and totals["pts"] == 0 and totals["reb"] == 0 and totals["ast"] == 0:
                continue

            display_name = table_player_name(player_key)
            starter_mark = "S" if getattr(p, "is_starter", False) else ""
            q1 = compact_quarter_player_cell(rows, 1)
            q2 = compact_quarter_player_cell(rows, 2)
            q3 = compact_quarter_player_cell(rows, 3)
            q4 = compact_quarter_player_cell(rows, 4)
            total_cell = f"{int(totals['pts'])}/{int(totals['reb'])}/{int(totals['ast'])}"

            print(
                f"{display_name:<{PLAYER_NAME_COL_WIDTH}} {p.position:<3} {starter_mark:^2} "
                f"{q1:>8} {q2:>8} {q3:>8} {q4:>8} {total_cell:>8} "
                f"{totals['minutes'] / 60:>5.1f} {int(totals['stl']):>3} {int(totals['blk']):>3} "
                f"{int(totals['tov']):>3} {int(totals['plus_minus']):>+3}"
            )

    print("=" * 120 + "\n")


def series_quarter_avg_cell(quarter_stats: Dict[int, Dict[str, float]], period: int, games: int) -> str:
    row = quarter_stats.get(period, {})
    div = max(1, games)
    return f"{row.get('pts', 0) / div:.1f}/{row.get('reb', 0) / div:.1f}/{row.get('ast', 0) / div:.1f}"


