            blk = q4.get("blk", 0) / games
            tov = q4.get("tov", 0) / games
            oreb = q4.get("oreb", 0) / games
            dreb = q4.get("dreb", 0) / games
            pf = q4.get("pf", 0) / games
            plus_minus = q4.get("plus_minus", 0) / games
