def commit_turnover(player: Player, team: Team):
    player.tov += 1
    team.team_tov += 1


def record_defensive_turnover(defender: Player | None, offender: Player | None):
    if defender is None:
        return
    if not hasattr(defender, "defended_diet") or defender.defended_diet is None:
        defender.defended_diet = {}
    defender.defended_diet["turnover"] = defender.defended_diet.get("turnover", 0) + 1

    if offender is not None:
        if not hasattr(defender, "defended_matchup_diet") or defender.defended_matchup_diet is None:
            defender.defended_matchup_diet = {}
        matchup_bucket = defender.defended_matchup_diet.setdefault(offender.name, {})
        matchup_bucket["turnover"] = matchup_bucket.get("turnover", 0) + 1


def current_sim_period_key():
    if isinstance(globals().get("SIM_CONTEXT"), dict):
        period = SIM_CONTEXT.get("period")
        if isinstance(period, int) and period > 0:
            return period if period <= 4 else "OT"
    return None


def record_shot_diet(team: Team, shot_type: str, context: str = "", player: Player = None,
                     defender: Player = None, quality_mult: float | None = None):
    if not hasattr(team, "shot_diet") or team.shot_diet is None:
        team.shot_diet = {}

    add_to_shot_diet(team.shot_diet, shot_type, context, made=False)
    add_shot_quality_to_diet(team.shot_diet, quality_mult)
    period_key = current_sim_period_key()
    if period_key is not None:
        if not hasattr(team, "quarter_shot_diet") or team.quarter_shot_diet is None:
            team.quarter_shot_diet = {}
        q_bucket = team.quarter_shot_diet.setdefault(period_key, {})
        add_to_shot_diet(q_bucket, shot_type, context, made=False)
        add_shot_quality_to_diet(q_bucket, quality_mult)
    clutch_context = is_clutch_shot_context()
    if clutch_context:
        if not hasattr(team, "clutch_shot_diet") or team.clutch_shot_diet is None:
            team.clutch_shot_diet = {}
        add_to_shot_diet(team.clutch_shot_diet, shot_type, context, made=False)
        add_shot_quality_to_diet(team.clutch_shot_diet, quality_mult)

    if player is not None:
        if not hasattr(player, "shot_diet") or player.shot_diet is None:
            player.shot_diet = {}
        add_to_shot_diet(player.shot_diet, shot_type, context, made=False)
        add_shot_quality_to_diet(player.shot_diet, quality_mult)
        if period_key is not None:
            if not hasattr(player, "quarter_shot_diet") or player.quarter_shot_diet is None:
                player.quarter_shot_diet = {}
            pq_bucket = player.quarter_shot_diet.setdefault(period_key, {})
            add_to_shot_diet(pq_bucket, shot_type, context, made=False)
            add_shot_quality_to_diet(pq_bucket, quality_mult)
        if isinstance(globals().get("SIM_CONTEXT"), dict) and SIM_CONTEXT.get("period") == 4:
            player.fourth_fga = getattr(player, "fourth_fga", 0) + 1
        if clutch_context:
            if not hasattr(player, "clutch_shot_diet") or player.clutch_shot_diet is None:
                player.clutch_shot_diet = {}
            add_to_shot_diet(player.clutch_shot_diet, shot_type, context, made=False)
            add_shot_quality_to_diet(player.clutch_shot_diet, quality_mult)

    if defender is not None:
        if not hasattr(defender, "defended_diet") or defender.defended_diet is None:
            defender.defended_diet = {}
        defend_context = defensive_diet_context(context)
        add_to_shot_diet(defender.defended_diet, shot_type, defend_context, made=False)
        record_defended_matchup_diet(defender, player, shot_type, defend_context, made=False)


def record_shot_make(team: Team, shot_type: str, context: str = "", player: Player = None, defender: Player = None):
    if not hasattr(team, "shot_diet") or team.shot_diet is None:
        team.shot_diet = {}

    add_to_shot_diet(team.shot_diet, shot_type, context, made=True)
    period_key = current_sim_period_key()
    if period_key is not None:
        if not hasattr(team, "quarter_shot_diet") or team.quarter_shot_diet is None:
            team.quarter_shot_diet = {}
        q_bucket = team.quarter_shot_diet.setdefault(period_key, {})
        add_to_shot_diet(q_bucket, shot_type, context, made=True)
    clutch_context = is_clutch_shot_context()
    if clutch_context:
        if not hasattr(team, "clutch_shot_diet") or team.clutch_shot_diet is None:
            team.clutch_shot_diet = {}
        add_to_shot_diet(team.clutch_shot_diet, shot_type, context, made=True)

    if player is not None:
        if not hasattr(player, "shot_diet") or player.shot_diet is None:
            player.shot_diet = {}
        add_to_shot_diet(player.shot_diet, shot_type, context, made=True)
        if period_key is not None:
            if not hasattr(player, "quarter_shot_diet") or player.quarter_shot_diet is None:
                player.quarter_shot_diet = {}
            pq_bucket = player.quarter_shot_diet.setdefault(period_key, {})
            add_to_shot_diet(pq_bucket, shot_type, context, made=True)
        if clutch_context:
            if not hasattr(player, "clutch_shot_diet") or player.clutch_shot_diet is None:
                player.clutch_shot_diet = {}
            add_to_shot_diet(player.clutch_shot_diet, shot_type, context, made=True)

    if defender is not None:
        if not hasattr(defender, "defended_diet") or defender.defended_diet is None:
            defender.defended_diet = {}
        defend_context = defensive_diet_context(context)
        add_to_shot_diet(defender.defended_diet, shot_type, defend_context, made=True)
        record_defended_matchup_diet(defender, player, shot_type, defend_context, made=True)

def shot_diet_pct(diet: Dict[str, int], key: str) -> float:
    attempts = diet.get(key, 0)
    if attempts <= 0:
        return 0.0
    return diet.get(f"{key}_made", 0) / attempts


def apply_ai_adjustment(team: Team, key: str, message: str) -> bool:
    made = getattr(team, "ai_adjustments", set())
    if key in made:
        return False
    made.add(key)
    team.ai_adjustments = made
    print(message)
    return True


def maybe_shot_diet_adjustment(team: Team, opponent: Team, period: int):
    if period >= 4:
        return

    team_plan = getattr(team, "game_plan", {})
    diet = getattr(team, "shot_diet", {})
    opp_diet = getattr(opponent, "shot_diet", {})

    fga = sum(diet.get(k, 0) for k in ("three", "mid", "rim", "post", "dunk"))
    opp_fga = sum(opp_diet.get(k, 0) for k in ("three", "mid", "rim", "post", "dunk"))
    if fga < 16 or opp_fga < 16:
        return

    adjusted = False
    three_rate = diet.get("three", 0) / max(1, fga)
    paint_rate = diet.get("paint", 0) / max(1, fga)
    three_pct = shot_diet_pct(diet, "three")
    paint_pct = shot_diet_pct(diet, "paint")

    opp_three_rate = opp_diet.get("three", 0) / max(1, opp_fga)
    opp_paint_rate = opp_diet.get("paint", 0) / max(1, opp_fga)
    opp_three_pct = shot_diet_pct(opp_diet, "three")
    opp_paint_pct = shot_diet_pct(opp_diet, "paint")
    opp_catch_pct = shot_diet_pct(opp_diet, "catch_shoot")
    opp_fastbreak_pct = shot_diet_pct(opp_diet, "fastbreak")

    if three_rate >= 0.42 and three_pct < 0.31:
        team_plan["offense"] = "attack_paint"
        adjusted |= apply_ai_adjustment(team, "off_cold_threes", f"{team.name} adjust the offense after cold perimeter shooting and look to pressure the paint.")
    elif paint_rate >= 0.42 and paint_pct < 0.46:
        team_plan["offense"] = "motion"
        adjusted |= apply_ai_adjustment(team, "off_stalled_paint", f"{team.name} adjust the offense after tough paint finishes and get into more movement.")
    elif three_rate < 0.28 and paint_pct < 0.52 and shot_diet_pct(diet, "mid") < 0.42:
        team_plan["offense"] = "hunt_threes"
        adjusted |= apply_ai_adjustment(team, "off_need_spacing", f"{team.name} adjust the offense and hunt cleaner spacing.")

    if three_rate >= 0.48 and three_pct >= 0.39 and diet.get("three", 0) >= 12:
        team_plan["offense"] = "hunt_threes"
        adjusted |= apply_ai_adjustment(team, "off_green_light_threes", f"{team.name} lean into the hot three-point shooting and keep spacing the floor.")
    elif shot_diet_pct(diet, "iso") >= 0.52 and diet.get("iso", 0) >= 5:
        team_plan["offense"] = "star_spread"
        adjusted |= apply_ai_adjustment(team, "off_hot_iso", f"{team.name} notice the isolation advantage and space the floor around the matchup.")

    if opp_paint_rate >= 0.40 and opp_paint_pct >= 0.54:
        team_plan["defense"] = "wall_paint"
        team_plan["limit_paint"] = True
        team_plan["star_coverage"] = team_plan.get("star_coverage", "shade_help")
        adjusted |= apply_ai_adjustment(team, "def_wall_paint", f"{team.name} adjust defensively after {opponent.name} keep scoring in the paint.")
    elif (opp_three_rate >= 0.38 and opp_three_pct >= 0.38) or opp_catch_pct >= 0.43:
        team_plan["defense"] = "stay_home"
        team_plan["limit_threes"] = True
        adjusted |= apply_ai_adjustment(team, "def_limit_threes", f"{team.name} adjust defensively to run shooters off the line and stay attached.")

    if opp_diet.get("three", 0) >= 14 and opp_three_rate >= 0.45 and opp_three_pct >= 0.36:
        team_plan["defense"] = "stay_home"
        team_plan["limit_threes"] = True
        team_plan["top_lock_shooters"] = True
        adjusted |= apply_ai_adjustment(team, "def_top_lock_threes", f"{team.name} top-lock the shooters after {opponent.name} keep firing from three.")

    opp_iso_pct = shot_diet_pct(opp_diet, "iso")
    if opp_diet.get("iso", 0) >= 6 and opp_iso_pct >= 0.48:
        team_plan["defense"] = "blitz"
        team_plan["limit_iso"] = True
        adjusted |= apply_ai_adjustment(team, "def_trap_iso", f"{team.name} adjust defensively and send more heat at isolation touches.")
    elif opp_diet.get("catch_shoot", 0) >= 7 and opp_catch_pct >= 0.40:
        team_plan["defense"] = "switch"
        team_plan["limit_threes"] = True
        adjusted |= apply_ai_adjustment(team, "def_switch_catch_shoot", f"{team.name} adjust defensively to switch more actions and take away clean catches.")
    elif opp_three_rate < 0.26 and opp_paint_rate >= 0.36:
        team_plan["defense"] = "pack_paint"
        team_plan["limit_paint"] = True
        adjusted |= apply_ai_adjustment(team, "def_pack_paint", f"{team.name} adjust defensively and crowd the lane against poor spacing.")

    if opp_diet.get("fastbreak", 0) >= 5 and opp_fastbreak_pct >= 0.68:
        team_plan["limit_transition"] = True
        adjusted |= apply_ai_adjustment(team, "def_sprint_back", f"{team.name} emphasize getting back after {opponent.name} punish them in transition.")

    if opp_diet.get("putback", 0) >= 3 or opponent.team_reb and opponent.team_reb > 0 and opponent.team_reb:
        opp_oreb = sum(p.oreb_stat for p in opponent.roster)
        if opp_oreb >= 5:
            team.def_reb_emphasis = True
            team_plan["box_out"] = True
            adjusted |= apply_ai_adjustment(team, "def_box_out", f"{team.name} emphasize the defensive glass after giving up extra chances.")

    if adjusted:
        team.game_plan = team_plan


def non_shooting_foul_chance(defender: Player, foul_kind: str) -> float:
    physicality = 0.90 if PLAYOFF_MODE else 1.08
    foul_caution = foul_trouble_foul_factor(defender)
    if foul_kind == "reach":
        return physicality * foul_caution * (0.010 + defender.steal * 0.012 + foul_rate_sim(defender) * 0.035)
    if foul_kind == "blocking":
        return physicality * foul_caution * (0.008 + foul_rate_sim(defender) * 0.045)
    if foul_kind == "loose_ball":
        return physicality * foul_caution * (0.006 + foul_rate_sim(defender) * 0.030)
    if foul_kind == "illegal_screen":
        return physicality * foul_caution * (0.004 + foul_rate_sim(defender) * 0.025)
    if foul_kind == "off_ball":
        return physicality * foul_caution * (0.004 + foul_rate_sim(defender) * 0.020)
    return physicality * foul_caution * 0.005


def shooting_foul_type_multiplier(shot_type: str) -> float:
    if shot_type == "dunk":
        return 2.05
    if shot_type == "rim":
        return 1.90
    if shot_type == "post":
        return 1.72
    if shot_type == "post_fade":
        return 0.72
    if shot_type == "mid":
        return 0.52
    if shot_type == "three":
        return 0.24
    return 1.0


def and_one_type_multiplier(shot_type: str) -> float:
    if shot_type == "dunk":
        return 1.55
    if shot_type == "rim":
        return 1.42
    if shot_type == "post":
        return 1.30
    if shot_type == "post_fade":
        return 0.58
    if shot_type == "mid":
        return 0.55
    if shot_type == "three":
        return 0.22
    return 1.0


def charge_chance(shooter: Player, defender: Player, shot_type: str) -> float:
    if shot_type not in ("rim", "dunk", "post"):
        return 0.0
    pressure = 0.012 + defender.interior_def * 0.018 + defender.perimeter_def * 0.008
    recklessness = shooter.drive_tendency * 0.018 + shooter.usage * 0.012
    return min(0.055, pressure + recklessness)


def pass_interception_chance(passer: Player, receiver: Player, defender: Player) -> float:
    passer_security = 0.55 * passer.playmaking + 0.45 * passer.ball_handle
    lane_read = 0.65 * defender.steal + 0.35 * defender.perimeter_def
    receiver_pressure = 1.0 - 0.25 * receiver.ball_handle
    chance = 0.004 + lane_read * receiver_pressure * 0.034 - passer_security * 0.010
    return max(0.0025, min(0.040, chance))


def call_foul(team: Team, player: Player, label: str):
    register_foul(team, player)
    print(label)
    time.sleep(SLEEP * 0.6)

    if player.pf >= 6:
        foul_out_sub(team, player)


def attempt_on_ball_steal(handler: Player, defender: Player) -> bool:
    norm_steal = defender.steal
    ball_sec = 0.6 * handler.ball_handle + 0.4 * handler.playmaking
    base = 0.052
    p = base * norm_steal / (0.5 + 0.5 * ball_sec)
    p *= max(0.75, 1.0 - max(0.0, (defender.minutes / 60 - 36) * 0.006))
    return random.random() < p


def rebound_position_multiplier(player: Player, miss_type: str, offensive: bool) -> float:
    pos = player.position.upper()
    if pos == "C":
        mult = 1.20
    elif pos == "PF":
        mult = 1.12
    elif pos == "SF":
        mult = 1.00
    elif pos == "SG":
        mult = 0.93
    else:
        mult = 0.86

    if miss_type == "jumper":
        if pos in ("PG", "SG"):
            mult *= 0.96
        elif pos in ("SF", "PF"):
            mult *= 1.02
    else:
        if pos in ("C", "PF"):
            mult *= 1.06
        elif pos in ("PG", "SG"):
            mult *= 0.88

    rating = player.oreb if offensive else player.dreb
    if offensive and pos in ("PG", "SG") and rating < 0.45:
        mult *= 0.70
    if not offensive and pos in ("PG", "SG") and rating < 0.45:
        mult *= 0.78
    if pos in ("PG", "SG") and rating >= 0.70:
        mult *= 1.16
    elif pos in ("PG", "SG") and rating >= 0.58:
        mult *= 1.08

    height_mult = 0.86 + max(0, min(14, player.height - 72)) * 0.022
    if player.height <= 74 and rating < 0.45:
        height_mult *= 0.90
    if "rebounder" in getattr(player, "badges", ()):
        height_mult *= 1.12

    return max(0.45, min(1.65, mult * height_mult))


def rebound_weight(player: Player, miss_type: str, offensive: bool) -> float:
    rating = player.oreb if offensive else player.dreb
    rating = max(0.02, rating)
    position_mult = rebound_position_multiplier(player, miss_type, offensive)
    motor = 0.90 + player.speed * 0.08 + (0.025 if "rebounder" in getattr(player, "badges", ()) else 0.0)
    current_boards = player.oreb_stat if offensive else player.dreb_stat
    total_boards = max(0, player.reb)
    glass_share_damper = 1.0 / (1.0 + current_boards * 0.135 + max(0, total_boards - 6) * 0.080)
    if "rebounder" in getattr(player, "badges", ()):
        glass_share_damper = max(glass_share_damper, 0.50)
    else:
        glass_share_damper = max(glass_share_damper, 0.40)
    rating_weight = max(0.001, (rating + 0.10) ** 1.62)
    return max(0.001, rating_weight * position_mult * motor * glass_share_damper)


def choose_rebounder(off: Team, dff: Team, miss_type: str) -> Tuple[Team, Player]:
    sanitize_live_lineups(off, dff)
    base_off_chance = 0.15 if miss_type == "jumper" else 0.30
    off_reb_rating = sum(p.oreb for p in off.on_floor) / max(1, len(off.on_floor))
    def_reb_rating = sum(p.dreb for p in dff.on_floor) / max(1, len(dff.on_floor))
    off_chance = base_off_chance + (off_reb_rating - def_reb_rating) * 0.12
    offense = getattr(off, "game_plan", {}).get("offense", "balanced")
    if offense == "five_out":
        off_chance *= 0.88
    elif offense == "four_out_one_in":
        off_chance *= 0.98
    elif offense == "three_out_two_in":
        off_chance *= 1.12
    elif offense == "post_heavy":
        off_chance *= 1.16
    elif offense == "star_spread":
        off_chance *= 0.94
    if getattr(dff, "def_reb_emphasis", False):
        off_chance *= 0.76
    if getattr(off, "crash_glass_emphasis", False):
        off_chance *= 1.10
    off_chance = max(0.08, min(0.42, off_chance))
    if random.random() < off_chance:
        team = off
        weights = [rebound_weight(p, miss_type, offensive=True) for p in team.on_floor]
    else:
        team = dff
        weights = [rebound_weight(p, miss_type, offensive=False) for p in team.on_floor]

    total = sum(weights)
    if total <= 0:
        rebounder = random.choice(team.on_floor)
    else:
        r = random.random() * total
        cum = 0.0
        rebounder = team.on_floor[-1]
        for p, w in zip(team.on_floor, weights):
            cum += w
            if r <= cum:
                rebounder = p
                break
    rebounder.reb += 1
    if team is off:
        rebounder.oreb_stat += 1
    else:
        rebounder.dreb_stat += 1
    team.team_reb += 1
    team.last_rebounder = rebounder
    return team, rebounder

def shot_skill_disparity_multiplier(rating: float, shot_type: str) -> float:
    if shot_type == "three":
        center = 0.90
        high_scale = 0.48
        low_scale = 0.90
        floor = 0.76
        ceiling = 1.08
    elif shot_type in ("mid", "post_fade"):
        center = 0.78
        high_scale = 0.35
        low_scale = 0.55
        floor = 0.86
        ceiling = 1.08
    else:
        center = 0.80
        high_scale = 0.25
        low_scale = 0.42
        floor = 0.88
        ceiling = 1.06

    if rating >= center:
        return min(ceiling, 1.0 + (rating - center) * high_scale)
    return max(floor, 1.0 - (center - rating) * low_scale)


def elite_interior_scorer(player: Player) -> bool:
    return (
        player.height >= 80
        and (player.rim_rating >= 0.92 or player.dunk_rating >= 0.92)
        and (player.post_tendency >= 0.28 or player.drive_tendency >= 0.30 or player.usage >= 0.28)
    )


def wide_open_jumper_floor(shooter: Player, shot_type: str, defender: Player | None = None) -> float:
    # This floor used to be shooter-only, which meant a great closeout
    # defender and a poor one produced the exact same catch-and-shoot make
    # chance whenever the shot was flagged as a "good look" -- the pre-floor,
    # defender-aware probability just got overridden. A strong, engaged
    # perimeter defender now shaves a little off the floor itself; a below-
    # average one leaves it untouched.
    defense_shave = max(0.0, effective_perimeter_def(defender) - 0.55) * 0.16 if defender is not None else 0.0
    if shot_type == "three":
        if shooter.three_rating >= 0.90:
            floor = 0.58 + (shooter.three_rating - 0.90) * 0.95
            floor += max(0.0, shooter.shot_iq - 0.78) * 0.05
            return min(0.70, floor) - defense_shave

        floor = 0.36 + max(0.0, shooter.three_rating - 0.70) * 0.36
        floor += max(0.0, shooter.shot_iq - 0.78) * 0.025
        return min(0.54, floor) - defense_shave

    if shot_type == "mid":
        if shooter.mid_rating >= 0.90:
            floor = 0.68 + (shooter.mid_rating - 0.90) * 0.45
            floor += max(0.0, shooter.shot_iq - 0.78) * 0.04
            return min(0.78, floor) - defense_shave

        floor = 0.46 + max(0.0, shooter.mid_rating - 0.70) * 0.55
        floor += max(0.0, shooter.shot_iq - 0.78) * 0.035
        return min(0.66, floor) - defense_shave

    return 0.0


def shot_make_prob(shooter: Player, defender: Player, shot_type: str,
                   team: Team = None, opponent: Team = None,
                   period: int = 1, period_time: int = 720) -> float:
    if team is None or opponent is None:
        team = Team("temp", [shooter])
        opponent = Team("temp opponent", [defender])
    skill_rating = 0.75
    if shot_type == "three":
        rating = effective_rating(shooter.three_rating, shooter, team, opponent, period, period_time)
        skill_rating = rating
        p = rating * 0.66
        p *= (1 - 0.58 * effective_perimeter_def(defender))

    elif shot_type == "mid":
        rating = effective_rating(shooter.mid_rating, shooter, team, opponent, period, period_time)
        skill_rating = rating
        p = rating * 0.74
        p *= (1 - 0.56 * effective_perimeter_def(defender))

    elif shot_type == "rim":
        rating = effective_rating(shooter.rim_rating, shooter, team, opponent, period, period_time)
        skill_rating = rating
        elite_big_finish = elite_interior_scorer(shooter)
        elite_slash_finish = shooter.rim_rating >= 0.92 and (shooter.drive_tendency >= 0.18 or shooter.usage >= 0.28)
        if elite_big_finish:
            defense_tax = 0.38
            finish_base = 0.94
        elif elite_slash_finish:
            defense_tax = 0.56
            finish_base = 0.85
        else:
            # This bucket covers most of the league -- ordinary guards and
            # wings finishing at the rim, not dominant post players or elite
            # high-usage slashers. A 0.60 defense tax against a strong rim
            # protector (interior_def ~0.85+) was cutting even a decent
            # finisher's rim conversion down to the 20-35% range, which is
            # far below what an ordinary NBA player actually shoots at the
            # rim even when well-defended (45%+ is typical). That produced
            # correlated, team-wide bad shooting nights against good interior
            # defenses -- a bigger driver of unrealistic blowout margins than
            # any per-shot situational modifier.
            defense_tax = 0.48
            finish_base = 0.85
        p = rating * finish_base
        p *= (1 - defense_tax * effective_interior_def(defender))

    elif shot_type == "dunk":
        rating = effective_rating(shooter.dunk_rating, shooter, team, opponent, period, period_time)
        skill_rating = rating
        defense_tax = 0.42 if elite_interior_scorer(shooter) else 0.58
        p = rating * (0.94 if elite_interior_scorer(shooter) else 0.88)
        p *= (1 - defense_tax * effective_interior_def(defender))
        p = max(0.50 if elite_interior_scorer(shooter) else 0.45, p)

    elif shot_type == "post":
        rim = effective_rating(shooter.rim_rating, shooter, team, opponent, period, period_time)
        mid = effective_rating(shooter.mid_rating, shooter, team, opponent, period, period_time)
        base = 0.68 * rim + 0.32 * mid
        skill_rating = base
        # Post shots were landing around 29% league-wide -- well below a real
        # post-up's efficiency even accounting for contact and length down
        # low. Raised the finish base and eased the interior-defense tax.
        defense_tax = 0.34 if elite_interior_scorer(shooter) else 0.48
        p = base * (0.98 if elite_interior_scorer(shooter) else 0.90)
        p *= (1 - defense_tax * effective_interior_def(defender))

    elif shot_type == "post_fade":
        rating = effective_rating(shooter.mid_rating, shooter, team, opponent, period, period_time)
        post_balance = 0.55 * shooter.mid_rating + 0.25 * shooter.post_tendency + 0.20 * shooter.shot_iq
        skill_rating = rating
        p = rating * (0.80 + min(0.08, shooter.post_tendency * 0.12))
        p *= 1.0 + max(0.0, post_balance - 0.74) * 0.14
        p *= (1 - 0.40 * effective_interior_def(defender))

    else:
        rim = effective_rating(shooter.rim_rating, shooter, team, opponent, period, period_time)
        mid = effective_rating(shooter.mid_rating, shooter, team, opponent, period, period_time)
        base = 0.6 * rim + 0.4 * mid
        skill_rating = base
        p = base * 0.76
        p *= (1 - 0.61 * effective_interior_def(defender))

    p *= shot_skill_disparity_multiplier(skill_rating, shot_type)

    # Baseline locked in purely from skill vs. matchup quality. Everything
    # below this point is situational (fatigue, chemistry, scheme, quality
    # of look, confidence, hot/cold streaks, defensive focus, height, late-
    # game pressure...) -- each one individually modest and capped, but
    # nothing stops several of them landing against the same team in the
    # same stretch. See the dampening step right before the final return,
    # which keeps that compounding from snowballing into a far bigger swing
    # than any single factor was ever meant to produce on its own.
    base_p = p

    creation_boost = 1 + (shooter.playmaking - 0.5) * 0.12
    p *= creation_boost

    comfort = 1 + (shooter.shot_tendency - 0.5) * 0.08
    p *= comfort
    p *= fatigue_offense_factor(shooter)
    p *= offensive_scheme_multiplier(team, opponent, shot_type, shooter)
    p *= defensive_scheme_multiplier(opponent, shot_type, shooter)
    p *= bench_chemistry_multiplier(team, shooter)
    p *= lineup_chemistry_multiplier(team, shooter, shot_type)
    quality_mult = getattr(shooter, "shot_quality_mult", 1.0)
    if quality_mult < 1.0:
        bad_look_penalty = 1.0 + max(0.0, 0.70 - shooter.shot_iq) * 0.45
        quality_mult = 1.0 - (1.0 - quality_mult) * bad_look_penalty
    elif quality_mult > 1.0:
        good_look_bonus = 0.90 + shooter.shot_iq * 0.12
        if shot_type in ("three", "mid"):
            # A "good look" bonus (catch-and-shoot, kickouts, movement
            # shooting) shouldn't ignore who's closing out -- a sharp,
            # engaged perimeter defender should still meaningfully cut into
            # it, not just the shooter's own touch.
            good_look_bonus = max(0.55, good_look_bonus - effective_perimeter_def(defender) * 0.18)
        quality_mult = 1.0 + (quality_mult - 1.0) * good_look_bonus
    p *= quality_mult
    open_jumper_floor = wide_open_jumper_floor(shooter, shot_type, defender) if quality_mult >= 1.08 else 0.0

    if quality_mult < 0.97:
        if shot_type in ("three", "mid"):
            p *= 1.0 - max(0.0, effective_perimeter_def(defender) - 0.55) * 0.16
        elif is_paint_shot(shot_type):
            p *= 1.0 - max(0.0, effective_interior_def(defender) - 0.55) * 0.18

    if shot_type == "three" and getattr(shooter, "limitless_range_attempt", False):
        p *= limitless_range_make_bonus(shooter)
        if getattr(shooter, "heat_check_attempt", False):
            p *= 1.03 + min(0.06, getattr(shooter, "confidence", 0.0) * 0.02)

    shot_iq_efficiency = 0.99 + max(0.0, shooter.shot_iq - 0.82) * 0.02
    if shot_type in ("three", "mid") and shooter.shot_iq < 0.72:
        shot_iq_efficiency -= (0.72 - shooter.shot_iq) * 0.30
    if is_paint_shot(shot_type) and shooter.shot_iq < 0.62:
        shot_iq_efficiency -= (0.62 - shooter.shot_iq) * 0.14
    if quality_mult < 0.96:
        shot_iq_efficiency -= max(0.0, 0.70 - shooter.shot_iq) * 0.14
    if shooter.usage >= 0.28 and shooter.shot_iq < 0.62:
        shot_iq_efficiency -= (0.62 - shooter.shot_iq) * 0.08
    p *= shot_iq_efficiency

    if period >= 4:
        elite_closer_score = 0.56 * shooter.clutchness + 0.44 * shooter.shot_iq
        if elite_closer_score >= 0.90:
            pressure = 0.65 if abs(team.score - opponent.score) <= 8 else 0.35
            if team.score < opponent.score:
                pressure += 0.25
            if period_time <= 6 * 60:
                pressure += 0.18
            if period_time <= 2 * 60:
                pressure += 0.12
            p *= 1.0 + min(0.16, (elite_closer_score - 0.90) * pressure * 0.42)

            if shot_type in ("three", "mid"):
                if quality_mult >= 1.04:
                    floor = 0.44 if shot_type == "three" else 0.50
                elif quality_mult >= 0.97:
                    floor = 0.40 if shot_type == "three" else 0.46
                else:
                    floor = 0.36 if shot_type == "three" else 0.41
                p = max(p, floor)

    shot_creator_bonus = getattr(shooter, "shot_creator_quality_bonus", 0.0)
    if shot_creator_bonus:
        p *= 1.0 + shot_creator_bonus

    posterizer_bonus = getattr(shooter, "posterizer_quality_bonus", 0.0)
    if posterizer_bonus and shot_type == "dunk":
        p *= 1.0 + posterizer_bonus

    # Hot/cold streak and confidence are each individually capped and modest
    # per shot -- but unlike a one-off situational bonus, they PERSIST across
    # many consecutive shots by the same player once triggered (confidence
    # saturates near its cap after just 3-4 makes in a row, then every shot
    # for the rest of the game gets that same bonus until he cools off).
    # That sustained, correlated advantage across a whole quarter's worth of
    # shots -- not any single shot's probability -- is what was driving
    # unrealistically large game-to-game scoring swings between evenly
    # matched teams. Halving the caps keeps the "hot hand" feel without
    # letting it compound into a shooting-percentage gap real defenses
    # couldn't produce.
    hot = getattr(shooter, "hot_streak", 0)
    cold = getattr(shooter, "cold_streak", 0)
    if hot >= 2:
        p *= 1.0 + min(0.04, hot * 0.0125)
    if cold >= 3:
        p *= 0.97
    confidence = getattr(shooter, "confidence", 0.0)
    if confidence:
        p *= 1.0 + max(-0.04, min(0.04, confidence * 0.025))

    if is_paint_shot(shot_type):
        p *= paint_spacing_multiplier(team, shooter)

    if getattr(opponent, "defensive_focus", None) == shooter.name:
        p *= 0.88 + shooter.shot_iq * 0.08

    size = height_advantage(defender, shooter)
    height_tax = 0.65 if quality_mult >= 1.12 else 1.0
    if quality_mult < 0.97:
        height_tax = 1.35
    if shot_type == "three":
        p *= 1.0 - 0.075 * height_tax * size
    elif shot_type == "mid":
        p *= 1.0 - 0.075 * height_tax * size
    elif shot_type in ("rim", "post"):
        p *= 1.0 - 0.112 * height_tax * size
    elif shot_type == "post_fade":
        p *= 1.0 - 0.085 * height_tax * size
    elif shot_type == "dunk":
        p *= 1.0 - 0.088 * height_tax * size

    if shooter.shot_iq < 0.50:
        if shot_type in ("three", "mid"):
            p = min(p, 0.46 + shooter.shot_iq * 0.16)
        elif shot_type in ("rim", "post"):
            p = min(p, 0.58 + shooter.shot_iq * 0.22)

    if elite_interior_scorer(shooter) and is_paint_shot(shot_type):
        interior_floor = 0.50 if shot_type == "post" else 0.47 if shot_type == "rim" else 0.52
        if shot_type == "post_fade":
            interior_floor = 0.43 + max(0.0, shooter.mid_rating - 0.82) * 0.22
        if getattr(opponent, "defensive_focus", None) == shooter.name:
            interior_floor -= 0.04
        if quality_mult < 0.90:
            interior_floor -= 0.04
        p = max(p, interior_floor)

    if period >= 4 and shot_type in ("three", "mid"):
        elite_closer_score = 0.56 * shooter.clutchness + 0.44 * shooter.shot_iq
        if elite_closer_score >= 0.90:
            if quality_mult >= 1.04:
                late_floor = 0.44 if shot_type == "three" else 0.50
            elif quality_mult >= 0.97:
                late_floor = 0.40 if shot_type == "three" else 0.46
            else:
                late_floor = 0.36 if shot_type == "three" else 0.41
            if getattr(opponent, "defensive_focus", None) == shooter.name:
                late_floor -= 0.015
            p = max(p, late_floor)

    if open_jumper_floor:
        p = max(p, open_jumper_floor)

    if shot_type in ("three", "mid"):
        contest = effective_perimeter_def(defender)
        if open_jumper_floor:
            p *= 1.0 - max(0.0, contest - 0.82) * 0.02
        else:
            p *= 1.0 - max(0.0, contest - 0.60) * 0.10
    elif is_paint_shot(shot_type):
        contest = effective_interior_def(defender)
        if quality_mult >= 1.12:
            p *= 1.0 - max(0.0, contest - 0.80) * 0.04
        else:
            p *= 1.0 - max(0.0, contest - 0.60) * 0.12

    if open_jumper_floor:
        p = max(p, open_jumper_floor)

    # A truly wide-open shot at the rim -- the same "good look" signal that
    # already floors open threes/mid shots -- should just go in. There's no
    # defender there to contest it; nothing downstream should still be able
    # to knock it below a make.
    if shot_type in ("rim", "dunk") and quality_mult >= 1.08:
        return 1.0

    if base_p > 0.001:
        situational_ratio = p / base_p
        # Real situational swings (confidence, matchups, schemes, streaks)
        # pass through completely untouched up to +/-35% -- that's the
        # normal, intended range for any one or two of these factors acting
        # together. Beyond that, it means several modest penalties or
        # bonuses have all landed on the same shot at once; soften the
        # excess by half instead of letting it multiply straight through,
        # which is what was turning ordinary variance into runaway quarters
        # between evenly-matched teams.
        deviation = situational_ratio - 1.0
        threshold = 0.35
        excess = abs(deviation) - threshold
        if excess > 0:
            sign = 1.0 if deviation > 0 else -1.0
            situational_ratio = 1.0 + sign * (threshold + excess * 0.5)
            p = base_p * situational_ratio

    return max(0.05, min(0.90, p))


def defensive_scheme_multiplier(def_team: Team, shot_type: str, shooter: Player) -> float:
    plan = getattr(def_team, "game_plan", {})
    scheme = plan.get("defense", "standard")
    player_coverage = plan.get("player_coverages", {}).get(shooter.name)
    mult = 1.0

    if scheme == "wall_paint":
        mult *= 0.95 if is_post_family_shot(shot_type) else 0.91 if shot_type in ("rim", "dunk") else 1.03
    elif scheme == "pack_paint":
        mult *= 0.93 if is_post_family_shot(shot_type) else 0.88 if shot_type in ("rim", "dunk") else 1.05
    elif scheme == "stay_home":
        mult *= 0.94 if shot_type == "three" else 1.02 if is_paint_shot(shot_type) else 1.0
    elif scheme == "top_lock":
        if shot_type == "three":
            mult *= 0.89
        elif shot_type in ("rim", "dunk"):
            mult *= 1.04
    elif scheme == "switch":
        if shot_type in ("three", "mid"):
            mult *= 0.96
        else:
            mult *= 1.02 if shooter.height >= 82 else 0.99
    elif scheme == "drop":
        if shot_type in ("rim", "dunk"):
            mult *= 0.94
        if shot_type in ("three", "mid"):
            mult *= 1.03
    elif scheme == "blitz":
        if shot_type in ("three", "mid") and shooter.ball_handle < 0.76:
            mult *= 0.92
        if shot_type in ("rim", "dunk"):
            mult *= 1.05
    elif scheme == "zone":
        if is_paint_shot(shot_type):
            mult *= 0.93
        if shot_type == "three":
            mult *= 1.04
    elif scheme == "show_recover":
        if shot_type in ("rim", "dunk"):
            mult *= 0.98
        elif shot_type == "three":
            mult *= 0.97 if shooter.playmaking < 0.78 else 1.01
    elif scheme == "load_star":
        if getattr(def_team, "defensive_focus", None) == shooter.name:
            mult *= 0.91 if shooter.playmaking < 0.78 else 0.96

    if plan.get("limit_threes") and shot_type == "three":
        mult *= 0.88 if plan.get("top_lock_shooters") else 0.92
    if plan.get("limit_paint") and is_paint_shot(shot_type):
        mult *= 0.90
    if plan.get("limit_iso") and getattr(shooter, "iso_tendency", 0.0) >= 0.65:
        mult *= 0.92
    if player_coverage in ("shade_help", "late_double_rotate"):
        mult *= 0.96 if shooter.playmaking >= 0.78 else 0.92
    elif player_coverage == "early_double":
        mult *= 0.93 if shooter.playmaking >= 0.78 else 0.89
    elif player_coverage == "trap_force_pass":
        mult *= 0.91 if shooter.playmaking >= 0.78 else 0.86
    elif player_coverage == "stay_home":
        mult *= 0.94 if shot_type == "three" else 1.02 if is_paint_shot(shot_type) else 1.0
    elif player_coverage == "sag_rim":
        if is_paint_shot(shot_type):
            mult *= 0.90
        elif shot_type == "three":
            mult *= 1.12
        elif shot_type == "mid":
            mult *= 1.05
    elif player_coverage == "gap_help":
        if is_paint_shot(shot_type):
            mult *= 0.94
        elif shot_type == "three":
            mult *= 1.06
    elif player_coverage == "stay_close":
        if shot_type == "three":
            mult *= 0.93
        elif shot_type == "mid":
            mult *= 0.96
        elif shot_type in ("rim", "dunk"):
            mult *= 1.04
    elif player_coverage == "deny_catch":
        if shot_type in ("three", "mid"):
            mult *= 0.91
        elif shot_type in ("rim", "dunk"):
            mult *= 1.06
    elif player_coverage == "full_pressure":
        if shot_type in ("three", "mid"):
            mult *= 0.94 if shooter.ball_handle < 0.82 else 0.98
        elif shot_type in ("rim", "dunk"):
            mult *= 1.05 if shooter.ball_handle >= 0.78 else 1.01
    elif player_coverage == "go_under":
        if shot_type in ("rim", "dunk"):
            mult *= 0.96
        elif shot_type == "three":
            mult *= 1.08
        elif shot_type == "mid":
            mult *= 1.02
    elif player_coverage == "no_help":
        if shot_type == "three":
            mult *= 0.92
        elif is_paint_shot(shot_type):
            mult *= 1.08
    elif player_coverage == "switch_screens":
        if shot_type in ("three", "mid"):
            mult *= 0.97
        elif shot_type in ("post", "post_fade", "rim") and shooter.height >= 80:
            mult *= 1.02
    elif player_coverage == "top_lock" and shot_type == "three":
        mult *= 0.88
    return mult


def offensive_scheme_multiplier(team: Team, opponent: Team, shot_type: str, shooter: Player) -> float:
    offense = getattr(team, "game_plan", {}).get("offense", "balanced")
    defense = getattr(opponent, "game_plan", {}).get("defense", "standard")

    if offense == "five_out":
        if not lineup_can_five_out(team):
            return 0.94 if shot_type in ("three", "mid") else 0.90
        if shot_type == "three":
            return 1.05 if defense != "stay_home" else 0.98
        if shot_type in ("rim", "dunk"):
            return 1.05 if defense not in ("pack_paint", "wall_paint") else 0.96

    if offense == "four_out_one_in":
        non_spacers = sum(1 for p in getattr(team, "on_floor", []) if is_non_spacer(p))
        if shot_type in ("rim", "dunk"):
            return 1.035 if non_spacers <= 1 and defense not in ("pack_paint", "wall_paint") else 0.98
        if shot_type == "three":
            return 1.015 if non_spacers <= 1 else 0.98
        if is_post_family_shot(shot_type):
            return 1.02

    if offense == "three_out_two_in":
        if is_paint_shot(shot_type):
            return 1.03 if defense not in ("pack_paint", "wall_paint", "zone") else 0.94
        if shot_type == "three":
            return 0.96 if defense != "pack_paint" else 1.01

    if offense == "post_heavy":
        if is_post_family_shot(shot_type):
            return 1.07 if defense not in ("pack_paint", "wall_paint") else 0.94
        if shot_type in ("rim", "dunk"):
            return 1.025 if defense != "wall_paint" else 0.95
        if shot_type == "three":
            return 0.97

    if offense == "hunt_threes":
        if shot_type == "three":
            return 1.04 if defense in ("wall_paint", "pack_paint", "drop") else 0.95 if defense == "stay_home" else 1.0
        if shot_type in ("rim", "dunk"):
            return 0.98

    if offense == "attack_paint":
        if is_paint_shot(shot_type):
            return 1.05 if defense in ("stay_home", "switch") else 0.92 if defense in ("wall_paint", "pack_paint", "zone") else 1.0
        if shot_type == "three":
            return 0.96

    if offense == "star_spread":
        if getattr(opponent, "defensive_focus", None) == shooter.name or defense == "blitz":
            return 0.94 if shooter.playmaking < 0.78 else 0.99
        if shooter.usage >= 0.30:
            return 1.03

    if offense == "motion":
        if defense in ("switch", "stay_home"):
            return 0.98
        if shot_type in ("three", "mid", "rim"):
            return 1.025

    return 1.0


def bench_chemistry_multiplier(team: Team, shooter: Player) -> float:
    bench_count = sum(1 for p in team.on_floor if not getattr(p, "is_starter", False))
    if bench_count < 3:
        return 1.0

    style = getattr(team, "coach_style", {}).get("offensive_style", "")
    mult = 1.0
    if style in ("ball movement", "motion split", "pace motion"):
        mult += 0.030
    if team.name in ("2014 San Antonio Spurs", "2025 Indiana Pacers", "2017 Golden State Warriors", "2015 Atlanta Hawks"):
        mult += 0.030
    if shooter.playmaking >= 0.62 or shooter.three_rating >= 0.80:
        mult += 0.015
    return min(1.075, mult)


def lineup_chemistry_score(team: Team) -> float:
    players = getattr(team, "on_floor", [])
    if len(players) < 5:
        return 0.0

    archetypes = [getattr(p, "archetype", "balanced") for p in players]
    creators = sum(1 for p in players if p.playmaking >= 0.72 or p.archetype in ("floor_general", "post_hub"))
    spacers = sum(1 for p in players if player_perimeter_gravity(p) >= 0.72)
    non_spacers = sum(1 for p in players if is_non_spacer(p))
    rim_threats = sum(1 for p in players if p.archetype in ("rim_runner", "slasher") or p.dunk_tendency >= 0.55)
    stoppers = sum(1 for p in players if p.archetype in ("lockdown", "rim_protector", "three_and_d"))

    score = 0.0
    if creators >= 1 and spacers >= 3:
        score += 0.045
    if creators >= 2 and spacers >= 2:
        score += 0.030
    if "post_hub" in archetypes and spacers >= 3:
        score += 0.035
    if "floor_general" in archetypes and rim_threats >= 1:
        score += 0.025
    if lineup_can_five_out(team):
        score += 0.030
    if stoppers >= 3:
        score += 0.012

    if creators == 0:
        score -= 0.050
    if non_spacers >= 2:
        score -= 0.055
    if spacers <= 1 and non_spacers >= 1:
        score -= 0.035

    return max(-0.10, min(0.10, score))


def lineup_chemistry_multiplier(team: Team, player: Player, shot_type: str) -> float:
    chemistry = lineup_chemistry_score(team)
    mult = 1.0 + chemistry

    archetype = getattr(player, "archetype", "balanced")
    if chemistry > 0:
        if archetype in ("movement_shooter", "three_and_d") and shot_type == "three":
            mult += chemistry * 0.28
        elif archetype in ("rim_runner", "slasher") and shot_type in ("rim", "dunk"):
            mult += chemistry * 0.24
        elif archetype in ("post_hub", "post_scorer") and shot_type in ("post", "post_fade", "rim"):
            mult += chemistry * 0.16
    return max(0.88, min(1.13, mult))


def floor_spacing_score(team: Team, exclude: Player = None) -> float:
    spacers = [p for p in getattr(team, "on_floor", []) if p is not exclude]
    if not spacers:
        return 0.50

    scores = []
    for p in spacers:
        scores.append(player_perimeter_gravity(p))

    return sum(scores) / len(scores)


def player_perimeter_gravity(player: Player) -> float:
    gravity = 0.58 * player.three_rating + 0.32 * min(1.0, player.three_tendency * 1.85) + 0.10 * player.shot_tendency
    if is_non_spacer(player):
        gravity *= 0.42
    if player.three_rating >= 0.86 and player.three_tendency >= 0.36:
        gravity += 0.10
    if "movement_shooter" in player.badges or "catch_shoot" in player.badges:
        gravity += 0.06
    if player.usage >= 0.30 and player.iso_tendency >= 0.78:
        gravity += 0.04
    return max(0.04, min(1.10, gravity))


def team_offball_gravity(team: Team, exclude: Player = None) -> float:
    teammates = [p for p in getattr(team, "on_floor", []) if p is not exclude]
    if not teammates:
        return 0.50
    return sum(player_perimeter_gravity(p) for p in teammates) / len(teammates)


def paint_spacing_multiplier(team: Team, shooter: Player) -> float:
    spacing = team_offball_gravity(team, shooter)
    non_spacers = sum(1 for p in getattr(team, "on_floor", []) if p is not shooter and is_non_spacer(p))
    offense = getattr(team, "game_plan", {}).get("offense", "balanced")

    mult = 1.0
    if spacing < 0.55:
        mult -= (0.55 - spacing) * 0.66
    elif spacing > 0.68:
        mult += min(0.060, (spacing - 0.68) * 0.16)

    if non_spacers >= 2:
        mult -= 0.070
    elif non_spacers == 1 and spacing < 0.58:
        mult -= 0.030
    elif non_spacers == 0 and spacing >= 0.62:
        mult += 0.018

    if shooter.post_tendency >= 0.28 and shooter.height >= 82:
        mult += 0.015

    if offense == "five_out":
        mult += 0.045 if lineup_can_five_out(team) else -0.070
    elif offense == "four_out_one_in":
        mult += 0.025 if non_spacers <= 1 else -0.030
    elif offense == "three_out_two_in":
        if shooter.post_tendency >= 0.24 and shooter.height >= 80:
            mult += 0.010
        else:
            mult -= 0.050
    elif offense == "post_heavy":
        if shooter.post_tendency >= 0.28 and shooter.height >= 80:
            mult += 0.030
        else:
            mult -= 0.045
    elif offense == "star_spread" and shooter.usage >= 0.28:
        mult += 0.020

    return max(0.78, min(1.06, mult))


def defensive_communication_error(off: Team, dff: Team, shooter: Player, shot_type: str,
                                  play_context: str | None, period: int, period_time: int) -> bool:
    if shot_type not in ("three", "mid", "rim", "dunk"):
        return False
    if getattr(dff, "coverage_error_cooldown", 0) > 0:
        dff.coverage_error_cooldown -= 1
        return False

    plan = getattr(dff, "game_plan", {})
    scheme = plan.get("defense", "standard")
    coach_iq = getattr(dff, "coach_style", {}).get("coach_iq", 0.62)
    ball_movement = getattr(off, "coach_style", {}).get("ball_movement", 1.0)
    gravity = team_offball_gravity(off, shooter)

    chance = 0.006 + max(0.0, ball_movement - 1.0) * 0.010 + max(0.0, gravity - 0.68) * 0.024
    if play_context in ("floppy", "elevator", "handoff", "ball_movement_chain", "post_split") or play_context in PLAYBOOK_CONTEXTS:
        chance += 0.010
    if scheme in ("switch", "show_recover", "load_star", "blitz"):
        chance += 0.010
    if plan.get("top_lock_shooters") and shot_type == "three":
        chance -= 0.004
    chance *= 1.0 - max(0.0, coach_iq - 0.62) * 0.45
    if period >= 4 and period_time <= 180:
        chance *= 0.70

    if random.random() < max(0.002, min(0.035, chance)):
        dff.coverage_error_cooldown = 6
        lines = [
            f"{dff.name} miscommunicate on the coverage and {shooter.name} slips free.",
            f"The switch is late and {shooter.name} gets a clean window.",
            f"{dff.name} lose track of {shooter.name} for a beat.",
            f"The help points one way while {shooter.name} flashes into open space.",
        ]
        print(random.choice(lines))
        time.sleep(SLEEP * 0.45)
        return True
    return False



def block_prob(defender: Player, shot_type: str, shooter: Player = None) -> float:
    if is_paint_shot(shot_type):
        p = 0.020 + 0.175 * defender.block * foul_trouble_defense_factor(defender)
        p *= 1.0 + max(0.0, effective_interior_def(defender) - 0.78) * 0.22
    else:
        p = 0.006 + 0.050 * defender.block * foul_trouble_defense_factor(defender)

    if shooter is not None:
        if is_paint_shot(shot_type):
            # Blocking at the rim is fundamentally a size-and-strength
            # contest. Both terms used to be too flat: a badly undersized
            # defender only lost ~20% of his block chance against a
            # dominant big, and a true rim protector's size/skill edge
            # barely raised his -- so small guards were blocking centers
            # at a non-trivial rate while elite shot-blockers weren't
            # separating enough from average ones. Both are bidirectional
            # and much steeper now.
            size_edge = height_advantage(defender, shooter)
            p *= max(0.30, 1.0 + 0.50 * size_edge)
            skill_edge = defender.interior_def - max(shooter.rim_rating, shooter.dunk_rating)
            p *= max(0.40, min(1.55, 1.0 + skill_edge * 0.50))
        else:
            p *= max(0.45, 1.0 + 0.18 * height_advantage(defender, shooter))

    fatigue_drag = max(0.0, (defender.minutes / 60 - 42) * 0.0015) * stamina_fatigue_multiplier(defender)
    return max(0.003, p * (1.0 - fatigue_drag))


def process_block(defender: Player, team_def: Team):
    defender.blk_stat += 1
    team_def.team_blk += 1


def process_steal(defender: Player, team_def: Team, handler: Player, team_off: Team):
    defender.stl += 1
    team_def.team_stl += 1
    team_def.last_stealer = defender
    handler.tov += 1
    team_off.team_tov += 1
    record_defensive_turnover(defender, handler)


def block_voice_line(defender: Player, shooter: Player, shot_type: str, context: str = "") -> str:
    if context == "putback":
        key = "putback"
    elif context == "transition":
        key = "transition"
    elif shot_type == "dunk":
        key = "dunk"
    elif shot_type == "post_fade":
        key = "jumper"
    elif shot_type == "post":
        key = "post"
    elif shot_type == "rim":
        key = "rim"
    else:
        key = "jumper"
    return random.choice(block_voice_lines[key]).format(
        defender=defender.name,
        shooter=shooter.name,
    )


def steal_voice_line(defender: Player, handler: Player, kind: str = "on_ball",
                     passer: Player = None, receiver: Player = None) -> str:
    key = kind if kind in steal_voice_lines else "on_ball"
    return random.choice(steal_voice_lines[key]).format(
        defender=defender.name,
        handler=handler.name,
        passer=(passer or handler).name,
        receiver=(receiver or handler).name,
    )


def register_foul(team: Team, player: Player):
    player.pf += 1
    team.team_pf += 1
    team.quarter_fouls = getattr(team, "quarter_fouls", 0) + 1


def choose_fouling_defender(team_def: Team, primary_defender: Player,
                            shooter: Player, shot_type: str,
                            context: str = "") -> Player:
    candidates = [p for p in team_def.on_floor if not p.fouled_out]
    if not candidates:
        return primary_defender

    paint_play = is_paint_shot(shot_type)
    avg_pf = sum(p.pf for p in candidates) / max(1, len(candidates))
    weights = []

    for p in candidates:
        if p is primary_defender:
            role_weight = 2.25 if not paint_play else 1.55
        elif paint_play and (can_play_position(p, "PF") or can_play_position(p, "C") or p.height >= 78):
            role_weight = 1.05
        elif paint_play:
            role_weight = 0.42
        elif p.perimeter_def >= 0.66 and (can_play_position(p, "PG") or can_play_position(p, "SG") or can_play_position(p, "SF")):
            role_weight = 0.34
        else:
            role_weight = 0.12

        if context in ("double", "paint_help", "dump_off") and p is not primary_defender:
            role_weight *= 1.35
        if context in ("switch", "mismatch_hunt") and p is primary_defender:
            role_weight *= 1.15

        foul_profile = 0.55 + foul_rate_sim(p) * 2.4
        if paint_play:
            foul_profile += p.interior_def * 0.10
        else:
            foul_profile += p.perimeter_def * 0.06

        if p.pf >= 5:
            trouble = 0.14
        elif p.pf >= 4:
            trouble = 0.30
        elif p.pf >= 3:
            trouble = 0.58
        else:
            trouble = 1.0

        spread = 1.0
        if p.pf > avg_pf:
            spread *= max(0.45, 1.0 - (p.pf - avg_pf) * 0.22)
        elif p.pf < avg_pf:
            spread *= min(1.35, 1.0 + (avg_pf - p.pf) * 0.12)

        if is_superstar(p, team_def) and p.pf >= 3:
            trouble *= 0.72

        weights.append(max(0.01, role_weight * foul_profile * trouble * spread))

    total = sum(weights)
    if total <= 0:
        return primary_defender

    r = random.random() * total
    running = 0.0
    for p, w in zip(candidates, weights):
        running += w
        if r <= running:
            return p

    return primary_defender


def in_bonus(team: Team) -> bool:
    return getattr(team, "quarter_fouls", 0) >= rules_bonus_fouls()


def update_shot_rhythm(player: Player, made: bool, shot_type: str | None = None):
    if made:
        player.hot_streak = getattr(player, "hot_streak", 0) + 1
        player.cold_streak = 0
        player.confidence = min(3.0, getattr(player, "confidence", 0.0) + 0.45)
        if shot_type in ("three", "mid"):
            player.jumper_make_streak = getattr(player, "jumper_make_streak", 0) + 1
            player.just_caught_fire = player.jumper_make_streak == 3
        else:
            player.just_caught_fire = False
    else:
        player.cold_streak = getattr(player, "cold_streak", 0) + 1
        player.hot_streak = 0
        player.confidence = max(-3.0, getattr(player, "confidence", 0.0) - 0.35)
        if shot_type in ("three", "mid"):
            player.jumper_make_streak = 0
        player.just_caught_fire = False


def clear_shot_temp_bonuses(player: Player):
    player.shot_quality_mult = 1.0
    player.shot_creator_quality_bonus = 0.0
    player.posterizer_quality_bonus = 0.0
    player.limitless_range_attempt = False
    player.heat_check_attempt = False


def maybe_crowd_moment(team: Team, opponent: Team, player: Player, points: int):
    if getattr(player, "just_caught_fire", False):
        print(f"The crowd rises as {player.name} catches fire.")
        player.just_caught_fire = False
        time.sleep(SLEEP * 0.4)
    elif getattr(team, "current_run", 0) >= 10 and random.random() < 0.35:
        print(f"{team.name} have the building buzzing after that run.")
        time.sleep(SLEEP * 0.4)


def maybe_defensive_adjustment(defending_team: Team, scorer: Player):
    styles = getattr(defending_team, "coach_style", {})
    coach_iq = styles.get("coach_iq", 0.62)
    matchup_adjustment = styles.get("matchup_adjustment", 1.0)
    trigger_score = 12 if coach_iq >= 0.72 else 16
    already_focused = getattr(defending_team, "defensive_focus", None) == scorer.name
    scoring_pressure = star_scoring_pressure(scorer)
    star_heat = scorer.pts >= trigger_score and getattr(scorer, "hot_streak", 0) >= 2
    star_problem = scorer.pts >= 10 and scoring_pressure >= 0.58 and scorer.fga >= 5

    if (star_heat or star_problem) and not already_focused:
        chance = min(0.82, 0.22 + coach_iq * 0.42 + matchup_adjustment * 0.12)
        if random.random() >= chance:
            return
        defending_team.defensive_focus = scorer.name
        plan = getattr(defending_team, "game_plan", {})
        plan["star_target"] = scorer.name
        plan["star_coverage"] = coverage_plan_for_star(scorer)
        plan["defense"] = "load_star"
        defending_team.game_plan = plan
        defending_team.double_team_cooldown = 0
        possible_stoppers = [p for p in defending_team.on_floor if not p.fouled_out]
        stopper = max(possible_stoppers, key=lambda p: defensive_matchup_score(p, scorer), default=None)
        if stopper:
            if plan["star_coverage"] == "trap_force_pass":
                print(f"{defending_team.name} adjust defensively, putting {stopper.name} on {scorer.name} and showing early traps.")
            elif plan["star_coverage"] in ("early_double", "late_double_rotate"):
                print(f"{defending_team.name} adjust defensively, putting {stopper.name} on {scorer.name} with help loaded behind it.")
            else:
                print(f"{defending_team.name} adjust defensively, putting {stopper.name} on {scorer.name} as the primary matchup.")
        else:
            print(f"{defending_team.name} adjust defensively and load up on {scorer.name}.")
        time.sleep(SLEEP * 0.5)


def maybe_technical_foul(team: Team, opponent: Team, period: int, period_time: int,
                         teamA: Team, teamB: Team, reason: str = "arguing the call"):
    if getattr(team, "tech_cooldown", 0) > 0:
        team.tech_cooldown -= 1
        return

    if random.random() > 0.012:
        return

    candidates = [p for p in team.on_floor if not p.fouled_out]
    shooter = max(opponent.on_floor, key=lambda p: p.ft_rating)
    offender = random.choice(candidates) if candidates else None
    team.tech_cooldown = 8

    if offender:
        print(f"Technical foul on {offender.name} for {reason}.")
    else:
        print(f"Technical foul on {team.name} for {reason}.")
    time.sleep(SLEEP * 0.5)
    shoot_retained_free_throw(shooter, opponent, period, period_time, teamA, teamB, label="technical free throw")


def maybe_challenge_call(challenging_team: Team, call_text: str) -> bool:
    if not getattr(challenging_team, "challenge_available", True):
        return False
    if random.random() > 0.08:
        return False

    challenging_team.challenge_available = False
    print(f"{challenging_team.name} challenge the call: {call_text}")
    time.sleep(SLEEP * 0.6)

    overturned = random.random() < 0.38
    if overturned:
        print("After review, the call is overturned.")
    else:
        print("After review, the call stands.")
        if challenging_team.timeouts > 0:
            challenging_team.timeouts -= 1
            print(f"{challenging_team.name} lose a timeout. Timeouts left: {challenging_team.timeouts}.")
    time.sleep(SLEEP * 0.6)
    return overturned


def shot_quality(shooter: Player, defender: Player, shot_type: str, period: int, period_time: int) -> Tuple[str, float]:
    if is_paint_shot(shot_type):
        pressure = defender.interior_def
    else:
        pressure = defender.perimeter_def

    late_clock = period_time % 24 <= 4 and period_time > 4
    creation = 0.5 * shooter.ball_handle + 0.35 * shooter.playmaking + 0.15 * shooter.usage
    handle_creation = max(0.0, shooter.ball_handle - 0.76)
    if shot_type in ("three", "mid", "post_fade"):
        creation += handle_creation * 0.30
        if "shot_creator" in getattr(shooter, "badges", ()):
            creation += handle_creation * 0.14
        if badge_tier(shooter, "ankle_breaker") > 0:
            creation += handle_creation * (0.08 + badge_tier(shooter, "ankle_breaker") * 0.025)
    elif shot_type in ("rim", "dunk"):
        creation += handle_creation * 0.12
    score = creation - pressure * 1.08 - 0.12 * height_advantage(defender, shooter)
    score += max(0.0, shooter.shot_iq - 0.74) * 0.06
    score -= max(0.0, 0.70 - shooter.shot_iq) * 0.25

    if late_clock:
        return "late-clock forced", 0.86 + max(0.0, shooter.shot_iq - 0.74) * 0.04 - max(0.0, 0.58 - shooter.shot_iq) * 0.06
    if shooter.usage < 0.16 and shooter.shot_iq < 0.68 and score < 0.08:
        return "rushed role-player look", 0.88 - max(0.0, 0.68 - shooter.shot_iq) * 0.08
    elite_handle = shooter.ball_handle >= 0.88 and shot_type in ("three", "mid")
    if elite_handle and score >= 0.18:
        handle_bonus = max(0.0, shooter.ball_handle - 0.82) * 0.11
        return "wide open", 1.18 + handle_bonus + max(0.0, shooter.shot_iq - 0.84) * 0.035
    if score >= 0.28:
        handle_bonus = max(0.0, shooter.ball_handle - 0.82) * 0.10 if shot_type in ("three", "mid") else 0.0
        return "wide open", 1.18 + handle_bonus + max(0.0, shooter.shot_iq - 0.84) * 0.035
    if elite_handle and score >= -0.14:
        handle_bonus = max(0.0, shooter.ball_handle - 0.84) * 0.07
        return "lightly contested", 0.97 + handle_bonus + max(0.0, shooter.shot_iq - 0.84) * 0.01 - max(0.0, 0.58 - shooter.shot_iq) * 0.02
    if score >= 0.06:
        handle_bonus = max(0.0, shooter.ball_handle - 0.84) * 0.06 if shot_type in ("three", "mid") else 0.0
        return "lightly contested", 0.97 + handle_bonus + max(0.0, shooter.shot_iq - 0.84) * 0.01 - max(0.0, 0.58 - shooter.shot_iq) * 0.02
    if score <= -0.28:
        return "smothered", 0.76 - max(0.0, 0.70 - shooter.shot_iq) * 0.08
    return "tightly contested", 0.89 + max(0.0, shooter.shot_iq - 0.84) * 0.01 - max(0.0, 0.60 - shooter.shot_iq) * 0.04


def signature_move_line(player: Player, shot_type: str, context: str | None = None):
    signatures = {
        
    }
    if player.name in signatures and random.random() < 0.28:
        return signatures[player.name]
    offball_contexts = {
        "catch_shoot", "pnr_catch_shoot", "double_wide_open", "extra_pass_open",
        "late_catch_shoot", "late_oreb_kickout"
    }
    if (
        "movement_shooter" in player.badges
        and shot_type == "three"
        and context in offball_contexts
        and random.random() < 0.18
    ):
        return "sprints off a screen and catches in rhythm."
    if "lob_threat" in player.badges and shot_type == "dunk" and random.random() < 0.18:
        return "loads up above the rim as the pass arrives."
    return None


def maybe_injury_stinger(player: Player, team: Team, shot_type: str, period: int):
    if period < 2 or getattr(player, "injury_limited", False):
        return
    if shot_type not in ("rim", "dunk") or random.random() > 0.006:
        return
    player.injury_limited = True
    print(f"{player.name} comes up a little slow after the contact and will be watched by the bench.")
    time.sleep(SLEEP * 0.6)


def run_inbound_play(off: Team, dff: Team, period: int, period_time: int,
                     teamA: Team, teamB: Team, matchups: Dict[Player, Player]) -> Tuple[Team, int] | None:
    if not getattr(off, "inbound_pending", False):
        return None

    late_ato = period >= 4 and period_time <= 30 and abs(off.score - dff.score) <= 4
    after_timeout = bool(getattr(off, "ato_pending", False))
    # A scripted inbound play doesn't have to happen every time:
    #  - with 5-24 seconds left it's just a normal pass into the last shot
    #    (the late-game / end-of-quarter possession logic takes over), and
    #  - an ordinary dead-ball inbound is usually just a plain inbound pass
    #    into a normal possession; only sometimes is it a drawn-up play.
    #    Timeouts and late close games still get the drawn-up play.
    if 5 <= period_time <= 24 or (not after_timeout and not late_ato and random.random() >= 0.25):
        off.inbound_pending = False
        off.ato_pending = False
        return None

    off.inbound_pending = False
    ato_boost = after_timeout
    off.ato_pending = False
    inbounder = max(off.on_floor, key=lambda p: p.playmaking)
    low_clock_inbound = period_time <= 8 or late_ato
    spent = min(period_time, 1 if low_clock_inbound else random.randint(2, 4))
    score_time = max(0, period_time - spent)
    need_three = late_ato and off.score <= dff.score - 3
    need_quick_two = late_ato and off.score in (dff.score - 1, dff.score - 2)

    # Inbound plays are drawn up for one of two looks: a three, or a lob
    # for an alley-oop. Pick the best shooter for the first and the best
    # lob finisher for the second.
    others = [p for p in off.on_floor if p is not inbounder] or list(off.on_floor)
    three_targets = sorted(
        [p for p in others if p.three_tendency > 0] or others,
        key=lambda p: 0.52 * p.three_rating + 0.26 * p.clutchness + 0.22 * p.shot_tendency,
        reverse=True,
    )
    lob_targets = sorted(
        others,
        key=lambda p: 0.50 * p.dunk_rating + 0.30 * p.rim_rating + 0.20 * p.dunk_tendency,
        reverse=True,
    )
    if need_three:
        inbound_play = "three"
    elif need_quick_two:
        inbound_play = "alley_oop"
    else:
        lob_quality = 0.50 * lob_targets[0].dunk_rating + 0.30 * lob_targets[0].rim_rating + 0.20 * lob_targets[0].dunk_tendency
        lob_chance = clamp(0.20 + (lob_quality - 0.50), 0.10, 0.60)
        inbound_play = "alley_oop" if random.random() < lob_chance else "three"
    target = lob_targets[0] if inbound_play == "alley_oop" else three_targets[0]
    defender = matchups.get(target, random.choice(dff.on_floor))

    if need_three:
        lines = [
            f"{off.name} space the floor for a quick three. {target.name} breaks toward the arc.",
            f"{inbounder.name} waits for the screen-the-screener action and finds {target.name} outside.",
            f"{off.name} use {target.name} as the late clock shooter off the inbound."
        ]
    elif inbound_play == "alley_oop":
        lines = [
            f"{off.name} run a lob out of the inbound. {target.name} cuts backdoor toward the rim.",
            f"{inbounder.name} looks for the lob on the sideline inbound as {target.name} sprints to the rim.",
            f"{off.name} stack the lane on the inbound, trying to spring {target.name} for an alley-oop.",
            f"{off.name} clear the strong side and free {target.name} above the rim for the lob.",
        ]
    else:
        lines = [
            f"{off.name} run a sideline inbound. {target.name} curls off a screen toward the arc.",
            f"{inbounder.name} scans the floor on the inbound and looks for {target.name} on the perimeter.",
            f"{off.name} flare {target.name} to the wing off the inbound for a three.",
        ]
    if ato_boost:
        lines.extend([
            f"{off.name} use the timeout to disguise the inbound action for {target.name}.",
            f"{target.name} breaks free out of the timeout set as {inbounder.name} waits him out.",
        ])
    print(random.choice(lines))
    time.sleep(SLEEP * 0.6)

    if random.random() < pass_interception_chance(inbounder, target, defender) * 0.8:
        process_steal(defender, dff, inbounder, off)
        print(f"{defender.name} blows up the inbound play and steals it.")
        time.sleep(SLEEP * 0.6)
        return dff, spent

    if inbound_play == "alley_oop":
        shot_type = "dunk"
        lob_passes = [line for line in alley_oop_passes if "roller" not in line]
        print(f"{inbounder.name} {random.choice(lob_passes)} {target.name}" + ("" if target.name.endswith(".") else "."))
        time.sleep(SLEEP * 0.4)
        print(f"{target.name} {random.choice(alley_oop_catches)}.")
        time.sleep(SLEEP * 0.3)
        print(f"{target.name} {random.choice(alley_oop_finish_attempts)}.")
    else:
        shot_type = "three"
        if low_clock_inbound:
            print(f"{target.name} catches, turns, and lets the three go.")
        else:
            print(f"{target.name} catches and fires out of the inbound action.")
    time.sleep(SLEEP * 0.5)

    target.fga += 1
    q_label, q_mult = shot_quality(target, defender, shot_type, period, score_time)
    if ato_boost:
        q_mult = max(q_mult, 1.08 + getattr(off, "coach_style", {}).get("coach_iq", 0.62) * 0.07)
    target.shot_quality_mult = q_mult
    record_shot_diet(off, shot_type, shot_quality_diet_context("inbound", q_label), target, defender)
    if shot_type == "three":
        target.tpa += 1
    made = random.random() < shot_make_prob(target, defender, shot_type, off, dff, period, score_time)
    clear_shot_temp_bonuses(target)

    if made:
        pts = 3 if shot_type == "three" else 2
        target.fgm += 1
        target.pts += pts
        record_shot_make(off, shot_type, shot_quality_diet_context("inbound", q_label), target, defender)
        if shot_type == "three":
            target.tpm += 1
        off.score += pts
        if shot_type in ("rim", "dunk"):
            off.points_paint += pts
        record_score_event(off, dff, pts, period, score_time, teamA, teamB, check_timeout=False)
        record_assist(inbounder, off, pts)
        if inbound_play == "alley_oop":
            print(f"{target.name} {random.choice(alley_oop_makes)}")
        else:
            print(f"{target.name} converts the inbound set, exactly what they drew up.")
        print_scoreboard(period, score_time, teamA, teamB)
        maybe_call_timeout_after_score(off, dff, period, score_time, teamA, teamB)
        return dff, spent

    if inbound_play == "alley_oop":
        print(f"{target.name} {random.choice(alley_oop_misses)}")
    else:
        print(f"{target.name} cannot finish the inbound look.")
    reb_team, rebounder = choose_rebounder(off, dff, "jumper" if shot_type == "three" else "rim")
    print(commentator_rebound(rebounder.name, reb_team.name))
    print_scoreboard(period, score_time, teamA, teamB)
    if reb_team is off:
        off.frontcourt_after_oreb = True
    return reb_team, spent


def maybe_sit_foul_trouble(team: Team, player: Player, period: int):
    thresholds = {1: 2, 2: 3, 3: 4}
    locked_until = foul_rest_until_period(player, period)
    if locked_until is not None:
        player.foul_rest_until = max(getattr(player, "foul_rest_until", 0), locked_until)

    if period not in thresholds or player.pf < thresholds[period]:
        return
    if player not in team.on_floor or player.fouled_out or not team.bench:
        return
    if getattr(team, "garbage_time_locked", False):
        return

    replacement = max(
        [p for p in team.bench if not p.fouled_out and not is_foul_rest_locked(p, period)],
        key=overall_rating,
        default=None
    )
    if replacement is None:
        return

    idx = team.on_floor.index(player)
    team.on_floor[idx] = replacement
    team.bench.remove(replacement)
    team.bench.append(player)
    balance_lineup_positions(team)
    print(f"{team.name} protect {player.name} with {player.pf} fouls; {replacement.name} comes in to steady the rotation.")
    time.sleep(SLEEP * 0.6)


def handle_offensive_rebound(off: Team, dff: Team, rebounder: Player,
                             period: int, period_time: int,
                             teamA: Team, teamB: Team) -> Tuple[Team, int]:
    """
    Resolve an offensive board immediately so the next line does not restart
    at halfcourt. Returns next possession and extra seconds used.
    """
    if period_time <= 10:
        spent = min(period_time, random.randint(1, 3) if period_time <= 5 else random.randint(2, 4))
        score_time = max(0, period_time - spent)

        putback_chance = 0.44 + rebounder.oreb * 0.85 + rebounder.rim_rating * 0.16
        putback_chance = min(0.82, putback_chance)
        need_three = off.score <= dff.score - 3
        late_need_score = period >= 4 and off.score < dff.score

        if not need_three and random.random() < putback_chance:
            defender = random.choice(dff.on_floor)
            putback_type = "dunk" if random.random() < effective_dunk_attempt_chance(rebounder) else "rim"

            print(f"{rebounder.name} {random.choice(oreb_putback_lines)} with the clock almost gone.")
            time.sleep(SLEEP * 0.45)

            rebounder.fga += 1
            record_shot_diet(off, putback_type, "late_putback|contested", rebounder, defender)

            if random.random() < block_prob(defender, putback_type, rebounder):
                print(block_voice_line(defender, rebounder, putback_type, "late_putback"))
                process_block(defender, dff)
                time.sleep(SLEEP * 0.45)
                next_reb_team, next_rebounder = choose_rebounder(off, dff, "rim")
                print(f"{next_rebounder.name} controls the rebound as the clock keeps running.")
                print_scoreboard(period, score_time, teamA, teamB)
                if next_reb_team is off:
                    off.frontcourt_after_oreb = True
                return (off if next_reb_team is off else dff), spent

            make_prob = shot_make_prob(rebounder, defender, putback_type, off, dff, period, period_time)
            if random.random() < make_prob:
                rebounder.fgm += 1
                rebounder.pts += 2
                record_shot_make(off, putback_type, "late_putback|contested", rebounder, defender)
                off.score += 2
                off.points_paint += 2
                off.second_chance_pts += 2
                record_score_event(off, dff, 2, period, score_time, teamA, teamB, check_timeout=False)

                print(f"{rebounder.name} converts the quick second-chance look.")
                time.sleep(SLEEP * 0.55)
                print_scoreboard(period, score_time, teamA, teamB)
                maybe_call_timeout_after_score(off, dff, period, score_time, teamA, teamB)
                return dff, spent

            print(f"{rebounder.name} cannot get the putback to fall.")
            time.sleep(SLEEP * 0.45)
            next_reb_team, next_rebounder = choose_rebounder(off, dff, "rim")
            print(f"{next_rebounder.name} comes down with it as the clock keeps running.")
            print_scoreboard(period, score_time, teamA, teamB)
            if next_reb_team is off:
                off.frontcourt_after_oreb = True
            return (off if next_reb_team is off else dff), spent

        kickout_options = [p for p in off.on_floor if p is not rebounder]
        if need_three:
            shooters = [p for p in kickout_options if p.three_tendency > 0 and p.three_rating >= 0.70]
            if shooters:
                kickout_options = shooters
        receiver = max(
            kickout_options or [rebounder],
            key=lambda p: (
                (0.60 * p.three_rating if need_three else 0.32 * p.three_rating)
                + 0.28 * p.mid_rating
                + 0.18 * p.shot_tendency
                + 0.12 * p.clutchness
            )
        )
        defender = matchups_defender_for_player(dff, receiver) if "matchups_defender_for_player" in globals() else random.choice(dff.on_floor)
        shot_type = "three" if need_three or (late_need_score and period_time <= 5 and receiver.three_rating >= 0.76) else choose_shot_type(receiver, defender, off, dff, period, period_time)
        if shot_type in ("post", "dunk"):
            shot_type = "rim"

        late_kickout_lines = [
            "{rebounder} grabs the offensive board and fires it straight to {receiver}.",
            "{rebounder} keeps it alive and finds {receiver} with no time to waste.",
            "{rebounder} rips it down and snaps the pass out to {receiver}.",
            "{rebounder} wins the rebound and immediately kicks to {receiver}.",
            "{rebounder} saves the possession and hits {receiver} for the quick look.",
        ]
        print(random.choice(late_kickout_lines).format(rebounder=rebounder.name, receiver=receiver.name))
        time.sleep(SLEEP * 0.45)
        if shot_type == "three":
            print(f"{receiver.name} catches behind the arc and fires before the defense can load up.")
        elif shot_type == "mid":
            print(f"{receiver.name} steps into the quick second-chance jumper.")
        else:
            print(f"{receiver.name} attacks the open lane before the defense can reset.")
        time.sleep(SLEEP * 0.45)

        receiver.shot_quality_mult = getattr(receiver, "shot_quality_mult", 1.0) * 1.12
        make_prob = shot_make_prob(receiver, defender, shot_type, off, dff, period, period_time)
        clear_shot_temp_bonuses(receiver)

        receiver.fga += 1
        if shot_type == "three":
            receiver.tpa += 1
        record_shot_diet(off, shot_type, "late_oreb_kickout|wide_open", receiver, defender)

        if random.random() < make_prob:
            pts = 3 if shot_type == "three" else 2
            receiver.fgm += 1
            receiver.pts += pts
            if shot_type == "three":
                receiver.tpm += 1
            off.score += pts
            if shot_type == "rim":
                off.points_paint += 2
            off.second_chance_pts += pts
            record_shot_make(off, shot_type, "late_oreb_kickout|open", receiver, defender)
            if receiver is not rebounder:
                record_assist(rebounder, off, pts)
            record_score_event(off, dff, pts, period, score_time, teamA, teamB, check_timeout=False)
            print(f"{receiver.name} cashes the quick second-chance shot.")
            time.sleep(SLEEP * 0.55)
            print_scoreboard(period, score_time, teamA, teamB)
            maybe_call_timeout_after_score(off, dff, period, score_time, teamA, teamB)
            return dff, spent

        print(f"{receiver.name}'s quick second-chance look is off.")
        time.sleep(SLEEP * 0.45)
        miss_kind = "rim" if shot_type == "rim" else "jumper"
        next_reb_team, next_rebounder = choose_rebounder(off, dff, miss_kind)
        print(f"{next_rebounder.name} secures the rebound as the final seconds drain.")
        print_scoreboard(period, score_time, teamA, teamB)
        if next_reb_team is off:
            off.frontcourt_after_oreb = True
        return (off if next_reb_team is off else dff), spent

    extra_time = random.randint(2, 5)
    score_time = max(0, period_time - extra_time)
    putback_chance = 0.40 + rebounder.oreb * 0.90 + rebounder.rim_rating * 0.12
    putback_chance = min(0.78, putback_chance)

    if random.random() >= putback_chance:
        receiver = choose_shooter_excluding(off, rebounder)
        print(random.choice(oreb_kickout_lines).format(rebounder=rebounder.name, receiver=receiver.name))
        time.sleep(SLEEP * 0.7)
        print(random.choice(oreb_reset_lines).format(handler=receiver.name, team=off.name))
        off.reset_after_oreb = True
        print_scoreboard(period, score_time, teamA, teamB)
        return off, extra_time

    defender = random.choice(dff.on_floor)
    putback_type = "dunk" if random.random() < effective_dunk_attempt_chance(rebounder) else "rim"

    print(f"{rebounder.name} {random.choice(oreb_putback_lines)}.")
    time.sleep(SLEEP * 0.6)

    rebounder.fga += 1
    record_shot_diet(off, putback_type, "putback|contested", rebounder, defender)

    if random.random() < block_prob(defender, putback_type, rebounder):
        print(block_voice_line(defender, rebounder, putback_type, "putback"))
        process_block(defender, dff)
        time.sleep(SLEEP * 0.6)

        next_reb_team, next_rebounder = choose_rebounder(off, dff, "rim")
        print(f"{next_rebounder.name} controls the rebound after the block.")
        print_scoreboard(period, score_time, teamA, teamB)
        return (off if next_reb_team is off else dff), extra_time

    make_prob = shot_make_prob(rebounder, defender, putback_type, off, dff, period, period_time)

    if random.random() < make_prob:
        rebounder.fgm += 1
        rebounder.pts += 2
        record_shot_make(off, putback_type, "putback|contested", rebounder, defender)
        off.score += 2
        off.points_paint += 2
        off.second_chance_pts += 2
        record_score_event(off, dff, 2, period, score_time, teamA, teamB, check_timeout=False)

        if putback_type == "dunk":
            print(f"{rebounder.name} slams home the putback.")
        else:
            print(f"{rebounder.name} lays in the second-chance bucket.")

        time.sleep(SLEEP * 0.7)
        print_scoreboard(period, score_time, teamA, teamB)
        maybe_call_timeout_after_score(off, dff, period, score_time, teamA, teamB)
        return dff, extra_time

    print(f"{rebounder.name} misses the quick putback.")
    time.sleep(SLEEP * 0.6)

    next_reb_team, next_rebounder = choose_rebounder(off, dff, "rim")
    print(f"{next_rebounder.name} comes away with the rebound.")
    print_scoreboard(period, score_time, teamA, teamB)
    return (off if next_reb_team is off else dff), extra_time



def shoot_free_throws(shooter: Player, team: Team, n: int, period: int, period_time: int,
                      teamA: Team, teamB: Team, sub_after_first: bool = False,
                      protected: Player = None) -> Team:
    defense = teamB if team is teamA else teamA
    protected = protected or shooter
    previous_free_throw_shooter = getattr(team, "free_throw_shooter", None)
    team.free_throw_shooter = shooter

    def finish_free_throw_trip(next_team: Team) -> Team:
        if previous_free_throw_shooter is None:
            if getattr(team, "free_throw_shooter", None) is shooter:
                delattr(team, "free_throw_shooter")
        else:
            team.free_throw_shooter = previous_free_throw_shooter
        return next_team

    for i in range(n):
        is_final_ft = (i == n - 1)
        intentional_miss = (
            is_final_ft and period >= 4 and period_time <= 4
            and 1 <= team.score - defense.score <= 2
            and getattr(defense, "timeouts", 0) <= 0
        )

        shooter.fta += 1
        ft_rating = effective_ft_rating(shooter, team, defense, period, period_time)
        made = False if intentional_miss else random.random() < ft_rating

        if made:
            shooter.ftm += 1
            shooter.pts += 1
            team.score += 1
            record_score_event(team, defense, 1, period, period_time, teamA, teamB)

            print(f"{shooter.name} is good at the line.")
            time.sleep(SLEEP * 0.4)
            print_scoreboard(period, period_time, teamA, teamB)
            time.sleep(SLEEP * 0.5)

            if sub_after_first and i == 0 and n > 1:
                dead_ball_subs(
                    teamA, teamB, period, period_time,
                    protected_teamA=(protected or shooter) if team is teamA else None,
                    protected_teamB=(protected or shooter) if team is teamB else None,
                )

            if is_final_ft:
                return finish_free_throw_trip(defense)

        else:
            if intentional_miss:
                print(f"{shooter.name} intentionally misses the free throw to burn the final seconds.")
            else:
                print(f"{shooter.name} leaves the free throw short.")
            time.sleep(SLEEP * 0.4)
            print_scoreboard(period, period_time, teamA, teamB)
            time.sleep(SLEEP * 0.5)

            if sub_after_first and i == 0 and n > 1:
                dead_ball_subs(
                    teamA, teamB, period, period_time,
                    protected_teamA=(protected or shooter) if team is teamA else None,
                    protected_teamB=(protected or shooter) if team is teamB else None,
                )

            if is_final_ft:
                reb_team, rebounder = choose_rebounder(team, defense, "jumper")
                print(commentator_rebound(rebounder.name, reb_team.name))
                time.sleep(SLEEP * 0.6)
                print_scoreboard(period, period_time, teamA, teamB)
                if reb_team is team:
                    next_team, _ = handle_offensive_rebound(team, defense, rebounder, period, period_time, teamA, teamB)
                    return finish_free_throw_trip(next_team)
                return finish_free_throw_trip(reb_team)

    return finish_free_throw_trip(defense)


def shoot_retained_free_throw(shooter: Player, team: Team, period: int, period_time: int,
                              teamA: Team, teamB: Team, label: str = "free throw"):
    defense = teamB if team is teamA else teamA

    shooter.fta += 1
    made = random.random() < effective_ft_rating(shooter, team, defense, period, period_time)

    if made:
        shooter.ftm += 1
        shooter.pts += 1
        team.score += 1
        record_score_event(team, defense, 1, period, period_time, teamA, teamB)
        print(f"{shooter.name} knocks down the {label}.")
    else:
        print(f"{shooter.name} cannot cash the {label}.")

    time.sleep(SLEEP * 0.5)
    print_scoreboard(period, period_time, teamA, teamB)
    time.sleep(SLEEP * 0.5)


def end_of_quarter_heave(off: Team, dff: Team, period: int, period_time: int,
                         teamA: Team, teamB: Team):
    sorted_pm = sorted(
        off.on_floor,
        key=lambda p: 0.6 * p.ball_handle + 0.25 * p.playmaking + 0.15 * p.usage,
        reverse=True
    )
    ballhandlers = sorted_pm[:2] if len(sorted_pm) >= 2 else sorted_pm
    shooter = random.choice(ballhandlers)
    print(f"Clock winding down... {shooter.name} brings it up and has to heave from half court.")
    time.sleep(SLEEP * 0.5)

    defender = random.choice(dff.on_floor)
    heave_prob = 0.01 + shooter.three_rating * 0.04
    heave_prob = max(0.01, min(0.07, heave_prob))
    if random.random() < heave_prob:
        shooter.fga += 1
        record_shot_diet(off, "three", "heave|contested", shooter, defender)
        record_shot_make(off, "three", "heave|contested", shooter, defender)
        shooter.fgm += 1
        shooter.tpa += 1
        shooter.tpm += 1
        shooter.pts += 3
        off.score += 3
        record_score_event(off, dff, 3, period, 0, teamA, teamB)

        print_scoreboard(period, 0, teamA, teamB)
        print(f"{shooter.name} drills the half-court heave at the buzzer.")
    else:
        print_scoreboard(period, 0, teamA, teamB)
        print(f"{shooter.name}'s half-court heave is off the mark. It won't count against his stats.")
    time.sleep(SLEEP * 0.9)


def end_of_quarter_catch_shoot_three(off: Team, dff: Team, period: int, period_time: int,
                                     teamA: Team, teamB: Team):
    inbounder = choose_ballhandler(off)
    shooters = [
        p for p in off.on_floor
        if p is not inbounder and p.three_tendency > 0 and p.three_rating >= 0.74
    ]
    if not shooters:
        shooters = [p for p in off.on_floor if p is not inbounder] or list(off.on_floor)

    shooter = max(
        shooters,
        key=lambda p: (
            0.58 * p.three_rating + 0.22 * p.shot_tendency + 0.12 * p.clutchness + 0.08 * p.speed
        ) * catch_shoot_receiver_factor(p)
    )
    defender = random.choice(dff.on_floor)

    inbound_context = (
        getattr(off, "inbound_pending", False)
        or getattr(off, "ato_pending", False)
        or getattr(off, "late_timeout_advance", False)
    )
    if inbound_context:
        lines = [
            f"{off.name} get into a quick sideline action with {period_time} seconds left.",
            f"{inbounder.name} triggers it quickly as {shooter.name} sprints off the screen.",
            f"{shooter.name} curls into space and catches beyond the arc.",
            f"{inbounder.name} finds {shooter.name} for the catch-and-shoot three.",
        ]
    else:
        lines = [
            f"{off.name} push it live with {period_time} seconds left and no timeout advance.",
            f"{inbounder.name} races it over halfcourt as {shooter.name} fills the open side.",
            f"{shooter.name} gets his feet set above the arc.",
            f"{inbounder.name} hits {shooter.name} for the quick catch-and-shoot three.",
        ]
    for line in lines:
        print(line)
        time.sleep(SLEEP * 0.35)

    shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * (1.18 + catch_shoot_badge_quality_bonus(shooter))
    make_prob = shot_make_prob(shooter, defender, "three", off, dff, period, period_time)
    clear_shot_temp_bonuses(shooter)

    shooter.fga += 1
    shooter.tpa += 1
    record_shot_diet(off, "three", "late_catch_shoot|contested", shooter, defender)

    made = random.random() < make_prob
    if made:
        shooter.fgm += 1
        shooter.tpm += 1
        shooter.pts += 3
        off.score += 3
        record_shot_make(off, "three", "late_catch_shoot|contested", shooter, defender)
        if inbounder is not shooter:
            record_assist(inbounder, off, 3)
        record_score_event(off, dff, 3, period, 0, teamA, teamB)
        print_scoreboard(period, 0, teamA, teamB)
        print(f"{shooter.name} buries the catch-and-shoot three before the horn.")
    else:
        print_scoreboard(period, 0, teamA, teamB)
        print(f"{shooter.name}'s catch-and-shoot three at the horn is off.")
    time.sleep(SLEEP * 0.9)


def should_take_late_game_last_shot(off: Team, dff: Team, period: int, period_time: int) -> bool:
    if period < 4:
        return False
    if period_time < 18 or period_time > 30:
        return False
    deficit = dff.score - off.score
    # Tied: hold for a winner. Down 1-3: hold for a tying or winning shot.
    return 0 <= deficit <= 3


def run_late_game_last_shot_possession(off: Team, dff: Team, period: int, period_time: int,
                                       teamA: Team, teamB: Team,
                                       matchups: Dict[Player, Player]) -> Tuple[Team, int]:
    deficit = dff.score - off.score
    need_three = deficit == 3
    # The shot clock only turns off once under 24 seconds remain in the
    # period -- that's the only case where holding for the game clock's
    # entire remaining time is legal. With more than 24 on the clock, the
    # offense still has to get a shot up within 24 seconds of taking the
    # ball, so at least (period_time - 24) has to be left when it goes up.
    if period_time > 24:
        score_time = max(0, period_time - 24) + (random.randint(0, 2) if period_time >= 20 else random.randint(0, 1))
    else:
        score_time = random.randint(0, 2) if period_time >= 20 else random.randint(0, 1)
    spent = max(1, period_time - score_time)

    shooter = choose_closing_star_scorer(off, need_three=need_three)
    handler = choose_closing_initiator(off, shooter)
    last_passer = None

    if deficit == 0:
        print(f"{off.name} can take the last shot. {handler.name} walks it up and lets the clock bleed.")
    elif deficit == 3:
        print(f"{off.name} need a three to stay alive. {handler.name} brings it up and lets the clock become part of the pressure.")
    else:
        print(f"{off.name} can tie or win it here. {handler.name} holds for the final possession.")
    time.sleep(SLEEP)

    if handler is not shooter and random.random() < 0.68:
        pass_lines = [
            f"{handler.name} waits until the clock gets low and gives it to {shooter.name}.",
            f"{handler.name} points everyone through, then hits {shooter.name} coming to the ball.",
            f"{handler.name} draws the first defender up and delivers to {shooter.name}.",
        ]
        print(random.choice(pass_lines))
        time.sleep(SLEEP)
        last_passer = handler
    else:
        iso_lines = [
            f"{shooter.name} waves everyone flat and keeps the matchup for himself.",
            f"{shooter.name} pounds one controlled dribble as the building starts to rise.",
            f"{shooter.name} sizes up the defender, eyes locked on the clock, and goes into the final move.",
            f"{shooter.name} calls his own number with the game on the line.",
            f"{shooter.name} wants this shot and clears out the strong side.",
            f"{shooter.name} takes a deep breath and isolates on the wing.",
            f"{shooter.name} stares down the defense before starting his move.",
            f"{shooter.name} slows the pace to a crawl with the clock ticking.",
            f"{shooter.name} signals for everyone to clear out and get out of the way.",
            f"{shooter.name} puts the ball on the floor, feeling out the moment.",
            f"{shooter.name} settles into his stance, locked in on the closer's shot.",
            f"{shooter.name} backs his defender down with the season on the line.",
            f"{shooter.name} takes the moment head-on and starts his isolation.",
            f"{shooter.name} rocks the dribble, waiting for the right window.",
            f"{shooter.name} shows no hesitation stepping into the biggest shot of the game.",
            f"{shooter.name} calls for the ball, knowing exactly what's coming.",
            f"{shooter.name} eyes the defender, ready to make the read.",
            f"{shooter.name} takes his time, letting the clock bleed down.",
            f"{shooter.name} squares up, fully aware of the stakes.",
            f"{shooter.name} clears the paint and goes to work in isolation.",
            f"{shooter.name} sets his feet and stares into the defender's eyes.",
            f"{shooter.name} pounds the air out of the ball before attacking.",
            f"{shooter.name} locks in, knowing the whole building is watching.",
        ]
        print(random.choice(iso_lines))
        time.sleep(SLEEP)

    defender = matchups.get(shooter, random.choice(dff.on_floor))
    if need_three:
        shot_type = "three" if shooter.three_tendency > 0 else choose_shot_type(shooter, defender, off, dff, period, score_time)
    elif deficit in (1, 2):
        if shooter.drive_tendency > 0 and random.random() < 0.52:
            shot_type = "rim"
        else:
            shot_type = choose_shot_type(shooter, defender, off, dff, period, score_time)
    else:
        shot_type = choose_shot_type(shooter, defender, off, dff, period, score_time)

    if shot_type == "rim" and random.random() < effective_dunk_attempt_chance(shooter):
        shot_type = "dunk"

    print_late_clock_shot_attempt(shooter, shot_type, assisted=bool(last_passer))
    time.sleep(SLEEP * 0.8)

    foul_chance = foul_draw_sim(shooter) * usage_foul_weight(shooter) * FOUL_SCALE
    foul_chance *= shooting_foul_type_multiplier(shot_type) * 0.82
    if random.random() < foul_chance:
        fouler = choose_fouling_defender(dff, defender, shooter, shot_type, "last_shot")
        register_foul(dff, fouler)
        shooter.fouls_drawn += 1
        off.fouls_drawn += 1
        print(f"{fouler.name} gets him on the final shot. {shooter.name} will shoot with {score_time} seconds left.")
        time.sleep(SLEEP)
        if fouler.pf >= 6:
            foul_out_sub(dff, fouler)
        n_ft = 3 if shot_type == "three" else 2
        next_possession = shoot_free_throws(
            shooter, off, n_ft, period, score_time, teamA, teamB,
            sub_after_first=True, protected=shooter
        )
        return next_possession, spent

    if random.random() < block_prob(defender, shot_type, shooter):
        shooter.fga += 1
        if shot_type == "three":
            shooter.tpa += 1
        record_shot_diet(off, shot_type, "last_shot|contested", shooter, defender, quality_mult=0.90)
        print(block_voice_line(defender, shooter, shot_type))
        process_block(defender, dff)
        time.sleep(SLEEP)
        if score_time <= 1:
            print_scoreboard(period, score_time, teamA, teamB)
            return dff, spent
        reb_team, rebounder = choose_rebounder(off, dff, "rim" if is_paint_shot(shot_type) else "jumper")
        print(f"{rebounder.name} controls the rebound as the clock expires.")
        print_scoreboard(period, score_time, teamA, teamB)
        return (off if reb_team is off else dff), spent

    q_label, q_mult = shot_quality(shooter, defender, shot_type, period, score_time)
    context = "last_shot|wide_open" if q_label == "wide open" else "last_shot|contested"
    shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * q_mult
    make_prob = shot_make_prob(shooter, defender, shot_type, off, dff, period, score_time)
    final_quality_mult = getattr(shooter, "shot_quality_mult", q_mult)
    clear_shot_temp_bonuses(shooter)

    shooter.fga += 1
    if shot_type == "three":
        shooter.tpa += 1
    record_shot_diet(off, shot_type, context, shooter, defender, quality_mult=final_quality_mult)

    if random.random() < make_prob:
        pts = 3 if shot_type == "three" else 2
        score_before = off.score
        shooter.fgm += 1
        shooter.pts += pts
        if shot_type == "three":
            shooter.tpm += 1
        off.score += pts
        if is_paint_shot(shot_type):
            off.points_paint += pts
        record_shot_make(off, shot_type, context, shooter, defender)
        if last_passer and last_passer is not shooter:
            record_assist(last_passer, off, pts)
        record_score_event(off, dff, pts, period, score_time, teamA, teamB, check_timeout=False)
        if is_late_go_ahead_make(score_before, dff.score, pts, period, score_time):
            print(commentator_game_winner(shooter.name, off.name, shot_type, score_time))
        elif off.score == dff.score:
            print(commentator_game_tying_shot(shooter.name, off.name, shot_type, score_time))
        else:
            print(f"{shooter.name} hits the last-shot look.")
        time.sleep(SLEEP * 1.1)
        print_scoreboard(period, score_time, teamA, teamB)
        maybe_call_timeout_after_score(off, dff, period, score_time, teamA, teamB)
        return dff, spent

    update_shot_rhythm(shooter, False, shot_type)
    if deficit == 0:
        print(f"{shooter.name} cannot win it at the horn.")
    elif need_three:
        print(f"{shooter.name} cannot tie it from deep.")
    else:
        print(f"{shooter.name} misses the final look.")
    time.sleep(SLEEP)

    if score_time <= 1:
        print_scoreboard(period, score_time, teamA, teamB)
        return dff, spent

    reb_team, rebounder = choose_rebounder(off, dff, "rim" if is_paint_shot(shot_type) else "jumper")
    print(f"{rebounder.name} pulls down the rebound as the clock runs out.")
    print_scoreboard(period, score_time, teamA, teamB)
    return (off if reb_team is off else dff), spent


def run_late_game_quick_possession(off: Team, dff: Team, period: int, period_time: int,
                                   teamA: Team, teamB: Team,
                                   matchups: Dict[Player, Player]) -> Tuple[Team, int]:
    if period_time <= 5:
        spent = period_time
    elif period_time <= 10:
        spent = min(period_time, random.randint(2, 4))
    elif period_time <= 16:
        spent = min(period_time, random.randint(3, 5))
    else:
        spent = min(period_time, random.randint(4, 6))
    score_time = max(0, period_time - spent)
    quick_clock = period_time <= 24
    need_three = off.score <= dff.score - 3
    frontcourt_quick = getattr(off, "frontcourt_quick_touch", False)
    if frontcourt_quick:
        off.frontcourt_quick_touch = False
    shooter = choose_closing_star_scorer(off, need_three=need_three)
    handler = choose_closing_initiator(off, shooter)
    last_passer = None

    if frontcourt_quick:
        print(f"{off.name} keep it alive in the frontcourt and need one quick decision with {period_time} seconds left.")
    else:
        print(f"{off.name} need this fast with {period_time} seconds left.")
    time.sleep(SLEEP * 0.75)

    if handler is not shooter:
        if frontcourt_quick:
            late_pass_lines = [
                f"{handler.name} catches and immediately hits {shooter.name}.",
                f"{handler.name} moves it right away to {shooter.name}.",
                f"{handler.name} finds {shooter.name} on the quick second-chance touch.",
                f"{handler.name} wastes no time and delivers to {shooter.name}.",
            ]
        else:
            late_pass_lines = [
                f"{handler.name} gets it up quickly and hits {shooter.name}.",
                f"{handler.name} advances it and finds {shooter.name} coming to the ball.",
                f"{handler.name} wastes no time and gets it to {shooter.name}.",
                f"{handler.name} pushes the tempo and delivers to {shooter.name}.",
            ]
        print(random.choice(late_pass_lines))
        time.sleep(SLEEP * 0.75)
        last_passer = handler
    else:
        if frontcourt_quick:
            attack_lines = [
                f"{handler.name} catches in the frontcourt and goes straight into the shot.",
                f"{handler.name} gathers the loose possession and attacks immediately.",
                f"{handler.name} sees the clock and takes it himself.",
            ]
        else:
            attack_lines = [
                f"{handler.name} keeps it and attacks before the defense can set.",
                f"{handler.name} turns upcourt and goes straight into the shot.",
                f"{handler.name} rejects the delay and takes it himself.",
            ]
        print(random.choice(attack_lines))
        time.sleep(SLEEP * 0.75)

    defender = matchups.get(shooter, random.choice(dff.on_floor))
    if need_three:
        shot_type = "three" if shooter.three_tendency > 0 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif off.score in (dff.score - 1, dff.score - 2):
        shot_type = "rim" if shooter.drive_tendency > 0 and random.random() < 0.62 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    else:
        shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)

    play_context = "late_quick"
    package_shot_type = clutch_shot_package_type(shooter, defender, off, dff, period, period_time, shot_type)
    if package_shot_type is not None and not quick_clock:
        shot_type = package_shot_type
        play_context = "late_quick|clutch_package"
        print(clutch_package_voice_line(shooter, shot_type))
        time.sleep(SLEEP * 0.75)

    if shot_type == "rim" and random.random() < effective_dunk_attempt_chance(shooter):
        shot_type = "dunk"

    if quick_clock:
        print_late_clock_shot_attempt(shooter, shot_type, assisted=bool(last_passer))
    elif shot_type == "dunk":
        print(f"{shooter.name} gets downhill and goes up strong.")
        time.sleep(SLEEP * 0.75)
    else:
        print_shot_attempt_sequence(shooter, shot_type, "late_quick")

    foul_chance = foul_draw_sim(shooter) * usage_foul_weight(shooter) * FOUL_SCALE
    foul_chance *= shooting_foul_type_multiplier(shot_type)
    if random.random() < foul_chance:
        fouler = choose_fouling_defender(dff, defender, shooter, shot_type, "late_quick")
        register_foul(dff, fouler)
        shooter.fouls_drawn += 1
        off.fouls_drawn += 1
        print(f"Foul on {fouler.name}. {shooter.name} will shoot with {score_time} seconds left.")
        time.sleep(SLEEP * 0.5)
        if fouler.pf >= 6:
            foul_out_sub(dff, fouler)
        n_ft = 3 if shot_type == "three" else 2
        next_possession = shoot_free_throws(
            shooter, off, n_ft, period, score_time, teamA, teamB,
            sub_after_first=True, protected=shooter
        )
        return next_possession, spent

    if random.random() < block_prob(defender, shot_type, shooter):
        shooter.fga += 1
        if shot_type == "three":
            shooter.tpa += 1
        record_shot_diet(off, shot_type, "late_quick|contested", shooter, defender, quality_mult=0.92)
        print(block_voice_line(defender, shooter, shot_type))
        process_block(defender, dff)
        time.sleep(SLEEP * 0.5)
        reb_team, rebounder = choose_rebounder(off, dff, "rim" if is_paint_shot(shot_type) else "jumper")
        print(f"{rebounder.name} controls the rebound.")
        print_scoreboard(period, score_time, teamA, teamB)
        if reb_team is off:
            off.frontcourt_after_oreb = True
        return (off if reb_team is off else dff), spent

    q_label, q_mult = shot_quality(shooter, defender, shot_type, period, score_time)
    context = "late_quick|wide_open" if q_label == "wide open" else "late_quick|contested"
    shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * q_mult
    make_prob = shot_make_prob(shooter, defender, shot_type, off, dff, period, score_time)
    final_quality_mult = getattr(shooter, "shot_quality_mult", q_mult)
    clear_shot_temp_bonuses(shooter)

    shooter.fga += 1
    if shot_type == "three":
        shooter.tpa += 1
    record_shot_diet(off, shot_type, context, shooter, defender, quality_mult=final_quality_mult)

    if random.random() < make_prob:
        pts = 3 if shot_type == "three" else 2
        score_before = off.score
        shooter.fgm += 1
        shooter.pts += pts
        if shot_type == "three":
            shooter.tpm += 1
        late_go_ahead = is_late_go_ahead_make(score_before, dff.score, pts, period, score_time)
        off.score += pts
        if is_paint_shot(shot_type):
            off.points_paint += pts
        record_shot_make(off, shot_type, context, shooter, defender)
        if last_passer and last_passer is not shooter:
            record_assist(last_passer, off, pts)
        record_score_event(off, dff, pts, period, score_time, teamA, teamB, check_timeout=False)
        if late_go_ahead:
            print(commentator_game_winner(shooter.name, off.name, shot_type, score_time))
        elif q_label == "wide open":
            print(f"{shooter.name} knocks down the quick clean look.")
        else:
            line = random.choice(def_int_make) if is_paint_shot(shot_type) else random.choice(def_per_make)
            print(f"{shooter.name} knocks it down. {defender.name} {line}")
        time.sleep(SLEEP * 1.1)
        print_scoreboard(period, score_time, teamA, teamB)
        maybe_call_timeout_after_score(off, dff, period, score_time, teamA, teamB)
        return dff, spent

    update_shot_rhythm(shooter, False, shot_type)
    if q_label == "wide open":
        print(f"{shooter.name} misses the quick clean look.")
    else:
        line = random.choice(def_int_miss) if is_paint_shot(shot_type) else random.choice(def_per_miss)
        print(f"{shooter.name} misses. {defender.name} {line}")
    time.sleep(SLEEP * 0.5)

    reb_team, rebounder = choose_rebounder(off, dff, "rim" if is_paint_shot(shot_type) else "jumper")
    print(f"{rebounder.name} pulls down the rebound.")
    time.sleep(SLEEP * 0.4)
    if reb_team is off and score_time > 2:
        next_possession, extra_spent = handle_offensive_rebound(off, dff, rebounder, period, score_time, teamA, teamB)
        return next_possession, min(period_time, spent + extra_spent)
    print_scoreboard(period, score_time, teamA, teamB)
    return (off if reb_team is off else dff), spent

# ============================================================
# SHOOTER / HANDLER SELECTION
# ============================================================

def true_primary_shot_creator(player: Player) -> bool:
    return (
        player.usage >= 0.34
        and player.shot_tendency >= 0.62
        and (
            player.iso_tendency >= 0.58
            or player.ball_handle >= 0.86
            or player.three_tendency >= 0.48
        )
    )


def shooter_weight(player: Player) -> float:
    if player.shot_tendency <= 0:
        return 0.0

    usage_factor = max(0.03, player.usage ** 1.95)
    shot_intent = max(0.03, player.shot_tendency ** 1.60)
    playmaking_drag = 1.0 - 0.30 * player.playmaking
    if player.usage >= 0.30 and player.shot_tendency >= 0.55:
        playmaking_drag = max(playmaking_drag, 0.86)
    elif player.shot_tendency >= 0.70:
        playmaking_drag = max(playmaking_drag, 0.82)
    rhythm = 1.0 + min(0.35, getattr(player, "hot_streak", 0) * 0.10)
    if getattr(player, "cold_streak", 0) >= 3:
        rhythm *= 0.82
    if player.usage < 0.24:
        confidence = getattr(player, "confidence", 0.0)
        if confidence > 0:
            rhythm *= 1.0 + min(0.22, confidence * 0.06)
        elif confidence < 0:
            rhythm *= 1.0 + max(-0.28, confidence * 0.08)
    role_volume = 1.0
    if player.usage < 0.18 and player.fga >= 8:
        role_volume *= max(0.24, 1.0 - (player.fga - 7) * 0.16)
    elif player.usage < 0.22 and player.fga >= 12:
        role_volume *= max(0.38, 1.0 - (player.fga - 11) * 0.11)
    elif player.name == "Karl-Anthony Towns" and player.fga >= 14:
        role_volume *= max(0.08, 1.0 - (player.fga - 13) * 0.20)
    elif player.name == "Jalen Brunson" and player.fga >= 22:
        role_volume *= max(0.54, 1.0 - (player.fga - 21) * 0.06)
    elif player.name in ("Tyrese Haliburton", "Pascal Siakam", "Myles Turner") and player.fga >= 16:
        role_volume *= max(0.34, 1.0 - (player.fga - 15) * 0.12)
    elif player.name in ("Andrew Nembhard", "Bennedict Mathurin", "Aaron Nesmith", "Obi Toppin", "T.J. McConnell") and player.fga >= 13:
        role_volume *= max(0.44, 1.0 - (player.fga - 12) * 0.10)
    elif player.fga >= 14:
        role_volume *= max(0.62, 1.0 - (player.fga - 13) * 0.06)

    soft_cap = shot_volume_soft_cap(player)
    explicit_target = getattr(player, "target_fga_soft_cap", None)
    if explicit_target is not None and player.fga < explicit_target:
        # Explicit team-role targets are active goals, not merely ceilings.
        # Increase touches while a featured scorer is materially below target.
        deficit_ratio = (float(explicit_target) - player.fga) / max(1.0, float(explicit_target))
        role_volume *= 1.0 + min(0.48, deficit_ratio * 0.72)
    if player.fga > soft_cap:
        overage = player.fga - soft_cap
        drop_rate = 0.11 if true_primary_shot_creator(player) else 0.18
        role_volume *= max(0.22 if true_primary_shot_creator(player) else 0.12, 1.0 - overage * drop_rate)
    elif player.usage >= 0.30 and player.shot_tendency >= 0.55 and player.fga < soft_cap * 0.55:
        role_volume *= 1.0 + min(0.38, (soft_cap * 0.55 - player.fga) * 0.045)

    if player.shot_tendency < 0.45 and player.fga >= 22:
        role_volume *= max(0.08, 1.0 - (player.fga - 21) * 0.28)

    depth_factor = getattr(player, "team_depth_scoring_factor", 0.0)
    if getattr(player, "primary_scorer", False) and depth_factor > 0:
        if true_primary_shot_creator(player):
            role_volume *= 1.0 + depth_factor * 0.18
        else:
            role_volume *= 1.0 - depth_factor * 0.35
    elif player.shot_tendency >= 0.18 and player.usage < 0.24:
        role_volume *= 1.0 + depth_factor * 0.40

    if player.pts >= 36:
        role_volume *= max(0.12, 1.0 - (player.pts - 35) * 0.10)
    elif player.pts >= 32 and player.usage < 0.38:
        role_volume *= max(0.20, 1.0 - (player.pts - 31) * 0.08)
    elif player.pts >= 28 and player.shot_tendency < 0.48:
        role_volume *= max(0.25, 1.0 - (player.pts - 27) * 0.10)

    return max(
        0.0001,
        usage_factor
        * shot_intent
        * playmaking_drag
        * rhythm
        * role_volume
        * role_discipline_multiplier(player)
        * fatigue_touch_multiplier(player)
    )


def shot_volume_soft_cap(player: Player) -> float:
    explicit_cap = getattr(player, "target_fga_soft_cap", None)
    if explicit_cap is not None:
        return max(4.0, float(explicit_cap))
    cap = 5.0 + player.shot_tendency * 30.0 + player.usage * 8.5
    depth_factor = getattr(player, "team_depth_scoring_factor", 0.0)
    if getattr(player, "primary_scorer", False):
        if true_primary_shot_creator(player):
            cap += depth_factor * 4.0
        else:
            cap -= depth_factor * 6.0
    elif player.shot_tendency >= 0.18:
        cap += depth_factor * 2.5
    return max(4.0, cap)


def coach_shot_role_multiplier(team: Team, player: Player) -> float:
    styles = getattr(team, "coach_style", {})
    heliocentric = styles.get("heliocentric", 0.50)
    ball_movement = styles.get("ball_movement", 1.0)
    top_usage = max((p.usage for p in team.on_floor), default=player.usage)
    top_shot = max((p.shot_tendency for p in team.on_floor), default=player.shot_tendency)
    is_primary = player.usage >= top_usage - 0.025 or player.shot_tendency >= top_shot - 0.025

    mult = 1.0
    if heliocentric >= 0.90:
        mult *= 1.0 + (0.34 * heliocentric if is_primary else -0.22 * heliocentric)
    elif ball_movement >= 1.24:
        mult *= 0.88 if is_primary and player.fga >= 10 else 1.0
        if not is_primary and player.shot_tendency >= 0.16:
            mult *= 1.10

    style = styles.get("offensive_style", "")
    if style == "five-out" and player.three_tendency >= 0.25:
        mult *= 1.12
    elif style in ("post hub", "triangle/post") and (player.post_tendency >= 0.18 or can_play_position(player, "C")):
        mult *= 1.10
    elif style == "rim pressure" and (player.drive_tendency >= 0.28 or player.dunk_tendency >= 0.45):
        mult *= 1.12

    archetype = getattr(player, "archetype", "balanced")
    if archetype in ("isolation_scorer", "pullup_shooter") and player.ball_handle >= 0.72:
        mult *= 1.08
    elif archetype == "movement_shooter" and player.three_tendency >= 0.42:
        mult *= 1.07
    elif archetype in ("rim_runner", "slasher") and style == "rim pressure":
        mult *= 1.08
    elif archetype == "connector" and ball_movement >= 1.18:
        mult *= 1.05
    elif archetype in ("lockdown", "rim_protector") and player.shot_tendency < 0.24:
        mult *= 0.88

    return max(0.30, min(1.65, mult))


def coach_handler_multiplier(team: Team, player: Player) -> float:
    styles = getattr(team, "coach_style", {})
    heliocentric = styles.get("heliocentric", 0.50)
    ball_movement = styles.get("ball_movement", 1.0)
    top_creation = max((0.55 * p.playmaking + 0.30 * p.ball_handle + 0.15 * p.usage for p in team.on_floor), default=0.0)
    creation = 0.55 * player.playmaking + 0.30 * player.ball_handle + 0.15 * player.usage

    mult = 1.0
    if heliocentric >= 0.90:
        mult *= 1.0 + (0.42 * heliocentric if creation >= top_creation - 0.04 else -0.20 * heliocentric)
    elif ball_movement >= 1.24:
        mult *= 1.0 + max(0.0, player.playmaking - 0.56) * 0.34
        if player.usage >= 0.32 and player.playmaking < 0.76:
            mult *= 0.82

    style = styles.get("offensive_style", "")
    if style == "post hub" and (can_play_position(player, "C") or can_play_position(player, "PF")) and player.playmaking >= 0.58:
        mult *= 1.35
    elif style == "showtime" and player.speed >= 0.76:
        mult *= 1.16

    archetype = getattr(player, "archetype", "balanced")
    if archetype in ("floor_general", "post_hub"):
        mult *= 1.18
    elif archetype == "connector":
        mult *= 1.08
    elif archetype in ("movement_shooter", "rim_runner", "lockdown") and player.playmaking < 0.62:
        mult *= 0.84

    return max(0.32, min(1.75, mult))


def has_shot_volume_left(player: Player) -> bool:
    if player.shot_tendency >= 0.48 or player.usage >= 0.32:
        return player.fga <= shot_volume_soft_cap(player) + 3.0
    return player.fga <= shot_volume_soft_cap(player) + 1.0


def can_be_designed_shooter(player: Player) -> bool:
    return not player.fouled_out and player.shot_tendency > 0

def role_discipline_multiplier(player: Player) -> float:
    mult = 1.0
    if player.usage < 0.12 and player.shot_tendency < 0.18:
        mult *= 0.55 + player.shot_iq * 0.34
    elif player.usage < 0.18 and player.shot_tendency < 0.26:
        mult *= 0.72 + player.shot_iq * 0.24

    if player.shot_iq < 0.62 and player.fga >= 7 and player.usage < 0.24:
        mult *= max(0.46, 1.0 - (player.fga - 6) * 0.10)
    if "movement_shooter" in player.badges and player.three_tendency >= 0.45:
        mult *= 1.08
    if "iso_scorer" in player.badges and player.usage >= 0.28:
        mult *= 1.06
    if player.usage < 0.18 and player.fga >= 9 and getattr(player, "hot_streak", 0) < 2:
        mult *= max(0.42, 1.0 - (player.fga - 8) * 0.12)
    if player.usage < 0.22 and player.shot_iq >= 0.78 and getattr(player, "hot_streak", 0) >= 2:
        mult *= 1.12
    if player.usage >= 0.30 and player.fga <= 8 and player.shot_tendency >= 0.45:
        mult *= 1.10
    return max(0.30, min(1.18, mult))

def foul_trouble_attack_score(defender: Player) -> float:
    if defender.pf < 3:
        return 0.0
    value = 0.42 * effective_perimeter_def(defender) + 0.48 * effective_interior_def(defender) + 0.10 * overall_rating(defender)
    foul_pressure = (defender.pf - 2) * 0.25
    return value + foul_pressure

def find_foul_trouble_target(off: Team, dff: Team, matchups: Dict[Player, Player]) -> Tuple[Player | None, Player | None]:
    if getattr(off, "foul_hunt_cooldown", 0) > 0:
        off.foul_hunt_cooldown -= 1
        return None, None
    candidates = []
    for shooter, defender in matchups.items():
        if shooter not in off.on_floor or defender not in dff.on_floor or defender.fouled_out:
            continue
        if defender.pf < 3:
            continue
        attack_skill = 0.38 * shooter.rim_rating + 0.24 * shooter.drive_tendency + 0.20 * foul_draw_sim(shooter) + 0.18 * shooter.usage
        candidates.append((foul_trouble_attack_score(defender) + attack_skill, shooter, defender))
    if not candidates:
        return None, None
    _, shooter, defender = max(candidates, key=lambda item: item[0])
    if random.random() < min(0.62, 0.18 + shooter.playmaking * 0.15 + shooter.usage * 0.55 + defender.pf * 0.05):
        off.foul_hunt_cooldown = 4
        return shooter, defender
    return None, None


def designed_shooter_options(players: List[Player], fallback: Player | None = None) -> List[Player]:
    options = [p for p in players if can_be_designed_shooter(p)]
    if options:
        return options
    if fallback is not None and not fallback.fouled_out:
        return [fallback]
    return [p for p in players if not p.fouled_out] or list(players)


def reroute_zero_tendency_shooter(team: Team, shooter: Player, passer: Player | None = None) -> Player:
    if can_be_designed_shooter(shooter):
        return shooter

    candidates = designed_shooter_options([p for p in team.on_floor if p is not shooter], passer)
    if not candidates:
        return shooter

    return max(candidates, key=shooter_weight)


