def team_playbook_play(off: Team) -> str | None:
    plays = TEAM_PLAYBOOKS.get(off.name)
    if not plays:
        return None
    styles = getattr(off, "coach_style", {})
    frequency = (0.24 + styles.get("coach_iq", 0.62) * 0.10) * styles.get("playbook_frequency", 1.0)
    frequency_cap = 0.62 if off.name == "2027 Los Angeles Lakers" else 0.48
    if off.name == "2027 Los Angeles Lakers":
        frequency = max(frequency, 0.62)
    if random.random() < min(frequency_cap, frequency):
        return random.choice(plays)
    return None


def real_play_type(off: Team, handler: Player) -> str:
    team_play = team_playbook_play(off)
    if team_play:
        return team_play

    styles = getattr(off, "coach_style", {})
    three_pref = styles.get("three_preference", 1.0)
    ball_movement = styles.get("ball_movement", 1.0)
    heliocentric = styles.get("heliocentric", 0.50)
    pnr_frequency = styles.get("pnr_frequency", 1.0)
    style_name = styles.get("offensive_style", "balanced")
    plan = getattr(off, "game_plan", {}).get("offense", "balanced")
    has_big_hub = any((can_play_position(p, "C") or can_play_position(p, "PF")) and p.playmaking >= 0.70 for p in off.on_floor)
    has_movement = any("movement_shooter" in p.badges for p in off.on_floor)
    iso_creation = isolation_creation_score(handler)

    plays = [
        "high_pnr", "empty_corner_pnr", "spain_pnr", "handoff", "horns",
        "floppy", "elevator", "backdoor", "drive_kick", "post_split", "iso"
    ]
    weights = [
        (1.8 + handler.playmaking) * pnr_frequency * (1.0 + heliocentric * 0.18),
        (1.1 + handler.ball_handle) * pnr_frequency * (1.0 + heliocentric * 0.28),
        (0.9 + handler.playmaking * 0.8) * pnr_frequency,
        (1.0 + (0.6 if has_big_hub else 0.0)) * ball_movement,
        (0.9 + (0.4 if has_big_hub else 0.0)) * ball_movement,
        (0.7 + (1.0 if has_movement or three_pref > 1.0 else 0.0)) * ball_movement * three_pref,
        (0.55 + (1.0 if has_movement or three_pref > 1.0 else 0.0)) * ball_movement * three_pref,
        (0.55 + handler.playmaking * 0.7) * ball_movement,
        (0.75 + handler.playmaking) * (0.85 + ball_movement * 0.25),
        (0.7 + (0.8 if has_big_hub else 0.0)) * (1.0 + max(0.0, ball_movement - 1.0) * 0.40),
        (0.20 + handler.usage * 0.55 + handler.iso_tendency * 1.55 + iso_creation * 1.35) * (0.55 + heliocentric * 0.70),
    ]
    if style_name == "five-out":
        for idx in (1, 5, 6, 8):
            weights[idx] *= 1.22
    elif style_name in ("post hub", "triangle/post"):
        weights[4] *= 1.18
        weights[9] *= 1.45
        weights[10] *= 0.82
    elif style_name == "rim pressure":
        weights[0] *= 1.18
        weights[1] *= 1.12
        weights[7] *= 1.15
    elif style_name in ("ball movement", "motion split", "pace motion", "showtime"):
        for idx in (3, 4, 5, 7, 8):
            weights[idx] *= 1.18
        weights[10] *= 0.70
    elif style_name == "heliocentric spread":
        for idx in (0, 1, 8, 10):
            weights[idx] *= 1.22
        weights[3] *= 0.72
        weights[4] *= 0.78

    if plan == "five_out":
        for idx in (1, 5, 6, 8):
            weights[idx] *= 1.22
        weights[9] *= 0.82
    elif plan == "four_out_one_in":
        for idx in (0, 1, 3, 8, 9):
            weights[idx] *= 1.10
    elif plan == "three_out_two_in":
        weights[0] *= 1.08
        weights[2] *= 1.10
        weights[4] *= 1.16
        weights[9] *= 1.28
        weights[5] *= 0.82
        weights[6] *= 0.82
    elif plan == "post_heavy":
        weights[4] *= 1.18
        weights[9] *= 1.55
        weights[10] *= 0.78
        weights[5] *= 0.72
        weights[6] *= 0.72
    elif plan == "motion":
        for idx in (3, 4, 5, 7, 8):
            weights[idx] *= 1.18
        weights[10] *= 0.72
    elif plan == "star_spread":
        for idx in (0, 1, 8, 10):
            weights[idx] *= 1.25
        weights[3] *= 0.76
        weights[4] *= 0.82

    if handler.iso_tendency >= 0.82 and handler.usage >= 0.28:
        weights[10] *= 1.35
        weights[3] *= 0.82
        weights[4] *= 0.90
    elif handler.iso_tendency < 0.25:
        weights[10] *= 0.45
    return random.choices(plays, weights=weights, k=1)[0]


def isolation_creation_score(player: Player) -> float:
    if not can_be_designed_shooter(player):
        return 0.0
    return (
        0.34 * player.iso_tendency
        + 0.26 * player.shot_tendency
        + 0.25 * player.ball_handle
        + 0.07 * player.usage
        + 0.08 * max(player.three_rating, player.mid_rating, player.rim_rating)
    )


def team_iso_attempt_target(team: Team) -> float:
    iso_players = sorted(
        [p for p in team.roster if can_be_designed_shooter(p)],
        key=lambda p: p.iso_tendency * 0.60 + p.usage * 0.25 + p.ball_handle * 0.15,
        reverse=True
    )
    if not iso_players:
        return 6.0

    top = iso_players[:3]
    top_iso = sum(p.iso_tendency for p in top) / len(top)
    high_iso_count = sum(1 for p in top if p.iso_tendency >= 0.78)
    heliocentric = getattr(team, "coach_style", {}).get("heliocentric", 0.50)
    target = 6.4 + top_iso * 4.8 + high_iso_count * 0.65 + max(0.0, heliocentric - 0.60) * 1.2
    return max(5.5, min(13.0, target))


def iso_volume_pressure(team: Team, period: int, period_time: int) -> float:
    elapsed = (min(period, 4) - 1) * rules_quarter_seconds() + (rules_quarter_seconds() - max(0, period_time))
    game_progress = max(0.0, min(1.0, elapsed / max(1, rules_game_seconds())))
    expected = team_iso_attempt_target(team) * game_progress
    current = getattr(team, "shot_diet", {}).get("iso", 0)
    return expected - current


def player_by_name(on_floor: List[Player], names: Tuple[str, ...]) -> Player | None:
    return next((p for p in on_floor if p.name in names), None)


def playmaking_hub_score(player: Player) -> float:
    badge_bonus = 0.08 if ("post_hub" in player.badges or "transition_engine" in player.badges) else 0.0
    if player.name == "Rajon Rondo":
        badge_bonus += 0.14
    return (
        0.58 * player.playmaking
        + 0.24 * player.ball_handle
        + 0.10 * player.usage
        + 0.08 * player.clutchness
        + badge_bonus
    )


def assist_load_factor(player: Player, team: Team) -> float:
    if player.name == "Rajon Rondo":
        if player.ast < 11:
            return 1.12
        if player.ast < 13:
            return 0.78
        return 0.54
    team_assists = sum(p.ast for p in team.roster)
    if team_assists < 6:
        return 1.0

    expected_share = max(0.08, playmaking_hub_score(player) / max(0.01, sum(playmaking_hub_score(p) for p in team.roster)))
    actual_share = player.ast / max(1, team_assists)
    if actual_share <= expected_share:
        return assist_volume_factor(player)

    overload = actual_share - expected_share
    factor = max(0.20, 1.0 - overload * 4.2)
    return max(0.10, factor * assist_volume_factor(player))


def assist_distribution_multiplier(player: Player, team: Team) -> float:
    team_assists = sum(p.ast for p in team.roster)
    if team_assists < 6:
        return 1.0

    expected_share = max(0.08, playmaking_hub_score(player) / max(0.01, sum(playmaking_hub_score(p) for p in team.roster)))
    actual_share = player.ast / max(1, team_assists)
    gap = expected_share - actual_share
    if gap > 0:
        return min(1.28, 1.0 + gap * 1.6)
    return max(0.42, 1.0 + gap * 1.8)


def assist_volume_factor(player: Player) -> float:
    if player.name == "Rajon Rondo":
        if player.ast >= 15:
            return 0.62
        if player.ast >= 13:
            return 0.85
        return 1.12
    if player.name == "Stephen Curry":
        if player.ast >= 7:
            return 0.26
        if player.ast >= 5:
            return 0.48
        if player.ast >= 4:
            return 0.70
        return 0.92
    if player.playmaking >= 0.90:
        if player.ast >= 13:
            return 0.42
        if player.ast >= 11:
            return 0.58
        if player.ast >= 9:
            return 0.78
        return 0.96
    if player.playmaking >= 0.82:
        if player.ast >= 10:
            return 0.38
        if player.ast >= 8:
            return 0.58
        if player.ast >= 6:
            return 0.82
        return 0.96
    if player.playmaking >= 0.72:
        if player.ast >= 8:
            return 0.30
        if player.ast >= 6:
            return 0.52
        if player.ast >= 4:
            return 0.80
        return 0.94
    if player.ast >= 6:
        return 0.22
    if player.ast >= 4:
        return 0.52
    return 1.0


def assist_phase_relief(player: Player) -> float:
    """
    Keep elite passers alive after halftime.
    The assist dampener uses full-game totals, so strong first halves used to
    make Q3/Q4 creation dry up too much.
    """
    period = int(SIM_CONTEXT.get("period", 1) or 1)
    if period < 3:
        return 1.0
    if player.playmaking >= 0.90:
        if period == 3:
            return 1.08
        # For elite creators, clutchness means better late-game reads as well
        # as scoring. This prevents clutch stars such as 2027 LeBron from
        # losing their passing value when the fourth-quarter pressure rises.
        clutch_creation = max(0.0, player.clutchness - 0.70) * 0.35
        return min(1.24, 1.12 + clutch_creation)
    if player.playmaking >= 0.82:
        return 1.04 if period == 3 else 1.08
    if player.playmaking >= 0.72:
        return 1.02 if period == 3 else 1.05
    return 1.0


def choose_play_hub(team: Team, names: Tuple[str, ...] = tuple()) -> Player:
    candidates = [
        p for p in team.on_floor
        if not p.fouled_out and (not names or p.name in names)
    ]
    if names and len(candidates) < 3:
        support = [
            p for p in team.on_floor
            if p not in candidates
            and not p.fouled_out
            and (p.playmaking >= 0.45 or can_play_position(p, "PG") or can_play_position(p, "SG"))
        ]
        candidates.extend(sorted(support, key=playmaking_hub_score, reverse=True)[:3])
    if not candidates:
        candidates = [p for p in team.on_floor if not p.fouled_out] or list(team.on_floor)

    current_initiator = getattr(team, "current_play_initiator", None)
    if current_initiator in candidates and random.random() < 0.72:
        return current_initiator

    weights = [
        max(0.01, playmaking_hub_score(p) ** 1.75)
        * assist_load_factor(p, team)
        * coach_handler_multiplier(team, p)
        * (0.68 if team.name in ("2016 Golden State Warriors", "2017 Golden State Warriors", "2019 Golden State Warriors", "2022 Golden State Warriors") and p.name == "Stephen Curry" else 1.0)
        * (1.28 if team.name in ("2016 Golden State Warriors", "2017 Golden State Warriors", "2019 Golden State Warriors", "2022 Golden State Warriors") and p.name in ("Draymond Green", "Andre Iguodala") else 1.0)
        for p in candidates
    ]
    return random.choices(candidates, weights=weights, k=1)[0]


def weighted_target(options: List[Player], weight_fn, default: Player) -> Player:
    options = designed_shooter_options(options, default)
    if not options:
        return default
    weights = [max(0.01, play_target_score(p, weight_fn(p))) for p in options]
    return random.choices(options, weights=weights, k=1)[0]


def play_target_tendency_multiplier(player: Player) -> float:
    if player.shot_tendency <= 0:
        return 0.0
    return 0.06 + 3.05 * (player.shot_tendency ** 1.55)


def play_target_score(player: Player, base_score: float) -> float:
    volume_factor = 1.0 if has_shot_volume_left(player) else 0.18
    return max(0.0, base_score) * play_target_tendency_multiplier(player) * volume_factor


def best_play_target(options: List[Player], score_fn, default: Player) -> Player:
    options = designed_shooter_options(options, default)
    if not options:
        return default
    return max(options, key=lambda p: play_target_score(p, score_fn(p)), default=default)


