    if play_type == "backdoor":
        options = designed_shooter_options([p for p in off.on_floor if p is not handler and (p.rim_rating >= 0.80 or p.dunk_tendency >= 0.25)], current_shooter)
        target = best_play_target(options, lambda p: 0.55 * p.rim_rating + 0.25 * p.dunk_rating + 0.20 * p.dunk_tendency, current_shooter)
        print(f"{handler.name} sees {target.name} fake to the arc and cut backdoor.")
        return target, handler, "backdoor"

    if play_type == "drive_kick":
        options = designed_shooter_options([p for p in off.on_floor if p is not handler and p.three_rating >= 0.78], current_shooter)
        target = best_play_target(options, lambda p: 0.6 * p.three_rating + 0.25 * p.three_tendency + 0.15 * shooter_weight(p), current_shooter)
        print(f"{handler.name} gets downhill and bends the defense toward the paint.")
        return target, handler, "drive_kick"

    if play_type == "handoff":
        options = designed_shooter_options([p for p in off.on_floor if p is not handler and p.ball_handle >= 0.45], current_shooter)
        target = best_play_target(options, lambda p: 0.5 * p.three_rating + 0.3 * p.rim_rating + 0.2 * p.usage, current_shooter)
        print(f"{handler.name} flows into a dribble handoff with {target.name}.")
        return target, handler, "handoff"

    if play_type == "horns":
        passers = [p for p in off.on_floor if p is not handler and (can_play_position(p, "PF") or can_play_position(p, "C"))]
        passer = max(passers, key=lambda p: 0.65 * p.playmaking + 0.35 * p.mid_rating, default=handler)
        cutters = [p for p in off.on_floor if p is not passer]
        cutters = designed_shooter_options(cutters, current_shooter)
        target = best_play_target(cutters, lambda p: 0.35 * p.rim_rating + 0.30 * p.three_rating + 0.20 * p.usage + 0.15 * p.ball_handle, current_shooter)
        print(f"{passer.name} catches at the elbow with both sides spaced.")
        return target, passer, "horns"

    if play_type == "post_split":
        bigs = [p for p in off.on_floor if can_play_position(p, "PF") or can_play_position(p, "C")]
        bigs = designed_shooter_options(bigs, current_shooter)
        target = best_play_target(bigs, lambda p: 0.45 * p.post_tendency + 0.35 * p.mid_rating + 0.20 * p.playmaking, current_shooter)
        print(f"{target.name} catches inside as two teammates cut around him.")
        return target, handler, "post_split"

    if play_type == "empty_corner_pnr":
        print(f"The weak-side corner clears out as the screen comes up high.")
        return current_shooter, None, "empty_corner_pnr"

    if play_type == "spain_pnr":
        print("A guard sneaks behind the big defender as the screen arrives up top.")
        return current_shooter, None, "spain_pnr"

    if play_type == "sideline_curl_three":
        options = designed_shooter_options([p for p in off.on_floor if p is not handler and p.three_rating >= 0.78], current_shooter)
        target = best_play_target(options, lambda p: 0.64 * p.three_rating + 0.20 * p.clutchness + 0.16 * shooter_weight(p), current_shooter)
        print(f"{target.name} starts in the corner, curls off the sideline screen, and shows his hands above the arc.")
        return target, handler, "sideline_curl_three"

    if play_type == "ghost_screen_three":
        options = designed_shooter_options([p for p in off.on_floor if p.three_rating >= 0.78 or p.ball_handle >= 0.76], current_shooter)
        target = best_play_target(options, lambda p: 0.50 * p.three_rating + 0.26 * p.ball_handle + 0.24 * p.clutchness, current_shooter)
        print(f"{handler.name} gestures for the screen, but it slips out early and {target.name} pops into space.")
        return target, handler if handler is not target else None, "ghost_screen_three"

    if play_type == "quick_slip":
        bigs = [p for p in off.on_floor if p is not handler and (can_play_position(p, "PF") or can_play_position(p, "C"))]
        target = best_play_target(bigs or off.on_floor, lambda p: 0.55 * p.rim_rating + 0.25 * p.dunk_tendency + 0.20 * p.clutchness, current_shooter)
        print(f"{target.name} fakes the screen and slips straight into the paint before the help can tag him.")
        return target, handler, "quick_slip"

    if play_type == "iso":
        if can_be_designed_shooter(handler) and isolation_creation_score(handler) >= 0.54 and has_shot_volume_left(handler):
            target = handler
        else:
            target = best_play_target(
                off.on_floor,
                lambda p: shooter_weight(p) * (1 + p.usage) + isolation_creation_score(p) * 0.35,
                current_shooter
            )
        print(f"{off.name} flatten out and let {target.name} hunt one-on-one.")
        return target, None, "iso"

    print("The screen comes high and the floor opens around the ball.")
    return current_shooter, None, "high_pnr"


