def hunt_mismatch(off: Team, dff: Team, matchups: Dict[Player, Player],
                  period: int, period_time: int,
                  ballhandler: Player | None = None) -> Tuple[Player, Player] | None:
    coach_iq = getattr(off, "coach_style", {}).get("coach_iq", 0.62)
    hunt_chance = 0.18 + coach_iq * 0.14
    if getattr(off, "offensive_hunt_target", None):
        hunt_chance += 0.18
    if random.random() > min(0.48, hunt_chance):
        return None

    options = []
    possible_scorers = [ballhandler] if ballhandler in off.on_floor else list(off.on_floor)
    for scorer in possible_scorers:
        if scorer is None:
            continue
        if not can_be_designed_shooter(scorer):
            continue
        if scorer.usage < 0.24 and scorer.shot_tendency < 0.42:
            continue
        defender = matchups.get(scorer)
        if defender is None:
            continue
        target_bonus = 0.28 if defender.name == getattr(off, "offensive_hunt_target", None) else 0.0
        defender_quality = 0.60 * effective_perimeter_def(defender) + 0.40 * effective_interior_def(defender)
        size_problem = max(0, defender.height - scorer.height) * 0.015

        # Good offenses hunt weak links. They should not keep calling a switch
        # just to attack a lockdown defender unless a coach explicitly tagged
        # that player and the scorer still owns a clear creation edge.
        if target_bonus == 0 and defender_quality >= 0.64:
            continue
        if target_bonus == 0 and effective_perimeter_def(defender) >= 0.68 and effective_interior_def(defender) >= 0.55:
            continue
        if "lockdown" in defender.badges and target_bonus == 0:
            continue

        weakness_bonus = max(0.0, 0.68 - defender_quality) * 1.45
        good_defender_penalty = max(0.0, defender_quality - 0.64) * 1.20
        if "lockdown" in defender.badges:
            good_defender_penalty += 0.25

        edge = (
            0.55 * scorer.usage
            + 0.35 * scorer.ball_handle
            + 0.30 * scorer.shot_tendency
            + weakness_bonus
            - good_defender_penalty
            - size_problem
            + target_bonus
        )
        if edge > 0.40:
            options.append((edge, defender_quality, scorer, defender))

    if not options:
        return None

    _, _, scorer, defender = max(options, key=lambda item: (item[0], -item[1]))
    print(f"{off.name} hunt the matchup and bring {defender.name} into the action against {scorer.name}.")
    if defender.name == getattr(off, "offensive_hunt_target", None) and random.random() < 0.45:
        off.offensive_hunt_target = None
    time.sleep(SLEEP * 0.5)
    return scorer, defender


def should_double_team(shooter: Player, defender: Player, off: Team, dff: Team,
                       period: int, period_time: int, shot_type: str) -> bool:
    focused_star = getattr(dff, "defensive_focus", None) == shooter.name
    plan = getattr(dff, "game_plan", {})
    player_coverage = plan.get("player_coverages", {}).get(shooter.name)
    star_coverage = player_coverage or (plan.get("star_coverage", "standard") if focused_star else "standard")
    if shot_type == "three" and shooter.three_rating < 0.88 and not focused_star:
        return False
    if getattr(dff, "double_team_cooldown", 0) > 0:
        dff.double_team_cooldown -= 1
        return False
    styles = getattr(dff, "coach_style", {})
    coach_iq = styles.get("coach_iq", 0.62)
    help_aggression = styles.get("help_aggression", 1.0)
    pressure = star_scoring_pressure(shooter)
    scoring_threat = shooter.pts >= 18 or shooter.usage >= 0.32 or focused_star or pressure >= 0.60
    hot_scorer = getattr(shooter, "hot_streak", 0) >= 2 and shooter.pts >= 12
    post_or_drive = is_paint_shot(shot_type) and (shooter.post_tendency + shooter.drive_tendency) >= 0.28
    late_star = period >= 4 and period_time <= 6 * 60 and shooter.clutchness >= 0.82
    weak_defender = (0.60 * defender.perimeter_def + 0.40 * defender.interior_def) <= 0.58
    targeted_weak_link = defender.name == getattr(off, "offensive_hunt_target", None)
    if not (scoring_threat or hot_scorer or post_or_drive or late_star or targeted_weak_link):
        return False
    chance = 0.055 + coach_iq * 0.065 + (help_aggression - 1.0) * 0.06
    if focused_star:
        chance += 0.07
    if star_coverage == "trap_force_pass":
        chance += 0.09
    elif star_coverage == "early_double":
        chance += 0.06
    elif star_coverage == "late_double_rotate":
        chance += 0.035
    elif star_coverage == "full_pressure":
        chance += 0.035
    elif star_coverage in ("stay_home", "no_help", "stay_close", "deny_catch"):
        chance -= 0.035
    elif star_coverage in ("sag_rim", "gap_help") and is_paint_shot(shot_type):
        chance += 0.020
    if weak_defender and (targeted_weak_link or shooter.usage >= 0.26):
        chance += 0.055
    if is_paint_shot(shot_type):
        chance += 0.04
    if shooter.playmaking < 0.62:
        chance += 0.055
    elif shooter.playmaking >= 0.86:
        chance -= 0.035
    if defender.pf >= 4:
        chance += 0.05
    max_chance = 0.36 if shooter.playmaking < 0.64 else 0.29
    send_double = random.random() < max(0.04, min(max_chance, chance))
    if send_double:
        dff.double_team_cooldown = 3 if coach_iq >= 0.70 else 4
    return send_double


def double_team_turnover_chance(player: Player, defender: Player, dff: Team, coverage: str) -> float:
    styles = getattr(dff, "coach_style", {})
    pressure = 0.015 + styles.get("coach_iq", 0.62) * 0.020 + styles.get("help_aggression", 1.0) * 0.018
    pressure += max(0.0, 0.70 - player.playmaking) * 0.115
    pressure += max(0.0, 0.68 - player.ball_handle) * 0.070
    pressure += max(0.0, 0.72 - player.shot_iq) * 0.035
    pressure += max(0.0, effective_perimeter_def(defender) - 0.70) * 0.045
    if coverage == "trap_force_pass":
        pressure += 0.030
    elif coverage == "early_double":
        pressure += 0.018
    elif coverage == "late_double_rotate":
        pressure += 0.010
    return max(0.012, min(0.18, pressure))


def is_non_spacer(player: Player) -> bool:
    return player.three_tendency <= 0.10 and player.mid_tendency <= 0.10


def catch_shoot_receiver_factor(player: Player) -> float:
    """
    Primary iso creators can still shoot off the catch, but the offense should
    prefer using them as initiators instead of parking them as spot-up targets.
    """
    factor = 1.0

    if player.iso_tendency >= 0.88 and player.usage >= 0.28:
        factor *= 0.16
    elif player.iso_tendency >= 0.74 and player.usage >= 0.24:
        factor *= 0.42
    elif player.iso_tendency >= 0.62 and player.usage >= 0.22:
        factor *= 0.68

    if player.ball_handle >= 0.86 and player.playmaking >= 0.76:
        factor *= 0.58

    badges = getattr(player, "badges", set())
    if "movement_shooter" in badges:
        factor *= 1.34
    if "catch_shoot" in badges:
        factor *= 1.46

    return max(0.06, min(1.50, factor))


def catch_shoot_badge_quality_bonus(player: Player) -> float:
    bonus = 0.0
    if "catch_shoot" in getattr(player, "badges", ()):
        bonus += 0.065
    if "movement_shooter" in getattr(player, "badges", ()):
        bonus += 0.030
    return bonus


def ankle_breaker_chance(shooter: Player, defender: Player, play_context: str | None) -> float:
    if play_context not in ("iso", "mismatch_hunt", "foul_hunt", "pressure_pullup", "pressure_drive"):
        return 0.0
    if shooter.ball_handle < 0.74:
        return 0.0

    tier = badge_tier(shooter, "ankle_breaker")
    handle_edge = max(0.0, shooter.ball_handle - defender.perimeter_def)
    chance = 0.006 + max(0.0, shooter.ball_handle - 0.74) * 0.030 + handle_edge * 0.028
    chance += tier * 0.030
    if shooter.name == "Kyrie Irving":
        chance += 0.015
    if defender.perimeter_def >= 0.80:
        chance *= 0.70
    return max(0.0, min(0.16, chance))


def dribble_combo_chance(shooter: Player, defender: Player, play_context: str | None,
                         period: int, period_time: int) -> float:
    if period_time <= 8:
        return 0.0
    if shooter.ball_handle < 0.76:
        return 0.0
    if play_context in ("deep_paint_touch", "roller", "popper", "alley_oop", "pnr_catch_shoot", "catch_shoot", "extra_pass_open", "post_split"):
        return 0.0

    context_bonus = 0.0
    if play_context in ("iso", "mismatch_hunt", "fourth_star_touch"):
        context_bonus += 0.075
    elif play_context in ("handoff", "horns", "pressure_pullup", "pressure_drive"):
        context_bonus += 0.045
    elif play_context in (None, "reset", "handler"):
        context_bonus += 0.025
    tier = badge_tier(shooter, "ankle_breaker")
    handle_edge = max(0.0, shooter.ball_handle - defender.perimeter_def)
    chance = 0.070 + max(0.0, shooter.ball_handle - 0.76) * 0.34 + shooter.iso_tendency * 0.055
    chance += shooter.shot_tendency * 0.055 + context_bonus + tier * 0.030 + handle_edge * 0.075
    if shooter.playmaking >= 0.82:
        chance += 0.035
    if shooter.ball_handle >= 0.90:
        chance += 0.055
    elif shooter.ball_handle >= 0.84:
        chance += 0.030
    if defender.perimeter_def >= 0.84:
        chance *= 0.82
    if period >= 4 and period_time <= 6 * 60 and shooter.clutchness >= 0.82:
        chance += 0.040
    return max(0.0, min(0.58, chance))


def dribble_combo_action(shooter: Player, defender: Player, team: Team, opponent: Team,
                         period: int, period_time: int, play_context: str | None) -> Tuple[str, float]:
    handle_edge = shooter.ball_handle - defender.perimeter_def
    rim_pull = shooter.drive_tendency * shooter.rim_rating
    three_pull = three_attempt_tendency_curve(shooter.three_tendency) * shooter.three_rating
    mid_pull = shooter.mid_tendency * shooter.mid_rating
    pass_pull = shooter.playmaking * max(0.0, 0.78 - shooter.shot_iq + 0.20)

    three_weight = max(0.02, 0.12 + three_pull * 0.52 + shooter.shot_tendency * 0.16 + max(0.0, handle_edge) * 0.12)
    mid_weight = max(0.02, 0.12 + mid_pull * 0.50 + shooter.shot_tendency * 0.14 + max(0.0, handle_edge) * 0.10)
    drive_weight = max(0.03, 0.16 + rim_pull * 0.50 + effective_speed(shooter) * 0.16 + max(0.0, handle_edge) * 0.12)
    pass_weight = max(0.02, 0.08 + pass_pull * 0.28 + shooter.playmaking * 0.12)

    if play_context in ("iso", "mismatch_hunt"):
        three_weight *= 1.14
        mid_weight *= 1.18
        pass_weight *= 0.78
    elif play_context in ("handoff", "pressure_pullup"):
        three_weight *= 1.16
        mid_weight *= 1.10
    elif play_context == "pressure_drive":
        drive_weight *= 1.22
    if period >= 4 and period_time <= 90 and team.score < opponent.score:
        three_weight *= 1.18
        mid_weight *= 1.12
        pass_weight *= 0.80

    if shooter.three_tendency <= 0 or shooter.three_rating < 0.66:
        three_weight *= 0.15
    if shooter.mid_tendency <= 0 or shooter.mid_rating < 0.66:
        mid_weight *= 0.20
    if shooter.drive_tendency <= 0:
        drive_weight *= 0.20

    total = three_weight + mid_weight + drive_weight + pass_weight
    r = random.random() * total
    if r < three_weight:
        action = "pullup_three"
    elif r < three_weight + mid_weight:
        action = "pullup_mid"
    elif r < three_weight + mid_weight + drive_weight:
        action = "drive"
    else:
        action = "pass"

    quality = 1.02 + max(0.0, shooter.ball_handle - 0.78) * 0.16 + max(0.0, handle_edge) * 0.08
    if badge_tier(shooter, "ankle_breaker") > 0:
        quality += badge_tier(shooter, "ankle_breaker") * 0.012
    if defender.perimeter_def >= 0.84:
        quality -= 0.035
    return action, max(0.96, min(1.16, quality))


def print_dribble_combo(shooter: Player, defender: Player, action: str):
    opener = random.choice(dribble_combo_openers).format(shooter=shooter.name, defender=defender.name)
    link = random.choice(varied_dribble_chain_links(1) or dribble_combo_links)
    opener = opener.rstrip(".")
    print(f"{opener} {link}")
    time.sleep(SLEEP * 0.55)

    def finish_line(line: str) -> str:
        line = line.strip()
        if line.startswith("He "):
            line = f"{shooter.name} {line[3:]}"
        elif line.startswith("he "):
            line = f"{shooter.name} {line[3:]}"
        if not line.endswith("."):
            line += "."
        return line

    if action == "pullup_three":
        print(finish_line(random.choice(dribble_combo_three_finishes)))
        time.sleep(SLEEP * 0.45)
    elif action == "pullup_mid":
        print(finish_line(random.choice(dribble_combo_mid_finishes)))
        time.sleep(SLEEP * 0.45)
    elif action == "drive":
        print(finish_line(random.choice(dribble_combo_drive_finishes)))
        time.sleep(SLEEP * 0.45)


def shot_creator_contested_bonus(player: Player, quality_label: str, shot_type: str) -> float:
    if "shot_creator" not in getattr(player, "badges", ()):
        return 0.0
    if shot_type not in ("three", "mid"):
        return 0.0
    if quality_label not in ("lightly contested", "tightly contested", "smothered", "late-clock forced"):
        return 0.0
    return 0.050 + max(0.0, player.ball_handle - 0.80) * 0.045 + max(0.0, player.shot_iq - 0.72) * 0.020


def posterizer_quality_bonus(player: Player, defender: Player) -> float:
    if "posterizer" not in getattr(player, "badges", ()):
        return 0.0
    size_or_power = max(0.0, player.dunk_rating - defender.interior_def)
    return 0.055 + player.dunk_tendency * 0.045 + size_or_power * 0.030


def effective_dunk_attempt_chance(player: Player) -> float:
    chance = player.dunk_tendency * DUNK_RATE_SCALE
    if "posterizer" in getattr(player, "badges", ()):
        chance += 0.055 + max(0.0, player.dunk_rating - 0.82) * 0.065
    return max(0.0, min(0.78, chance))


def weighted_open_shot_target(options: List[Player], score_fn) -> Player | None:
    if not options:
        return None

    weights = []
    for p in options:
        base = max(0.01, score_fn(p))
        diet = getattr(p, "shot_diet", {})
        wide_open_seen = diet.get("wide_open", 0)
        catch_seen = diet.get("catch_shoot", 0)
        repeat_damper = max(0.42, 1.0 - wide_open_seen * 0.10 - catch_seen * 0.025)
        weights.append((base * repeat_damper) ** 1.15)

    return random.choices(options, weights=weights, k=1)[0]


def find_double_team_kickout(off: Team, shooter: Player) -> Player:
    options = [p for p in off.on_floor if p is not shooter and not is_non_spacer(p)]
    options = designed_shooter_options(options, None)
    if not options:
        options = [p for p in off.on_floor if p is not shooter]
    elite_passer = shooter.playmaking >= 0.86
    return weighted_open_shot_target(
        options,
        lambda p: (
            (0.66 if elite_passer else 0.55) * p.three_rating
            + (0.20 if elite_passer else 0.25) * p.mid_rating
            + (0.10 if elite_passer else 0.20) * shooter_weight(p)
            + (0.04 if elite_passer else 0.0) * p.shot_tendency
        ) * catch_shoot_receiver_factor(p)
    )


def catch_shoot_creation_chance(passer: Player, shooter: Player, context: str) -> float:
    chance = 0.08 + passer.playmaking * 0.34 + passer.ball_handle * 0.08
    if context == "double":
        chance += 0.12 + max(0.0, passer.playmaking - 0.78) * 0.55
    elif context == "pnr":
        chance += 0.05
    elif context == "swing":
        chance += 0.04
    if shooter.three_rating >= 0.82 and shooter.three_tendency >= 0.24:
        chance += 0.10
    elif shooter.three_rating >= 0.76 and shooter.three_tendency > 0:
        chance += 0.06
    if "catch_shoot" in shooter.badges:
        chance += 0.07
    if "movement_shooter" in shooter.badges:
        chance += 0.035
    if passer.playmaking < 0.60:
        chance *= 0.70
    chance *= catch_shoot_receiver_factor(shooter)
    cap = 0.88 if context == "double" and passer.playmaking >= 0.86 else 0.68
    return max(0.05, min(cap, chance))


def find_pnr_catch_shoot_target(off: Team, handler: Player, screener: Player) -> Player | None:
    options = [
        p for p in off.on_floor
        if p not in (handler, screener)
        and not is_non_spacer(p)
        and can_be_designed_shooter(p)
        and p.three_tendency > 0
        and p.three_rating >= 0.74
    ]
    if not options:
        return None
    return weighted_open_shot_target(
        options,
        lambda p: (
            0.55 * p.three_rating + 0.25 * p.three_tendency + 0.20 * shooter_weight(p)
        ) * catch_shoot_receiver_factor(p)
    )


def is_non_shooting_big(player: Player) -> bool:
    return is_non_spacer(player) or (
        (can_play_position(player, "PF") or can_play_position(player, "C"))
        and player.three_rating < 0.45
        and player.three_tendency <= 0.08
    )


def find_paint_help_defender(off: Team, dff: Team, driver: Player,
                             primary_defender: Player,
                             matchups: Dict[Player, Player]) -> Tuple[Player | None, Player | None]:
    candidates = []
    for teammate in off.on_floor:
        if teammate is driver:
            continue
        if not is_non_spacer(teammate) and not (can_play_position(teammate, "PF") or can_play_position(teammate, "C")):
            continue
        if not is_non_spacer(teammate) and (teammate.three_rating >= 0.72 or teammate.three_tendency >= 0.18):
            continue

        helper = matchups.get(teammate)
        if helper is None or helper is primary_defender or helper.fouled_out:
            continue

        help_value = (
            0.52 * helper.interior_def
            + 0.34 * helper.block
            + 0.10 * height_advantage(helper, driver)
            + 0.04 * getattr(dff, "coach_style", {}).get("help_aggression", 1.0)
            + (0.16 if is_non_spacer(teammate) else 0.0)
        )
        finish_value = 0.55 * teammate.rim_rating + 0.30 * teammate.dunk_rating + 0.15 * teammate.dunk_tendency
        candidates.append((help_value + finish_value * 0.15, teammate, helper))

    if not candidates:
        return None, None

    _, teammate, helper = max(candidates, key=lambda item: item[0])
    return teammate, helper


def maybe_low_man_help(off: Team, dff: Team, driver: Player, defender: Player,
                       shot_type: str, matchups: Dict[Player, Player],
                       period: int, period_time: int) -> Tuple[Player, Player, str, Player | None, str | None, bool]:
    if shot_type not in ("rim", "dunk", "post"):
        return driver, defender, shot_type, None, None, False

    teammate, helper = find_paint_help_defender(off, dff, driver, defender, matchups)
    if teammate is None or helper is None:
        return driver, defender, shot_type, None, None, False

    styles = getattr(dff, "coach_style", {})
    help_chance = (
        0.045
        + styles.get("help_aggression", 1.0) * 0.055
        + helper.interior_def * 0.085
        + helper.block * 0.06
        - teammate.three_rating * 0.06
        + (0.08 if is_non_spacer(teammate) else 0.0)
    )
    if getattr(dff, "defensive_focus", None) == driver.name:
        help_chance += 0.035
    if random.random() > max(0.04, min(0.22, help_chance)):
        return driver, defender, shot_type, None, None, False

    help_lines = [
        f"{helper.name} leaves {teammate.name} in the dunker spot and slides over to help.",
        f"{helper.name} sinks off {teammate.name} and meets the drive in the paint.",
        f"{helper.name} tags the lane early, daring {driver.name} to make the dump-off pass.",
        f"{helper.name} steps across from the weak side to protect the rim.",
    ]
    print(random.choice(help_lines))
    time.sleep(SLEEP * 0.5)

    dump_chance = (
        0.08
        + driver.playmaking * 0.42
        + driver.ball_handle * 0.12
        - helper.interior_def * 0.10
        - helper.block * 0.05
    )
    if "transition_engine" in driver.badges or "post_hub" in driver.badges:
        dump_chance += 0.08

    if random.random() < max(0.08, min(0.62, dump_chance)):
        dump_finisher = teammate.rim_rating >= 0.74 or teammate.dunk_rating >= 0.74 or teammate.height >= 80
        if not can_be_designed_shooter(teammate) and not dump_finisher:
            driver.shot_quality_mult = getattr(driver, "shot_quality_mult", 1.0) * (0.88 - helper.interior_def * 0.05)
            return driver, helper, shot_type, None, "paint_help", False

        dump_lines = [
            f"{driver.name} slips the pass to {teammate.name} underneath.",
            f"{driver.name} drops it off to {teammate.name} before the help can recover.",
            f"{driver.name} reads the rotation and feeds {teammate.name} at the rim.",
            f"{driver.name} wraps a pass around the help to {teammate.name}.",
        ]
        print(random.choice(dump_lines))
        time.sleep(SLEEP * 0.5)
        elite_rim_helper = helper.block >= 0.82 or (helper.block >= 0.72 and helper.interior_def >= 0.88)
        # A driver who beats the first defender AND finds the drop-off before
        # the help fully recovers gets his teammate a catch-and-go finish, not
        # a contested one -- he goes straight up with it. Even against a
        # good-shot-blocking helper that's a clearly favorable look, not a
        # merely-average one.
        teammate.shot_quality_mult = getattr(teammate, "shot_quality_mult", 1.0) * (1.30 if elite_rim_helper else 1.55)
        dump_type = "dunk" if random.random() < effective_dunk_attempt_chance(teammate) else "rim"
        return teammate, helper, dump_type, driver, "dump_off_elite_help" if elite_rim_helper else "dump_off", True

    driver.shot_quality_mult = getattr(driver, "shot_quality_mult", 1.0) * (0.82 - helper.interior_def * 0.08)
    return driver, helper, shot_type, None, "paint_help", False

def switch_handler_advantage(handler: Player, switched_defender: Player, original_defender: Player) -> float:
    """
    Estimate whether the handler should actually like keeping the ball after a switch.
    Similar-sized forwards are not automatic mismatches; the edge should come from
    a real gap in mobility or containment.
    """
    handler_creation = (
        0.38 * handler.ball_handle
        + 0.22 * effective_speed(handler)
        + 0.20 * max(handler.mid_rating, handler.rim_rating)
        + 0.12 * handler.three_rating
        + 0.08 * handler.shot_iq
    )

    def switch_pressure(defender: Player) -> float:
        size = max(0.0, height_advantage(defender, handler))
        return (
            0.50 * effective_perimeter_def(defender)
            + 0.16 * effective_interior_def(defender)
            + 0.22 * effective_speed(defender)
            + 0.12 * size
        )

    original_pressure = switch_pressure(original_defender)
    new_pressure = switch_pressure(switched_defender)
    role_penalty = 0.0
    if handler.position in ("SF", "PF") and switched_defender.position in ("SF", "PF"):
        role_penalty += 0.07
    if switched_defender.height >= handler.height - 1 and switched_defender.position in ("SF", "PF"):
        role_penalty += 0.04

    return (original_pressure - new_pressure) + (handler_creation - new_pressure) * 0.32 - role_penalty

def maybe_pick_and_roll(off: Team, dff: Team,
                        handler: Player,
                        matchups: Dict[Player, Player]) -> Tuple[Player, Player, Player | None, str | None]:
    """
    Mostly guard-led pick-and-roll.
    Returns: handler, defender, screener, action_result
      action_result can be:
        None, "handler", "roller", "alley_oop", "popper", "pnr_catch_shoot", "reset"
    """
    if not (can_play_position(handler, "PG") or can_play_position(handler, "SG")):
        return handler, matchups.get(handler, random.choice(dff.on_floor)), None, None

    # Guards run this often, wings sometimes.
    pnr_chance = 0.28 + handler.playmaking * 0.22
    if random.random() > pnr_chance:
        return handler, matchups.get(handler, random.choice(dff.on_floor)), None, None

    screeners = [
        p for p in off.on_floor
        if p is not handler and (can_play_position(p, "PF") or can_play_position(p, "C"))
    ]
    if not screeners:
        return handler, matchups.get(handler, random.choice(dff.on_floor)), None, None

    screener = max(
        screeners,
        key=lambda p: 0.45 * p.rim_rating + 0.25 * p.dunk_rating + 0.20 * p.mid_rating + 0.10 * p.playmaking
    )

    handler_def = matchups.get(handler, random.choice(dff.on_floor))
    screener_def = matchups.get(screener, random.choice(dff.on_floor))
    screener_size_edge_on_handler_def = max(0, screener.height - handler_def.height)
    screener_size_edge_on_screener_def = max(0, screener.height - screener_def.height)

    print(f"{handler.name} calls for a high screen from {screener.name}.")
    time.sleep(SLEEP * 0.7)

    switch_chance = 0.18 + 0.30 * screener_def.perimeter_def + 0.15 * handler_def.interior_def
    scheme = getattr(dff, "game_plan", {}).get("defense", "standard")
    if scheme == "switch":
        switch_chance += 0.22
    elif scheme == "drop":
        switch_chance -= 0.18
    elif scheme in ("blitz", "show_recover"):
        switch_chance -= 0.08
    switch_chance = max(0.06, min(0.65, switch_chance))

    switched = random.random() < switch_chance

    if switched:
        print(f"{dff.name} switch it. {screener_def.name} picks up {handler.name}.")
        time.sleep(SLEEP * 0.6)
        defender = screener_def

        handler_edge = switch_handler_advantage(handler, defender, handler_def)
        screener_has_size_mismatch = screener_size_edge_on_handler_def >= 4
        force_screener_touch = screener_has_size_mismatch and random.random() < min(
            0.88,
            0.42 + handler.playmaking * 0.34 + screener_size_edge_on_handler_def * 0.035
        )

        if force_screener_touch and can_be_designed_shooter(screener) and has_shot_volume_left(screener):
            if screener.three_tendency >= 0.24 and screener.three_rating >= 0.72 and random.random() < 0.36:
                print(f"{screener.name} pops out with a smaller defender stuck on him, and {handler.name} finds him.")
                return screener, handler_def, screener, "popper"

            print(f"{screener.name} seals the smaller defender after the switch, and {handler.name} feeds him.")
            lob_chance = min(
                0.78,
                0.08 + handler.playmaking * 0.42 + screener.dunk_tendency * 0.22 + screener_size_edge_on_handler_def * 0.025
            )
            if random.random() < lob_chance:
                print(f"{handler.name} {random.choice(alley_oop_passes)} {screener.name}.")
                time.sleep(SLEEP * 0.5)
                print(f"{screener.name} {random.choice(alley_oop_catches)}.")
                return screener, handler_def, screener, "alley_oop"
            return screener, handler_def, screener, "roller"

        if handler_edge > 0.24 and random.random() < (0.34 if screener_has_size_mismatch else 0.62):
            switch_attack_lines = [
                f"{handler.name} sees the slower defender and keeps the ball.",
                f"{handler.name} has the switch he wanted and goes to work.",
                f"{handler.name} waves off the reset and attacks the switch.",
                f"{handler.name} pulls it back out to isolate the switched defender.",
            ]
            print(random.choice(switch_attack_lines))
            return handler, defender, screener, "handler"

        if handler_edge > 0.14 and random.random() < 0.24:
            print(f"{handler.name} keeps the dribble alive against the switch.")
            return handler, defender, screener, "handler"

        if can_be_designed_shooter(screener) and has_shot_volume_left(screener) and random.random() < screener.rim_rating * 0.35:
            print(f"{screener.name} slips behind the switch and rolls to the rim.")
            lob_chance = min(0.65, 0.08 + handler.playmaking * 0.42 + screener.dunk_tendency * 0.22)
            if random.random() < lob_chance:
                print(f"{handler.name} {random.choice(alley_oop_passes)} {screener.name}.")
                time.sleep(SLEEP * 0.5)
                print(f"{screener.name} {random.choice(alley_oop_catches)}.")
                return screener, handler_def, screener, "alley_oop"
            return screener, handler_def, screener, "roller"

        print(f"{handler.name} pulls it back out after the switch.")
        return handler, defender, screener, "reset"

    else:
        print(f"{handler_def.name} fights over the screen while {screener.name} rolls.")
        time.sleep(SLEEP * 0.6)

        height_mismatch = max(0, screener_size_edge_on_screener_def)
        roll_chance = 0.32 + handler.playmaking * 0.28 + screener.rim_rating * 0.20 + height_mismatch * 0.035
        pop_chance = 0.12 + screener.three_tendency * 0.28 + screener.mid_tendency * 0.16
        if height_mismatch >= 4 and screener.three_tendency >= 0.18 and screener.three_rating >= 0.70:
            pop_chance += height_mismatch * 0.018
        if height_mismatch >= 4:
            roll_chance += 0.12
        roll_chance = min(0.86, roll_chance)
        pop_chance = min(0.48, pop_chance)
        catch_shoot_target = find_pnr_catch_shoot_target(off, handler, screener)
        if catch_shoot_target and random.random() < catch_shoot_creation_chance(handler, catch_shoot_target, "pnr"):
            target_def = matchups.get(catch_shoot_target, random.choice(dff.on_floor))
            spray_lines = [
                f"{handler.name} sees the low man tag the roll and sprays it to {catch_shoot_target.name}.",
                f"{handler.name} pulls the help in and skips it out to {catch_shoot_target.name}.",
                f"{handler.name} reads the weak-side rotation and hits {catch_shoot_target.name}.",
                f"{handler.name} turns the corner, draws two, and fires it out to {catch_shoot_target.name}.",
                f"{handler.name} makes the defense collapse and finds {catch_shoot_target.name} outside."
            ]
            print(random.choice(spray_lines))
            return catch_shoot_target, target_def, screener, "pnr_catch_shoot"

        r = random.random()
        if r < roll_chance:
            if not can_be_designed_shooter(screener) or not has_shot_volume_left(screener):
                print(f"{handler.name} keeps it after the roll is covered.")
                return handler, handler_def, screener, "handler"
            lob_chance = min(0.70, 0.10 + handler.playmaking * 0.45 + screener.dunk_tendency * 0.25 - screener_def.interior_def * 0.12)
            if random.random() < lob_chance:
                print(f"{handler.name} {random.choice(alley_oop_passes)} {screener.name}.")
                time.sleep(SLEEP * 0.5)
                print(f"{screener.name} {random.choice(alley_oop_catches)}.")
                return screener, screener_def, screener, "alley_oop"

            roll_lines = [
                f"{handler.name} threads it to {screener.name} on the roll.",
                f"{handler.name} slips a bounce pass to {screener.name} diving down the lane.",
                f"{handler.name} hits {screener.name} in stride on the roll.",
                f"{handler.name} feeds {screener.name} as he cuts to the rim.",
                f"{handler.name} drops it off to {screener.name} rolling hard."
            ]
            print(random.choice(roll_lines))
            return screener, screener_def, screener, "roller"

        if r < roll_chance + pop_chance:
            if not can_be_designed_shooter(screener) or not has_shot_volume_left(screener):
                print(f"{handler.name} pulls it back out after the pop is covered.")
                return handler, handler_def, screener, "handler"
            print(f"{screener.name} pops into space and {handler.name} finds him.")
            return screener, screener_def, screener, "popper"

        print(f"{handler.name} turns the corner off the screen.")
        return handler, handler_def, screener, "handler"


def choose_shooter(team: Team) -> Player:
    players = designed_shooter_options(team.on_floor)
    volume_options = [p for p in players if has_shot_volume_left(p)]
    if volume_options:
        players = volume_options
    weights = [shooter_weight(p) * coach_shot_role_multiplier(team, p) for p in players]
    total = sum(weights)
    if total <= 0:
        return random.choice(players)
    r = random.random() * total
    cum = 0.0
    chosen = players[-1]
    for p, w in zip(players, weights):
        cum += w
        if r <= cum:
            chosen = p
            break
    return chosen

def try_pass_interception(passer: Player, receiver: Player,
                          off: Team, dff: Team,
                          matchups: Dict[Player, Player]) -> bool:
    defender = matchups.get(receiver, random.choice(dff.on_floor))

    if random.random() < pass_interception_chance(passer, receiver, defender):
        defender.stl += 1
        dff.team_stl += 1
        dff.last_stealer = defender
        commit_turnover(passer, off)
        record_defensive_turnover(defender, passer)

        print(steal_voice_line(defender, passer, "pass", passer=passer, receiver=receiver))
        time.sleep(SLEEP * 0.8)
        return True

    return False

def choose_shooter_excluding(team: Team, exclude: Player, allow_non_spacers: bool = True) -> Player:
    players = [
        p for p in team.on_floor
        if p is not exclude and (allow_non_spacers or not is_non_spacer(p))
    ]
    players = designed_shooter_options(players, None)
    if not players:
        players = [p for p in team.on_floor if p is not exclude]
    if not players:
        return exclude
    volume_options = [p for p in players if has_shot_volume_left(p)]
    if volume_options:
        players = volume_options
    weights = [shooter_weight(p) * coach_shot_role_multiplier(team, p) for p in players]
    total = sum(weights)
    if total <= 0:
        return random.choice(players)
    r = random.random() * total
    cum = 0.0
    chosen = players[-1]
    for p, w in zip(players, weights):
        cum += w
        if r <= cum:
            chosen = p
            break
    return chosen


def choose_ball_movement_receiver(team: Team, passer: Player, avoid: Tuple[Player, ...] = tuple()) -> Player:
    players = [
        p for p in team.on_floor
        if p is not passer
        and p not in avoid
        and not is_non_spacer(p)
    ]
    players = designed_shooter_options(players, None)
    if not players:
        players = [p for p in team.on_floor if p is not passer]
    if not players:
        return passer

    weights = [
        max(
            0.01,
            0.42 * shooter_weight(p)
            + 0.18 * p.three_rating
            + 0.16 * p.mid_rating
            + 0.12 * p.rim_rating
            + 0.12 * assist_load_factor(p, team)
        )
        * coach_shot_role_multiplier(team, p)
        for p in players
    ]
    return random.choices(players, weights=weights, k=1)[0]


def maybe_reroute_spurs_role_shot(team: Team, shooter: Player) -> Player:
    if team.name != "2014 San Antonio Spurs":
        return shooter

    reroute_chance = 0.0
    if shooter.name == "Danny Green" and shooter.fga >= 10:
        reroute_chance = 0.88
    elif shooter.name == "Kawhi Leonard" and shooter.fga >= 14:
        reroute_chance = 0.90
    elif shooter.name == "Tim Duncan" and shooter.fga >= 18:
        reroute_chance = 0.72
    elif shooter.usage < 0.18 and shooter.fga >= 11:
        reroute_chance = 0.55

    if reroute_chance <= 0 or random.random() >= reroute_chance:
        return shooter

    options = [
        p for p in team.on_floor
        if p is not shooter
        and p.name in ("Tony Parker", "Manu Ginobili", "Tim Duncan", "Boris Diaw", "Patty Mills")
        and not (p.name == "Tim Duncan" and p.fga >= 18)
        and not (p.name in ("Tony Parker", "Manu Ginobili") and p.fga >= 18)
    ]
    if not options:
        return shooter
    weights = [
        max(0.01, 0.35 * p.usage + 0.25 * p.mid_rating + 0.25 * p.rim_rating + 0.15 * p.playmaking)
        for p in options
    ]
    return random.choices(options, weights=weights, k=1)[0]


