    if len(stars) == 1:
        team.last_mavs_2024_fourth_star = stars[0].name
        return stars[0]

    luka_fga = getattr(luka, "fourth_fga", 0)
    kyrie_fga = getattr(kyrie, "fourth_fga", 0)

