    if choices:
        if need_three:
            three_choices = [p for p in choices if any(word in p for word in ("pin", "relocate", "corner", "pindown", "slot", "shake"))]
            return random.choice(three_choices or list(choices))
        return random.choice(choices)

    if need_three and any(p.three_rating >= 0.84 and p.three_tendency >= 0.30 for p in team.on_floor):
        return random.choice(("floppy", "elevator", "drive_kick", "sideline_curl_three", "ghost_screen_three"))
