def choose_ballhandler(team: Team) -> Player:
    """
    Default: initiate through the best creators, prioritizing playmaking.
    Special-case: 2017 Warriors -> Curry and Draymond initiate most actions;
    KD is treated more like an elite scoring release valve than a point forward.
    """
    if team.name in ("2016 Golden State Warriors", "2017 Golden State Warriors", "2019 Golden State Warriors", "2022 Golden State Warriors"):
        preferred = [p for p in team.on_floor if p.name in ("Stephen Curry", "Draymond Green", "Andre Iguodala", "Shaun Livingston")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.45)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (0.72 if p.name == "Stephen Curry" else 1.0)
                * (1.28 if p.name in ("Draymond Green", "Andre Iguodala") else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    if team.name == "1987 Los Angeles Lakers":
        magic = player_by_name(team.on_floor, ("Magic Johnson",))
        # Showtime runs through Magic -- he brought the ball up and
        # orchestrated the offense on nearly every single possession, an
        # even more extreme case than a typical modern point-forward hub.
        if magic is not None and not magic.fouled_out and random.random() < 0.90:
            return magic
        preferred = [p for p in team.on_floor if p.name in ("Magic Johnson", "Byron Scott", "James Worthy")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.60)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (2.40 if p.name == "Magic Johnson" else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    if team.name == "1987 Boston Celtics":
        dj = player_by_name(team.on_floor, ("Dennis Johnson",))
        # DJ ran the Celtics' offense as the primary initiator; Bird was the
        # focal scorer and secondary creator, not the team's main ball-handler
        # on most possessions.
        if dj is not None and not dj.fouled_out and random.random() < 0.78:
            return dj
        preferred = [p for p in team.on_floor if p.name in ("Dennis Johnson", "Danny Ainge", "Larry Bird")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.60)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (2.00 if p.name == "Dennis Johnson" else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    if team.name == "2014 San Antonio Spurs":
        preferred = [p for p in team.on_floor if p.name in ("Tony Parker", "Manu Ginobili", "Boris Diaw", "Patty Mills")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.35)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (1.35 if p.name == "Tony Parker" else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    if team.name == "2027 Philadelphia 76ers":
        lebron = player_by_name(team.on_floor, ("LeBron James",))
        # LeBron is Philadelphia's point forward. Keep a little secondary
        # initiation for Maxey/Simons, but have LeBron bring up and organize
        # the large majority of possessions throughout the entire game.
        if lebron is not None and not lebron.fouled_out and random.random() < 0.84:
            return lebron
        preferred = [p for p in team.on_floor if p.name in ("LeBron James", "Tyrese Maxey", "Anfernee Simons")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.60)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (2.15 if p.name == "LeBron James" else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    if team.name == "2024 Dallas Mavericks":
        # Luka runs the offense in the 1st and 3rd; Kyrie takes the reins
        # in the 2nd and 4th -- an explicit quarter-by-quarter alternation
        # of who initiates (and therefore scores) the Mavs' offense.
        period = SIM_CONTEXT.get("period", 1)
        primary_name = "Luka Doncic" if period in (1, 3) else "Kyrie Irving"
        primary = player_by_name(team.on_floor, (primary_name,))
        if primary is not None and not primary.fouled_out and random.random() < 0.80:
            return primary
        preferred = [p for p in team.on_floor if p.name in ("Luka Doncic", "Kyrie Irving")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.50)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (2.20 if p.name == primary_name else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    if team.name == "2026 Dallas Mavericks":
        flagg = player_by_name(team.on_floor, ("Cooper Flagg",))
        # Flagg runs Dallas's offense as the primary initiator -- he's
        # listed at SF but plays like a point forward, bringing the ball
        # up and setting up the action on most possessions.
        if flagg is not None and not flagg.fouled_out and random.random() < 0.70:
            return flagg
        preferred = [p for p in team.on_floor if p.name in ("Cooper Flagg", "Brandon Williams", "Max Christie")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.60)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (2.20 if p.name == "Cooper Flagg" else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    if team.name == "2012 Boston Celtics":
        rondo = player_by_name(team.on_floor, ("Rajon Rondo",))
        # Rondo brought the ball up and ran the offense on almost every
        # possession -- he wasn't a scorer competing for touches with Pierce
        # and Allen, he was the engine setting them up. His playmaking is
        # already at the rating ceiling (0.99), so there's no rating left to
        # raise; this is purely about making sure he actually gets the
        # touches his rating already says he should.
        if rondo is not None and not rondo.fouled_out and random.random() < 0.90:
            return rondo
        preferred = [p for p in team.on_floor if p.name in ("Rajon Rondo", "Paul Pierce", "Ray Allen")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.60)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (2.20 if p.name == "Rajon Rondo" else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    if team.name == "2027 Denver Nuggets":
        jokic = player_by_name(team.on_floor, ("Nikola Jokic",))
        # Jokic's playmaking doesn't come from bringing the ball up like a
        # guard -- it comes from elbow and high-post touches, dribble
        # hand-offs, and short-roll reads. The generic PG/SG-gated handler
        # logic below structurally locks a pure center out of ever being
        # the possession hub, which is exactly backwards for a point-center.
        # Route the offense through him directly instead -- Murray's share
        # (and thus his assist opportunities) drops purely as a byproduct
        # of fewer possessions to initiate, not from any rating or cap.
        if jokic is not None and not jokic.fouled_out and random.random() < 0.62:
            return jokic
        preferred = [p for p in team.on_floor if p.name in ("Nikola Jokic", "Jamal Murray", "Aaron Gordon")]
        if preferred:
            weights = [
                max(0.01, playmaking_hub_score(p) ** 1.60)
                * assist_load_factor(p, team)
                * coach_handler_multiplier(team, p)
                * fatigue_touch_multiplier(p)
                * (2.10 if p.name == "Nikola Jokic" else 1.0)
                for p in preferred
            ]
            return random.choices(preferred, weights=weights, k=1)[0]

    # Any position can be a bring-up candidate if the handle and playmaking
    # actually back it up -- a "point center" or point forward shouldn't be
    # structurally locked out just because he isn't a guard. This used to
    # only extend the exception to SFs, which is exactly backwards: real
    # non-guard playmaking hubs (a Jokic, a Draymond) are usually bigs.
    bring_up_candidates = [
        p for p in team.on_floor
        if can_play_position(p, "PG")
        or can_play_position(p, "SG")
        or (p.ball_handle >= 0.64 and p.playmaking >= 0.58)
    ]
    if not bring_up_candidates:
        bring_up_candidates = [
            p for p in team.on_floor
            if p.ball_handle >= 0.55 or p.playmaking >= 0.62
        ]
    if not bring_up_candidates:
        bring_up_candidates = list(team.on_floor)

    sorted_players = sorted(bring_up_candidates, key=playmaking_hub_score, reverse=True)
    top_four = sorted_players[:4] if len(sorted_players) >= 4 else sorted_players
    weights = [
        max(0.01, playmaking_hub_score(p) ** 1.50)
        * assist_load_factor(p, team)
        * coach_handler_multiplier(team, p)
        * fatigue_touch_multiplier(p)
        * (0.28 if can_play_position(p, "C") else 1.0)
        * (0.55 if can_play_position(p, "PF") and not can_play_position(p, "SF") else 1.0)
        for p in top_four
    ]
    return random.choices(top_four, weights=weights, k=1)[0]


def maybe_secondary_initiator(team: Team, primary: Player) -> Player:
    if primary.name == "Rajon Rondo" and primary.ast < 11:
        return primary
    if team.name == "2027 Philadelphia 76ers" and primary.name == "LeBron James":
        # Do not undo the point-forward assignment immediately after choosing
        # him as the primary handler. His assist load is managed downstream.
        return primary
    if primary.ast < 4:
        return primary

    candidates = [
        p for p in team.on_floor
        if p is not primary
        and not p.fouled_out
        and not (team.name == "2027 Philadelphia 76ers" and p.name == "Jaylen Brown")
        and (p.playmaking >= 0.45 or can_play_position(p, "PG") or can_play_position(p, "SG"))
    ]
    if not candidates:
        return primary

    team_assists = sum(p.ast for p in team.roster)
    primary_share = primary.ast / max(1, team_assists)
    chance = min(0.82, 0.18 + primary.ast * 0.055 + max(0.0, primary_share - 0.34) * 0.90)
    if random.random() >= chance:
        return primary

    weights = [
        max(0.01, playmaking_hub_score(p) ** 1.25)
        * assist_load_factor(p, team)
        * assist_distribution_multiplier(p, team)
        for p in candidates
    ]
    return random.choices(candidates, weights=weights, k=1)[0]


def choose_secondary_assist_passer(team: Team, shooter: Player, primary: Player | None) -> Player | None:
    candidates = [
        p for p in team.on_floor
        if p is not shooter
        and p is not primary
        and not p.fouled_out
        and (p.playmaking >= 0.58 or can_play_position(p, "PG") or can_play_position(p, "SG"))
        and (p.playmaking >= 0.90 or p.ast < 10)
    ]
    if not candidates:
        return None

    weights = [
        max(0.01, 0.54 * p.playmaking + 0.28 * p.ball_handle + 0.12 * p.usage + 0.06 * p.clutchness)
        * assist_load_factor(p, team)
        * assist_distribution_multiplier(p, team)
        for p in candidates
    ]
    return random.choices(candidates, weights=weights, k=1)[0]


def immediate_catch_chance(passer: Player, base: float, slope: float = 0.44,
                           lo: float = 0.20, hi: float = 0.78, bonus: float = 0.0) -> float:
    """
    Shared probability model for "did this pass turn into an immediate,
    uninterrupted catch-and-shoot" -- used at every non-guaranteed assist
    pathway (paint entries, PNR feeds, dribble-combo kick-outs, pressure
    resets, double-team kickouts). Once this comes back True, the resulting
    make IS a direct assist, full stop -- that's not up for a second gate.
    What varies by pathway is only how likely the catch was to actually be
    that clean in the first place, which is why every call site here scales
    off the same one thing: the passer's playmaking. Each caller supplies
    its own base/slope/bonus so the exact numbers per pathway are unchanged;
    this just stops the formula shape itself from being re-typed everywhere.
    """
    return max(lo, min(hi, base + slope * passer.playmaking + bonus))


def assist_credit_chance(passer: Player, shooter: Player, shot_type: str,
                         pnr_result: str | None = None,
                         quick_shot: bool = True) -> float:
    # A direct pass into a shot IS an assist -- that isn't up for a
    # coin flip. The passer's playmaking instead governs, upstream, how
    # often a possession actually produces that direct/quick look in the
    # first place (see the immediate_chance calc where quick_shot_for_assist
    # gets decided) rather than retroactively denying credit for one that
    # already happened.
    if quick_shot:
        return 1.0
    # Delayed finishes may still be assisted, but at a substantially lower
    # rate than true one-motion catches. Playmaking remains the main driver.
    base = 0.36 + passer.playmaking * 0.34
    if can_play_position(passer, "PG"):
        base += 0.09
    if "post_hub" in passer.badges or "transition_engine" in passer.badges:
        base += 0.08
    if pnr_result in ("roller", "popper", "alley_oop"):
        base += 0.24
    if pnr_result in ("dump_off", "dump_off_elite_help"):
        base += 0.30
    if pnr_result in ("floppy", "elevator", "handoff", "horns", "drive_kick", "backdoor", "double_kick", "double_wide_open", "pnr_catch_shoot", "extra_pass_open", "post_split", "ball_movement_chain", "sideline_curl_three", "ghost_screen_three", "quick_slip"):
        base += 0.20
    if pnr_result in ("double_wide_open", "pnr_catch_shoot", "extra_pass_open"):
        base += 0.07
    if pnr_result in PLAYBOOK_CONTEXTS:
        base += 0.18
    if pnr_result == "spain_pnr":
        base += 0.16
    if pnr_result == "fastbreak":
        base += 0.18
    if shot_type in ("dunk", "rim"):
        base += 0.10
    if not quick_shot:
        base -= 0.16
    if passer.playmaking < 0.55:
        base -= 0.26
    elif passer.playmaking < 0.62:
        base -= 0.18
    elif passer.playmaking < 0.72:
        base -= 0.07
    if passer.usage >= 0.28 and passer.playmaking < 0.78:
        base -= 0.18
    if passer.name == "Kevin Durant":
        base -= 0.30
    base *= assist_volume_factor(passer)
    base *= assist_phase_relief(passer)
    if passer.name == "Rajon Rondo" and passer.ast < 13:
        base *= 1.06
    if pnr_result in ("dump_off", "dump_off_elite_help") and shot_type in ("rim", "dunk"):
        return max(0.78, min(0.96, base))
    if passer.playmaking <= 0.65:
        base *= 0.62
    if passer.playmaking < 0.45:
        return max(0.03, min(0.22, base))
    if passer.playmaking < 0.55:
        return max(0.05, min(0.30, base))
    if passer.playmaking <= 0.65:
        return max(0.08, min(0.44, base))
    if passer.playmaking < 0.82:
        return max(0.12, min(0.66, base))
    if passer.playmaking < 0.90:
        return max(0.14, min(0.76, base))
    return max(0.15, min(0.86, base))


def transition_take_foul_chance(defender: Player, period: int, period_time: int) -> float:
    if period >= 4 and period_time <= 2 * 60:
        return 0.0
    chance = TRANSITION_TAKE_FOUL_RATE + foul_rate_sim(defender) * 0.20
    if PLAYOFF_MODE:
        chance *= 0.85
    return max(0.04, min(0.32, chance))


def choose_chasedown_defender(def_team: Team, finisher: Player) -> Player | None:
    candidates = [
        p for p in def_team.on_floor
        if not p.fouled_out
        and p is not finisher
        and (badge_tier(p, "chasedown") > 0 or (p.block >= 0.42 and effective_speed(p) >= 0.72))
    ]
    if not candidates:
        return None

    weights = [
        max(
            0.01,
            0.48 * effective_speed(p)
            + 0.30 * p.block
            + 0.12 * p.interior_def
            + 0.10 * p.perimeter_def
            + badge_tier(p, "chasedown") * 0.18
        )
        for p in candidates
    ]
    return random.choices(candidates, weights=weights, k=1)[0]


def chasedown_block_chance(defender: Player, finisher: Player, shot_type: str) -> float:
    if shot_type not in ("rim", "dunk"):
        return 0.0
    tier = badge_tier(defender, "chasedown")
    speed_edge = max(0.0, effective_speed(defender) - effective_speed(finisher))
    chance = 0.010 + tier * 0.020 + defender.block * 0.055 + speed_edge * 0.055
    if defender.name == "LeBron James":
        chance += 0.020
    if shot_type == "dunk":
        chance *= 0.82
    if PLAYOFF_MODE:
        chance *= 1.06
    return max(0.0, min(0.20, chance))


# ============================================================
# POSSESSION / PLAY
# ============================================================

def run_fastbreak(def_team: Team, off_team: Team, period: int, period_time: int,
                  teamA: Team, teamB: Team,
                  source: str = "live", trigger_player: Player | None = None):
    ballhandlers = sorted(
        def_team.on_floor,
        key=lambda p: 0.40 * p.ball_handle + 0.25 * p.playmaking + 0.25 * effective_speed(p) + 0.10 * p.usage,
        reverse=True
    )[:2]
    if trigger_player in def_team.on_floor and source == "steal":
        handler = trigger_player
    elif trigger_player in def_team.on_floor and source == "rebound":
        rebound_push_score = 0.48 * effective_speed(trigger_player) + 0.30 * trigger_player.ball_handle + 0.22 * trigger_player.playmaking
        handler = trigger_player if random.random() < max(0.12, min(0.62, rebound_push_score)) else random.choice(ballhandlers)
    else:
        weights = [max(0.01, 0.40 * p.ball_handle + 0.28 * effective_speed(p) + 0.22 * p.playmaking + 0.10 * p.usage) for p in ballhandlers]
        handler = random.choices(ballhandlers, weights=weights, k=1)[0]
    print(f"{handler.name} turns defense into offense and races into the open floor.")
    time.sleep(SLEEP * 0.7)

    finisher = handler
    fastbreak_passer = None
    if source == "steal":
        pass_ahead_chance = max(0.18, min(0.48, 0.42 - effective_speed(handler) * 0.20 + handler.playmaking * 0.16))
    elif source == "rebound":
        pass_ahead_chance = max(0.50, min(0.82, 0.58 + handler.playmaking * 0.18 - effective_speed(handler) * 0.06))
    else:
        pass_ahead_chance = 0.54

    if random.random() < pass_ahead_chance:
        finisher = choose_shooter_excluding(def_team, handler, allow_non_spacers=True)
        fastbreak_passer = handler
        line = random.choice(pp5)
        print(f"{handler.name} {line} {finisher.name} on the break.")
        time.sleep(SLEEP * 0.6)

    defender = random.choice(off_team.on_floor)
    transition_ballhandler = finisher if fastbreak_passer is not None else handler
    transition_three_options = [
        p for p in def_team.on_floor
        if p is not transition_ballhandler
        and p.three_tendency >= 0.28
        and p.three_rating >= 0.78
        and has_shot_volume_left(p)
        and catch_shoot_receiver_factor(p) >= 0.20
    ]
    transition_three_chance = 0.11 + transition_ballhandler.playmaking * 0.13
    if source == "rebound":
        transition_three_chance += 0.06
    transition_three_chance *= THREE_ATTEMPT_SCALE
    # Once the ball has already been passed ahead, finish that break instead of
    # narrating another kick-out from the original handler.
    if fastbreak_passer is None and transition_three_options and random.random() < min(0.34, transition_three_chance):
        shooter = weighted_open_shot_target(
            transition_three_options,
            lambda p: (
                0.55 * p.three_rating + 0.20 * p.shot_tendency + 0.15 * p.speed + 0.10 * p.clutchness
            ) * catch_shoot_receiver_factor(p)
        )
        print(f"{transition_ballhandler.name} draws the defense in transition and sprays it out to {shooter.name}.")
        time.sleep(SLEEP * 0.45)
        print(f"{shooter.name} {random.choice(wide_open_catch_shoot_lines)}")
        time.sleep(SLEEP * 0.55)

        transition_catch_quality = 1.14 + catch_shoot_badge_quality_bonus(shooter)
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * transition_catch_quality
        make_prob = shot_make_prob(shooter, defender, "three", def_team, off_team, period, period_time)
        make_prob = max(make_prob, min(0.60, 0.45 + shooter.three_rating * 0.12 + effective_speed(shooter) * 0.04))
        clear_shot_temp_bonuses(shooter)

        shooter.fga += 1
        shooter.tpa += 1
        record_shot_diet(def_team, "three", "fastbreak_catch_shoot|wide_open", shooter, defender, quality_mult=transition_catch_quality)

        if random.random() < make_prob:
            shooter.fgm += 1
            shooter.tpm += 1
            shooter.pts += 3
            def_team.score += 3
            def_team.fastbreak_pts += 3
            record_shot_make(def_team, "three", "fastbreak_catch_shoot|wide_open", shooter, defender)
            if transition_ballhandler is not shooter:
                record_assist(transition_ballhandler, def_team, 3)
            record_score_event(def_team, off_team, 3, period, period_time, teamA, teamB, check_timeout=False)
            update_shot_rhythm(shooter, True, "three")
            print(f"{shooter.name} knocks down the transition three.")
            time.sleep(SLEEP * 0.7)
            print_scoreboard(period, period_time, teamA, teamB)
            maybe_call_timeout_after_score(def_team, off_team, period, period_time, teamA, teamB)
            return off_team

        update_shot_rhythm(shooter, False, "three")
        print(f"{shooter.name} misses the wide open transition three.")
        time.sleep(SLEEP * 0.6)
        reb_team, rebounder = choose_rebounder(def_team, off_team, "jumper")
        print(f"{rebounder.name} pulls down the rebound.")
        time.sleep(SLEEP * 0.6)
        print_scoreboard(period, period_time, teamA, teamB)
        return reb_team

    rim_attack_chance = max(0.72, min(0.93, 0.76 + effective_speed(finisher) * 0.16))
    shot_type = "rim" if random.random() < rim_attack_chance else "mid"

    if shot_type == "rim" and random.random() < effective_dunk_attempt_chance(finisher):
        shot_type = "dunk"

    foul_chance = foul_draw_sim(finisher) * usage_foul_weight(finisher) * FOUL_SCALE * 1.30 * foul_trouble_foul_factor(defender)
    if PLAYOFF_MODE:
        foul_chance *= 0.88
    is_foul = random.random() < foul_chance

    if is_foul:
        fouler = choose_fouling_defender(off_team, defender, finisher, shot_type, "transition")
        register_foul(off_team, fouler)
        finisher.fouls_drawn += 1
        def_team.fouls_drawn += 1

        if random.random() < TRANSITION_FLAGRANT_RATE:
            print(random.choice(transition_flagrant_lines).format(
                defender=fouler.name,
                finisher=finisher.name
            ))
            time.sleep(SLEEP * 0.6)
            print(f"Flagrant foul on {fouler.name}. {finisher.name} gets one free throw, and {def_team.name} keep possession.")
            time.sleep(SLEEP * 0.6)

            if fouler.pf >= 6:
                foul_out_sub(off_team, fouler)

            shoot_retained_free_throw(finisher, def_team, period, period_time, teamA, teamB, label="flagrant free throw")
            dead_ball_subs(
                teamA, teamB, period, period_time,
                protected_teamA=finisher if def_team is teamA else None,
                protected_teamB=finisher if def_team is teamB else None,
            )
            return def_team

        if random.random() < 0.08:
            print(f"Clear path foul on {fouler.name}. {finisher.name} had open floor ahead.")
            time.sleep(SLEEP * 0.6)
            print(f"{finisher.name} shoots one, and {def_team.name} keep possession.")
            time.sleep(SLEEP * 0.6)

            if fouler.pf >= 6:
                foul_out_sub(off_team, fouler)
            else:
                maybe_sit_foul_trouble(off_team, fouler, period)

            shoot_retained_free_throw(
                finisher, def_team, period, period_time, teamA, teamB,
                label="clear-path free throw"
            )
            dead_ball_subs(
                teamA, teamB, period, period_time,
                protected_teamA=finisher if def_team is teamA else None,
                protected_teamB=finisher if def_team is teamB else None,
            )
            return def_team

        if random.random() < transition_take_foul_chance(fouler, period, period_time):
            take_ft_shooter = max(def_team.on_floor, key=lambda p: effective_ft_rating(p, def_team, off_team, period, period_time))
            print(random.choice(transition_take_foul_lines).format(
                defender=fouler.name,
                handler=handler.name,
                finisher=finisher.name
            ))
            time.sleep(SLEEP * 0.6)
            print(f"Transition take foul on {fouler.name}. {take_ft_shooter.name} shoots one, and {def_team.name} keep possession.")
            time.sleep(SLEEP * 0.6)

            if fouler.pf >= 6:
                foul_out_sub(off_team, fouler)
            else:
                maybe_sit_foul_trouble(off_team, fouler, period)

            shoot_retained_free_throw(
                take_ft_shooter, def_team, period, period_time, teamA, teamB,
                label="take-foul free throw"
            )
            dead_ball_subs(
                teamA, teamB, period, period_time,
                protected_teamA=take_ft_shooter if def_team is teamA else None,
                protected_teamB=take_ft_shooter if def_team is teamB else None,
            )
            return def_team

        print(commentator_foul(fouler.name, finisher.name))
        time.sleep(SLEEP * 0.6)
        maybe_technical_foul(off_team, def_team, period, period_time, teamA, teamB, reason="arguing the transition foul")

        if fouler.pf >= 6:
            foul_out_sub(off_team, fouler)
        else:
            maybe_sit_foul_trouble(off_team, fouler, period)

        next_possession = shoot_free_throws(
            finisher, def_team, 2, period, period_time, teamA, teamB,
            sub_after_first=True, protected=finisher
        )
        return next_possession

    chasedown_defender = choose_chasedown_defender(off_team, finisher) if shot_type in ("rim", "dunk") else None
    if chasedown_defender is not None and random.random() < chasedown_block_chance(chasedown_defender, finisher, shot_type):
        record_shot_diet(def_team, shot_type, "fastbreak|contested", finisher, chasedown_defender, quality_mult=0.90)
        finisher.fga += 1
        print(random.choice(chasedown_block_lines).format(
            defender=chasedown_defender.name,
            finisher=finisher.name
        ))
        process_block(chasedown_defender, off_team)
        time.sleep(SLEEP * 0.7)

        reb_team, rebounder = choose_rebounder(def_team, off_team, "rim")
        print(f"{rebounder.name} comes down with the rebound after the chasedown block.")
        time.sleep(SLEEP * 0.6)
        print_scoreboard(period, period_time, teamA, teamB)
        return reb_team

    transition_block_chance = block_prob(defender, shot_type, finisher) * (0.45 if shot_type in ("rim", "dunk") else 0.60)
    if random.random() < transition_block_chance:
        record_shot_diet(def_team, shot_type, "fastbreak|contested", finisher, defender, quality_mult=0.94)
        finisher.fga += 1
        if shot_type == "three":
            finisher.tpa += 1
        if shot_type == "dunk":
            print(block_voice_line(defender, finisher, shot_type, "transition"))
        else:
            print(block_voice_line(defender, finisher, shot_type, "transition"))

        process_block(defender, off_team)
        time.sleep(SLEEP * 0.7)

        reb_team, rebounder = choose_rebounder(def_team, off_team, "rim")
        print(commentator_rebound(rebounder.name, reb_team.name))
        time.sleep(SLEEP * 0.6)

        return reb_team

    # Not every break is a clean one -- how much separation the finisher
    # actually has (his speed vs. the recovering defender's, plus whether
    # this came off a live-ball steal, which tends to produce the cleanest
    # numbers advantage) decides whether this is a genuinely wide-open look
    # or one the defense partially ran down. Only the wide-open subset gets
    # the full "this basically always goes in" treatment; a contested break
    # still carries real miss chance like any other shot.
    speed_edge = effective_speed(finisher) - effective_speed(defender)
    open_break_chance = 0.52 + max(-0.30, min(0.32, speed_edge * 0.65))
    if source == "steal":
        open_break_chance += 0.14
    elif source == "rebound":
        open_break_chance -= 0.06
    open_break_chance = max(0.22, min(0.90, open_break_chance))
    fastbreak_wide_open = random.random() < open_break_chance

    if shot_type in ("rim", "dunk"):
        transition_boost = (1.35 + effective_speed(finisher) * 0.20) if fastbreak_wide_open else (0.86 + effective_speed(finisher) * 0.14)
    else:
        transition_boost = (1.15 + effective_speed(finisher) * 0.15) if fastbreak_wide_open else (0.88 + effective_speed(finisher) * 0.10)
    if source == "steal":
        transition_boost += 0.06
    if shot_type == "dunk":
        transition_poster_bonus = posterizer_quality_bonus(finisher, defender)
        if transition_poster_bonus:
            finisher.posterizer_quality_bonus = transition_poster_bonus
    finisher.shot_quality_mult = getattr(finisher, "shot_quality_mult", 1.0) * transition_boost
    make_prob = shot_make_prob(finisher, defender, shot_type, def_team, off_team, period, period_time)
    if shot_type in ("rim", "dunk"):
        transition_floor = (0.72 if fastbreak_wide_open else 0.52) + effective_speed(finisher) * 0.10 + finisher.rim_rating * 0.05
        if shot_type == "dunk":
            transition_floor += 0.04
        if source == "steal":
            transition_floor += 0.03
        make_prob = max(make_prob, min(0.88, transition_floor))
    else:
        base_mid_floor = 0.54 if fastbreak_wide_open else 0.40
        make_prob = max(make_prob, min(0.68, base_mid_floor + effective_speed(finisher) * 0.08 + finisher.mid_rating * 0.06))
    clear_shot_temp_bonuses(finisher)

    fastbreak_context = "fastbreak|wide_open" if fastbreak_wide_open else "fastbreak|contested"

    finisher.fga += 1
    record_shot_diet(def_team, shot_type, fastbreak_context, finisher, defender, quality_mult=transition_boost)
    if shot_type == "three":
        finisher.tpa += 1

    made = random.random() < make_prob

    if made:
        pts = 3 if shot_type == "three" else 2
        finisher.fgm += 1
        finisher.pts += pts
        record_shot_make(def_team, shot_type, fastbreak_context, finisher, defender)

        if shot_type == "three":
            finisher.tpm += 1

        def_team.score += pts
        def_team.fastbreak_pts += pts
        if shot_type in ("rim", "dunk"):
            def_team.points_paint += pts
        record_score_event(def_team, off_team, pts, period, period_time, teamA, teamB, check_timeout=False)
        update_shot_rhythm(finisher, True, shot_type)
        maybe_injury_stinger(finisher, def_team, shot_type, period)

        if (
            fastbreak_passer
            and fastbreak_passer is not finisher
        ):
            record_assist(fastbreak_passer, def_team, pts)

        if shot_type == "dunk":
            line = random.choice(dunk_poster_lines).format(defender=defender.name)
            print(f"{finisher.name} takes off in transition and {line}")
        else:
            line = random.choice(def_int_make) if is_paint_shot(shot_type) else random.choice(def_per_make)
            print(commentator_make(finisher.name, defender.name, shot_type, line))

        time.sleep(SLEEP * 0.7)
        print_scoreboard(period, period_time, teamA, teamB)
        maybe_crowd_moment(def_team, off_team, finisher, pts)
        maybe_defensive_adjustment(off_team, finisher)
        maybe_call_timeout_after_score(def_team, off_team, period, period_time, teamA, teamB)
        return off_team

    else:
        update_shot_rhythm(finisher, False, shot_type)
        if shot_type == "dunk":
            line = random.choice(dunk_miss_lines)
            print(f"{finisher.name} goes for the hammer but {line}")
        else:
            line = random.choice(def_int_miss) if is_paint_shot(shot_type) else random.choice(def_per_miss)
            print(commentator_miss(finisher.name, defender.name, shot_type, line))

        time.sleep(SLEEP * 0.7)

        reb_team, rebounder = choose_rebounder(def_team, off_team, "rim")
        print(commentator_rebound(rebounder.name, reb_team.name))
        time.sleep(SLEEP * 0.6)

        # Offensive rebound on the break: immediate putback.
        if reb_team is def_team:
            putback_defender = random.choice(off_team.on_floor)
            putback_type = "dunk" if random.random() < effective_dunk_attempt_chance(rebounder) else "rim"

            print(f"{rebounder.name} goes right back up with it.")
            time.sleep(SLEEP * 0.6)

            if random.random() < block_prob(putback_defender, putback_type, rebounder):
                print(block_voice_line(putback_defender, rebounder, putback_type, "putback"))
                process_block(putback_defender, off_team)
                time.sleep(SLEEP * 0.6)

                second_reb_team, second_rebounder = choose_rebounder(def_team, off_team, "rim")
                print(commentator_rebound(second_rebounder.name, second_reb_team.name))
                time.sleep(SLEEP * 0.6)
                print_scoreboard(period, period_time, teamA, teamB)
                return second_reb_team

            rebounder.fga += 1
            record_shot_diet(def_team, putback_type, "putback|contested", rebounder, putback_defender)
            make_prob = shot_make_prob(
                rebounder, putback_defender, putback_type,
                def_team, off_team, period, period_time
            )

            if random.random() < make_prob:
                rebounder.fgm += 1
                rebounder.pts += 2
                record_shot_make(def_team, putback_type, "putback|contested", rebounder, putback_defender)
                def_team.score += 2
                def_team.points_paint += 2
                def_team.second_chance_pts += 2
                def_team.fastbreak_pts += 2
                record_score_event(def_team, off_team, 2, period, period_time, teamA, teamB)

                if putback_type == "dunk":
                    print(f"{rebounder.name} slams home the putback in transition.")
                else:
                    print(f"{rebounder.name} lays in the putback after the offensive board.")

                time.sleep(SLEEP * 0.7)
                print_scoreboard(period, period_time, teamA, teamB)
                return off_team

            print(f"{rebounder.name} misses the quick putback.")
            time.sleep(SLEEP * 0.6)

            second_reb_team, second_rebounder = choose_rebounder(def_team, off_team, "rim")
            print(commentator_rebound(second_rebounder.name, second_reb_team.name))
            time.sleep(SLEEP * 0.6)
            print_scoreboard(period, period_time, teamA, teamB)
            return second_reb_team

        print_scoreboard(period, period_time, teamA, teamB)
        return reb_team


def should_push_after_rebound(rebounder: Player, team: Team, miss_kind: str,
                              period: int, period_time: int) -> bool:
    if period_time <= 8:
        return False

    handlers = sorted(
        team.on_floor,
        key=lambda p: 0.36 * p.ball_handle + 0.28 * p.playmaking + 0.26 * effective_speed(p) + 0.10 * p.usage,
        reverse=True
    )
    lead_handler = handlers[0] if handlers else rebounder
    pace = getattr(team, "coach_style", {}).get("pace", 1.0)
    transition_skill = (
        0.32 * lead_handler.ball_handle
        + 0.24 * lead_handler.playmaking
        + 0.30 * effective_speed(lead_handler)
        + 0.14 * effective_speed(rebounder)
    )
    chance = 0.13 + transition_skill * 0.22 + max(0.0, pace - 1.0) * 0.12
    if miss_kind == "jumper":
        chance += 0.11
    if "transition_engine" in lead_handler.badges:
        chance += 0.10
    return random.random() < max(0.08, min(0.42, chance))


def post_fade_attempt_chance(shooter: Player, defender: Player) -> float:
    if shooter.post_tendency <= 0 or shooter.mid_tendency <= 0:
        return 0.0

    post_size = 0.10 if shooter.height >= 78 else 0.0
    mid_touch = max(0.0, shooter.mid_rating - 0.68) * 0.55
    mid_usage = min(0.24, shooter.mid_tendency * 0.34)
    post_usage = min(0.18, shooter.post_tendency * 0.22)
    iq_bonus = max(0.0, shooter.shot_iq - 0.70) * 0.16
    defender_wall = max(0.0, effective_interior_def(defender) - 0.68) * 0.15
    poor_mid_penalty = max(0.0, 0.72 - shooter.mid_rating) * 0.32

    chance = 0.04 + post_size + mid_touch + mid_usage + post_usage + iq_bonus + defender_wall - poor_mid_penalty
    if shooter.mid_rating >= shooter.rim_rating + 0.08:
        chance += 0.08
    if shooter.rim_rating >= shooter.mid_rating + 0.14 and shooter.height >= 82:
        chance -= 0.08

    return max(0.0, min(0.48, chance))


def choose_shot_type(shooter: Player, defender: Player,
                     team: Team = None, opponent: Team = None,
                     period: int = 1, period_time: int = 720) -> str:
    if team is None or opponent is None:
        team = Team("temp", [shooter])
        opponent = Team("temp opponent", [defender])

    if is_non_spacer(shooter):
        return "post" if shooter.post_tendency >= shooter.drive_tendency else "rim"

    three_pref = getattr(getattr(team, "coach_style", {}), "get", lambda *_: 1.0)("three_preference", 1.0)
    plan = getattr(team, "game_plan", {}).get("offense", "balanced")
    if plan == "hunt_threes":
        three_pref *= 1.18
    elif plan == "five_out" and lineup_can_five_out(team):
        three_pref *= 1.12
    elif plan == "four_out_one_in":
        three_pref *= 1.04
    elif plan == "three_out_two_in":
        three_pref *= 0.92
    elif plan == "post_heavy":
        three_pref *= 0.84
    elif plan == "attack_paint":
        three_pref *= 0.88
    defensive_scheme = getattr(opponent, "game_plan", {}).get("defense", "standard")
    if defensive_scheme in ("stay_home", "top_lock") or getattr(opponent, "game_plan", {}).get("top_lock_shooters"):
        three_pref *= 0.86
    elif defensive_scheme in ("pack_paint", "wall_paint", "zone", "drop"):
        three_pref *= 1.08
    shot_options = ("three", "mid", "rim", "post")
    raw_weights = [
        effective_tendency(three_attempt_tendency_curve(shooter.three_tendency), shooter, team, opponent, period, period_time) * three_pref * THREE_ATTEMPT_SCALE * (1 - 0.30 * defender.perimeter_def),
        effective_tendency(shooter.mid_tendency, shooter, team, opponent, period, period_time) * (1 - 0.25 * defender.perimeter_def),
        effective_tendency(shooter.drive_tendency, shooter, team, opponent, period, period_time) * (1 - 0.25 * defender.interior_def),
        # Modest across-the-board bump -- post shots were a bit too rare
        # relative to how often a real post_tendency rating should get used.
        effective_tendency(shooter.post_tendency, shooter, team, opponent, period, period_time) * (1 - 0.30 * defender.interior_def) * 1.15,
    ]
    offball_gravity = team_offball_gravity(team, shooter)
    if offball_gravity >= 0.70:
        raw_weights[2] *= 1.0 + min(0.16, (offball_gravity - 0.70) * 0.55)
        raw_weights[3] *= 1.0 + min(0.10, (offball_gravity - 0.70) * 0.35)
    elif offball_gravity < 0.54:
        raw_weights[2] *= max(0.82, 1.0 - (0.54 - offball_gravity) * 0.60)
        raw_weights[3] *= max(0.86, 1.0 - (0.54 - offball_gravity) * 0.42)
        if shooter.three_rating >= 0.76:
            raw_weights[0] *= 1.0 + (0.54 - offball_gravity) * 0.25

    if player_perimeter_gravity(shooter) >= 0.86 and defender.perimeter_def < 0.72:
        raw_weights[0] *= 1.06

    is_big = can_play_position(shooter, "PF") or can_play_position(shooter, "C") or shooter.height >= 80
    resolve = min(1.0, 0.34 * shooter.usage + 0.26 * shooter.shot_iq + 0.22 * shooter.ball_handle + 0.18 * shooter.clutchness)
    perimeter_pressure = max(0.0, effective_perimeter_def(defender) - 0.64)
    interior_pressure = max(0.0, effective_interior_def(defender) - 0.66)

    if perimeter_pressure > 0 and not is_big:
        jumper_push = min(0.38, perimeter_pressure * (0.62 - 0.28 * resolve))
        jumper_push = max(0.04, jumper_push)
        raw_weights[0] *= 1.0 - jumper_push
        raw_weights[1] *= 1.0 - jumper_push * 0.78
        if shooter.drive_tendency > 0:
            raw_weights[2] *= 1.0 + jumper_push * (0.95 + shooter.ball_handle * 0.35)
        if shooter.post_tendency > 0 and shooter.height >= 78:
            raw_weights[3] *= 1.0 + jumper_push * 0.35
    elif perimeter_pressure > 0 and is_big and shooter.three_tendency >= 0.20:
        raw_weights[0] *= 1.0 - min(0.16, perimeter_pressure * 0.20)

    if interior_pressure > 0:
        paint_push = min(0.36, interior_pressure * (0.58 - 0.24 * resolve))
        paint_push = max(0.03, paint_push)
        raw_weights[2] *= 1.0 - paint_push
        raw_weights[3] *= 1.0 - paint_push * (0.65 if is_big else 0.92)
        if not is_big:
            raw_weights[0] *= 1.0 + paint_push * 0.50 * three_pref
            raw_weights[1] *= 1.0 + paint_push * 0.72
        elif shooter.mid_rating >= 0.76 or shooter.three_rating >= 0.74:
            raw_weights[0] *= 1.0 + paint_push * 0.25 * three_pref
            raw_weights[1] *= 1.0 + paint_push * 0.45
    if plan == "attack_paint":
        raw_weights[2] *= 1.18
        raw_weights[3] *= 1.12
    elif plan == "five_out":
        if lineup_can_five_out(team):
            raw_weights[0] *= 1.12
            raw_weights[2] *= 1.08
        else:
            raw_weights[0] *= 0.96
            raw_weights[2] *= 0.88
            raw_weights[3] *= 0.90
    elif plan == "four_out_one_in":
        raw_weights[0] *= 1.04
        raw_weights[2] *= 1.06
        raw_weights[3] *= 1.04
    elif plan == "three_out_two_in":
        raw_weights[0] *= 0.90
        raw_weights[1] *= 0.96
        raw_weights[2] *= 1.08
        raw_weights[3] *= 1.18
    elif plan == "post_heavy":
        raw_weights[0] *= 0.86
        raw_weights[1] *= 0.94
        raw_weights[2] *= 1.06
        raw_weights[3] *= 1.30
    elif plan == "motion":
        raw_weights[0] *= 1.06
        raw_weights[1] *= 1.08
        raw_weights[2] *= 1.04
    elif plan == "star_spread":
        if shooter.usage >= 0.28 or shooter.iso_tendency >= 0.70:
            raw_weights[0] *= 1.05
            raw_weights[1] *= 1.06
            raw_weights[2] *= 1.06
    if defensive_scheme in ("pack_paint", "wall_paint", "zone"):
        raw_weights[2] *= 0.88
        raw_weights[3] *= 0.90
        raw_weights[0] *= 1.08
    elif defensive_scheme == "drop":
        raw_weights[2] *= 0.92
        raw_weights[1] *= 1.08
        raw_weights[0] *= 1.04
    elif defensive_scheme in ("stay_home", "top_lock") or getattr(opponent, "game_plan", {}).get("top_lock_shooters"):
        raw_weights[0] *= 0.82
        raw_weights[2] *= 1.10
    elif defensive_scheme == "switch":
        raw_weights[1] *= 0.96
        raw_weights[3] *= 1.05 if shooter.height >= 80 else 0.98
    if getattr(team, "game_plan", {}).get("foul_strategy") == "attack_foul_trouble" and defender.pf >= 3:
        raw_weights[2] *= 1.18
        raw_weights[3] *= 1.12
    if defender.pf >= 4 and not defender.fouled_out:
        raw_weights[2] *= 1.20 + shooter.foul_draw * 0.16
        raw_weights[3] *= 1.12 + shooter.foul_draw * 0.12
        raw_weights[0] *= 0.94
        raw_weights[1] *= 0.98
    if shooter.usage < 0.16 and shooter.shot_iq < 0.68:
        raw_weights[0] *= 0.82
        raw_weights[1] *= 0.88
        if shooter.rim_rating >= 0.78:
            raw_weights[2] *= 1.06

    scoring_ratings = {
        "three": shooter.three_rating,
        "mid": shooter.mid_rating,
        "rim": shooter.rim_rating,
        "post": 0.58 * shooter.rim_rating + 0.42 * shooter.mid_rating,
    }
    best_rating = max(scoring_ratings.values())
    weights = []
    for typ, raw in zip(shot_options, raw_weights):
        gap = max(0.0, best_rating - scoring_ratings[typ])
        if shooter.shot_iq >= 0.50:
            iq_factor = 1.0 - gap * (shooter.shot_iq - 0.50) * 1.35
        else:
            iq_factor = 1.0 + gap * (0.50 - shooter.shot_iq) * 0.95
        if typ in ("three", "mid") and defender.perimeter_def >= 0.78:
            iq_factor *= 1.0 - max(0.0, shooter.shot_iq - 0.55) * 0.18
        if typ in ("rim", "post") and defender.interior_def >= 0.80:
            iq_factor *= 1.0 - max(0.0, shooter.shot_iq - 0.55) * 0.18
        weights.append(max(0.0, raw * max(0.42, iq_factor)))
    total = sum(weights)

    if total == 0:
        return "rim"

    r = random.random() * total
    cum = 0.0

    for w, typ in zip(weights, shot_options):
        cum += w
        if r <= cum:
            if typ == "post" and random.random() < post_fade_attempt_chance(shooter, defender):
                return "post_fade"
            return typ

    return "rim"


def announce_ball_transfer(passer: Player | None, receiver: Player, context: str = ""):
    if passer is None or passer is receiver:
        return

    if context == "closing_star":
        lines = [
            f"{passer.name} gets it back to {receiver.name} to let the star work.",
            f"{passer.name} reverses it to {receiver.name} as the offense clears space.",
            f"{passer.name} gives it up to {receiver.name} with the clock getting serious.",
        ]
    elif context == "reroute":
        lines = [
            f"{passer.name} passes up the look and moves it to {receiver.name}.",
            f"{passer.name} keeps it moving and finds {receiver.name}.",
            f"{passer.name} gives it up to {receiver.name} for a better option.",
        ]
    else:
        lines = [
            f"{passer.name} {random.choice(pp5)} {receiver.name}.",
            f"{passer.name} moves it along to {receiver.name}.",
            f"{passer.name} swings it over to {receiver.name}.",
        ]

    print(random.choice(lines))
    time.sleep(SLEEP * 0.55)

def defense_pressure_choice(shooter: Player, defender: Player, play_context: str | None) -> str | None:
    if play_context in ("deep_paint_touch", "iso"):
        return None

    is_big = can_play_position(shooter, "PF") or can_play_position(shooter, "C") or shooter.height >= 80
    resolve = min(1.0, 0.34 * shooter.usage + 0.24 * shooter.shot_iq + 0.20 * shooter.ball_handle + 0.14 * shooter.clutchness + 0.08 * shooter.playmaking)
    good_player = resolve >= 0.66 or shooter.usage >= 0.28 or shooter.shot_iq >= 0.80
    perimeter_heat = max(0.0, effective_perimeter_def(defender) - 0.76)
    interior_wall = max(0.0, effective_interior_def(defender) - 0.80)

    if perimeter_heat > 0 and not is_big:
        pass_chance = min(0.28, perimeter_heat * (0.48 - resolve * 0.22))
        screen_chance = min(0.24, perimeter_heat * (0.24 + resolve * 0.24))
        drive_chance = min(0.22, perimeter_heat * shooter.ball_handle * shooter.drive_tendency * 0.70)
        if true_primary_shot_creator(shooter):
            pass_chance *= 0.48
            screen_chance *= 0.72
            drive_chance *= 1.18
        roll = random.random()
        if good_player and roll < screen_chance:
            return "screen"
        if roll < screen_chance + drive_chance:
            return "drive"
        if roll < screen_chance + drive_chance + pass_chance:
            return "pass"

    if interior_wall > 0 and not is_big:
        pass_chance = min(0.26, interior_wall * (0.44 - resolve * 0.18))
        screen_chance = min(0.18, interior_wall * (0.18 + resolve * 0.18))
        pullup_chance = min(0.22, interior_wall * max(shooter.mid_tendency, shooter.three_tendency) * 0.62)
        if true_primary_shot_creator(shooter):
            pass_chance *= 0.52
            screen_chance *= 0.76
            pullup_chance *= 1.22
        roll = random.random()
        if good_player and roll < screen_chance:
            return "screen"
        if roll < screen_chance + pullup_chance:
            return "pullup"
        if roll < screen_chance + pullup_chance + pass_chance:
            return "pass"

    if interior_wall > 0 and is_big and shooter.post_tendency < 0.30 and shooter.playmaking >= 0.55:
        if random.random() < min(0.16, interior_wall * 0.20):
            return "pass"

    return None


def run_ato_play(off: Team, dff: Team, period: int, period_time: int,
                 teamA: Team, teamB: Team, matchups: Dict[Player, Player]) -> Tuple[Team, int] | None:
    if not getattr(off, "ato_pending", False):
        return None
    off.ato_pending = False
    if period_time <= 4:
        return None

    coach_iq = getattr(off, "coach_style", {}).get("coach_iq", 0.62)
    need_three = period >= 4 and period_time <= 90 and off.score <= dff.score - 3
    need_two = period >= 4 and period_time <= 90 and off.score in (dff.score - 1, dff.score - 2)
    spent = min(period_time, random.randint(7, 14))
    score_time = max(0, period_time - spent)
    initiator = max(off.on_floor, key=lambda p: 0.48 * p.playmaking + 0.32 * p.ball_handle + 0.20 * p.usage)

    if need_three:
        target = max(off.on_floor, key=lambda p: 0.58 * p.three_rating + 0.22 * p.clutchness + 0.20 * shooter_weight(p))
        shot_type = "three"
    elif need_two:
        target = max(off.on_floor, key=lambda p: 0.42 * p.rim_rating + 0.26 * p.mid_rating + 0.18 * p.clutchness + 0.14 * shooter_weight(p))
        shot_type = "rim" if target.rim_rating >= target.mid_rating or random.random() < 0.58 else "mid"
    else:
        target = max(
            off.on_floor,
            key=lambda p: (
                0.24 * p.three_rating
                + 0.24 * p.rim_rating
                + 0.18 * p.mid_rating
                + 0.18 * p.shot_tendency
                + 0.16 * p.clutchness
            ) * role_discipline_multiplier(p)
        )
        shot_type = choose_shot_type(target, matchups.get(target, random.choice(dff.on_floor)), off, dff, period, period_time)

    defender = matchups.get(target, random.choice(dff.on_floor))
    lines = [
        f"{off.name} come out of the timeout with quick misdirection for {target.name}.",
        f"{initiator.name} waits for the action to unfold and hits {target.name} out of the timeout.",
        f"{off.name} use the timeout to free {target.name} with layered screening.",
        f"{target.name} curls into space as {off.name} execute the timeout set.",
    ]
    print(random.choice(lines))
    time.sleep(SLEEP * 0.65)

    if shot_type == "rim" and target.dunk_tendency >= 0.50 and random.random() < 0.25 + initiator.playmaking * 0.35:
        shot_type = "dunk"
        print(f"{initiator.name} puts it near the rim for {target.name}.")
    elif shot_type == "three":
        print(f"{target.name} catches off the timeout action and rises from three.")
    else:
        print(f"{target.name} catches with an advantage and goes right into the look.")
    time.sleep(SLEEP * 0.5)

    q_label, q_mult = shot_quality(target, defender, shot_type, period, score_time)
    target.shot_quality_mult = max(q_mult, 1.06 + coach_iq * 0.08)
    final_quality_mult = target.shot_quality_mult

    target.fga += 1
    record_shot_diet(off, shot_type, shot_quality_diet_context("ato", q_label), target, defender, quality_mult=final_quality_mult)
    if shot_type == "three":
        target.tpa += 1

    made = random.random() < shot_make_prob(target, defender, shot_type, off, dff, period, score_time)
    clear_shot_temp_bonuses(target)

    if made:
        pts = 3 if shot_type == "three" else 2
        target.fgm += 1
        target.pts += pts
        record_shot_make(off, shot_type, "ato", target, defender)
        if shot_type == "three":
            target.tpm += 1
        off.score += pts
        if is_paint_shot(shot_type):
            off.points_paint += pts
        record_score_event(off, dff, pts, period, score_time, teamA, teamB, check_timeout=False)
        update_shot_rhythm(target, True, shot_type)
        if initiator is not target:
            record_assist(initiator, off, pts)
        print(f"{target.name} converts the timeout play.")
        print_scoreboard(period, score_time, teamA, teamB)
        maybe_call_timeout_after_score(off, dff, period, score_time, teamA, teamB)
        return dff, spent

    update_shot_rhythm(target, False, shot_type)
    print(f"{target.name} misses the timeout look.")
    reb_team, rebounder = choose_rebounder(off, dff, "jumper" if shot_type in ("three", "mid") else "rim")
    print(f"{rebounder.name} pulls down the rebound.")
    print_scoreboard(period, score_time, teamA, teamB)
    return reb_team, spent


def simulate_possession(off: Team, dff: Team,
                        period: int, period_time: int,
                        teamA: Team, teamB: Team,
                        matchups: Dict[Player, Player]) -> Tuple[Team, int]:

    sanitize_live_lineups(off, dff)
    frontcourt_after_oreb = getattr(off, "frontcourt_after_oreb", False)
    if frontcourt_after_oreb:
        off.frontcourt_after_oreb = False

    if consume_manual_timeout_stop(off):
        return off, 0

    if period >= 4 and period_time < 24 and abs(off.score - dff.score) > 7:
        handler = choose_ballhandler(off)
        print(f"{off.name} are up enough to let the clock run. {handler.name} holds it near midcourt.")
        time.sleep(SLEEP * 0.6)
        print(f"{off.name} dribble out the final seconds.")
        return off, period_time

    inbound_result = run_inbound_play(off, dff, period, period_time, teamA, teamB, matchups)
    if inbound_result is not None:
        return inbound_result

    ato_result = run_ato_play(off, dff, period, period_time, teamA, teamB, matchups)
    if ato_result is not None:
        return ato_result

    if period >= 4 and period_time <= 5 and off.score <= dff.score:
        if frontcourt_after_oreb or getattr(off, "reset_after_oreb", False):
            off.frontcourt_quick_touch = True
            off.reset_after_oreb = False
        return run_late_game_quick_possession(off, dff, period, period_time, teamA, teamB, matchups)

    if frontcourt_after_oreb and period >= 4 and period_time <= 10 and off.score < dff.score:
        off.frontcourt_quick_touch = True
        return run_late_game_quick_possession(off, dff, period, period_time, teamA, teamB, matchups)

    if period >= 4 and period_time <= 26 and 0 < off.score - dff.score <= 8:
        handler = choose_ballhandler(off)
        print(f"{off.name} are ahead and hold the ball. {handler.name} keeps it away from pressure.")
        time.sleep(SLEEP * 0.6)
        print(f"{off.name} do not look for a shot with the clock in their favor.")
        return off, period_time

    if should_take_late_game_last_shot(off, dff, period, period_time):
        return run_late_game_last_shot_possession(off, dff, period, period_time, teamA, teamB, matchups)

    if period >= 4 and 5 < period_time <= 24 and off.score < dff.score:
        return run_late_game_quick_possession(off, dff, period, period_time, teamA, teamB, matchups)

    possession_time = random.randint(12, 24)
    pace = getattr(getattr(off, "coach_style", {}), "get", lambda *_: 1.0)("pace", 1.0)
    if pace > 1.0:
        possession_time = max(11, int(possession_time / pace))

    if period <= 3 and period_time <= 24:
        possession_time = period_time
        print(f"{off.name} hold for the final shot of the quarter.")
    elif period_time <= 24:
        possession_time = random.randint(3, max(3, min(9, period_time)))
        if off.score < dff.score:
            print(f"{off.name} are short on clock and have to get into something fast.")
    elif period >= 4 and period_time <= 35 and off.score >= dff.score:
        possession_time = min(24, period_time, max(8, period_time - random.randint(1, 4)))
        print(f"{off.name} slow it down and look to use the clock.")
    reset_after_oreb = getattr(off, "reset_after_oreb", False)
    if reset_after_oreb:
        if period_time <= 10:
            possession_time = min(period_time, random.randint(1, 3) if period_time <= 5 else random.randint(2, 4))
            off.frontcourt_after_oreb = True
        else:
            possession_time = random.randint(9, 16)
        off.reset_after_oreb = False

    if possession_time > period_time:
        possession_time = period_time
        # RARE FULL-POSSESSION SHOT CLOCK VIOLATION
    if period_time >= 24 and random.random() < shot_clock_violation_chance(off, dff, period, period_time):
        possession_time = 24
        handler = choose_ballhandler(off)
        describe_shot_clock_violation(off, dff, handler, matchups)
        print("Shot clock violation. The possession expires without a shot.")
        commit_turnover(handler, off)
        dead_ball_subs(teamA, teamB, period, period_time - possession_time)
        return dff, possession_time

    if getattr(dff, "game_plan", {}).get("foul_strategy") == "selective_hack" and period_time > 120:
        hack_targets = [
            p for p in off.on_floor
            if p.ft_rating < 0.62 and not p.fouled_out and p.pf < 6
        ]
        if hack_targets and dff.quarter_fouls >= 3 and random.random() < 0.18:
            target = min(hack_targets, key=lambda p: p.ft_rating)
            fouler = min([p for p in dff.on_floor if not p.fouled_out], key=lambda p: p.pf)
            print(f"{dff.name} intentionally foul {target.name} away from the ball to test him at the line.")
            register_foul(dff, fouler)
            next_possession = shoot_free_throws(target, off, 2, period, max(0, period_time - 2), teamA, teamB, sub_after_first=True, protected=target)
            return next_possession, 2


    closing_star_mode = period >= 4 and period_time <= 6 * 60 and abs(off.score - dff.score) <= 10
    fourth_star_mode = period >= 4 and not getattr(off, "garbage_time_locked", False)
    fourth_star_chance = fourth_quarter_star_shot_chance(off, dff, period, period_time)
    closing_star = None
    if closing_star_mode:
        closing_star = choose_closing_star_scorer(off, need_three=(off.score - dff.score <= -3 and period_time <= 90))
        handler = choose_closing_initiator(off, closing_star)
    else:
        handler = choose_ballhandler(off)
    pass_first_clutch_creator = (
        off.name == "2027 Philadelphia 76ers"
        and closing_star is not None
        and closing_star.name == "LeBron James"
        and closing_star.playmaking >= 0.90
    )
    # Philadelphia's LeBron remains the primary clutch decision-maker, but
    # does not get locked into being the shooter on nearly every possession.
    star_takeover_lock = closing_star_mode and closing_star is not None and not pass_first_clutch_creator
    if frontcourt_after_oreb and not reset_after_oreb:
        print(f"{off.name} keep it in the frontcourt after the offensive board and have to act fast.")
    elif reset_after_oreb:
        if period_time <= 10:
            reset_line = f"{handler.name} catches it in the frontcourt and has to go right away."
        else:
            reset_line = random.choice(oreb_reset_lines).format(handler=handler.name, team=off.name)
        print(reset_line)
    else:
        print(random.choice(play_setup_lines).format(handler=handler.name, team=off.name))
    time.sleep(SLEEP)
    if consume_manual_timeout_stop(off):
        return off, 0
    ball_owner = handler
    secondary_handler = maybe_secondary_initiator(off, handler)
    if secondary_handler is not handler:
        print(f"{handler.name} gives it up early to {secondary_handler.name} to start the action.")
        time.sleep(SLEEP * 0.5)
        if consume_manual_timeout_stop(off):
            return off, 0
        handler = secondary_handler
        ball_owner = handler
    off.current_play_initiator = handler
    shooter = choose_shooter(off)
    if closing_star_mode and closing_star is not None:
        shooter = closing_star
    elif fourth_star_mode and random.random() < fourth_star_chance:
        shooter = choose_fourth_quarter_star_scorer(
            off, dff, period, period_time,
            need_three=(off.score - dff.score <= -3 and period_time <= 90)
        )
    ball_movement = getattr(off, "coach_style", {}).get("ball_movement", 1.0)
    if not closing_star_mode and shooter is not handler and can_be_designed_shooter(handler):
        # First decide whether the handler actually gives the ball up. Elite
        # creators pass far more often; weak playmakers are likelier to keep
        # the possession and create their own attempt.
        pass_chance = (
            0.18
            + 0.56 * handler.playmaking
            + 0.10 * handler.ball_handle
            + 0.10 * max(-0.30, min(0.40, ball_movement - 1.0))
        )
        # Choosing a different eventual shooter does not mean the first
        # handler always supplies the final pass; possessions often include a
        # reset, hand-back, or an unassisted attack later in the clock.
        pass_chance *= 0.84
        pass_chance = max(0.30, min(0.90, pass_chance))
        if random.random() >= pass_chance:
            shooter = handler
    primary_creator_keep = shooter.usage >= 0.36 and shooter.shot_tendency >= 0.70
    if (
        not closing_star_mode
        and not primary_creator_keep
        and shooter is handler
        and ball_movement >= 1.15
        and random.random() < min(0.85, 0.35 + (ball_movement - 1.0) * 1.25)
    ):
        shooter = choose_shooter_excluding(off, handler, allow_non_spacers=False)
    last_passer: Player | None = None
    # Ordinary possessions are not catch-and-shoots by default. Specific
    # actions below opt into an immediate assisted finish.
    quick_shot_for_assist = False
    play_context: str | None = None
    pnr_result: str | None = None
    true_iso_attempt = False
    deep_paint_touch = False
    if closing_star_mode and random.random() < 0.72:
        play_type = clutch_package_play(off, need_three=(off.score - dff.score <= -3 and period_time <= 90))
    elif fourth_star_mode and random.random() < fourth_star_chance * 0.42:
        play_type = clutch_package_play(off, need_three=(off.score - dff.score <= -3 and period_time <= 90))
    else:
        play_type = real_play_type(off, handler)
    play_shooter, play_passer, play_context = apply_play_type_setup(play_type, off, handler, shooter)
    off.current_play_initiator = None
    if play_passer and play_passer is not play_shooter:
        last_passer = play_passer
        handler = play_passer
        ball_owner = play_passer
    if play_shooter is not shooter:
        shooter = play_shooter
        ball_owner = play_shooter
        quick_shot_for_assist = play_context in (
            "floppy", "elevator", "handoff", "horns", "backdoor", "drive_kick", "post_split"
        )
        if quick_shot_for_assist:
            # A designed pass does not automatically become a catch-and-shoot.
            # The receiver may hold, drive, or reset -- and a sharp passer
            # is what actually creates that clean, direct look in the first
            # place, so the passer's playmaking is the dominant term here,
            # not the shooter's own profile.
            immediate_chance = (
                0.10
                + 0.16 * shooter.three_tendency
                + 0.10 * shooter.shot_iq
                + 0.06 * shooter.shot_tendency
                + 0.40 * (play_passer.playmaking if play_passer is not None else handler.playmaking)
            )
            if play_context in ("floppy", "elevator", "handoff"):
                immediate_chance += 0.10
            elif play_context in ("horns", "post_split"):
                immediate_chance -= 0.08
            immediate_chance *= 0.72
            immediate_chance = max(0.22, min(0.62, immediate_chance))
            if random.random() >= immediate_chance:
                quick_shot_for_assist = False
    if (
        star_takeover_lock
        and closing_star is not None
        and shooter is not closing_star
        and play_context not in ("deep_paint_touch",)
        and random.random() < 0.96
    ):
        if ball_owner is not closing_star:
            announce_ball_transfer(ball_owner, closing_star, "closing_star")
            last_passer = ball_owner
            quick_shot_for_assist = True
        shooter = closing_star
        ball_owner = shooter
        play_context = "closing_star_touch"
    if play_context != "deep_paint_touch":
        rerouted = reroute_zero_tendency_shooter(off, shooter, ball_owner)
        if rerouted is not shooter:
            announce_ball_transfer(ball_owner, rerouted, "reroute")
            last_passer = ball_owner
            shooter = rerouted
            ball_owner = shooter

    if shooter is not handler:
        passer_for_entry = last_passer if last_passer and last_passer is not shooter else handler
        deep_paint_touch = is_non_shooting_big(shooter)
        if deep_paint_touch:
            paint_entry_lines = [
                f"{passer_for_entry.name} feeds {shooter.name} deep on the block.",
                f"{passer_for_entry.name} dumps it inside to {shooter.name} near the restricted area.",
                f"{passer_for_entry.name} hits {shooter.name} on the seal in the paint.",
                f"{passer_for_entry.name} gets it to {shooter.name} with position under the rim.",
            ]
            print(random.choice(paint_entry_lines))
            play_context = "deep_paint_touch"
            # A post-entry pass isn't automatically a direct assist feed --
            # the big still has to catch, seal, and go back up. Whether that
            # turns into an immediate score off the catch (an assist) or a
            # dribble/pump-fake/reset first is governed by the passer's
            # playmaking, same as every other quick-shot decision.
            paint_touch_chance = immediate_catch_chance(
                passer_for_entry, base=0.22, slope=0.42, lo=0.15, hi=0.72,
                bonus=0.08 if "post_hub" in passer_for_entry.badges else 0.0,
            )
            quick_shot_for_assist = random.random() < paint_touch_chance
        else:
            pline = random.choice(pp5)
            print(f"{passer_for_entry.name} {pline} {shooter.name}.")
        time.sleep(SLEEP * 0.8)
        if consume_manual_timeout_stop(off):
            return off, 0

        defender_on_receiver = matchups.get(shooter, random.choice(dff.on_floor))

        if random.random() < out_of_bounds_turnover_chance(passer_for_entry, shooter):
            print(f"{passer_for_entry.name}'s pass sails out of bounds. Turnover by {off.name}.")
            commit_turnover(passer_for_entry, off)
            dead_ball_subs(teamA, teamB, period, period_time - possession_time)
            return dff, random.randint(2, 5)

        if random.random() < deflection_out_of_bounds_chance(passer_for_entry, shooter, defender_on_receiver):
            print(f"{defender_on_receiver.name} gets a hand on the pass and knocks it out of bounds. {off.name} keep possession.")
            dead_ball_subs(teamA, teamB, period, period_time - possession_time)
            off.inbound_pending = True
            return off, random.randint(2, 5)

        if try_pass_interception(passer_for_entry, shooter, off, dff, matchups):
            next_possession = run_fastbreak(
                dff, off, period, period_time - possession_time, teamA, teamB,
                source="steal", trigger_player=getattr(dff, "last_stealer", None)
            )
            return next_possession, possession_time

        last_passer = passer_for_entry
        ball_owner = shooter

    extra_pass_chance = (0.15 + 0.52 * shooter.playmaking) * ball_movement
    if shooter.usage >= 0.36 and shooter.shot_tendency >= 0.70:
        extra_pass_chance *= 0.26 if true_primary_shot_creator(shooter) else 0.42
    elif shooter.usage >= 0.30 and shooter.shot_tendency >= 0.55:
        extra_pass_chance *= 0.68
    if fourth_star_mode and shooter in rotation_star_players(off):
        if period_time <= 6 * 60 and abs(off.score - dff.score) <= 12:
            extra_pass_chance *= 0.30 if shooter.playmaking < 0.88 else 0.52
        else:
            extra_pass_chance *= 0.55 if shooter.playmaking < 0.88 else 0.72
    if shooter.playmaking < 0.55:
        extra_pass_chance *= 0.38
    elif shooter.playmaking < 0.62:
        extra_pass_chance *= 0.58
    elif shooter.playmaking >= 0.82:
        extra_pass_chance *= 1.12
    if true_primary_shot_creator(shooter):
        extra_pass_chance *= max(0.42, 1.0 - max(0.0, shooter.iso_tendency - 0.50) * 0.74)
    if shooter.usage >= 0.28 and shooter.playmaking < 0.80:
        extra_pass_chance *= 0.88
    if shooter.name == "Kevin Durant":
        extra_pass_chance *= 0.60
    if star_takeover_lock:
        if shooter is closing_star:
            extra_pass_chance = 0.04 if shooter.playmaking < 0.90 else 0.12
        else:
            extra_pass_chance *= 0.25
    if play_context not in ("deep_paint_touch", "iso") and random.random() < extra_pass_chance:
        secondary = choose_shooter_excluding(off, shooter, allow_non_spacers=False)
        if secondary is not shooter:
            swing_line = random.choice(pp3)
            defender_on_secondary = matchups.get(secondary, random.choice(dff.on_floor))

            if random.random() < out_of_bounds_turnover_chance(shooter, secondary):
                print(f"{shooter.name} throws it out of bounds trying to find {secondary.name}.")
                commit_turnover(shooter, off)
                dead_ball_subs(teamA, teamB, period, period_time - possession_time)
                return dff, random.randint(2, 5)

            if random.random() < deflection_out_of_bounds_chance(shooter, secondary, defender_on_secondary):
                print(f"{defender_on_secondary.name} deflects the pass out of bounds. {off.name} will inbound.")
                dead_ball_subs(teamA, teamB, period, period_time - possession_time)
                off.inbound_pending = True
                return off, random.randint(2, 5)

            print(f"{shooter.name} {swing_line} {secondary.name}.")
            time.sleep(SLEEP * 0.8)

            if try_pass_interception(shooter, secondary, off, dff, matchups):
                next_possession = run_fastbreak(
                    dff, off, period, period_time - possession_time, teamA, teamB,
                    source="steal", trigger_player=getattr(dff, "last_stealer", None)
                )
                return next_possession, possession_time

            last_passer = shooter
            shooter = secondary
            ball_owner = shooter
            rerouted = reroute_zero_tendency_shooter(off, shooter, last_passer)
            if rerouted is not shooter:
                announce_ball_transfer(ball_owner, rerouted, "reroute")
                last_passer = ball_owner
                shooter = rerouted
                ball_owner = shooter
            quick_shot_for_assist = False
            if (
                shooter.three_tendency > 0
                and shooter.three_rating >= 0.74
                and random.random() < catch_shoot_creation_chance(last_passer, shooter, "swing") * 0.72
            ):
                quick_shot_for_assist = True
                play_context = "extra_pass_open"
                pnr_result = "extra_pass_open"
                shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * (1.10 + catch_shoot_badge_quality_bonus(shooter))

    if (not star_takeover_lock) and play_context not in ("deep_paint_touch", "iso") and period_time - possession_time > 2:
        # Possessions shouldn't default to "catch it and go" -- ball
        # movement continuing for another pass or two (instead of an
        # immediate shot) is the norm, not the exception, so the baseline
        # here is meaningfully higher and the ceiling is raised too.
        movement_base = 0.24 + max(0.0, ball_movement - 1.0) * 0.78
        if play_context in ("floppy", "elevator", "handoff", "horns", "drive_kick", "post_split") or play_context in PLAYBOOK_CONTEXTS:
            movement_base += 0.14
        if off.name in ("2016 Golden State Warriors", "2017 Golden State Warriors", "2019 Golden State Warriors", "2022 Golden State Warriors"):
            movement_base += 0.10
        elif "Spurs" in off.name:
            movement_base += 0.12
        elif "Cavaliers" in off.name:
            movement_base -= 0.04
        if closing_star_mode:
            movement_base *= 0.38 if shooter is closing_star else 0.55
        movement_base = max(0.10, min(0.72, movement_base))

        touched = [handler]
        if last_passer:
            touched.append(last_passer)
        if shooter not in touched:
            touched.append(shooter)

        max_extra_passes = 3 if random.random() < 0.40 else (2 if random.random() < 0.80 else 1)
        for pass_index in range(max_extra_passes):
            passer = shooter
            if passer.playmaking < 0.45 and random.random() < 0.48:
                break
            if passer.usage >= 0.30 and passer.playmaking < 0.82 and random.random() < 0.42:
                break

            pass_chance = movement_base
            if passer.playmaking >= 0.72:
                pass_chance += 0.12
            elif passer.playmaking < 0.55:
                pass_chance -= 0.10
            if passer.ast >= 7 and passer.playmaking < 0.90:
                pass_chance += 0.12
            pass_chance *= max(0.45, min(1.15, period_time / 18))

            if random.random() >= max(0.04, min(0.72, pass_chance)):
                break

            next_receiver = choose_ball_movement_receiver(off, passer, tuple(touched[-2:]))
            if next_receiver is passer:
                break

            defender_on_receiver = matchups.get(next_receiver, random.choice(dff.on_floor))
            movement_lines = [
                f"{passer.name} makes the extra pass to {next_receiver.name}.",
                f"{passer.name} swings it one more time to {next_receiver.name}.",
                f"{passer.name} touch-passes it to {next_receiver.name}.",
                f"{passer.name} skips it across to {next_receiver.name}.",
                f"{passer.name} keeps it moving and finds {next_receiver.name}.",
                f"{passer.name} reverses it quickly to {next_receiver.name}.",
            ]
            print(random.choice(movement_lines))
            time.sleep(SLEEP * 0.55)

            if random.random() < out_of_bounds_turnover_chance(passer, next_receiver) * 0.75:
                print(f"{passer.name} overthrows {next_receiver.name} on the extra pass.")
                commit_turnover(passer, off)
                dead_ball_subs(teamA, teamB, period, period_time - possession_time)
                return dff, random.randint(2, 5)

            if random.random() < deflection_out_of_bounds_chance(passer, next_receiver, defender_on_receiver) * 0.75:
                print(f"{defender_on_receiver.name} tips the extra pass out of bounds. {off.name} will inbound.")
                dead_ball_subs(teamA, teamB, period, period_time - possession_time)
                off.inbound_pending = True
                return off, random.randint(2, 5)

            if try_pass_interception(passer, next_receiver, off, dff, matchups):
                next_possession = run_fastbreak(
                    dff, off, period, period_time - possession_time, teamA, teamB,
                    source="steal", trigger_player=getattr(dff, "last_stealer", None)
                )
                return next_possession, possession_time

            last_passer = passer
            shooter = next_receiver
            ball_owner = shooter
            rerouted = reroute_zero_tendency_shooter(off, shooter, last_passer)
            if rerouted is not shooter:
                announce_ball_transfer(ball_owner, rerouted, "reroute")
                last_passer = ball_owner
                shooter = rerouted
                ball_owner = shooter
            quick_shot_for_assist = False
            play_context = "ball_movement_chain" if play_context is None else play_context
            if (
                shooter.three_tendency > 0
                and shooter.three_rating >= 0.74
                and random.random() < catch_shoot_creation_chance(last_passer, shooter, "swing") * 0.82
            ):
                quick_shot_for_assist = True
                play_context = "extra_pass_open"
                pnr_result = "extra_pass_open"
                shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * (1.10 + catch_shoot_badge_quality_bonus(shooter))
            touched.append(shooter)



    defender = matchups.get(shooter, random.choice(dff.on_floor))
    current_handler = shooter
    pnr_result = pnr_result

    foul_hunt_shooter, foul_hunt_defender = find_foul_trouble_target(off, dff, matchups)
    if foul_hunt_shooter is not None and foul_hunt_defender is not None:
        if ball_owner is not foul_hunt_shooter:
            announce_ball_transfer(ball_owner, foul_hunt_shooter, "mismatch")
            last_passer = ball_owner
            ball_owner = foul_hunt_shooter
        shooter = foul_hunt_shooter
        defender = foul_hunt_defender
        current_handler = shooter
        play_context = "foul_hunt"
        quick_shot_for_assist = False
        print(f"{off.name} recognize {defender.name}'s foul trouble and go right at him.")
        time.sleep(SLEEP * 0.55)

    pressure_choice = defense_pressure_choice(shooter, defender, play_context)
    if star_takeover_lock and shooter is closing_star and pressure_choice == "pass":
        pressure_choice = "drive" if shooter.drive_tendency > 0 and shooter.ball_handle >= 0.72 else "pullup"
    elif (
        fourth_star_mode
        and off.name == "2022 Brooklyn Nets"
        and shooter.name in ("Kevin Durant", "Kyrie Irving")
        and pressure_choice == "pass"
    ):
        pressure_choice = "pullup" if shooter.name == "Kevin Durant" else "drive"
    if pressure_choice == "pass":
        reset_target = choose_shooter_excluding(off, shooter, allow_non_spacers=False)
        if reset_target is not shooter:
            pressure_pass_lines = [
                f"{defender.name} crowds {shooter.name}, so {shooter.name} gives it up.",
                f"{defender.name} takes away the first option and {shooter.name} swings it out.",
                f"{shooter.name} feels the pressure from {defender.name} and moves it along.",
                f"{defender.name} sits on the move, forcing {shooter.name} to reset the action.",
                f"{defender.name} is playing him tight, and {shooter.name} decides to reset.",
                f"{defender.name} denies the airspace, so {shooter.name} lets the ball go.",
                f"{shooter.name} can't shake {defender.name} off the catch and kicks it back out.",
                f"{defender.name} is up in his grill, so {shooter.name} moves the ball on.",
                f"{shooter.name} respects the pressure from {defender.name} and doesn't force anything.",
            ]
            print(random.choice(pressure_pass_lines))
            time.sleep(SLEEP * 0.45)
            announce_ball_transfer(shooter, reset_target, "reroute")
            last_passer = shooter
            shooter = reset_target
            ball_owner = shooter
            defender = matchups.get(shooter, random.choice(dff.on_floor))
            current_handler = shooter
            # This is described as a reset under pressure, not a scoring
            # feed -- it should only occasionally turn into an immediate
            # catch-and-shoot, and that's mostly a function of how good a
            # passer is delivering it. Otherwise the new ball-handler just
            # continues the possession (drive, iso, another pass) instead
            # of an automatic assist.
            reroute_chance = immediate_catch_chance(last_passer, base=0.14, slope=0.35, lo=0.10, hi=0.55)
            quick_shot_for_assist = random.random() < reroute_chance
            play_context = "defense_reroute"
    elif pressure_choice == "screen":
        screen_lines = [
            f"{defender.name} is pressuring high, so {shooter.name} calls for help.",
            f"{shooter.name} sees the pressure and signals for a screen.",
            f"{defender.name} takes away the airspace, and {shooter.name} brings a screener up.",
            f"{shooter.name} slows it down and waits for the screen to arrive.",
            f"{defender.name} won't give an inch, so {shooter.name} waves a teammate over.",
            f"{shooter.name} can't get separation off the dribble and calls for a pick.",
            f"{defender.name} is playing him honest, so {shooter.name} looks for an angle off a screen.",
        ]
        print(random.choice(screen_lines))
        time.sleep(SLEEP * 0.45)
        play_context = "high_pnr"
        current_handler = shooter
    elif pressure_choice == "drive":
        drive_lines = [
            f"{defender.name} crowds the jumper, so {shooter.name} puts it on the floor.",
            f"{shooter.name} uses the pressure against {defender.name} and attacks downhill.",
            f"{defender.name} runs him off the line, and {shooter.name} drives it inside.",
            f"{defender.name} takes away the jumper, so {shooter.name} goes right by him.",
            f"{shooter.name} feels {defender.name} crowding the catch and puts it on the deck.",
            f"{defender.name} overplays the shot, and {shooter.name} makes him pay going downhill.",
        ]
        print(random.choice(drive_lines))
        time.sleep(SLEEP * 0.45)
        play_context = "pressure_drive"
    elif pressure_choice == "pullup":
        pullup_lines = [
            f"{defender.name} is sitting in the paint, so {shooter.name} looks for the pull-up window.",
            f"{shooter.name} sees the rim protection waiting and keeps the shot outside.",
            f"{defender.name} shades the lane, and {shooter.name} settles into space.",
            f"{defender.name} sags off to guard the drive, so {shooter.name} pulls up early.",
            f"{shooter.name} reads {defender.name} sagging and rises from the mid-range.",
            f"{defender.name} dares him to shoot it, and {shooter.name} obliges from the outside.",
        ]
        print(random.choice(pullup_lines))
        time.sleep(SLEEP * 0.45)
        play_context = "pressure_pullup"

    hunted = None if star_takeover_lock or play_context in ("deep_paint_touch", "iso") else hunt_mismatch(off, dff, matchups, period, period_time, current_handler)
    if hunted:
        shooter, defender = hunted
        if ball_owner is not shooter:
            announce_ball_transfer(ball_owner, shooter, "mismatch")
            last_passer = ball_owner
            ball_owner = shooter
        rerouted = reroute_zero_tendency_shooter(off, shooter, ball_owner)
        if rerouted is not shooter:
            announce_ball_transfer(ball_owner, rerouted, "reroute")
            last_passer = ball_owner
            shooter = rerouted
            ball_owner = shooter
        current_handler = shooter
        play_context = "mismatch_hunt"
        quick_shot_for_assist = False

    # GUARD-LED PICK AND ROLL WITH SWITCHES
    pnr_bonus = 0.26 if play_context in ("high_pnr", "empty_corner_pnr", "horns", "spain_pnr") else 0.0
    if (not star_takeover_lock) and play_context not in ("deep_paint_touch", "iso") and (can_play_position(current_handler, "PG") or can_play_position(current_handler, "SG")) and random.random() < 0.55 + pnr_bonus:
        pnr_shooter, pnr_defender, screener, pnr_result = maybe_pick_and_roll(off, dff, current_handler, matchups)

        if pnr_result:
            if pnr_shooter is not current_handler:
                last_passer = current_handler
                if pnr_result == "alley_oop":
                    # A lob is a catch-and-finish by definition -- there is
                    # no dribble, reset, or hesitation possible between the
                    # catch and the shot. A direct pass into a shot is an
                    # assist, full stop; nothing to gate here.
                    quick_shot_for_assist = True
                else:
                    # A live pick-and-roll read (hit the roller, find the
                    # popper) is a genuine assist chance, but not every PNR
                    # ball-handler delivers that pass cleanly enough for an
                    # immediate score -- the playmaking of whoever is running
                    # the action decides how often the catch turns into a shot
                    # right away versus another dribble, reset, or extra pass.
                    pnr_feed_chance = immediate_catch_chance(
                        current_handler, base=0.26, slope=0.44, lo=0.20, hi=0.82,
                        bonus=0.10 if pnr_result in ("roller", "popper", "pnr_catch_shoot") else 0.0,
                    )
                    quick_shot_for_assist = random.random() < pnr_feed_chance
            shooter = pnr_shooter
            ball_owner = shooter
            rerouted = reroute_zero_tendency_shooter(off, shooter, current_handler)
            if rerouted is not shooter:
                announce_ball_transfer(ball_owner, rerouted, "reroute")
                last_passer = ball_owner
                shooter = rerouted
                ball_owner = shooter
                defender = matchups.get(shooter, random.choice(dff.on_floor))
            else:
                defender = pnr_defender
                matchups[shooter] = defender
            play_context = pnr_result

    # END-GAME URGENCY

    margin = off.score - dff.score
    urgent = period >= 4 and period_time <= 90 and margin < 0

    if play_context not in ("deep_paint_touch", "iso") and urgent:
        # Down 3+ late: hunt threes. Down 1-2: best quick scorer.
        if closing_star is not None:
            new_shooter = closing_star
        elif margin <= -3:
            new_shooter = choose_closing_star_scorer(off, need_three=True)
        else:
            new_shooter = choose_closing_star_scorer(off, need_three=False)
        if ball_owner is not new_shooter:
            announce_ball_transfer(ball_owner, new_shooter, "closing_star")
            last_passer = ball_owner
            ball_owner = new_shooter
        shooter = new_shooter
        defender = matchups.get(shooter, random.choice(dff.on_floor))

        print(f"{off.name} need a quick score. {shooter.name} comes to the ball.")
        time.sleep(SLEEP * 0.5)

    star_preserve_contexts = {
        "deep_paint_touch", "iso", "roller", "popper", "alley_oop", "pnr_catch_shoot",
        "double_wide_open", "extra_pass_open", "dump_off", "drive_kick"
    }
    if (
        fourth_star_mode
        and not urgent
        and play_context not in star_preserve_contexts
        and pnr_result not in star_preserve_contexts
        and random.random() < fourth_star_chance * 0.62
    ):
        star_shooter = choose_fourth_quarter_star_scorer(
            off, dff, period, period_time,
            need_three=(off.score - dff.score <= -3 and period_time <= 90)
        )
        if star_shooter is not shooter:
            if ball_owner is not star_shooter:
                announce_ball_transfer(ball_owner, star_shooter, "closing_star")
                last_passer = ball_owner
                ball_owner = star_shooter
            shooter = star_shooter
            defender = matchups.get(shooter, random.choice(dff.on_floor))
            current_handler = shooter
            play_context = "fourth_star_touch"
            quick_shot_for_assist = False

    if play_context not in ("deep_paint_touch", "iso") and star_takeover_lock and random.random() < 0.94:
        clutch_options = [
            p for p in off.on_floor
            if p.usage >= 0.24 or p.clutchness >= 0.80
        ]
        if clutch_options:
            new_shooter = closing_star if closing_star is not None else choose_closing_star_scorer(off, need_three=False)
            if ball_owner is not new_shooter:
                announce_ball_transfer(ball_owner, new_shooter, "closing_star")
                last_passer = ball_owner
                ball_owner = new_shooter
            shooter = new_shooter
            defender = matchups.get(shooter, random.choice(dff.on_floor))
            current_handler = shooter
            quick_shot_for_assist = False


    # ⭐ ISOLATION vs QUICK SHOT DECISION
    shot_bias = (
        shooter.three_tendency +
        shooter.mid_tendency +
        shooter.drive_tendency +
        shooter.post_tendency
    ) / 4.0

    creation_iso = isolation_creation_score(shooter)
    iso_prob = 0.025 + creation_iso * 0.16 + shooter.iso_tendency * 0.18
    if shooter.ball_handle >= 0.78 and shooter.shot_tendency >= 0.42:
        iso_prob += 0.04 + shooter.iso_tendency * 0.04
    if shooter.shot_iq >= 0.78 and shooter.ball_handle >= 0.72:
        iso_prob += 0.03
    if shooter.shot_iq < 0.56 and shooter.usage >= 0.24:
        iso_prob += 0.02
    if shooter.playmaking >= 0.84:
        iso_prob -= 0.03
    if shooter.iso_tendency >= 0.82 and shooter.usage >= 0.28:
        iso_prob += 0.06
    elif shooter.iso_tendency < 0.25:
        iso_prob *= 0.55
    if play_context in PLAYBOOK_CONTEXTS or play_context in ("floppy", "elevator", "handoff", "horns", "drive_kick", "post_split", "ball_movement_chain"):
        iso_prob *= 0.35 + shooter.iso_tendency * 0.18

    pressure = iso_volume_pressure(off, period, period_time)
    if pressure > 1.0:
        iso_prob *= 1.0 + min(0.85, pressure * 0.16) * max(0.35, shooter.iso_tendency)
    elif pressure < -1.0:
        iso_prob *= max(0.40, 1.0 + pressure * 0.10)

    if shooter.iso_tendency < 0.45 and pressure > 0:
        iso_prob *= 0.72

    iso_cap = 0.36 if shooter.iso_tendency >= 0.82 else 0.30
    if pressure > 2.0 and shooter.iso_tendency >= 0.70:
        iso_cap += 0.06
    iso_prob = max(0.02, min(iso_cap, iso_prob))
    forced_iso_attempt = False
    iso_mult = None

    if play_context not in ("deep_paint_touch", "iso") and pnr_result not in ("roller", "popper", "alley_oop", "pnr_catch_shoot") and random.random() < iso_prob:
        play_context = "iso"
        pnr_result = "iso"
        true_iso_attempt = True
        quick_shot_for_assist = False
        iso_lines = [
            "sizes up his defender",
            "pounds the dribble in isolation",
            "waves everyone off",
            "backs it out and goes one-on-one",
            "takes his time reading the defense",
            "clears the side and attacks the matchup",
            "walks the defender down with a slow dribble",
            "switches hands low and studies the help",
            "gets the floor spaced and goes to work",
            "rocks the dribble between his legs",
            "jabs, resets, and keeps the defender guessing",
            "turns his shoulder and starts the one-on-one",
            "pulls it back out to attack in space",
            "signals for everyone to flatten out",
            "uses a live dribble to hunt his spot",
            "calls his own number and clears out",
            "waves the big away from the paint",
            "stares down his defender before attacking",
            "goes to his go-to move in isolation",
            "slows the game down to a crawl",
            "isolates on the wing and surveys the floor",
            "puts the ball on the deck and starts hunting",
            "signals for space and squares up",
            "rocks side to side, feeling out the angle",
            "settles into a one-on-one rhythm",
            "eyes the mismatch and attacks it",
            "takes his defender to the elbow",
            "walks it up top and calls for iso",
            "keeps two hands on the ball, reading the defense",
            "uses a shoulder fake before starting his move",
            "gets into his bag against the smaller defender",
            "changes speeds twice before committing",
            "backs his man down into single coverage",
            "clears the strong side and goes solo",
            "stares his man down before igniting the move"
        ]
        print(f"{shooter.name} {random.choice(iso_lines)}.")
        time.sleep(SLEEP * 0.8)

        outcome_line, iso_mult = isolation_shot_creation(shooter, defender)
        print(outcome_line)
        time.sleep(SLEEP * 0.5)
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * iso_mult
        forced_iso_attempt = iso_mult < 0.95

        # Playmaking kick-out
        kickout_chance = shooter.playmaking * 0.14
        if shooter.shot_iq >= 0.82 and iso_mult < 0.92:
            kickout_chance += 0.18
        if random.random() < kickout_chance:
            kickout = choose_shooter_excluding(off, shooter)
            print(f"{shooter.name} draws help and kicks it out to {kickout.name}.")
            time.sleep(SLEEP * 0.6)

            last_passer = shooter
            shooter = kickout
            ball_owner = shooter
            rerouted = reroute_zero_tendency_shooter(off, shooter, last_passer)
            if rerouted is not shooter:
                announce_ball_transfer(ball_owner, rerouted, "reroute")
                last_passer = ball_owner
                shooter = rerouted
                ball_owner = shooter
            defender = matchups.get(shooter, random.choice(dff.on_floor))
            play_context = "drive_kick"
            pnr_result = "drive_kick"
            true_iso_attempt = False
            quick_shot_for_assist = True
            forced_iso_attempt = False
            if random.random() < non_shooting_foul_chance(defender, "reach"):
                call_foul(dff, defender, f"Reach-in foul on {defender.name} as {shooter.name} tries to attack.")
                maybe_sit_foul_trouble(dff, defender, period)
                maybe_technical_foul(dff, off, period, period_time - possession_time, teamA, teamB)
                if in_bonus(dff):
                    print(f"{off.name} are in the bonus. {shooter.name} will shoot two.")
                    next_possession = shoot_free_throws(
                        shooter, off, 2, period, period_time - possession_time, teamA, teamB,
                        sub_after_first=True, protected=shooter
                    )
                    return next_possession, possession_time
                dead_ball_subs(
                    teamA, teamB, period, period_time - possession_time,
                    protected_teamA=shooter if off is teamA else None,
                    protected_teamB=shooter if off is teamB else None,
                )
                return off, random.randint(2, 5)

    rerouted_shooter = maybe_reroute_spurs_role_shot(off, shooter)
    if rerouted_shooter is not shooter:
        announce_ball_transfer(ball_owner, rerouted_shooter, "reroute")
        last_passer = ball_owner if ball_owner is not rerouted_shooter else last_passer
        shooter = rerouted_shooter
        ball_owner = shooter
        defender = matchups.get(shooter, random.choice(dff.on_floor))
        quick_shot_for_assist = True
        pnr_result = play_context or pnr_result

    # ON-BALL STEAL
    if play_context != "deep_paint_touch" and attempt_on_ball_steal(shooter, defender):
        print(steal_voice_line(defender, shooter, "on_ball"))
        process_steal(defender, dff, shooter, off)
        time.sleep(SLEEP * 0.9)
        next_possession = run_fastbreak(
            dff, off, period, period_time - possession_time, teamA, teamB,
            source="steal", trigger_player=defender
        )
        return next_possession, possession_time

    combo_creator = shooter
    combo_defender = defender
    combo_chance = dribble_combo_chance(combo_creator, combo_defender, play_context, period, period_time)
    combo_shot_described = False
    # If shooter's own dribble-combo chance is 0 (e.g. a low-ball-handle
    # shooter like Klay), this used to fall back to searching for a
    # DIFFERENT on-court player to hand the possession to -- with no pass or
    # hand-off ever described, so the commentary would jump from one
    # player's move straight into a completely different player's move.
    # Once a shot-creation sequence has already locked in a shooter (a true
    # isolation is the clearest case), there's no one left to silently swap
    # to; nothing here should override that.
    if combo_chance <= 0.0 and not true_iso_attempt:
        for possible_creator in (locals().get("current_handler"), ball_owner, handler):
            if (
                possible_creator in off.on_floor
                and possible_creator is not shooter
                and dribble_combo_chance(possible_creator, matchups.get(possible_creator, random.choice(dff.on_floor)), play_context, period, period_time) > 0.0
            ):
                combo_creator = possible_creator
                combo_defender = matchups.get(combo_creator, random.choice(dff.on_floor))
                combo_chance = dribble_combo_chance(combo_creator, combo_defender, play_context, period, period_time) * 0.85
                break

    if random.random() < combo_chance:
        combo_action, combo_quality = dribble_combo_action(combo_creator, combo_defender, off, dff, period, period_time, play_context)
        print_dribble_combo(combo_creator, combo_defender, combo_action)
        combo_creator.shot_quality_mult = getattr(combo_creator, "shot_quality_mult", 1.0) * combo_quality
        if combo_action == "pass":
            receiver_pool = [
                p for p in off.on_floor
                if p is not combo_creator and not is_non_spacer(p)
            ]
            if not receiver_pool:
                receiver_pool = [p for p in off.on_floor if p is not combo_creator]
            receiver = weighted_open_shot_target(
                receiver_pool,
                lambda p: (
                    0.34 * p.three_rating
                    + 0.24 * p.mid_rating
                    + 0.18 * p.rim_rating
                    + 0.14 * p.shot_tendency
                    + 0.10 * p.clutchness
                )
            ) or choose_shooter_excluding(off, shooter)
            print(random.choice(dribble_combo_pass_finishes).format(
                shooter=combo_creator.name,
                receiver=receiver.name
            ))
            time.sleep(SLEEP * 0.5)
            last_passer = combo_creator
            shooter = receiver
            ball_owner = shooter
            defender = matchups.get(shooter, random.choice(dff.on_floor))
            shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 1.07
            play_context = "handle_combo_pass"
            pnr_result = "handle_combo_pass"
            # Kicking out of a dribble combo isn't inherently a scoring
            # pass -- the receiver may have to gather, reset, or take an
            # extra dribble before shooting. The creator's playmaking
            # decides how often it's clean enough to count as immediate.
            combo_pass_chance = immediate_catch_chance(combo_creator, base=0.24, slope=0.44, lo=0.20, hi=0.78)
            quick_shot_for_assist = random.random() < combo_pass_chance
            forced_iso_attempt = False
        elif combo_action == "drive":
            shooter = combo_creator
            ball_owner = shooter
            defender = combo_defender
            play_context = "handle_combo_drive"
            pnr_result = "handle_combo_drive"
        elif combo_action == "pullup_three":
            shooter = combo_creator
            ball_owner = shooter
            defender = combo_defender
            shot_type = "three"
            play_context = "handle_combo_three"
            pnr_result = "handle_combo_three"
            combo_shot_described = True
        else:
            shooter = combo_creator
            ball_owner = shooter
            defender = combo_defender
            shot_type = "mid"
            play_context = "handle_combo_mid"
            pnr_result = "handle_combo_mid"
            combo_shot_described = True

    three_pref = getattr(getattr(off, "coach_style", {}), "get", lambda *_: 1.0)("three_preference", 1.0)

    if play_context == "handle_combo_three":
        # The dribble-combo flavor line already committed to a specific
        # shot (e.g. "gets to the elbow ... pulls up" for a mid-range look)
        # -- none of the situational branches below (which don't check
        # play_context at all, like the late-game trailing override) may
        # silently swap it for a different shot type after the fact.
        shot_type = "three" if shooter.three_tendency > 0 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context == "handle_combo_mid":
        shot_type = "mid" if shooter.mid_tendency > 0 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context == "handle_combo_drive":
        shot_type = "rim" if shooter.drive_tendency > 0 and random.random() < 0.74 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif 'pnr_result' in locals() and pnr_result == "alley_oop":
        shot_type = "dunk"
    elif 'pnr_result' in locals() and pnr_result == "roller":
        shot_type = "rim"
    elif 'pnr_result' in locals() and pnr_result == "popper":
        pop_three = shooter.three_tendency >= shooter.mid_tendency and random.random() < min(0.86, (0.25 + 0.35 * three_pref) * THREE_ATTEMPT_SCALE)
        shot_type = "three" if pop_three else "mid"
    elif 'pnr_result' in locals() and pnr_result == "pnr_catch_shoot":
        shot_type = "three" if shooter.three_tendency > 0 and shooter.three_rating >= 0.70 and random.random() < THREE_ATTEMPT_SCALE else "mid"
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 1.12
    elif play_context == "extra_pass_open":
        shot_type = "three" if shooter.three_tendency > 0 and shooter.three_rating >= 0.72 and random.random() < THREE_ATTEMPT_SCALE else "mid"
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * (1.08 + catch_shoot_badge_quality_bonus(shooter))
    elif period >= 4 and period_time <= 90 and off.score - dff.score <= -3:
        shot_type = "three" if shooter.three_tendency > 0 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif period >= 4 and period_time <= 45 and off.score - dff.score in (-1, -2):
        shot_type = "rim" if shooter.drive_tendency > 0 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context == "floppy":
        movement_three = shooter.three_rating >= shooter.mid_rating and random.random() < min(0.86, 0.30 + 0.35 * three_pref)
        shot_type = "three" if movement_three else "mid"
    elif play_context == "elevator":
        shot_type = "three" if random.random() < min(0.88, (0.38 + 0.30 * three_pref) * THREE_ATTEMPT_SCALE) else "mid"
        shooter.shot_quality_mult = 1.08
    elif play_context == "backdoor":
        shot_type = "dunk" if random.random() < effective_dunk_attempt_chance(shooter) else "rim"
        shooter.shot_quality_mult = 1.06
    elif play_context == "deep_paint_touch":
        shot_type = "dunk" if random.random() < effective_dunk_attempt_chance(shooter) else "post"
        shooter.shot_quality_mult = 1.08
    elif play_context == "drive_kick":
        kick_three = (
            shooter.three_rating >= 0.76
            and shooter.three_tendency > 0
            and random.random() < min(0.88, (0.30 + 0.35 * three_pref) * THREE_ATTEMPT_SCALE)
        )
        shot_type = "three" if kick_three else "mid"
        shooter.shot_quality_mult = 1.07
    elif play_context == "handle_combo_pass":
        if shooter.three_tendency > 0 and shooter.three_rating >= 0.74 and random.random() < min(0.84, (0.24 + shooter.three_tendency * 0.58 * three_pref) * THREE_ATTEMPT_SCALE):
            shot_type = "three"
        elif shooter.mid_tendency > 0 and shooter.mid_rating >= 0.72:
            shot_type = "mid"
        else:
            shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context == "pressure_drive":
        shot_type = "rim" if shooter.drive_tendency > 0 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context == "pressure_pullup":
        if shooter.three_tendency > 0 and shooter.three_rating >= shooter.mid_rating and random.random() < min(0.72, (0.18 + shooter.three_tendency * 0.65 * three_pref) * THREE_ATTEMPT_SCALE):
            shot_type = "three"
        else:
            shot_type = "mid" if shooter.mid_tendency > 0 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context == "foul_hunt":
        if shooter.drive_tendency > 0 and random.random() < 0.68:
            shot_type = "rim"
        elif shooter.post_tendency > 0.14 and shooter.height >= 78:
            shot_type = "post"
        else:
            shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context == "fourth_star_touch":
        shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * (1.02 + shooter.clutchness * 0.04)
    elif play_context == "horns":
        shot_type = "rim" if random.random() < 0.42 and shooter.rim_rating >= 0.78 else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context == "post_split":
        shot_type = "post" if shooter.post_tendency > 0.08 else "mid"
    elif play_context == "handoff":
        handoff_three_chance = min(0.88, (shooter.three_tendency * 0.75 * three_pref + 0.12) * THREE_ATTEMPT_SCALE)
        shot_type = "three" if random.random() < handoff_three_chance else choose_shot_type(shooter, defender, off, dff, period, period_time)
    elif play_context in PLAYBOOK_CONTEXTS:
        if play_context in ("lakers_shaq_seal", "bulls_triangle_post", "sixers_embiid_elbow"):
            shot_type = "post"
        elif play_context in ("rockets_spread_lob", "nuggets_gordon_dunker", "lakers_ad_duckin", "bucks_giannis_wall", "sixers_simmons_dunker", "thunder_russ_rim"):
            shot_type = "dunk" if random.random() < effective_dunk_attempt_chance(shooter) else "rim"
        elif play_context == "sixers_butler_slot":
            shot_type = "rim" if random.random() < 0.45 else "mid"
        elif (
            shooter.three_rating >= 0.80
            and shooter.three_tendency >= 0.25
            and random.random() < min(0.86, (0.25 + 0.36 * three_pref) * THREE_ATTEMPT_SCALE)
        ):
            shot_type = "three"
        elif shooter.rim_rating >= 0.86 and random.random() < 0.45:
            shot_type = "rim"
        else:
            shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 1.05
    elif play_context == "iso":
        shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)
    else:
        shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)


    if shot_type == "rim" and random.random() < effective_dunk_attempt_chance(shooter):
        shot_type = "dunk"

    limitless_event = None
    if not combo_shot_described and (shot_type == "three" or getattr(shooter, "jumper_make_streak", 0) >= 3):
        limitless_event = maybe_limitless_range_three(shooter, off, period, period_time - possession_time, dff)
        if limitless_event:
            shot_type = "three"
            play_context = limitless_event
            pnr_result = limitless_event
            shooter.limitless_range_attempt = True
            shooter.heat_check_attempt = limitless_event == "heat_check"
            shooter.shot_quality_mult = (
                getattr(shooter, "shot_quality_mult", 1.0)
                * limitless_range_quality_multiplier(shooter, heat_check=limitless_event == "heat_check")
            )

    ankle_breaker_open = False
    if not limitless_event and shot_type in ("three", "mid") and random.random() < ankle_breaker_chance(shooter, defender, play_context):
        ankle_breaker_open = True
        play_context = "ankle_breaker"
        pnr_result = "ankle_breaker"
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 1.15
        print(random.choice(ankle_breaker_lines).format(shooter=shooter.name, defender=defender.name))
        time.sleep(SLEEP * 0.55)

    double_teamed = False
    if not combo_shot_described and not limitless_event and not ankle_breaker_open and should_double_team(shooter, defender, off, dff, period, period_time, shot_type):
        double_teamed = True
        doubled_player = shooter
        doubled_player.double_teams_faced += 1
        print(f"{dff.name} send a second defender at {shooter.name}.")
        time.sleep(SLEEP * 0.5)
        plan = getattr(dff, "game_plan", {})
        coverage = plan.get("star_coverage", "standard") if getattr(dff, "defensive_focus", None) == doubled_player.name else "standard"
        trappers = [p for p in dff.on_floor if p is not defender and not p.fouled_out]
        second_defender = max(
            trappers,
            key=lambda p: 0.55 * effective_perimeter_def(p) + 0.30 * p.steal + 0.15 * p.speed,
            default=defender
        )
        if random.random() < double_team_turnover_chance(doubled_player, second_defender, dff, coverage):
            print(steal_voice_line(second_defender, doubled_player, "double"))
            process_steal(second_defender, dff, doubled_player, off)
            time.sleep(SLEEP * 0.7)
            next_possession = run_fastbreak(
                dff, off, period, period_time - possession_time, teamA, teamB,
                source="steal", trigger_player=second_defender
            )
            return next_possession, possession_time

        escape_chance = 0.12 + doubled_player.playmaking * 0.42 + doubled_player.ball_handle * 0.18 + doubled_player.shot_iq * 0.08
        if coverage == "trap_force_pass":
            escape_chance -= 0.04
        elif coverage == "late_double_rotate":
            escape_chance += 0.02
        escape_chance = max(0.20, min(0.78, escape_chance))
        if random.random() < escape_chance:
            keep_chance = 0.06
            if true_primary_shot_creator(doubled_player):
                keep_chance = 0.22 + max(0.0, doubled_player.iso_tendency - 0.60) * 0.28 + max(0.0, doubled_player.usage - 0.34) * 0.24
                if period >= 4 and period_time <= 6 * 60:
                    keep_chance += doubled_player.clutchness * 0.08
                keep_chance = min(0.52, keep_chance)
            if random.random() < keep_chance:
                print(f"{doubled_player.name} splits the double and keeps the shot for himself.")
                time.sleep(SLEEP * 0.5)
                shooter = doubled_player
                ball_owner = shooter
                quick_shot_for_assist = False
                play_context = "iso"
                pnr_result = "double_split"
                shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 0.96
                shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)
            else:
                kickout = find_double_team_kickout(off, doubled_player)
                print(f"{doubled_player.name} beats the double and kicks it out to {kickout.name}")
                time.sleep(SLEEP * 0.5)
                # A rushed kickout out of a live double is a real turnover
                # risk when the passer isn't a good decision-maker -- only
                # sharp playmakers reliably get this pass all the way there
                # clean. This scales continuously with playmaking rather
                # than a hard cutoff, same as every other assist pathway.
                kickout_defender = matchups.get(kickout, random.choice(dff.on_floor))
                kickout_risk = max(0.01, 0.10 - doubled_player.playmaking * 0.09)
                if random.random() < deflection_out_of_bounds_chance(doubled_player, kickout, kickout_defender) + kickout_risk:
                    print(f"{kickout_defender.name} reads the kickout and tips it away. {off.name if random.random() < 0.5 else dff.name} scrambles for it.")
                    commit_turnover(doubled_player, off)
                    dead_ball_subs(teamA, teamB, period, period_time - possession_time)
                    return dff, random.randint(2, 5)
                last_passer = doubled_player
                shooter = kickout
                ball_owner = shooter
                defender = matchups.get(shooter, random.choice(dff.on_floor))
                wide_open_chance = catch_shoot_creation_chance(doubled_player, shooter, "double")
                # Smooth playmaking scaling instead of a hard cliff: better
                # passers make this kickout look clean and immediate far
                # more often, worse ones still get it there but it's less
                # likely to be a true, direct assist read.
                elite_passer_double = doubled_player.playmaking >= 0.86
                playmaking_scale = max(0.30, min(1.0, (doubled_player.playmaking - 0.40) / 0.46))
                should_fire_open = random.random() < wide_open_chance * playmaking_scale
                # Beating a double is only a *clean, direct* read -- and thus
                # a genuine assist -- when the passer actually has the vision
                # to make it one. A mediocre playmaker's kickout still gets
                # the ball to a teammate, but it isn't automatically credited;
                # it falls through to the skill-scaled delayed-assist check
                # instead, same as any other non-immediate look.
                quick_shot_for_assist = should_fire_open or elite_passer_double
                if shooter.three_tendency > 0 and shooter.three_rating >= 0.72 and should_fire_open:
                    play_context = "double_wide_open"
                    pnr_result = "double_wide_open"
                    shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * (1.20 + catch_shoot_badge_quality_bonus(shooter))
                    shot_type = "three"
                else:
                    play_context = "double_kick"
                    pnr_result = "double_kick"
                    if elite_passer_double:
                        play_context = "double_wide_open"
                        pnr_result = "double_wide_open"
                        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 1.16
                        if shooter.three_tendency > 0 and shooter.three_rating >= 0.68:
                            shot_type = "three"
                        elif shooter.mid_rating >= shooter.rim_rating:
                            shot_type = "mid"
                        else:
                            shot_type = "rim"
                    else:
                        if random.random() < 0.58:
                            shooter.shot_quality_mult = 1.06
                        shot_type = "three" if shooter.three_rating >= shooter.mid_rating and shooter.three_tendency > 0 and random.random() < THREE_ATTEMPT_SCALE else "mid"
        else:
            forced_mult = 0.76 if doubled_player.playmaking < 0.64 else 0.84
            shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * forced_mult
            quick_shot_for_assist = False

    paint_helper_triggered = False
    if play_context == "iso":
        paint_context = None
        dumped_off = False
        dump_passer = None
    else:
        shooter, defender, shot_type, dump_passer, paint_context, dumped_off = maybe_low_man_help(
            off, dff, shooter, defender, shot_type, matchups, period, period_time - possession_time
        )
    if paint_context:
        paint_helper_triggered = True
        play_context = paint_context
        if dumped_off and dump_passer:
            last_passer = dump_passer
            ball_owner = shooter
            pnr_result = "dump_off"
            quick_shot_for_assist = True
        elif paint_context == "paint_help":
            quick_shot_for_assist = False

    forced_advantage_context = play_context in ("double_wide_open", "dump_off", "dump_off_elite_help") or pnr_result in ("double_wide_open", "dump_off", "dump_off_elite_help")
    if not forced_advantage_context and not has_shot_volume_left(shooter) and not (star_takeover_lock and shooter is closing_star):
        reset_target = choose_shooter_excluding(off, shooter)
        if reset_target is not shooter and has_shot_volume_left(reset_target):
            print(f"{shooter.name} passes up the look and swings it to {reset_target.name}.")
            time.sleep(SLEEP * 0.5)
            last_passer = shooter
            shooter = reset_target
            ball_owner = shooter
            defender = matchups.get(shooter, random.choice(dff.on_floor))
            play_context = "extra_pass"
            pnr_result = "extra_pass"
            quick_shot_for_assist = True
            shot_type = choose_shot_type(shooter, defender, off, dff, period, period_time)
            if shot_type == "rim" and random.random() < effective_dunk_attempt_chance(shooter):
                shot_type = "dunk"

    handle_chain_pass = maybe_dribble_chain_pass(
        off, dff, shooter, shot_type, play_context or pnr_result,
        matchups, period, period_time - possession_time
    )
    if handle_chain_pass:
        last_passer = shooter
        shooter, defender, shot_type = handle_chain_pass
        ball_owner = shooter
        play_context = "handle_combo_pass"
        pnr_result = "handle_combo_pass"
        quick_shot_for_assist = True
        forced_iso_attempt = False
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 1.08

    # LOW-CHANCE OFFENSIVE CHARGE
    if random.random() < charge_chance(shooter, defender, shot_type):
        if maybe_challenge_call(off, f"offensive foul on {shooter.name}"):
            off.inbound_pending = True
            return off, random.randint(2, 5)
        charge_line = random.choice(charge_voice_lines).format(defender=defender.name, shooter=shooter.name)
        call_foul(off, shooter, f"Offensive foul on {shooter.name}. {charge_line}")
        maybe_sit_foul_trouble(off, shooter, period)
        commit_turnover(shooter, off)
        dead_ball_subs(teamA, teamB, period, period_time - possession_time)
        return dff, possession_time

    # LOW-CHANCE DEFENSIVE BLOCKING FOUL BEFORE SHOT
    if shot_type in ("rim", "dunk") and random.random() < non_shooting_foul_chance(defender, "blocking"):
        fouler = choose_fouling_defender(dff, defender, shooter, shot_type, "paint_help")
        if maybe_challenge_call(dff, f"blocking foul on {fouler.name}"):
            off.inbound_pending = True
            return off, random.randint(2, 5)
        call_foul(dff, fouler, f"Blocking foul on {fouler.name}. {shooter.name} was cut off on the drive.")
        maybe_sit_foul_trouble(dff, fouler, period)
        maybe_technical_foul(dff, off, period, period_time - possession_time, teamA, teamB)
        if in_bonus(dff):
            print(f"{off.name} are in the bonus. {shooter.name} will shoot two.")
            next_possession = shoot_free_throws(
                shooter, off, 2, period, period_time - possession_time, teamA, teamB,
                sub_after_first=True, protected=shooter
            )
            return next_possession, possession_time
        dead_ball_subs(
            teamA, teamB, period, period_time - possession_time,
            protected_teamA=shooter if off is teamA else None,
            protected_teamB=shooter if off is teamB else None,
        )
        return off, random.randint(2, 5)

    catch_shoot_context = play_context in ("pnr_catch_shoot", "double_wide_open", "extra_pass_open", "handle_combo_pass") or pnr_result in ("pnr_catch_shoot", "double_wide_open", "extra_pass_open", "handle_combo_pass")
    open_shot_context = (catch_shoot_context or ankle_breaker_open) and shot_type in ("three", "mid")
    attempt_context = "iso_forced" if forced_iso_attempt and play_context == "iso" else (play_context or pnr_result)
    # A clean, unforced isolation creation ("rises cleanly", "walks into his
    # favorite window") already narrated a complete move -- printing a
    # second, separate go-to-shot sequence after it is redundant and can
    # flatly contradict it (freezes the defender and rises cleanly, then in
    # the next line is somehow still driving at the rim).
    iso_already_described = play_context == "iso" and iso_mult is not None and iso_mult >= 1.10
    chain_will_describe_shot = should_print_dribble_chain(shooter, shot_type, attempt_context)
    signature_line = None if combo_shot_described or chain_will_describe_shot or catch_shoot_context or (shot_type == "dunk" and pnr_result != "alley_oop") else signature_move_line(shooter, shot_type, attempt_context)
    if signature_line:
        print(f"{shooter.name} {signature_line}")
        time.sleep(SLEEP * 0.4)

    if pnr_result == "heat_check" and shot_type == "three":
        print(f"{shooter.name} {random.choice(heat_check_lines)}")

    elif pnr_result == "limitless" and shot_type == "three":
        print(f"{shooter.name} {random.choice(limitless_range_lines)}")

    elif ankle_breaker_open and shot_type == "three":
        print(f"{shooter.name} steps into the open three after the move.")

    elif ankle_breaker_open and shot_type == "mid":
        print(f"{shooter.name} rises into the open jumper after the shake.")

    elif catch_shoot_context and shot_type == "three":
        print(f"{shooter.name} {random.choice(wide_open_catch_shoot_lines)}")

    elif catch_shoot_context and shot_type == "mid":
        catch_mid_lines = [
            "catches inside the arc, gets balanced, and rises.",
            "turns the pass into a quick rhythm midrange jumper.",
            "catches at the elbow and shoots before the help can recover.",
            "steps into the pocket off the pass and pulls up.",
            "receives it in stride near the nail and lets it go.",
        ]
        print(f"{shooter.name} {random.choice(catch_mid_lines)}")

    elif combo_shot_described and shot_type in ("three", "mid"):
        pass

    elif shot_type == "three":
        if not iso_already_described:
            print_shot_attempt_sequence(shooter, shot_type, attempt_context)

    elif shot_type == "mid":
        if not iso_already_described:
            print_shot_attempt_sequence(shooter, shot_type, attempt_context)
    elif shot_type == "rim":
        if not iso_already_described:
            print_shot_attempt_sequence(shooter, shot_type, attempt_context)
    elif shot_type == "dunk":
        gather = random.choice(dunk_gather_lines)
        drive = random.choice(cpl)
        if pnr_result == "alley_oop":
            print(f"{shooter.name} {random.choice(alley_oop_finish_attempts)}.")
        elif pnr_result == "roller":
            roll_finish_lines = [
                "catches on the move and goes straight to the rim.",
                "takes the pocket pass and powers up.",
                "rolls into the lane and rises to finish.",
                "takes it in stride and goes up strong.",
                "catches below the foul line and attacks the rim."
            ]
            print(f"{shooter.name} {random.choice(roll_finish_lines)}")
        elif play_context == "deep_paint_touch":
            deep_dunk_lines = [
                "catches, gathers, and goes straight up strong.",
                "takes the entry pass and powers up at the rim.",
                "keeps it high and rises for the dunk.",
                "turns from the seal and tries to finish above the rim.",
            ]
            print(f"{shooter.name} {random.choice(deep_dunk_lines)}")
        elif not iso_already_described:
            print(f"{shooter.name} {drive}")
            time.sleep(SLEEP * 0.5)
            print(f"{shooter.name} {gather}")
    else:
        if iso_already_described:
            pass
        elif play_context == "deep_paint_touch":
            deep_post_finish_lines = [
                "keeps it high and goes right up.",
                "turns over his inside shoulder and puts it up.",
                "uses his body to shield the defender and flips it up.",
                "catches on the seal and goes straight into the finish.",
                "takes one power dribble and lays it in traffic.",
            ]
            print(f"{shooter.name} {random.choice(deep_post_finish_lines)}")
        else:
            print_shot_attempt_sequence(shooter, shot_type, play_context or pnr_result)
    time.sleep(SLEEP * 0.8)

    quality_label, quality_mult = shot_quality(shooter, defender, shot_type, period, period_time - possession_time)
    if play_context == "double_wide_open":
        quality_label = "wide open"
        quality_mult = max(quality_mult, 1.20 + (catch_shoot_badge_quality_bonus(shooter) if shot_type in ("three", "mid") else 0.0))
    elif open_shot_context:
        quality_label = "wide open"
        quality_mult = max(quality_mult, 1.20 + catch_shoot_badge_quality_bonus(shooter))
    elif play_context == "dump_off":
        quality_label = "wide open"
        quality_mult = max(quality_mult, 1.24)
    elif play_context == "dump_off_elite_help":
        quality_label = "lightly contested"
        quality_mult = max(quality_mult, 1.02)
    elif defensive_communication_error(off, dff, shooter, shot_type, play_context, period, period_time - possession_time):
        quality_label = "wide open"
        quality_mult = max(quality_mult, 1.16)
    creator_bonus = shot_creator_contested_bonus(shooter, quality_label, shot_type)
    if creator_bonus:
        shooter.shot_creator_quality_bonus = creator_bonus
    poster_bonus = posterizer_quality_bonus(shooter, defender) if shot_type == "dunk" else 0.0
    if poster_bonus:
        shooter.posterizer_quality_bonus = poster_bonus
    raw_diet_context = pnr_result or play_context
    if true_iso_attempt and raw_diet_context in ("handle_combo_drive", "handle_combo_three", "handle_combo_mid"):
        raw_diet_context = "iso"
    diet_context = shot_quality_diet_context(raw_diet_context, quality_label)
    shooter.shot_quality_mult = quality_mult * getattr(shooter, "shot_quality_mult", 1.0)

    

    # FOUL CHECK
    foul_chance = foul_draw_sim(shooter) * usage_foul_weight(shooter) * FOUL_SCALE * foul_trouble_foul_factor(defender)
    offensive_foul_plan = getattr(off, "game_plan", {}).get("foul_strategy", "normal")
    defensive_foul_plan = getattr(dff, "game_plan", {}).get("foul_strategy", "normal")
    foul_chance *= shooting_foul_type_multiplier(shot_type)
    if offensive_foul_plan == "attack_foul_trouble" and defender.pf >= 3:
        foul_chance *= 1.18
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 1.04
    if play_context == "foul_hunt" and defender.pf >= 3:
        foul_chance *= 1.22 + min(0.22, foul_draw_sim(shooter) * 0.35)
        shooter.shot_quality_mult = getattr(shooter, "shot_quality_mult", 1.0) * 1.03
    if defensive_foul_plan == "avoid_fouls":
        foul_chance *= 0.82
    elif defensive_foul_plan == "wall_paint" and is_paint_shot(shot_type):
        foul_chance *= 1.08
    if double_teamed:
        foul_chance *= 0.90
    if paint_helper_triggered and is_paint_shot(shot_type):
        foul_chance *= 0.92
    if PLAYOFF_MODE:
        foul_chance *= 0.88
    
    if random.random() < foul_chance:
        clear_shot_temp_bonuses(shooter)
        foul_context = "paint_help" if paint_helper_triggered else "double" if double_teamed else play_context or pnr_result or ""
        fouler = choose_fouling_defender(dff, defender, shooter, shot_type, foul_context)
        register_foul(dff, fouler)
        shooter.fouls_drawn += 1
        off.fouls_drawn += 1
        if fouler.pf >= 6:
            foul_out_sub(dff, fouler)
        else:
            maybe_sit_foul_trouble(dff, fouler, period)

        print(commentator_foul(fouler.name, shooter.name))
        time.sleep(SLEEP * 0.7)
        maybe_technical_foul(dff, off, period, period_time - possession_time, teamA, teamB)

        n_ft = 3 if shot_type == "three" else 2
        print(f"{shooter.name} steps to the line for {n_ft}.")
        time.sleep(SLEEP * 0.6)

        next_possession = shoot_free_throws(
            shooter, off, n_ft,
            period, period_time - possession_time,
            teamA, teamB,
            sub_after_first=True, protected=shooter
        )

        if should_close_game(teamA, teamB, period, period_time - possession_time):
            if auto_subs_allowed(off):
                force_starter_lineup(off)
            if auto_subs_allowed(dff):
                force_starter_lineup(dff)

        return next_possession, possession_time


    # BLOCK CHECK
    if random.random() < block_prob(defender, shot_type, shooter):
        final_quality_mult = getattr(shooter, "shot_quality_mult", quality_mult)
        clear_shot_temp_bonuses(shooter)
        print(block_voice_line(defender, shooter, shot_type))

        process_block(defender, dff)
        time.sleep(SLEEP * 0.7)

        shooter.fga += 1
        record_shot_diet(off, shot_type, diet_context, shooter, defender, quality_mult=final_quality_mult)
        update_shot_rhythm(shooter, False, shot_type)
        if shot_type == "three":
            shooter.tpa += 1

        # Block knocked out of bounds: offense keeps it.
        # Game clock runs for the play, but the possession stays with the same team.
        if random.random() < block_out_of_bounds_chance(shot_type):
            print(f"The block caroms out of bounds. {off.name} will keep possession.")
            dead_ball_subs(teamA, teamB, period, period_time - possession_time)
            print_scoreboard(period, period_time - possession_time, teamA, teamB)
            off.inbound_pending = True
            return off, possession_time

        miss_kind = "rim" if is_paint_shot(shot_type) else "jumper"
        reb_team, rebounder = choose_rebounder(off, dff, miss_kind)

        print(commentator_rebound(rebounder.name, reb_team.name))
        time.sleep(SLEEP * 0.6)

        if reb_team is off:
            next_team, extra_time = handle_offensive_rebound(
                off, dff, rebounder,
                period, period_time - possession_time,
                teamA, teamB
            )
            return next_team, possession_time + extra_time

        if should_push_after_rebound(rebounder, dff, miss_kind, period, period_time - possession_time):
            print(f"{dff.name} look to run after the rebound.")
            next_possession = run_fastbreak(
                dff, off, period, period_time - possession_time, teamA, teamB,
                source="rebound", trigger_player=rebounder
            )
            return next_possession, possession_time

        print_scoreboard(period, period_time - possession_time, teamA, teamB)
        return dff, possession_time

    # SHOT RESOLUTION
    final_quality_mult = getattr(shooter, "shot_quality_mult", quality_mult)
    make_prob = shot_make_prob(shooter, defender, shot_type, off, dff, period, period_time)
    clear_shot_temp_bonuses(shooter)

    shooter.fga += 1
    record_shot_diet(off, shot_type, diet_context, shooter, defender, quality_mult=final_quality_mult)
    if shot_type == "three":
        shooter.tpa += 1

    if random.random() < make_prob:
        pts = 3 if shot_type == "three" else 2
        score_before = off.score
        shooter.fgm += 1
        shooter.pts += pts
        record_shot_make(off, shot_type, diet_context, shooter, defender)

        if shot_type == "three":
            shooter.tpm += 1

        score_time = period_time - possession_time
        late_go_ahead = is_late_go_ahead_make(score_before, dff.score, pts, period, score_time)
        off.score += pts
        if is_paint_shot(shot_type):
            off.points_paint += pts
        record_score_event(off, dff, pts, period, score_time, teamA, teamB, check_timeout=False)
        update_shot_rhythm(shooter, True, shot_type)
        maybe_injury_stinger(shooter, off, shot_type, period)

        assist_recorded = False
        assist_context = pnr_result or play_context
        if (
            last_passer
            and last_passer != shooter
            and random.random() < assist_credit_chance(
                last_passer, shooter, shot_type, assist_context, quick_shot_for_assist
            )
        ):
            record_assist(last_passer, off, pts)
            assist_recorded = True

        # LOW-CHANCE AND-ONE ON MADE SHOTS
        and_one_chance = foul_draw_sim(shooter) * usage_foul_weight(shooter) * FOUL_SCALE * 0.58 * foul_trouble_foul_factor(defender)
        and_one_chance *= and_one_type_multiplier(shot_type)

        if random.random() < and_one_chance:
            foul_context = "paint_help" if paint_helper_triggered else "double" if double_teamed else play_context or pnr_result or ""
            fouler = choose_fouling_defender(dff, defender, shooter, shot_type, foul_context)
            register_foul(dff, fouler)
            if fouler.pf >= 6:
                foul_out_sub(dff, fouler)
            else:
                maybe_sit_foul_trouble(dff, fouler, period)

            print_scoreboard(period, score_time, teamA, teamB)
            if shot_type == "three":
                print(f"And one! {fouler.name} clips {shooter.name} on the three-point make.")
            else:
                print(f"And one! {shooter.name} finishes through contact from {fouler.name}.")

            time.sleep(SLEEP * 0.7)

            dead_ball_subs(
                teamA, teamB, period, score_time,
                protected_teamA=shooter if off is teamA else None,
                protected_teamB=shooter if off is teamB else None,
            )

            next_possession = shoot_free_throws(
                shooter, off, 1,
                period, score_time,
                teamA, teamB
            )

            return next_possession, possession_time

        if late_go_ahead:
            print(commentator_game_winner(shooter.name, off.name, shot_type, score_time))
        elif pnr_result == "alley_oop":
            print(f"{shooter.name} {random.choice(alley_oop_makes)}")
        elif shot_type == "dunk":
            line = random.choice(dunk_poster_lines).format(defender=defender.name)
            print(f"{shooter.name} rises up and {line}")
        else:
            line = context_defense_line(shot_type, quality_label, True, pnr_result or play_context, defender)
            print(commentator_make(shooter.name, defender.name, shot_type, line))

        time.sleep(SLEEP * 0.8)
        print_scoreboard(period, score_time, teamA, teamB)
        maybe_crowd_moment(off, dff, shooter, pts)
        maybe_defensive_adjustment(dff, shooter)
        maybe_call_timeout_after_score(off, dff, period, score_time, teamA, teamB)
        return dff, possession_time

    else:
        update_shot_rhythm(shooter, False, shot_type)
        if pnr_result == "alley_oop":
            print(f"{shooter.name} {random.choice(alley_oop_misses)}")
        elif shot_type == "dunk":
            print(f"{shooter.name} goes for the poster but {random.choice(dunk_miss_lines)}")
        else:
            line = context_defense_line(shot_type, quality_label, False, pnr_result or play_context, defender)
            print(commentator_miss(shooter.name, defender.name, shot_type, line))

        time.sleep(SLEEP * 0.7)

        miss_kind = "rim" if is_paint_shot(shot_type) else "jumper"

        if random.random() < missed_shot_out_of_bounds_chance(shot_type):
            print(f"The miss caroms out of bounds. Possession goes to {dff.name}.")
            if maybe_challenge_call(off, "out-of-bounds call on the missed shot"):
                dead_ball_subs(teamA, teamB, period, period_time - possession_time)
                print_scoreboard(period, period_time - possession_time, teamA, teamB)
                off.inbound_pending = True
                return off, possession_time
            dead_ball_subs(teamA, teamB, period, period_time - possession_time)
            print_scoreboard(period, period_time - possession_time, teamA, teamB)
            return dff, possession_time

        reb_team, rebounder = choose_rebounder(off, dff, miss_kind)

        print(commentator_rebound(rebounder.name, reb_team.name))
        time.sleep(SLEEP * 0.6)

        if reb_team is off:
            next_team, extra_time = handle_offensive_rebound(
                off, dff, rebounder,
                period, period_time - possession_time,
                teamA, teamB
            )
            return next_team, possession_time + extra_time

        if should_push_after_rebound(rebounder, dff, miss_kind, period, period_time - possession_time):
            print(f"{dff.name} look to run after the defensive board.")
            next_possession = run_fastbreak(
                dff, off, period, period_time - possession_time, teamA, teamB,
                source="rebound", trigger_player=rebounder
            )
            return next_possession, possession_time

        time.sleep(SLEEP * 0.6)
        loose_fouler_team = dff if reb_team is off else off
        loose_candidates = [p for p in loose_fouler_team.on_floor if not p.fouled_out]
        if loose_candidates and random.random() < 0.035:
            fouler = random.choice(loose_candidates)
            call_foul(loose_fouler_team, fouler, f"Loose-ball foul on {fouler.name} fighting for the rebound.")
            maybe_sit_foul_trouble(loose_fouler_team, fouler, period)
            if in_bonus(loose_fouler_team):
                bonus_team = teamB if loose_fouler_team is teamA else teamA
                ft_shooter = max(bonus_team.on_floor, key=lambda p: p.ft_rating)
                print(f"{bonus_team.name} are in the bonus. {ft_shooter.name} will shoot two.")
                next_possession = shoot_free_throws(
                    ft_shooter, bonus_team, 2, period, period_time - possession_time,
                    teamA, teamB, sub_after_first=True, protected=ft_shooter
                )
                return next_possession, possession_time
            dead_ball_subs(teamA, teamB, period, period_time - possession_time)


        print_scoreboard(period, period_time - possession_time, teamA, teamB)
        return dff, possession_time


def find_center_for_jump(team: Team) -> Player:
    for p in team.on_floor:
        if can_play_position(p, "C"):
            return p
    return team.on_floor[0]


def add_minutes_for_possession(teamA: Team, teamB: Team, seconds: int):
    sanitize_live_lineups(teamA, teamB)
    for p in teamA.on_floor:
        p.minutes += seconds
        p.current_stint = getattr(p, "current_stint", 0) + seconds
    for p in teamB.on_floor:
        p.minutes += seconds
        p.current_stint = getattr(p, "current_stint", 0) + seconds
    for p in teamA.bench:
        p.current_stint = max(0, getattr(p, "current_stint", 0) - seconds * 2)
    for p in teamB.bench:
        p.current_stint = max(0, getattr(p, "current_stint", 0) - seconds * 2)
    record_lineup_minutes(teamA, seconds)
    record_lineup_minutes(teamB, seconds)


def maybe_announce_fatigue(teamA: Team, teamB: Team):
    if SIM_FAST_FORWARD:
        return
    if getattr(teamA, "suppress_fatigue_voice", False) or getattr(teamB, "suppress_fatigue_voice", False):
        return
    for team in (teamA, teamB):
        tired = [
            p for p in team.on_floor
            if getattr(p, "current_stint", 0) >= 10 * 60
            and getattr(p, "last_fatigue_notice_stint", 0) + 4 * 60 <= getattr(p, "current_stint", 0)
        ]
        if not tired:
            continue
        player = max(tired, key=lambda p: getattr(p, "current_stint", 0))
        player.last_fatigue_notice_stint = getattr(player, "current_stint", 0)
        print(f"{player.name} is carrying a long stint and starting to look a little heavy-legged.")
        time.sleep(SLEEP * 0.35)


def should_intentionally_foul(possession_team: Team, teamA: Team, teamB: Team,
                              period: int, period_time: int) -> bool:
    if period < 4 or period_time > 40:
        return False

    fouling_team = teamB if possession_team is teamA else teamA
    margin = fouling_team.score - possession_team.score

    # If the game is effectively decided below the shot clock, let it end.
    if period_time < 24 and abs(margin) > 7:
        return False

    # Close game, trailing defense, clock below shot-clock length: foul immediately.
    if period_time <= 26 and -8 <= margin < 0:
        return True

    # Up 3 very late: foul before a three-point attempt sometimes.
    if margin == 3 and period_time <= 10:
        return random.random() < 0.72

    # Only foul when trailing late.
    if margin >= 0:
        return False

    # Down 1-2, usually defend unless the clock is almost gone.
    if margin in (-1, -2):
        return period_time <= 10 and random.random() < 0.38

    # Down 3-6, foul to extend the game.
    if -6 <= margin <= -3:
        urgency = 0.60 if period_time > 24 else 0.88
        return random.random() < urgency

    # Down big, foul only if there is still a tiny chance.
    if -10 <= margin < -6:
        return period_time <= 28 and random.random() < 0.45

    return False


def maybe_late_game_timeout(possession_team: Team, teamA: Team, teamB: Team,
                            period: int, period_time: int) -> bool:
    if not can_advance_after_timeout(period, period_time):
        return False

    trailing = teamA if teamA.score < teamB.score else teamB
    leading = teamB if trailing is teamA else teamA
    if possession_team is not trailing:
        return False

    margin = leading.score - trailing.score
    if margin <= 0 or margin > 10 or trailing.timeouts <= 0:
        return False

    if period_time <= 5:
        use_chance = 0.95
    elif period_time <= 14 and margin <= 3:
        use_chance = 0.82
    elif period_time <= 35:
        use_chance = 0.62 if margin <= 6 else 0.48
    elif margin >= 6:
        use_chance = 0.38
    else:
        use_chance = 0.16

    if trailing.timeouts == 1 and period_time > 35 and margin <= 4:
        use_chance *= 0.45

    if random.random() > use_chance:
        return False

    trailing.timeouts -= 1
    trailing.inbound_pending = True
    trailing.ato_pending = True
    if auto_subs_allowed(teamA):
        force_closing_lineup(teamA)
    if auto_subs_allowed(teamB):
        force_closing_lineup(teamB)
    print(f"{trailing.name} use a late timeout to advance the ball. Timeouts left: {trailing.timeouts}.")
    time.sleep(SLEEP * 0.7)
    return True
def instant_foul_counter_catch_shoot(off, dff, period, period_time, teamA, teamB):
    spent = min(period_time, random.randint(1, 2))
    score_time = max(0, period_time - spent)

    passer = max(off.on_floor, key=lambda p: 0.6 * p.playmaking + 0.4 * p.ball_handle)
    shooters = [p for p in off.on_floor if p is not passer and p.three_rating >= 0.72]
    shooter = max(shooters or off.on_floor, key=lambda p: p.three_rating * p.shot_tendency * (1 + p.clutchness))

    defender = build_defensive_matchups(off, dff).get(shooter, random.choice(dff.on_floor))

    print(f"{dff.name} try to foul up three, but {off.name} counter with a quick catch-and-shoot look.")
    print(f"{passer.name} gets it out before the foul arrives to {shooter.name}.")
    print(f"{shooter.name} catches and fires from three.")

    shooter.fga += 1
    shooter.tpa += 1
    record_shot_diet(off, "three", "late_catch_shoot|contested", shooter, defender)

    make_prob = shot_make_prob(shooter, defender, "three", off, dff, period, period_time) * 1.03

    if random.random() < make_prob:
        shooter.fgm += 1
        shooter.tpm += 1
        shooter.pts += 3
        off.score += 3
        record_shot_make(off, "three", "late_catch_shoot|contested", shooter, defender)
        record_assist(passer, off, 3)
        record_score_event(off, dff, 3, period, score_time, teamA, teamB, check_timeout=False)
        print_scoreboard(period, score_time, teamA, teamB)
        print(f"{shooter.name} knocks it down before the foul can happen.")
        return dff, spent

    print(f"{shooter.name}'s quick three is off.")
    reb_team, rebounder = choose_rebounder(off, dff, "jumper")
    print(f"{rebounder.name} secures the rebound.")
    print_scoreboard(period, score_time, teamA, teamB)
    return reb_team, spent


def intentional_foul_target(possession_team: Team) -> Player:
    """
    Late intentional fouls usually happen as the inbound is received, so target
    the main ball handler the offense wants catching the pass.
    """
    available = [p for p in possession_team.on_floor if not p.fouled_out]
    if not available:
        return choose_ballhandler(possession_team)

    guards = [p for p in available if str(getattr(p, "position", "")).upper() in ("PG", "SG")]
    candidates = guards or available
    return max(
        candidates,
        key=lambda p: (
            0.45 * p.ball_handle
            + 0.35 * p.playmaking
            + 0.15 * p.ft_rating
            + 0.05 * p.usage
        )
    )


def intentional_foul(fouling_team: Team, possession_team: Team,
                     period: int, period_time: int,
                     teamA: Team, teamB: Team) -> Tuple[Team, int]:
    candidates = [p for p in fouling_team.on_floor if not p.fouled_out]
    if not candidates:
        return possession_team, 0



    if (
       period >= 4
       and period_time <= 10
       and fouling_team.score - possession_team.score == 3
       and random.random() < 0.45
    ):
       return instant_foul_counter_catch_shoot(
              possession_team, fouling_team, period, period_time, teamA, teamB
       )
    fouler = min(candidates, key=lambda p: p.pf)
    ballhandler = intentional_foul_target(possession_team)

    spent = random.randint(1, 2)
    register_foul(fouling_team, fouler)

    if fouling_team.score > possession_team.score:
        print(f"{fouling_team.name} foul up three before the shot. {fouler.name} wraps up {ballhandler.name}.")
    else:
        print(f"{fouling_team.name} foul intentionally to extend the game. {fouler.name} grabs {ballhandler.name}.")
    time.sleep(SLEEP * 0.6)

    if fouler.pf >= 6:
        foul_out_sub(fouling_team, fouler)
    else:
        maybe_sit_foul_trouble(fouling_team, fouler, period)

    next_possession = shoot_free_throws(
        ballhandler, possession_team, 2,
        period, max(0, period_time - spent),
        teamA, teamB,
        sub_after_first=True, protected=ballhandler
    )

    return next_possession, spent


def print_game_recap(teamA: Team, teamB: Team):
    all_players = teamA.roster + teamB.roster
    player_of_game = max(
        all_players,
        key=lambda p: p.pts + 1.2 * p.reb + 1.5 * p.ast + 3 * p.stl + 3 * p.blk_stat - 2 * p.tov
    )
    top_scorers = sorted(all_players, key=lambda p: p.pts, reverse=True)[:3]
    best_run_team = teamA if getattr(teamA, "biggest_run", 0) >= getattr(teamB, "biggest_run", 0) else teamB
    turning_points = [getattr(t, "last_turning_point", None) for t in (teamA, teamB) if getattr(t, "last_turning_point", None)]

    print("\nGAME RECAP")
    print("-" * 90)
    print(f"Player of the game: {player_of_game.name} - {player_of_game.pts} PTS, {player_of_game.reb} REB, {player_of_game.ast} AST, +/- {player_of_game.plus_minus:+d}.")
    print("Top scorers: " + ", ".join(f"{p.name} {p.pts}" for p in top_scorers) + ".")
    print(f"Biggest run: {best_run_team.name} with a {getattr(best_run_team, 'biggest_run', 0)}-0 burst.")
    if turning_points:
        print(f"Turning point: {turning_points[-1]}")
    print(
        f"Team extras: {teamA.name} paint {teamA.points_paint}, fastbreak {teamA.fastbreak_pts}, second chance {teamA.second_chance_pts}; "
        f"{teamB.name} paint {teamB.points_paint}, fastbreak {teamB.fastbreak_pts}, second chance {teamB.second_chance_pts}."
    )
    print("-" * 90)



def simulate_1v1_game(player_a: Player, player_b: Player, target_score: int = 11, win_by: int = 2) -> Tuple[Team, Team]:
    """
    Street-ball 1-on-1: no passing (there's no one to pass to), no free
    throws, make-it-take-it, and a defensive stop or turnover checks the
    ball back up top instead of a formal inbound. Reuses the same
    isolation/shot-creation/rebounding logic and voice lines as the main
    5-on-5 game so it feels consistent, just stripped down to a single
    matchup. Each player is wrapped in his own one-man "team" so the normal
    box score machinery (print_box_score, etc.) displays this exactly like
    any other game -- one player as one team, the other as the other.
    """
    team_a = Team(player_a.name, [player_a])
    team_b = Team(player_b.name, [player_b])
    team_a.init_lineup()
    team_b.init_lineup()
