def fantasy_team_label(team_name: str) -> str:
    parts = team_name.split()
    if not parts:
        return team_name
    year = parts[0] if parts[0].isdigit() else ""
    city_code = {
        "Atlanta": "ATL", "Boston": "BOS", "Brooklyn": "BKN", "Charlotte": "CHA",
        "Chicago": "CHI", "Cleveland": "CLE", "Dallas": "DAL", "Denver": "DEN",
        "Detroit": "DET", "Golden": "GSW", "Houston": "HOU", "Indiana": "IND",
        "Los": "LAL" if "Lakers" in team_name else "LAC", "Memphis": "MEM",
        "Miami": "MIA", "Milwaukee": "MIL", "Minnesota": "MIN", "New": "NYK" if "Knicks" in team_name else "NOP",
        "Oklahoma": "OKC", "Orlando": "ORL", "Philadelphia": "PHI", "Phoenix": "PHX",
        "Portland": "POR", "Sacramento": "SAC", "San": "SAS", "Toronto": "TOR",
        "Utah": "UTA", "Washington": "WAS",
    }.get(parts[1] if year and len(parts) > 1 else parts[0], parts[-1][:3].upper())
    return f"{year} {city_code}".strip()


def fantasy_player_clone(player: Player, team_name: str) -> Player:
    import copy

    clone = copy.deepcopy(player)
    clone.source_team = team_name
    clone.fantasy_base_name = player.name

    clone.pts = clone.reb = clone.ast = clone.stl = clone.blk_stat = clone.tov = 0
    clone.assist_pts_created = 0
    clone.pf = clone.fgm = clone.fga = clone.tpm = clone.tpa = clone.ftm = clone.fta = 0
    clone.minutes = 0
    clone.fouled_out = False
    clone.plus_minus = 0
    clone.oreb_stat = 0
    clone.dreb_stat = 0
    clone.fouls_drawn = 0
    clone.double_teams_faced = 0
    clone.is_starter = False
    clone.shot_diet = {}
    clone.quarter_shot_diet = {}
    clone.defended_diet = {}
    clone.quarter_stats = {}
    clone.foul_rest_until = 0
    clone.jumper_make_streak = 0
    clone.just_caught_fire = False
    clone.fourth_fga = 0
    clone.limitless_range_attempt = False
    clone.heat_check_attempt = False
    return clone


def fantasy_block_rating(player: Player) -> float:
    return max(0.0, min(100.0, player.block * 100.0))


def fantasy_ovr(player: Player) -> int:
    tpt = player.three_rating * 100
    mpt = player.mid_rating * 100
    lpt = player.rim_rating * 100
    pdef = player.perimeter_def * 100
    idef = player.interior_def * 100
    cpt = player.clutchness * 100
    pl = player.playmaking * 100
    dk = player.dunk_rating * 100
    bl = fantasy_block_rating(player)
    stl = player.steal * 100

    handle = player.ball_handle * 100
    speed = player.speed * 100
    rebound = (0.45 * player.oreb + 0.55 * player.dreb) * 100

    if player.position == "C":
        raw = (
            0.24 * lpt + 0.17 * idef + 0.14 * dk + 0.11 * bl +
            0.11 * rebound + 0.08 * cpt + 0.08 * mpt + 0.05 * pl +
            0.02 * tpt
        )
        if lpt >= 95 and dk >= 95:
            raw += 7
        elif lpt >= 92 and dk >= 88:
            raw += 4
        if idef >= 88 and bl >= 45:
            raw += 3.5
        elif idef >= 82 and bl >= 35:
            raw += 2.5
        if idef < 58:
            raw -= 3
        elif idef < 68:
            raw -= 1.5
        if pl >= 90 and mpt >= 90 and lpt >= 90:
            raw += 13
        elif pl >= 78 and (mpt >= 84 or tpt >= 80):
            raw += 7
        if "post_hub" in getattr(player, "badges", ()):
            raw += 4
    elif player.position == "SG":
        raw = (
            0.18 * tpt + 0.18 * mpt + 0.18 * lpt + 0.13 * pdef +
            0.12 * handle + 0.08 * cpt + 0.05 * dk + 0.05 * pl +
            0.03 * speed
        )
        scoring_peak = max(tpt, mpt, lpt)
        scoring_average = (tpt + mpt + lpt) / 3
        if scoring_peak >= 94 and cpt >= 88:
            raw += 3
        elif scoring_peak >= 90:
            raw += 1
        if pdef >= 82 and lpt >= 90 and mpt >= 90:
            raw += 2
        elif pdef >= 75 and scoring_peak >= 90:
            raw += 1
        if scoring_average >= 92 and pdef >= 82 and cpt >= 86:
            raw += 2
        elif scoring_average >= 88 and pdef >= 76:
            raw += 1
        if scoring_average >= 88 and handle >= 88 and pl >= 82:
            raw += 5
        elif scoring_average >= 86 and handle >= 84 and pl >= 74:
            raw += 2
        if scoring_average >= 88 and handle >= 88 and pl >= 90:
            raw += 2
        if scoring_average >= 89 and tpt >= 88 and pl >= 84:
            raw += 2
    elif can_play_position(player, "SF") or can_play_position(player, "PF"):
        raw = (
            0.14 * tpt + 0.14 * mpt + 0.14 * lpt + 0.12 * pdef +
            0.11 * idef + 0.08 * dk + 0.09 * rebound + 0.07 * pl +
            0.06 * cpt + 0.04 * handle + 0.01 * bl
        )
        scoring_peak = max(tpt, mpt, lpt)
        scoring_average = (tpt + mpt + lpt) / 3
        paint_creation_average = (mpt + lpt) / 2
        if pdef >= 80 and idef >= 70:
            raw += 2
        if scoring_peak >= 88:
            raw += 2
        elif scoring_peak >= 84:
            raw += 1
        if can_play_position(player, "PF") and lpt >= 88 and dk >= 84 and idef >= 78:
            raw += 2
        elif can_play_position(player, "PF") and lpt >= 84 and idef >= 74:
            raw += 1
        if can_play_position(player, "PF") and lpt >= 88 and rebound >= 74:
            raw += 1
        elif can_play_position(player, "PF") and lpt >= 86 and idef >= 78:
            raw += 1
        if can_play_position(player, "PF") and idef >= 84 and bl >= 35:
            raw += 2
        if can_play_position(player, "PF") and tpt < 78:
            interior_pf_score = (
                0.34 * lpt
                + 0.23 * dk
                + 0.19 * idef
                + 0.11 * rebound
                + 0.08 * bl
                + 0.05 * cpt
            )
            if interior_pf_score >= 88:
                raw += 3
            elif interior_pf_score >= 84:
                raw += 1.5
            elif interior_pf_score >= 80:
                raw += 0.75
            traditional_pf_score = (
                0.27 * lpt
                + 0.20 * idef
                + 0.17 * rebound
                + 0.13 * dk
                + 0.08 * mpt
                + 0.07 * pdef
                + 0.04 * bl
                + 0.04 * cpt
            )
            if lpt >= 90 and idef >= 90 and rebound >= 88:
                traditional_pf_score += 4
            elif lpt >= 88 and (idef >= 88 or rebound >= 88):
                traditional_pf_score += 2
            raw = max(raw, traditional_pf_score)
        if can_play_position(player, "PF") and tpt >= 84 and mpt >= 82:
            stretch_pf_score = (
                0.34 * tpt
                + 0.22 * mpt
                + 0.14 * lpt
                + 0.10 * pdef
                + 0.07 * pl
                + 0.06 * cpt
                + 0.04 * handle
                + 0.03 * dk
            )
            if tpt >= 90 and mpt >= 86:
                stretch_pf_score += 3
            elif tpt >= 86:
                stretch_pf_score += 1.5
            raw = max(raw, stretch_pf_score)
        if scoring_average >= 94 and mpt >= 94:
            raw += 5
        elif scoring_average >= 90 and mpt >= 90 and (tpt >= 84 or lpt >= 90):
            raw += 4
        elif scoring_average >= 84:
            raw += 3
        elif paint_creation_average >= 84:
            raw += 2
        if cpt >= 80 and scoring_peak >= 84:
            raw += 1
    else:
        raw = (
            0.30 * tpt + 0.14 * mpt + 0.12 * lpt + 0.18 * pl +
            0.11 * handle + 0.06 * pdef + 0.06 * cpt + 0.03 * speed
        )
        if player.position == "PG":
            if tpt >= 99:
                raw += 4
            elif tpt >= 97:
                raw += 2.5
            elif tpt >= 94:
                raw += 1.25

        if tpt >= 98 and handle >= 92 and mpt >= 90:
            raw += 4
        elif tpt >= 97 and handle >= 90 and cpt >= 85:
            raw += 1.5
        elif tpt >= 94 and handle >= 84 and (pl >= 72 or cpt >= 82):
            raw += 0.75

        creator_guard_average = (tpt + mpt + lpt + pl + handle + cpt) / 6
        if creator_guard_average >= 94:
            raw += 1
        elif creator_guard_average >= 91:
            raw += 0.5
        elif creator_guard_average >= 88:
            raw += 0.25

        creator_scoring_peak = max(tpt, mpt, lpt)
        if player.position == "PG" and pl >= 90 and tpt < 88:
            floor_general_score = (
                0.29 * pl + 0.15 * lpt + 0.14 * mpt + 0.13 * handle +
                0.08 * tpt + 0.08 * speed + 0.07 * pdef + 0.06 * cpt
            )
            if pl >= 96:
                floor_general_score += 3
            elif pl >= 92:
                floor_general_score += 1.5
            if lpt >= 88 and speed >= 84:
                floor_general_score += 1.5
            if tpt < 70:
                floor_general_score -= (70 - tpt) * 0.10
            if mpt < 82:
                floor_general_score -= (82 - mpt) * 0.04
            if tpt < 60 and mpt < 82:
                floor_general_score -= 1.5
            raw = max(raw, floor_general_score)
        # Two-way scorer: a guard who scores at a high level and defends
        # at a high level shouldn't be dragged down just because his
        # playmaking number is modest. This can only replace the score
        # when it comes out higher, so it never lowers anyone.
        guard_scoring_average = (tpt + mpt + lpt) / 3
        if player.position == "PG" and pl < 86 and pdef >= 80 and guard_scoring_average >= 88:
            two_way_score = (
                0.22 * tpt + 0.17 * mpt + 0.15 * lpt + 0.15 * pdef +
                0.11 * handle + 0.08 * cpt + 0.07 * pl + 0.05 * speed
            )
            if pdef >= 86 and creator_scoring_peak >= 97 and cpt >= 88:
                two_way_score += 3
            raw = max(raw, two_way_score)
        if pl >= 96 and handle >= 88:
            raw += 1.5
        elif pl >= 90 and handle >= 86:
            raw += 1
        if pl >= 94 and handle >= 92 and creator_scoring_peak >= 94:
            raw += 0.5
        if pl >= 88 and handle >= 88 and creator_scoring_peak >= 92:
            raw += 1.5
        elif pl >= 82 and handle >= 86 and creator_scoring_peak >= 90:
            raw += 0.5

    if player.position == "C" and raw > 93:
        raw = 93 + (raw - 93) * 0.38
    elif player.position == "PG" and raw > 93:
        raw = 93 + (raw - 93) * 0.68
    elif (can_play_position(player, "SF") or can_play_position(player, "PF")) and raw > 93:
        raw = 93 + (raw - 93) * 0.55

    ovr = round(raw)
    return max(40, min(99, int(ovr)))



def split_gui_series_sections(text: str) -> Dict[str, str]:
    markers = [
        ("game_box_scores", "SERIES GAME BOX SCORES"),
        ("series_averages", "SERIES AVERAGES"),
        ("fourth_quarter", "SERIES 4TH QUARTER PLAYER AVERAGES"),
        ("advanced", "SERIES ADVANCED STATS"),
        ("shot_defense", "SERIES SHOT DIET BOX SCORE"),
    ]
    positions = []
    for key, marker in markers:
        idx = text.find(marker)
        if idx >= 0:
            positions.append((idx, key, marker))
    positions.sort()
    result = {key: "" for key, _marker in markers}
    result["shot_defense"] = ""
    for i, (idx, key, _marker) in enumerate(positions):
        end = positions[i + 1][0] if i + 1 < len(positions) else len(text)
        result[key] = text[idx:end].strip()
    return result



def print_fantasy_pool_for_position(pos_code: str,
                                    pool: List[Tuple[Player, str]],
                                    taken_names: set,
                                    page: int = 0,
                                    page_size: int = 30):
    """
    Pretty-print available players at a position with ranking numbers.
    The full draft board stays available, but the screen only shows 30 at once.
    """
    available_pool = [
        (p, desc)
        for p, desc in pool
        if getattr(p, "fantasy_base_name", p.name) not in taken_names
    ]
    if not available_pool:
        print(f"\nNo available {pos_code}s left.")
        return

    start = page * page_size
    if start >= len(available_pool):
        page = 0
        start = 0
    end = min(start + page_size, len(available_pool))
    max_page = max(0, (len(available_pool) - 1) // page_size)
    print(f"\nAvailable {pos_code}s ({start + 1}-{end} of {len(available_pool)}):")
    for idx, (p, desc) in enumerate(available_pool[start:end], start=start + 1):
        print(f"  {idx}. {p.name}")
        print(f"     -> {desc}")
    if max_page > 0:
        print("Type N for next page, P for previous page, B to go back, or type a player name to search.")


def available_fantasy_pool(pool: List[Tuple[Player, str]], taken_names: set) -> List[Tuple[Player, str]]:
    return [
        (p, desc)
        for p, desc in pool
        if getattr(p, "fantasy_base_name", p.name) not in taken_names
    ]


def available_all_fantasy_players(pools: Dict[str, List[Tuple[Player, str]]],
                                  taken_names: set) -> List[Tuple[Player, str]]:
    players = []
    seen = set()
    for pool in pools.values():
        for player, desc in pool:
            key = getattr(player, "fantasy_base_name", player.name)
            if key in seen or key in taken_names:
                continue
            seen.add(key)
            players.append((player, desc))
    players.sort(key=lambda item: fantasy_ovr(item[0]), reverse=True)
    return players


def print_fantasy_full_pool(pools: Dict[str, List[Tuple[Player, str]]],
                            taken_names: set,
                            page: int = 0,
                            page_size: int = 30):
    available = available_all_fantasy_players(pools, taken_names)
    if not available:
        print("\nNo available players left.")
        return

    start = page * page_size
    if start >= len(available):
        page = 0
        start = 0
    end = min(start + page_size, len(available))
    max_page = max(0, (len(available) - 1) // page_size)

    print(f"\nAll available players ({start + 1}-{end} of {len(available)}):")
    print(fantasy_stat_header(prefix_width=5))
    for idx, (player, _) in enumerate(available[start:end], start=start + 1):
        print(f"  {idx:>2}. {fantasy_stat_line(player)}  {player.name}")
    if max_page > 0:
        print("Type N for next page, P for previous page, B to go back, or type a player name to search.")


def browse_full_fantasy_pool(pools: Dict[str, List[Tuple[Player, str]]],
                             taken_names: set) -> Player:
    page = 0
    while True:
        visible_pool = available_all_fantasy_players(pools, taken_names)
        print_fantasy_full_pool(pools, taken_names, page=page)
        raw = input("Enter ranking number, N/P, B, or player name: ").strip()
        if raw.lower() == "b":
            return None
        if raw.lower() == "n":
            if (page + 1) * 30 < len(visible_pool):
                page += 1
            else:
                print("Already on the last page.")
            continue
        if raw.lower() == "p":
            page = max(0, page - 1)
            continue

        searched = find_fantasy_candidate_by_name(pools, raw, taken_names)
        if searched:
            chosen_version = choose_fantasy_player_version(searched)
            if chosen_version is not None:
                return chosen_version
            continue

        try:
            rank_choice = int(raw)
        except ValueError:
            print(f"Invalid input. Please enter a number 1-{len(visible_pool)}, N/P, B, or a player name.")
            continue
        if not (1 <= rank_choice <= len(visible_pool)):
            print(f"Ranking must be between 1 and {len(visible_pool)}.")
            continue

        candidate, _ = visible_pool[rank_choice - 1]
        chosen_version = choose_fantasy_player_version(candidate)
        if chosen_version is not None:
            return chosen_version


def build_best_lineup_by_overall(team: Team):
    """
    Build starting lineup purely by overall rating:
      - Starters = top 5 players by overall_rating.
      - Bench = everyone else.
    """
    sorted_players = sorted(team.roster, key=overall_rating, reverse=True)
    team.on_floor = sorted_players[:5]
    team.bench = identity_excluding(sorted_players, team.on_floor)
    balance_lineup_positions(team)


FANTASY_TEAM_COL_WIDTH = 30


def fantasy_stat_line(player: Player) -> str:
    return (
        f"{player.source_team:<{FANTASY_TEAM_COL_WIDTH}} {player.position:<3} "
        f"{fantasy_ovr(player):>3} "
        f"{round(player.playmaking * 100):>4} "
        f"{round(player.three_rating * 100):>4} "
        f"{round(player.mid_rating * 100):>4} "
        f"{round(player.rim_rating * 100):>4} "
        f"{round(player.perimeter_def * 100):>5} "
        f"{round(player.interior_def * 100):>5} "
        f"{round(player.steal * 100):>4} "
        f"{round(player.block * 100):>4} "
        f"{plan_label(getattr(player, 'archetype', 'balanced')):<18}"
    )


def fantasy_stat_header(prefix_width: int = 4) -> str:
    return (
        f"{'':<{prefix_width}}{'TEAM':<{FANTASY_TEAM_COL_WIDTH}} {'POS':<3} "
        f"{'OVR':>3} {'PLAY':>4} {'3PT':>4} {'MID':>4} {'RIM':>4} "
        f"{'PDEF':>5} {'IDEF':>5} {'STL':>4} {'BLK':>4} {'ARCHETYPE':<18}"
    )


def height_label(height_inches: int) -> str:
    try:
        inches = int(height_inches)
    except (TypeError, ValueError):
        inches = 0
    if inches <= 0:
        return "-"
    return f"{inches // 12}'{inches % 12}\""


def fantasy_player_preview_text(player: Player | None) -> str:
    if player is None:
        return "Select a player to view ratings."
    source = getattr(player, "source_team", "All-Time")
    badges = format_player_badges(player)
    secondary = ", ".join(getattr(player, "secondary_positions", ()) or default_secondary_positions(getattr(player, "position", "SF"))) or "-"
    go_to = go_to_shot_label(getattr(player, "go_to_shot", "") or default_player_go_to_shot(player))
    return (
        f"{player.name} | {source} | {player.position} | Secondary {secondary} | OVR {fantasy_ovr(player)} | {height_label(getattr(player, 'height', 0))}\n"
        f"Go-to shot: {go_to}\n"
        f"Ratings: 3PT {_rating_to_int(player.three_rating)} | MID {_rating_to_int(player.mid_rating)} | RIM {_rating_to_int(player.rim_rating)} | "
        f"DUNK {_rating_to_int(player.dunk_rating)} | FT {_rating_to_int(player.ft_rating)} | IQ {_rating_to_int(player.shot_iq)}\n"
        f"Role: USG {_rating_to_int(player.usage)} | SHOT {_rating_to_int(player.shot_tendency)} | ISO {_rating_to_int(player.iso_tendency)} | "
        f"PLAY {_rating_to_int(player.playmaking)} | HANDLE {_rating_to_int(player.ball_handle)} | SPEED {_rating_to_int(player.speed)}\n"
        f"Defense/Reb: PDEF {_rating_to_int(player.perimeter_def)} | IDEF {_rating_to_int(player.interior_def)} | STL {_rating_to_int(player.steal)} | "
        f"BLK {_rating_to_int(player.block)} | OREB {_rating_to_int(player.oreb)} | DREB {_rating_to_int(player.dreb)}\n"
        f"Badges: {badges or 'None'}"
    )


def confirm_fantasy_pick(player: Player) -> bool:
    print(f"\nSelected: {player.name}")
    print(fantasy_stat_header(prefix_width=2))
    print(f"  {fantasy_stat_line(player)}")
    while True:
        raw = input("Draft this player? Enter Y, N, or B to go back: ").strip().lower()
        if raw in ("y", "yes"):
            return True
        if raw in ("n", "no", "b"):
            return False
        print("Invalid input. Enter Y, N, or B.")


def choose_fantasy_player_version(candidate: Player) -> Player:
    versions = list(getattr(candidate, "fantasy_versions", [candidate]))
    if len(versions) <= 1:
        return candidate if confirm_fantasy_pick(candidate) else None

    print(f"\nChoose which version of {candidate.name} you want:")
    print(fantasy_stat_header(prefix_width=5))
    for idx, version in enumerate(versions, start=1):
        print(
            f"  {idx:>2}. {fantasy_stat_line(version)}"
        )

    while True:
        raw = input(f"Enter version number (1-{len(versions)}) or B to go back: ").strip()
        if raw.lower() == "b":
            return None
        try:
            choice = int(raw)
        except ValueError:
            print(f"Invalid input. Please enter a number 1-{len(versions)} or B.")
            continue
        if 1 <= choice <= len(versions):
            selected = versions[choice - 1]
            return selected if confirm_fantasy_pick(selected) else None
        print(f"Version must be between 1 and {len(versions)}.")


def find_fantasy_candidate_by_name(pools: Dict[str, List[Tuple[Player, str]]],
                                   query: str,
                                   taken_names: set) -> Player:
    needle = query.strip().lower()
    if not needle:
        return None

    exact_matches = []
    partial_matches = []
    seen = set()
    for pool in pools.values():
        for candidate, _ in pool:
            key = getattr(candidate, "fantasy_base_name", candidate.name)
            if key in seen or key in taken_names:
                continue
            seen.add(key)
            name = candidate.name.lower()
            if name == needle:
                exact_matches.append(candidate)
            elif needle in name:
                partial_matches.append(candidate)

    matches = exact_matches or partial_matches
    if not matches:
        return None

    matches.sort(key=fantasy_ovr, reverse=True)
    if len(matches) == 1:
        return matches[0]

    print("\nName search matches:")
    print(fantasy_stat_header(prefix_width=5))
    for idx, candidate in enumerate(matches[:20], start=1):
        print(f"  {idx:>2}. {fantasy_stat_line(candidate)}  {candidate.name}")

    while True:
        raw = input(f"Choose match number (1-{min(20, len(matches))}) or B to go back: ").strip()
        if raw.lower() == "b":
            return None
        try:
            choice = int(raw)
        except ValueError:
            print("Invalid input.")
            continue
        if 1 <= choice <= min(20, len(matches)):
            return matches[choice - 1]
        print("That match number is not available.")


def user_pick_from_pool(pools: Dict[str, List[Tuple[Player, str]]],
                        taken_names: set) -> Player:
    """
    Let the user choose a position (by number) and then a player ranking
    at that position. Ensures the player isn't already taken.
    """
    if GUI_FANTASY_PICKER is not None:
        picked = GUI_FANTASY_PICKER(pools, taken_names)
        while picked is None:
            print("Draft pick is required. Reopening the fantasy draft board.")
            picked = GUI_FANTASY_PICKER(pools, taken_names)
        if picked is not None:
            print(f"You drafted {picked.name} ({picked.position}) from {picked.source_team}.")
            return picked

    pos_order = ["PG", "SG", "SF", "PF", "C"]
    while True:
        print("\nChoose a position to draft:")
        for i, pos in enumerate(pos_order, start=1):
            print(f"  {i}. {pos}")
        print("  6. All players")
        print("Or type a player name to search the full board.")
        raw_position = input("Enter position number (1-6), ALL, or player name: ").strip()
        if raw_position.lower() in ("6", "all", "a"):
            chosen_version = browse_full_fantasy_pool(pools, taken_names)
            if chosen_version is None:
                continue
            print(f"You drafted {chosen_version.name} ({chosen_version.position}) from {chosen_version.source_team}.")
            return chosen_version
        searched = find_fantasy_candidate_by_name(pools, raw_position, taken_names)
        if searched:
            chosen_version = choose_fantasy_player_version(searched)
            if chosen_version is None:
                continue
            print(f"You drafted {chosen_version.name} ({chosen_version.position}) from {chosen_version.source_team}.")
            return chosen_version
        try:
            pos_choice = int(raw_position)
        except ValueError:
            print("No available player matched that name. Enter a number 1-6, ALL, or try another name.")
            continue
        if not (1 <= pos_choice <= 5):
            print("Position must be between 1 and 5, or choose 6 for all players.")
            continue

        pos_code = pos_order[pos_choice-1]
        pool = pools[pos_code]
        if not available_fantasy_pool(pool, taken_names):
            print(f"No available {pos_code}s left. Pick another position.")
            continue

        page = 0
        while True:
            visible_pool = available_fantasy_pool(pool, taken_names)
            print_fantasy_pool_for_position(pos_code, pool, taken_names, page=page)

            rank_input = input(f"Enter ranking number, N/P, B, or player name: ").strip()
            if rank_input.lower() == "b":
                break
            if rank_input.lower() == "n":
                if (page + 1) * 30 < len(visible_pool):
                    page += 1
                else:
                    print("Already on the last page.")
                continue
            if rank_input.lower() == "p":
                page = max(0, page - 1)
                continue
            if rank_input.lower() in ("all", "a"):
                chosen_version = browse_full_fantasy_pool(pools, taken_names)
                if chosen_version is None:
                    continue
                print(f"You drafted {chosen_version.name} ({chosen_version.position}) from {chosen_version.source_team}.")
                return chosen_version

            searched = find_fantasy_candidate_by_name(pools, rank_input, taken_names)
            if searched:
                chosen_version = choose_fantasy_player_version(searched)
                if chosen_version is None:
                    continue
                print(f"You drafted {chosen_version.name} ({chosen_version.position}) from {chosen_version.source_team}.")
                return chosen_version

            try:
                rank_choice = int(rank_input)
            except ValueError:
                print(f"Invalid input. Please enter a number 1-{len(visible_pool)}, N/P, B, or a player name.")
                continue
            if not (1 <= rank_choice <= len(visible_pool)):
                print(f"Ranking must be between 1 and {len(visible_pool)}.")
                continue

            candidate, _ = visible_pool[rank_choice - 1]

            chosen_version = choose_fantasy_player_version(candidate)
            if chosen_version is None:
                continue

            print(f"You drafted {chosen_version.name} ({pos_code}) from {chosen_version.source_team}.")
            return chosen_version

