def fantasy_roster_counts(players: List[Player]) -> Dict[str, int]:
    counts = {pos: 0 for pos in ("PG", "SG", "SF", "PF", "C")}
    for p in players:
        if p.position in counts:
            counts[p.position] += 1
    return counts


def fantasy_team_need_score(candidate: Player, ai_players: List[Player]) -> float:
    counts = fantasy_roster_counts(ai_players)
    pick_num = len(ai_players)
    score = 0.0

    if pick_num < 5:
        if counts.get(candidate.position, 0) == 0:
            score += 18
        elif candidate.position in ("SG", "SF") and counts.get("SG", 0) + counts.get("SF", 0) < 2:
            score += 8
        elif candidate.position in ("PF", "C") and counts.get("PF", 0) + counts.get("C", 0) < 2:
            score += 8
    else:
        min_depth = min(counts.values())
        if counts.get(candidate.position, 0) == min_depth:
            score += 7

    has_primary_scorer = any(p.usage >= 0.30 or fantasy_ovr(p) >= 94 for p in ai_players)
    has_creator = any(p.playmaking >= 0.78 or p.ball_handle >= 0.84 for p in ai_players)
    has_spacing = sum(1 for p in ai_players if p.three_rating >= 0.84 and p.three_tendency >= 0.28)
    has_rim_protector = any(p.interior_def >= 0.84 or p.block >= 0.62 for p in ai_players)

    if not has_primary_scorer and (candidate.usage >= 0.28 or fantasy_ovr(candidate) >= 92):
        score += 16
    if not has_creator and (candidate.playmaking >= 0.78 or candidate.ball_handle >= 0.84):
        score += 10
    if has_spacing < 2 and candidate.three_rating >= 0.84 and candidate.three_tendency >= 0.28:
        score += 9
    if not has_rim_protector and (candidate.interior_def >= 0.82 or candidate.block >= 0.60):
        score += 10

    return score


def fantasy_counter_user_score(candidate: Player, user_players: List[Player]) -> float:
    if not user_players:
        return 0.0

    user_elite_shooting = any(p.three_rating >= 0.90 and p.three_tendency >= 0.35 for p in user_players)
    user_iso_guards = any((p.ball_handle >= 0.88 or p.iso_tendency >= 0.50) and p.usage >= 0.25 for p in user_players)
    user_paint_force = any((p.rim_rating >= 0.92 or p.dunk_rating >= 0.92) and (p.usage >= 0.24 or can_play_position(p, "C")) for p in user_players)
    user_big_hub = any(can_play_position(p, "C") and p.playmaking >= 0.78 for p in user_players)
    user_size = sum(1 for p in user_players if p.height >= 80)

    score = 0.0
    if user_elite_shooting:
        score += candidate.perimeter_def * 8
        if candidate.height >= 78 and candidate.speed >= 0.72:
            score += 4
    if user_iso_guards:
        score += candidate.perimeter_def * 9 + candidate.steal * 10
    if user_paint_force:
        score += candidate.interior_def * 10 + fantasy_block_rating(candidate) * 0.10
        if can_play_position(candidate, "C") or can_play_position(candidate, "PF"):
            score += 5
    if user_big_hub:
        score += candidate.interior_def * 5 + candidate.steal * 6
        if candidate.three_rating >= 0.82 and can_play_position(candidate, "C"):
            score += 3
    if user_size >= 3:
        score += (candidate.oreb + candidate.dreb) * 16 + candidate.interior_def * 4

    user_best_ovr = max(fantasy_ovr(p) for p in user_players)
    if user_best_ovr >= 96 and fantasy_ovr(candidate) >= 92:
        score += 6

    return score


def fantasy_ai_candidate_score(candidate: Player, ai_players: List[Player], user_players: List[Player]) -> float:
    ovr = fantasy_ovr(candidate)
    score = ovr * 1.45
    draft_priority = {
        "Michael Jordan": 28,
        "LeBron James": 18,
        "Shaquille O'Neal": 12,
        "Kareem Abdul-Jabbar": 10,
        "Stephen Curry": 9,
        "Nikola Jokic": 8,
        "Kevin Durant": 8,
    }
    score += draft_priority.get(candidate.name, 0)
    score += fantasy_team_need_score(candidate, ai_players)
    score += fantasy_counter_user_score(candidate, user_players) * 0.55
    score += candidate.clutchness * 4
    if ovr >= 98:
        score += 22
    elif ovr >= 96:
        score += 14
    elif ovr >= 94:
        score += 8
    if candidate.usage >= 0.32 and candidate.shot_tendency >= 0.45:
        score += 5
    if ovr >= 97 and candidate.usage >= 0.30 and candidate.perimeter_def >= 0.78:
        score += 14
    elif ovr >= 96 and candidate.usage >= 0.28 and candidate.perimeter_def >= 0.74:
        score += 8
    if badge_tier(candidate, "clutch") >= 4 or badge_tier(candidate, "closer") >= 4:
        score += 4
    if candidate.usage >= 0.30 and len(ai_players) < 3:
        score += 5
    return score


def fantasy_ai_pick_reason(player: Player, ai_players: List[Player], user_players: List[Player]) -> str:
    if fantasy_team_need_score(player, ai_players) >= fantasy_counter_user_score(player, user_players) + 5:
        if player.usage >= 0.28 or fantasy_ovr(player) >= 92:
            return "to secure a primary star"
        if player.three_rating >= 0.84 and player.three_tendency >= 0.28:
            return "to improve spacing"
        if player.interior_def >= 0.82 or player.block >= 0.60:
            return "to add rim protection"
        return "to balance the roster"

    if fantasy_counter_user_score(player, user_players) > 0:
        user_paint_force = any((p.rim_rating >= 0.92 or p.dunk_rating >= 0.92) and (p.usage >= 0.24 or can_play_position(p, "C")) for p in user_players)
        if user_paint_force and (player.interior_def >= 0.82 or player.block >= 0.60):
            return "to counter your paint pressure"
        if player.perimeter_def >= 0.78:
            return "to counter your perimeter creators"
        if player.interior_def >= 0.82 or player.block >= 0.60:
            return "to counter your paint pressure"
        if player.three_rating >= 0.84:
            return "to punish help defense with shooting"

    if player.usage >= 0.30 or fantasy_ovr(player) >= 94:
        return "for star power"
    return "as the best fit available"


def ai_pick_from_pool(pools: Dict[str, List[Tuple[Player, str]]],
                      taken_names: set,
                      ai_current_players: List[Player],
                      user_players: List[Player]) -> Player:
    """
    Smarter AI:
      - Tracks its own roster by position.
      - For first 5 AI picks: tries to fill one of each position (PG, SG, SF, PF, C).
      - For bench picks: favors positions where it has the least depth.
    """
    pos_order = ["PG", "SG", "SF", "PF", "C"]

    counts = fantasy_roster_counts(ai_current_players)

    ai_picks_so_far = len(ai_current_players)

    # Decide which positions we want to target this pick
    if ai_picks_so_far < 5:
        # Still building starting 5: prioritize missing positions
        target_positions = [pos for pos in pos_order if counts[pos] == 0]
        if not target_positions:
            target_positions = pos_order[:]  # fallback to any
    else:
        # Bench picks: target positions with least depth
        min_count = min(counts.values())
        target_positions = [pos for pos in pos_order if counts[pos] == min_count]

    best_player = None
    best_score = -1.0

    for pos, pool in pools.items():
        for p, _ in pool:
            if getattr(p, "fantasy_base_name", p.name) in taken_names:
                continue
            score = fantasy_ai_candidate_score(p, ai_current_players, user_players)
            if pos in target_positions:
                score += 6
            elif ai_picks_so_far < 5 and fantasy_ovr(p) < 96:
                score -= 4
            if score > best_score:
                best_score = score
                best_player = p

    reason = fantasy_ai_pick_reason(best_player, ai_current_players, user_players)
    print(f"AI drafted {best_player.name} ({best_player.position}) {reason}.")
    return best_player
def build_best_lineup_by_position(team: Team):
    """
    Build starting lineup by positions:
      - Try to get one PG, SG, SF, PF, C.
      - If a position is missing, fill with next-best player overall.
    Bench = everyone else.
    """
    desired_order = ["PG", "SG", "SF", "PF", "C"]
    starters: List[Player] = []
    used = set()

    # First pass: best player at each position
    for pos in desired_order:
        candidates = [p for p in team.roster if can_play_position(p, pos) and not p.fouled_out]
        if candidates:
            best = max(candidates, key=overall_rating)
            if best not in used:
                starters.append(best)
                used.add(best)

    # If we still don't have 5, fill with best remaining players
    if len(starters) < 5:
        leftovers = [p for p in team.roster if p not in used and not p.fouled_out]
        leftovers_sorted = sorted(leftovers, key=overall_rating, reverse=True)
        for p in leftovers_sorted:
            if len(starters) >= 5:
                break
            starters.append(p)
            used.add(p)

    # Final assignment
    team.on_floor = starters[:5]
    team.bench = [p for p in team.roster if p not in team.on_floor]
    balance_lineup_positions(team)


def make_fantasy_team_factory(team_name: str, drafted_players: List[Player], user_controlled: bool = False):
    import copy

    def factory() -> Team:
        roster = [copy.deepcopy(p) for p in drafted_players]
        team = Team(team_name, roster)
        team.user_controlled = user_controlled
        team.fantasy_control_enabled = user_controlled
        build_best_lineup_by_overall(team)
        return team

    return factory


def fantasy_season_strength(team: Team) -> float:
    build_best_lineup_by_overall(team)
    ranked = sorted(team.roster, key=fantasy_ovr, reverse=True)
    top8 = ranked[:8] if len(ranked) >= 8 else ranked
    starters = ranked[:5]
    if not top8:
        return 50.0

    star_power = sum(fantasy_ovr(p) for p in starters[:2]) / max(1, len(starters[:2]))
    starter_power = sum(fantasy_ovr(p) for p in starters) / max(1, len(starters))
    depth_power = sum(fantasy_ovr(p) for p in top8) / max(1, len(top8))
    shooting = sum(p.three_rating * p.three_tendency for p in starters) / max(1, len(starters))
    inside = sum((p.rim_rating + p.dunk_rating) * 0.5 for p in starters) / max(1, len(starters))
    defense = sum(0.52 * p.perimeter_def + 0.48 * p.interior_def for p in starters) / max(1, len(starters))
    creation = sum(0.55 * p.playmaking + 0.45 * p.ball_handle for p in starters) / max(1, len(starters))
    clutch = sum(p.clutchness for p in starters[:3]) / max(1, len(starters[:3]))

    return (
        star_power * 0.24
        + starter_power * 0.30
        + depth_power * 0.18
        + shooting * 7.0
        + inside * 5.0
        + defense * 8.0
        + creation * 5.0
        + clutch * 3.0
    )


def fantasy_quick_game_result(team_a: Dict, team_b: Dict) -> Dict:
    diff = team_a["strength"] - team_b["strength"]
    win_prob = max(0.18, min(0.82, 0.50 + diff / 70.0))
    winner = team_a if random.random() < win_prob else team_b
    loser = team_b if winner is team_a else team_a
    base_margin = abs(diff) * 0.22 + random.gauss(6.5, 6.0)
    margin = max(1, int(round(base_margin)))
    winner_score = random.randint(104, 124)
    loser_score = max(82, winner_score - margin)
    return {"winner": winner, "loser": loser, "winner_score": winner_score, "loser_score": loser_score}


def build_fantasy_season_entries(drafted_rosters: Dict[str, List[Player]],
                                 user_team_name: str) -> List[Dict]:
    entries = []

    for name, roster in drafted_rosters.items():
        is_user = name == user_team_name
        factory = make_fantasy_team_factory(name, roster, user_controlled=is_user)
        team = factory()
        entries.append({
            "name": name,
            "factory": factory,
            "wins": 0,
            "losses": 0,
            "strength": fantasy_season_strength(team),
            "is_user": is_user,
        })

    return entries


def run_fantasy_82_game_season(drafted_rosters: Dict[str, List[Player]],
                               user_team_name: str) -> List[Dict]:
    entries = build_fantasy_season_entries(drafted_rosters, user_team_name)
    print("\n=== 82-GAME FANTASY SEASON ===")
    print("Regular season is simmed with team overall, shot profile, creation, defense, depth, and clutch ratings.")

    for _ in range(82):
        round_entries = entries[:]
        random.shuffle(round_entries)
        if len(round_entries) % 2 == 1:
            round_entries.pop()
        for i in range(0, len(round_entries), 2):
            result = fantasy_quick_game_result(round_entries[i], round_entries[i + 1])
            result["winner"]["wins"] += 1
            result["loser"]["losses"] += 1

    standings = sorted(entries, key=lambda item: (item["wins"], item["strength"]), reverse=True)
    print("\nFantasy season standings:")
    for seed, item in enumerate(standings, start=1):
        mark = " <-- your team" if item["is_user"] else ""
        print(f"{seed:>2}. {item['name']:<32} {item['wins']:>2}-{item['losses']:<2}  STR {item['strength']:.1f}{mark}")
    return standings


def season_entry_from_factory(name: str, factory) -> Dict:
    team = factory()
    team.init_lineup()
    apply_star_clutchness(team)
    assign_player_badges(team)
    build_best_lineup_by_overall(team)
    initialize_minute_targets(team)
    apply_rotation_profile(team)
    strength = fantasy_season_strength(team)
    conf = "East" if hash(name) % 2 == 0 else "West"
    return {
        "name": name,
        "factory": factory,
        "team": team,
        "strength": strength,
        "conference": conf,
        "wins": 0,
        "losses": 0,
        "pf": 0,
        "pa": 0,
        "player_totals": {},
        "team_totals": {
            "games": 0, "wins": 0, "pts": 0, "reb": 0, "oreb": 0, "dreb": 0, "ast": 0,
            "stl": 0, "blk": 0, "tov": 0, "pf": 0, "fgm": 0, "fga": 0,
            "tpm": 0, "tpa": 0, "ftm": 0, "fta": 0,
        },
    }


def season_player_minutes(team: Team) -> Dict[Player, float]:
    if not team.roster:
        return {}
    if not hasattr(team.roster[0], "target_minutes"):
        initialize_minute_targets(team)
        apply_rotation_profile(team)
    ranked = sorted(
        team.roster,
        key=lambda p: (
            getattr(p, "target_minutes", 0),
            overall_rating(p),
            getattr(p, "usage", 0),
            getattr(p, "clutchness", 0),
        ),
        reverse=True,
    )
    active = [p for p in ranked if getattr(p, "target_minutes", 0) > 0]
    if len(active) > 10:
        active = active[:10]
    elif not active:
        active = ranked[:10] if len(ranked) >= 10 else ranked
    if not active:
        return {}
    weights = []
    for idx, p in enumerate(active):
        target = getattr(p, "target_minutes", None)
        if target:
            base = float(target)
        elif idx < 5:
            base = 29.0 + 7.0 * max(0.0, overall_rating(p) - 0.80)
        else:
            base = max(9.0, 23.0 - 2.3 * (idx - 5))
        weights.append(max(4.0, base))
    scale = 240.0 / max(1.0, sum(weights))
    return {p: weights[i] * scale for i, p in enumerate(active)}


def empty_season_player_row() -> Dict:
    return {
        "games": 0, "minutes": 0, "pts": 0, "reb": 0, "oreb": 0, "dreb": 0, "ast": 0,
        "assist_pts_created": 0, "stl": 0, "blk": 0, "tov": 0, "pf": 0, "plus_minus": 0,
        "fgm": 0, "fga": 0, "tpm": 0, "tpa": 0, "ftm": 0, "fta": 0,
        "shot_diet": {}, "defended_diet": {}, "defended_matchup_diet": {}, "quarter_stats": {},
    }


def add_int_stat(row: Dict, key: str, value: float):
    row[key] = row.get(key, 0) + int(round(value))


def add_season_diet(row: Dict, made: int, attempts: int, shot_type: str, context: str = ""):
    for _ in range(max(0, attempts)):
        add_to_shot_diet(row["shot_diet"], shot_type, context, made=False)
    for _ in range(max(0, min(made, attempts))):
        add_to_shot_diet(row["shot_diet"], shot_type, context, made=True)


def add_season_defended_diet(row: Dict, made: int, attempts: int, shot_type: str, context: str = "season|contested"):
    diet = row.setdefault("defended_diet", {})
    for _ in range(max(0, attempts)):
        add_to_shot_diet(diet, shot_type, context, made=False)
    for _ in range(max(0, min(made, attempts))):
        add_to_shot_diet(diet, shot_type, context, made=True)


def simulate_quiet_season_team_game(entry: Dict, opponent: Dict, points: int, points_allowed: int, won: bool):
    team = entry["team"]
    minutes = season_player_minutes(team)
    players = list(minutes.keys())
    if not players:
        return

    shot_weights = []
    assist_weights = []
    rebound_weights = []
    total_minutes = max(1.0, sum(minutes.values()))
    for p in players:
        scoring = 0.34 * p.three_rating + 0.28 * p.mid_rating + 0.28 * p.rim_rating + 0.10 * p.dunk_rating
        shot_weights.append(max(0.03, minutes[p] * (0.35 + 1.80 * p.shot_tendency + 1.20 * p.usage) * scoring))
        creator_bonus = max(0.0, p.playmaking - 0.72) * 4.0
        elite_bonus = max(0.0, p.playmaking - 0.88) * 9.0
        handle_bonus = max(0.0, p.ball_handle - 0.72) * 0.55
        assist_weights.append(max(0.02, minutes[p] * (0.10 + 1.35 * p.playmaking + creator_bonus + elite_bonus + handle_bonus)))
        rebound_weights.append(max(0.02, minutes[p] * (0.25 + 0.72 * p.dreb + 0.28 * p.oreb)))

    total_shot_weight = max(1.0, sum(shot_weights))
    total_ast_weight = max(1.0, sum(assist_weights))
    total_reb_weight = max(1.0, sum(rebound_weights))
    team_fga = int(round(clamp_value(points * random.uniform(0.76, 0.86), 76, 101)))
    team_fta = int(round(clamp_value(points * random.uniform(0.16, 0.24), 12, 34)))
    team_tpa = int(round(team_fga * clamp_value(sum(three_attempt_tendency_curve(p.three_tendency) * minutes[p] for p in players) / max(1.0, sum(minutes.values())), 0.16, 0.56)))
    team_tpm = int(round(team_tpa * clamp_value(0.31 + 0.13 * (sum(p.three_rating * minutes[p] for p in players) / max(1.0, sum(minutes.values())) - 0.75), 0.28, 0.43)))
    team_ftm = int(round(team_fta * clamp_value(sum(p.ft_rating * minutes[p] for p in players) / max(1.0, sum(minutes.values())), 0.62, 0.88)))
    two_points = max(0, points - 3 * team_tpm - team_ftm)
    team_fgm = team_tpm + max(0, int(round(two_points / 2)))
    team_fga = max(team_fga, team_fgm + random.randint(28, 48))
    team_reb = int(round(clamp_value(41 + random.gauss(0, 5) + (entry["strength"] - opponent["strength"]) * 0.08, 30, 62)))
    team_oreb = int(round(clamp_value(team_reb * random.uniform(0.17, 0.27), 5, 18)))
    team_dreb = max(0, team_reb - team_oreb)
    playmaking_avg = sum(p.playmaking * minutes[p] for p in players) / total_minutes
    passing_rate = clamp_value(0.60 + (playmaking_avg - 0.62) * 0.22 + random.gauss(0, 0.030), 0.53, 0.72)
    ast_ceiling = 38 if playmaking_avg >= 0.86 else 35 if playmaking_avg >= 0.74 else 32
    team_ast = int(round(clamp_value(team_fgm * passing_rate, 18, ast_ceiling)))
    team_tov = int(round(clamp_value(13 - (playmaking_avg - 0.60) * 5 + random.gauss(0, 2), 6, 20)))
    team_stl = int(round(clamp_value(sum(p.steal * minutes[p] for p in players) / total_minutes * 9 + random.gauss(0, 1.5), 2, 13)))
    team_blk = int(round(clamp_value(sum(p.block * minutes[p] for p in players) / total_minutes * 8 + random.gauss(0, 1.5), 1, 12)))
    team_pf = int(round(clamp_value(18 + random.gauss(0, 3), 10, 30)))

    opponent_minutes = season_player_minutes(opponent["team"])
    opponent_players = list(opponent_minutes.keys())
    opponent_total_minutes = max(1.0, sum(opponent_minutes.values()))
    opp_three_rate = clamp_value(
        sum(three_attempt_tendency_curve(p.three_tendency) * opponent_minutes[p] for p in opponent_players) / opponent_total_minutes if opponent_players else 0.34,
        0.16, 0.56
    )
    opp_fga_est = int(round(clamp_value(points_allowed * random.uniform(0.76, 0.86), 76, 101)))
    opp_three_att = int(round(opp_fga_est * opp_three_rate))
    opp_remaining = max(0, opp_fga_est - opp_three_att)
    opp_mid_att = int(round(opp_remaining * 0.32))
    opp_post_att = int(round(opp_remaining * 0.14))
    opp_rim_att = max(0, opp_remaining - opp_mid_att - opp_post_att)
    defense_zone_totals = {
        "three": (opp_three_att, 0.36, "perimeter"),
        "mid": (opp_mid_att, 0.43, "perimeter"),
        "rim": (opp_rim_att, 0.59, "interior"),
        "post": (opp_post_att, 0.51, "interior"),
    }
    per_def_weight_total = max(1.0, sum(minutes[p] * (0.35 + p.perimeter_def + p.steal * 0.30) for p in players))
    int_def_weight_total = max(1.0, sum(minutes[p] * (0.35 + p.interior_def + p.block * 0.35 + p.dreb * 0.12) for p in players))

    assigned = {key: 0 for key in ("pts", "fga", "fgm", "tpa", "tpm", "fta", "ftm", "reb", "oreb", "dreb", "ast", "tov", "stl", "blk", "pf")}
    for idx, p in enumerate(players):
        key = player_stat_key(team, p)
        row = entry["player_totals"].setdefault(key, empty_season_player_row())
        row["games"] += 1
        row["minutes"] += int(round(minutes[p] * 60))
        share = shot_weights[idx] / total_shot_weight
        ast_share = assist_weights[idx] / total_ast_weight
        reb_share = rebound_weights[idx] / total_reb_weight
        if idx == len(players) - 1:
            pts = points - assigned["pts"]
            fga = team_fga - assigned["fga"]
            fgm = team_fgm - assigned["fgm"]
            tpa = team_tpa - assigned["tpa"]
            tpm = team_tpm - assigned["tpm"]
            fta = team_fta - assigned["fta"]
            ftm = team_ftm - assigned["ftm"]
            reb = team_reb - assigned["reb"]
            oreb = team_oreb - assigned["oreb"]
            dreb = team_dreb - assigned["dreb"]
            ast = max(0, team_ast - assigned["ast"])
            tov = team_tov - assigned["tov"]
            stl = team_stl - assigned["stl"]
            blk = team_blk - assigned["blk"]
            pf = team_pf - assigned["pf"]
        else:
            pts = max(0, int(round(points * share * random.uniform(0.84, 1.18))))
            fga = max(0, int(round(team_fga * share * random.uniform(0.86, 1.16))))
            fgm = max(0, min(fga, int(round(team_fgm * share * random.uniform(0.82, 1.20)))))
            tpa = max(0, int(round(team_tpa * share * (0.55 + three_attempt_tendency_curve(p.three_tendency)))))
            tpm = max(0, min(tpa, int(round(team_tpm * share * (0.65 + p.three_rating * 0.55)))))
            fta = max(0, int(round(team_fta * share * (0.75 + p.foul_draw * 0.35))))
            ftm = max(0, min(fta, int(round(fta * p.ft_rating))))
            reb = max(0, int(round(team_reb * reb_share * random.uniform(0.82, 1.18))))
            oreb = max(0, int(round(team_oreb * (minutes[p] * p.oreb) / max(1.0, sum(minutes[x] * x.oreb for x in players)) * random.uniform(0.82, 1.18))))
            dreb = max(0, reb - oreb)
            ast = max(0, int(round(team_ast * ast_share * random.uniform(0.74, 1.08))))
            tov = max(0, int(round(team_tov * (minutes[p] * (0.35 + p.usage + p.ball_handle * 0.35)) / max(1.0, sum(minutes[x] * (0.35 + x.usage + x.ball_handle * 0.35) for x in players)))))
            stl = max(0, int(round(team_stl * (minutes[p] * p.steal) / max(1.0, sum(minutes[x] * x.steal for x in players)))))
            blk = max(0, int(round(team_blk * (minutes[p] * p.block) / max(1.0, sum(minutes[x] * x.block for x in players)))))
            pf = max(0, int(round(team_pf * (minutes[p] * p.foul_rate) / max(1.0, sum(minutes[x] * x.foul_rate for x in players)))))
        for stat, value in (("pts", pts), ("fga", fga), ("fgm", fgm), ("tpa", tpa), ("tpm", tpm), ("fta", fta), ("ftm", ftm), ("reb", reb), ("oreb", oreb), ("dreb", dreb), ("ast", ast), ("tov", tov), ("stl", stl), ("blk", blk), ("pf", pf)):
            row[stat] += max(0, value)
            assigned[stat] += max(0, value)
        row["assist_pts_created"] += ast * random.choice((2, 2, 2, 3))
        row["plus_minus"] += int(round((points - points_allowed) * minutes[p] / 240.0))
        three_att = max(0, min(row["fga"], tpa))
        mid_att = max(0, int(round((fga - three_att) * p.mid_tendency / max(0.01, p.mid_tendency + p.drive_tendency + p.post_tendency))))
        post_att = max(0, int(round((fga - three_att - mid_att) * p.post_tendency / max(0.01, p.drive_tendency + p.post_tendency))))
        rim_att = max(0, fga - three_att - mid_att - post_att)
        add_season_diet(row, tpm, three_att, "three", "season|contested")
        add_season_diet(row, int(round(fgm * mid_att / max(1, fga))), mid_att, "mid", "season|contested")
        add_season_diet(row, int(round(fgm * rim_att / max(1, fga))), rim_att, "rim", "season|contested")
        add_season_diet(row, int(round(fgm * post_att / max(1, fga))), post_att, "post", "season|contested")
        for shot_type, (attempts, base_pct, defense_kind) in defense_zone_totals.items():
            if defense_kind == "perimeter":
                weight = minutes[p] * (0.35 + p.perimeter_def + p.steal * 0.30)
                weight_total = per_def_weight_total
                rating = p.perimeter_def
            else:
                weight = minutes[p] * (0.35 + p.interior_def + p.block * 0.35 + p.dreb * 0.12)
                weight_total = int_def_weight_total
                rating = p.interior_def
            defended_att = max(0, int(round(attempts * weight / weight_total * random.uniform(0.76, 1.14))))
            allowed_pct = clamp_value(base_pct * (1.18 - 0.28 * rating), 0.25, 0.74)
            defended_made = max(0, min(defended_att, int(round(defended_att * allowed_pct))))
            add_season_defended_diet(row, defended_made, defended_att, shot_type, "season|contested")

    totals = entry["team_totals"]
    totals["games"] += 1
    totals["wins"] += 1 if won else 0
    for key, value in (("pts", points), ("reb", team_reb), ("oreb", team_oreb), ("dreb", team_dreb), ("ast", team_ast), ("stl", team_stl), ("blk", team_blk), ("tov", team_tov), ("pf", team_pf), ("fgm", team_fgm), ("fga", team_fga), ("tpm", team_tpm), ("tpa", team_tpa), ("ftm", team_ftm), ("fta", team_fta)):
        totals[key] += value


def simulate_quiet_season_game(entry_a: Dict, entry_b: Dict):
    diff = entry_a["strength"] - entry_b["strength"] + random.choice((-1.8, 1.8))
    win_prob = clamp_value(1.0 / (1.0 + math.exp(-diff / 8.5)), 0.18, 0.82)
    a_wins = random.random() < win_prob
    expected_a = 112 + diff * 0.55 + random.gauss(0, 8)
    expected_b = 112 - diff * 0.35 + random.gauss(0, 8)
    score_a = int(round(clamp_value(expected_a, 86, 142)))
    score_b = int(round(clamp_value(expected_b, 86, 142)))
    if a_wins and score_a <= score_b:
        score_a = score_b + random.randint(1, 9)
    elif not a_wins and score_b <= score_a:
        score_b = score_a + random.randint(1, 9)
    entry_a["wins" if a_wins else "losses"] += 1
    entry_b["losses" if a_wins else "wins"] += 1
    entry_a["pf"] += score_a
    entry_a["pa"] += score_b
    entry_b["pf"] += score_b
    entry_b["pa"] += score_a
    simulate_quiet_season_team_game(entry_a, entry_b, score_a, score_b, a_wins)
    simulate_quiet_season_team_game(entry_b, entry_a, score_b, score_a, not a_wins)


def build_season_sections(entries: List[Dict],
                          series_totals: Dict | None = None,
                          series_team_totals: Dict | None = None) -> Dict:
    def season_ts(stats: Dict) -> float:
        denom = 2 * (stats.get("fga", 0) + 0.44 * stats.get("fta", 0))
        return 0.0 if denom == 0 else 100 * stats.get("pts", 0) / denom

    standings = []
    if series_totals is None:
        series_totals = {}
    if series_team_totals is None:
        series_team_totals = {}
    for entry in entries:
        games = max(1, entry["wins"] + entry["losses"])
        standings.append({
            "seed": 0,
            "conference": entry.get("conference", "-"),
            "team": entry["name"],
            "wins": entry["wins"],
            "losses": entry["losses"],
            "pct": entry["wins"] / games,
            "pf": entry["pf"] / games,
            "pa": entry["pa"] / games,
            "diff": (entry["pf"] - entry["pa"]) / games,
            "strength": entry["strength"],
        })
        if entry["name"] not in series_totals:
            series_totals[entry["name"]] = entry["player_totals"]
        if entry["name"] not in series_team_totals:
            series_team_totals[entry["name"]] = entry["team_totals"]
    standings.sort(key=lambda row: (row["wins"], row["diff"], row["strength"]), reverse=True)
    for idx, row in enumerate(standings, start=1):
        row["seed"] = idx
    all_players = [
        (team_name, name, stats)
        for team_name, players in series_totals.items()
        for name, stats in players.items()
        if stats.get("games", 0) > 0
    ]
    player_lookup = {}
    for entry in entries:
        team = entry.get("team")
        if not team:
            continue
        for player in getattr(team, "roster", []):
            player_lookup[(entry["name"], player_stat_key(team, player))] = player
    awards = []
    awards_table = []
    if all_players:
        def stat_line(team_name: str, stats: Dict) -> str:
            gp = max(1, stats.get("games", 1))
            return (
                f"{stats.get('pts', 0) / gp:.1f} PPG, "
                f"{stats.get('reb', 0) / gp:.1f} RPG, "
                f"{stats.get('ast', 0) / gp:.1f} APG, "
                f"{(stats.get('stl', 0) + stats.get('blk', 0)) / gp:.1f} stocks, "
                f"{season_ts(stats):.1f} TS%"
            )

        def defended_core_totals(stats: Dict) -> Tuple[int, int]:
            diet = stats.get("defended_diet", {}) or {}
            core_keys = ("three", "mid", "rim", "post", "dunk")
            attempts = sum(int(diet.get(key, 0) or 0) for key in core_keys)
            made = sum(int(diet.get(f"{key}_made", 0) or 0) for key in core_keys)
            return made, attempts

        def season_advanced_for(team_name: str, stats: Dict) -> Tuple:
            team = series_team_totals.get(team_name, {})
            opp_name = next((name for name in series_team_totals if name != team_name), None)
            opp = series_team_totals.get(opp_name, team)
            if not team or not opp:
                return (0.0,) * 25
            return calc_series_advanced(stats, team, opp)

        def defense_stat_line(team_name: str, stats: Dict) -> str:
            gp = max(1, stats.get("games", 1))
            mpg = stats.get("minutes", 0) / 60 / gp
            stocks = (stats.get("stl", 0) + stats.get("blk", 0)) / gp
            made, attempts = defended_core_totals(stats)
            allowed_pct = 100 * safe_div(made, attempts)
            adv = season_advanced_for(team_name, stats)
            return (
                f"{mpg:.1f} MPG, {stocks:.1f} stocks, "
                f"{attempts / gp:.1f} shots defended, {allowed_pct:.1f}% allowed, "
                f"{adv[23]:+.1f} DEF IMP"
            )

        def defensive_score(item: Tuple[str, str, Dict]) -> float:
            team_name, _name, stats = item
            player = player_lookup.get((team_name, _name))
            gp = max(1, stats.get("games", 1))
            mpg = stats.get("minutes", 0) / 60 / gp
            stocks_pg = (stats.get("stl", 0) + stats.get("blk", 0)) / gp
            dreb_pg = stats.get("dreb", 0) / gp
            pf_pg = stats.get("pf", 0) / gp
            made, attempts = defended_core_totals(stats)
            defended_pg = attempts / gp
            allowed_pct = safe_div(made, attempts)
            adv = season_advanced_for(team_name, stats)
            if player is not None:
                pos = str(getattr(player, "position", "")).upper()
                if pos in ("PF", "C"):
                    defense_skill = (
                        0.26 * player.perimeter_def
                        + 0.46 * player.interior_def
                        + 0.15 * player.block
                        + 0.08 * player.steal
                        + 0.05 * player.dreb
                    )
                elif pos in ("SG", "SF"):
                    defense_skill = (
                        0.42 * player.perimeter_def
                        + 0.28 * player.interior_def
                        + 0.16 * player.steal
                        + 0.08 * player.block
                        + 0.06 * player.dreb
                    )
                else:
                    defense_skill = (
                        0.52 * player.perimeter_def
                        + 0.16 * player.interior_def
                        + 0.22 * player.steal
                        + 0.05 * player.block
                        + 0.05 * player.dreb
                    )
            else:
                defense_skill = 0.62
            minute_factor = clamp_value(mpg / 30.0, 0.25, 1.18)
            low_min_penalty = max(0.0, 26.0 - mpg) * 0.85
            if mpg < 22.0:
                low_min_penalty += 8.0 + (22.0 - mpg) * 2.2
            low_work_penalty = max(0.0, 5.0 - defended_pg) * 0.32
            efficiency_bonus = (0.515 - allowed_pct) * 9.0 if attempts else -1.5
            skill_bonus = (defense_skill - 0.64) * 20.0
            weak_defender_penalty = max(0.0, 0.74 - defense_skill) * 58.0
            profile_floor_penalty = 22.0 if defense_skill < 0.68 else 0.0
            return (
                minute_factor * 1.8
                + stocks_pg * 4.2
                + dreb_pg * 0.28
                + defended_pg * 0.20
                + efficiency_bonus
                + skill_bonus
                + adv[23] * 0.85
                + adv[15] * 0.06
                - pf_pg * 0.32
                - low_min_penalty
                - low_work_penalty
                - weak_defender_penalty
                - profile_floor_penalty
            )

        mvp = max(all_players, key=lambda item: series_player_score(item[2]) + item[2].get("plus_minus", 0) / max(1, item[2].get("games", 1)) * 0.05)
        scorer = max(all_players, key=lambda item: item[2].get("pts", 0) / max(1, item[2].get("games", 1)))
        passer = max(all_players, key=lambda item: item[2].get("ast", 0) / max(1, item[2].get("games", 1)))
        defenders = sorted(all_players, key=defensive_score, reverse=True)
        all_nba = sorted(all_players, key=lambda item: series_player_score(item[2]) + item[2].get("plus_minus", 0) / max(1, item[2].get("games", 1)) * 0.03, reverse=True)
        dpoy = defenders[0]
        awards.append(("Season MVP", mvp[1], f"{mvp[0]} | {mvp[2].get('pts', 0) / max(1, mvp[2].get('games', 1)):.1f} PPG, {mvp[2].get('reb', 0) / max(1, mvp[2].get('games', 1)):.1f} RPG, {mvp[2].get('ast', 0) / max(1, mvp[2].get('games', 1)):.1f} APG"))
        awards.append(("DPOY", dpoy[1], f"{dpoy[0]} | {defense_stat_line(dpoy[0], dpoy[2])}"))
        awards.append(("Scoring Leader", scorer[1], f"{scorer[0]} | {scorer[2].get('pts', 0) / max(1, scorer[2].get('games', 1)):.1f} PPG | {season_ts(scorer[2]):.1f} TS%"))
        awards.append(("Assist Leader", passer[1], f"{passer[0]} | {passer[2].get('ast', 0) / max(1, passer[2].get('games', 1)):.1f} APG"))

        awards_table.append({"award": "MVP", "player": mvp[1], "team": mvp[0], "stats": stat_line(mvp[0], mvp[2])})
        awards_table.append({"award": "DPOY", "player": dpoy[1], "team": dpoy[0], "stats": defense_stat_line(dpoy[0], dpoy[2])})

        for team_no, start in enumerate((0, 5, 10), start=1):
            label = {1: "All-NBA First Team", 2: "All-NBA Second Team", 3: "All-NBA Third Team"}[team_no]
            for idx, (team_name, name, stats) in enumerate(all_nba[start:start + 5], start=1):
                awards_table.append({"award": label, "player": f"{idx}. {name}", "team": team_name, "stats": stat_line(team_name, stats)})

        for team_no, start in enumerate((0, 5), start=1):
            label = "All-Defensive First Team" if team_no == 1 else "All-Defensive Second Team"
            for idx, (team_name, name, stats) in enumerate(defenders[start:start + 5], start=1):
                awards_table.append({"award": label, "player": f"{idx}. {name}", "team": team_name, "stats": defense_stat_line(team_name, stats)})
    top_lines = ["82-GAME SEASON COMPLETE", "", "Standings"]
    for row in standings:
        top_lines.append(f"{row['seed']:>2}. {row['team']:<34} {row['wins']:>2}-{row['losses']:<2}  {row['pct']:.3f}  DIFF {row['diff']:+.1f}")
    return {
        "game_box_scores": "\n".join(top_lines),
        "postgame_recaps": "Season mode uses quiet simulation: no possession-by-possession play-by-play for the 82-game schedule.",
        "series_memory": "Regular-season awards and averages are generated from the same player ratings, tendencies, defense, rebounding, and shot diet categories.",
        "_season_standings": standings,
        "_season_awards": awards,
        "_season_awards_table": awards_table,
        "_season_player_totals": series_totals,
        "_season_team_totals": series_team_totals,
        "_series_totals": series_totals,
        "_series_team_totals": series_team_totals,
        "_winner_name": standings[0]["team"] if standings else None,
    }


def simulate_silent_season_game(factory_a, factory_b) -> Tuple[Team, Team]:
    import builtins
    import contextlib
    import io

    global SLEEP, SIM_FAST_FORWARD, SIM_JUMP_TARGET, SIM_PAUSED, SIM_SLEEP_SCALE
    global GUI_SERIES_UPDATE_QUEUE, GUI_SCOREBOARD_QUEUE

    team_a = factory_a()
    team_b = factory_b()
    team_a.init_lineup()
    team_b.init_lineup()
    apply_star_clutchness(team_a, team_b)
    assign_player_badges(team_a)
    assign_player_badges(team_b)

    original_sleep = SLEEP
    original_fast = SIM_FAST_FORWARD
    original_jump = SIM_JUMP_TARGET
    original_paused = SIM_PAUSED
    original_sleep_scale = SIM_SLEEP_SCALE
    original_input = builtins.input
    original_print = builtins.print
    original_time_sleep = time.sleep
    original_series_queue = GUI_SERIES_UPDATE_QUEUE
    original_scoreboard_queue = GUI_SCOREBOARD_QUEUE

    try:
        SLEEP = 0
        SIM_SLEEP_SCALE = 0
        SIM_FAST_FORWARD = True
        SIM_JUMP_TARGET = None
        SIM_PAUSED = False
        GUI_SERIES_UPDATE_QUEUE = None
        GUI_SCOREBOARD_QUEUE = None
        builtins.input = lambda _prompt="": ""
        builtins.print = lambda *args, **kwargs: None
        time.sleep = lambda *_args, **_kwargs: None
        with contextlib.redirect_stdout(io.StringIO()):
            simulate_game(team_a, team_b)
    finally:
        SLEEP = original_sleep
        SIM_FAST_FORWARD = original_fast
        SIM_JUMP_TARGET = original_jump
        SIM_PAUSED = original_paused
        SIM_SLEEP_SCALE = original_sleep_scale
        GUI_SERIES_UPDATE_QUEUE = original_series_queue
        GUI_SCOREBOARD_QUEUE = original_scoreboard_queue
        builtins.input = original_input
        builtins.print = original_print
        time.sleep = original_time_sleep

    return team_a, team_b


def run_quiet_82_game_season(selected_names: List[str], factories: Dict[str, object], section_queue=None, progress_queue=None) -> Dict:
    entries = [season_entry_from_factory(name, factories[name]) for name in selected_names if name in factories]
    if len(entries) < 2:
        print("Season mode needs at least two teams.")
        return {}
    entry_by_name = {entry["name"]: entry for entry in entries}
    season_player_totals = {}
    season_team_totals = {}
    completed_games = 0
    total_games = 82 * (len(entries) // 2)
    print("\n=== SEASON MODE ===")
    print(f"Quiet-simming 82 games for {len(entries)} teams with the full playoff game engine hidden from the GUI. No play-by-play will be printed during the regular season.")
    if progress_queue is not None:
        progress_queue.put({"season_progress": True, "completed": completed_games, "total": total_games})
    for game_no in range(82):
        round_entries = entries[:]
        random.shuffle(round_entries)
        if len(round_entries) % 2 == 1:
            round_entries.pop()
        for idx in range(0, len(round_entries), 2):
            entry_a = round_entries[idx]
            entry_b = round_entries[idx + 1]
            team_a, team_b = simulate_silent_season_game(entry_a["factory"], entry_b["factory"])

            add_player_to_series_totals(season_player_totals, team_a)
            add_player_to_series_totals(season_player_totals, team_b)
            add_team_to_series_totals(season_team_totals, team_a)
            add_team_to_series_totals(season_team_totals, team_b)

            actual_a = entry_by_name.get(team_a.name, entry_a)
            actual_b = entry_by_name.get(team_b.name, entry_b)
            actual_a["pf"] += team_a.score
            actual_a["pa"] += team_b.score
            actual_b["pf"] += team_b.score
            actual_b["pa"] += team_a.score
            if team_a.score > team_b.score:
                actual_a["wins"] += 1
                actual_b["losses"] += 1
                season_team_totals[team_a.name]["wins"] += 1
            elif team_b.score > team_a.score:
                actual_b["wins"] += 1
                actual_a["losses"] += 1
                season_team_totals[team_b.name]["wins"] += 1
            else:
                actual_a["losses"] += 1
                actual_b["losses"] += 1
            completed_games += 1
            if progress_queue is not None:
                progress_queue.put({"season_progress": True, "completed": completed_games, "total": total_games})
        if (game_no + 1) in (20, 41, 62, 82):
            print(f"Season sim progress: {game_no + 1}/82 games per team.")
    sections = build_season_sections(entries, season_player_totals, season_team_totals)
    if section_queue is not None:
        section_queue.put(sections)
    print("\nSeason complete. Standings, averages, advanced stats, shot diet, and awards are ready in the GUI.")
    return sections


def fantasy_background_series_winner(team_a: Dict, team_b: Dict) -> Dict:
    wins = {team_a["name"]: 0, team_b["name"]: 0}
    while wins[team_a["name"]] < 4 and wins[team_b["name"]] < 4:
        result = fantasy_quick_game_result(team_a, team_b)
        wins[result["winner"]["name"]] += 1
    winner = team_a if wins[team_a["name"]] == 4 else team_b
    loser = team_b if winner is team_a else team_a
    print(f"{winner['name']} beat {loser['name']} in the background, {wins[winner['name']]}-{wins[loser['name']]}.")
    return winner


def print_fantasy_playoff_bracket(round_name: str, teams: List[Dict]):
    print("\n" + "=" * 80)
    print(round_name)
    print("=" * 80)
    for idx in range(0, len(teams), 2):
        if idx + 1 < len(teams):
            print(f"{teams[idx]['seed']}. {teams[idx]['name']} vs {teams[idx + 1]['seed']}. {teams[idx + 1]['name']}")


def run_fantasy_playoffs_from_season(standings: List[Dict]):
    playoff_teams = [dict(item) for item in standings[:16]]
    for seed, item in enumerate(playoff_teams, start=1):
        item["seed"] = seed

    user_entry = next((item for item in playoff_teams if item["is_user"]), None)
    if user_entry is None:
        user_rank = next((idx for idx, item in enumerate(standings, start=1) if item["is_user"]), None)
        user_name = next((item["name"] for item in standings if item["is_user"]), "Your team")
        print(f"\n{user_name} missed the playoffs as seed {user_rank}. Season ends here.")
        return

    round_name = "Fantasy Playoffs - Round 1"
    current = playoff_teams
    while len(current) > 1:
        print_fantasy_playoff_bracket(round_name, current)
        winners = []
        for idx in range(0, len(current), 2):
            high_seed = current[idx]
            low_seed = current[idx + 1]
            if high_seed["is_user"] or low_seed["is_user"]:
                print("\nYour playoff series is being played with the full 5v5 engine.")
                winner_name = run_best_of_7_series(high_seed["factory"], low_seed["factory"], fantasy_customization=True)
                winner = high_seed if high_seed["name"] == winner_name else low_seed
                if not winner["is_user"]:
                    print("\nYour team has been eliminated. Remaining playoffs will finish in the background.")
            else:
                winner = fantasy_background_series_winner(high_seed, low_seed)
            winners.append(winner)

        winners.sort(key=lambda item: item["seed"])
        current = []
        while winners:
            if len(winners) == 1:
                current.append(winners.pop(0))
            else:
                current.append(winners.pop(0))
                current.append(winners.pop(-1))

        if len(current) == 8:
            round_name = "Fantasy Playoffs - Round 2"
        elif len(current) == 4:
            round_name = "Fantasy Playoffs - Conference Finals"
        elif len(current) == 2:
            round_name = "Fantasy Playoffs - Finals"

    print("\n" + "#" * 80)
    print(f"FANTASY PLAYOFF CHAMPION: {current[0]['name']}")
    print("#" * 80)


def fantasy_playoff_round_pairings(teams: List[Dict]) -> List[Tuple[Dict, Dict]]:
    ordered = sorted(teams, key=lambda item: item["seed"])
    pairings = []
    while len(ordered) >= 2:
        pairings.append((ordered.pop(0), ordered.pop(-1)))
    return pairings


def print_fantasy_conference_bracket(round_name: str, conference_name: str, teams: List[Dict]):
    print("\n" + "=" * 80)
    print(f"{round_name} - {conference_name}")
    print("=" * 80)
    for high_seed, low_seed in fantasy_playoff_round_pairings(teams):
        print(f"{high_seed['seed']}. {high_seed['name']} vs {low_seed['seed']}. {low_seed['name']}")


def run_fantasy_playoff_series(high_seed: Dict, low_seed: Dict) -> Dict:
    if high_seed["is_user"] or low_seed["is_user"]:
        print("\nYour playoff series is being played with the full 5v5 engine.")
        winner_name = run_best_of_7_series(
            high_seed["factory"],
            low_seed["factory"],
            fantasy_customization=True
        )
        winner = high_seed if high_seed["name"] == winner_name else low_seed
        if not winner["is_user"]:
            print("\nYour team has been eliminated. Remaining playoffs will finish in the background.")
        return winner

    return fantasy_background_series_winner(high_seed, low_seed)


def run_fantasy_conference_playoffs(conference_name: str, teams: List[Dict]) -> Dict:
    current = sorted(teams, key=lambda item: item["seed"])
    round_names = {
        8: "Fantasy Playoffs - First Round",
        4: "Fantasy Playoffs - Conference Semifinals",
        2: "Fantasy Playoffs - Conference Finals",
    }

    while len(current) > 1:
        round_name = round_names.get(len(current), "Fantasy Playoffs")
        print_fantasy_conference_bracket(round_name, conference_name, current)
        winners = []
        for high_seed, low_seed in fantasy_playoff_round_pairings(current):
            winners.append(run_fantasy_playoff_series(high_seed, low_seed))
        current = sorted(winners, key=lambda item: item["seed"])

    print(f"\n{current[0]['name']} win the {conference_name}.")
    return current[0]


def build_fantasy_playoff_entries(drafted_rosters: Dict[str, List[Player]],
                                  user_team_name: str,
                                  east_names: List[str],
                                  west_names: List[str]) -> Tuple[List[Dict], List[Dict]]:
    entries = build_fantasy_season_entries(drafted_rosters, user_team_name)
    by_name = {entry["name"]: entry for entry in entries}

    east = [by_name[name] for name in east_names]
    west = [by_name[name] for name in west_names]

    for conference_entries, conference_name in ((east, "Eastern Conference"), (west, "Western Conference")):
        conference_entries.sort(key=lambda item: item["strength"], reverse=True)
        for seed, entry in enumerate(conference_entries, start=1):
            entry["seed"] = seed
            entry["conference"] = conference_name

    return east, west


