def fantasy_random_conference_team_names(user_conference: str) -> Tuple[List[str], List[str]]:
    east_pool = [
        "Atlanta Hawks", "Boston Celtics", "Brooklyn Nets", "Charlotte Hornets",
        "Chicago Bulls", "Cleveland Cavaliers", "Detroit Pistons", "Indiana Pacers",
        "Miami Heat", "Milwaukee Bucks", "New York Knicks", "Orlando Magic",
        "Philadelphia 76ers", "Toronto Raptors", "Washington Wizards",
    ]
    west_pool = [
        "Dallas Mavericks", "Denver Nuggets", "Golden State Warriors", "Houston Rockets",
        "LA Clippers", "Los Angeles Lakers", "Memphis Grizzlies", "Minnesota Timberwolves",
        "New Orleans Pelicans", "Oklahoma City Thunder", "Phoenix Suns", "Portland Trail Blazers",
        "Sacramento Kings", "San Antonio Spurs", "Utah Jazz",
    ]

    east_names = random.sample(east_pool, 8)
    west_names = random.sample(west_pool, 8)

    if user_conference == "east":
        if GUI_OPTION_PICKER is not None:
            user_team = GUI_OPTION_PICKER("Choose Your Team", "Pick your Eastern Conference fantasy team.", east_names)
        else:
            user_team = input("\nChoose your Eastern team name from the generated field, or press Enter for the first team: ").strip()
        if user_team:
            match = next((name for name in east_names if name.lower() == user_team.lower()), None)
            if match:
                east_names.remove(match)
                east_names.insert(0, match)
            else:
                east_names[0] = user_team
    else:
        if GUI_OPTION_PICKER is not None:
            user_team = GUI_OPTION_PICKER("Choose Your Team", "Pick your Western Conference fantasy team.", west_names)
        else:
            user_team = input("\nChoose your Western team name from the generated field, or press Enter for the first team: ").strip()
        if user_team:
            match = next((name for name in west_names if name.lower() == user_team.lower()), None)
            if match:
                west_names.remove(match)
                west_names.insert(0, match)
            else:
                west_names[0] = user_team

    return east_names, west_names


