def select_user_fantasy_team(year_prefix: str) -> Tuple[str, List[str]]:
    from players_data import fantasy_team_factories
    factories = fantasy_team_factories(year_prefix)
    team_names = sorted(factory().name for factory in factories)
    if len(team_names) != 30:
        print(f"\nFound {len(team_names)} teams for this pool. The draft will use all of them.")

    if GUI_OPTION_PICKER is not None:
        selected = GUI_OPTION_PICKER("Choose Fantasy Team", "Pick the team you want to control.", team_names)
        if selected not in team_names:
            selected = team_names[0]
        return selected, [selected] + [t for t in team_names if t != selected]

    print("\nChoose the team you want to control:")
    for idx, name in enumerate(team_names, start=1):
        print(f"  {idx}. {name}")

    while True:
        raw = input(f"Enter team number (1-{len(team_names)}) or team name: ").strip()
        lowered = raw.lower()
        for name in team_names:
            if lowered == name.lower():
                return name, [name] + [t for t in team_names if t != name]
        try:
            choice = int(raw)
        except ValueError:
            print("No team matched that. Try the number or the exact team name.")
            continue
        if 1 <= choice <= len(team_names):
            selected = team_names[choice - 1]
            return selected, [selected] + [t for t in team_names if t != selected]
        print("That team number is not available.")


def fantasy_available_players(pools: Dict[str, List[Tuple[Player, str]]],
                              taken_names: set) -> List[Player]:
    available = []
    seen = set()
    for pool in pools.values():
        for candidate, _ in pool:
            key = getattr(candidate, "fantasy_base_name", candidate.name)
            if key in seen or key in taken_names:
                continue
            seen.add(key)
            available.append(candidate)
    return available


def ai_pick_for_fantasy_team(pools: Dict[str, List[Tuple[Player, str]]],
                             taken_names: set,
                             team_players: List[Player],
                             user_players: List[Player]) -> Player:
    best_player = None
    best_score = -9999.0
    for candidate in fantasy_available_players(pools, taken_names):
        score = fantasy_ai_candidate_score(candidate, team_players, user_players)
        score += random.uniform(-1.25, 1.25)
        if score > best_score:
            best_score = score
            best_player = candidate
    return best_player


def print_fantasy_draft_round_summary(round_num: int, picks: List[Tuple[str, Player]]):
    print(f"\nRound {round_num} picks:")
    for team_name, player in picks:
        print(f"  {team_name:<32} {player.name} ({player.position}) OVR {fantasy_ovr(player)}")


def run_fantasy_draft_and_game(year_prefix: str = None):
    from players_data import build_fantasy_player_pools
    """
    Run an 8-round, 30-team fantasy draft. User chooses one team, drafts first,
    every other team drafts, and the order snakes each round.
    """
    year_prefix = year_prefix or "2026 "
    pools = build_fantasy_player_pools(year_prefix)
    taken_names: set = set()

    picks_per_team = 8
    user_team_name, team_order = select_user_fantasy_team(year_prefix)
    drafted_rosters: Dict[str, List[Player]] = {name: [] for name in team_order}

    print("\n=== FANTASY DRAFT MODE ===")
    print(f"You control {user_team_name}.")
    print("All 30 teams will draft 8 players.")
    if year_prefix:
        pool_label = year_prefix.strip()
        print(f"The pool is built from every player across {pool_label} teams.")
    else:
        print("The pool is built from every player across every team in the sim.")
    print("Position boards show the top 30 at a time, and you can type any player name to search.")
    print("Draft order is snake: you pick first, then the other 29 teams pick, then the order reverses.")
    print("Draft by choosing a position number, then the ranking number of the player.\n")

    for round_num in range(1, picks_per_team + 1):
        current_order = team_order if round_num % 2 == 1 else list(reversed(team_order))
        round_picks = []
        print("\n" + "=" * 80)
        print(f"FANTASY DRAFT ROUND {round_num}")
        print("=" * 80)

        for team_name in current_order:
            if team_name == user_team_name:
                print(f"\n{user_team_name} are on the clock.")
                p = user_pick_from_pool(pools, taken_names)
                user_assign_position(p)  # <-- LET USER CHOOSE THEIR POSITION
                drafted_rosters[team_name].append(p)
                taken_names.add(getattr(p, "fantasy_base_name", p.name))
                round_picks.append((team_name, p))

                print(f"\nYour roster so far ({len(drafted_rosters[team_name])} players): "
                      f"{', '.join(pl.name for pl in drafted_rosters[team_name])}")
            else:
                p = ai_pick_for_fantasy_team(
                    pools,
                    taken_names,
                    drafted_rosters[team_name],
                    drafted_rosters[user_team_name]
                )
                drafted_rosters[team_name].append(p)
                taken_names.add(getattr(p, "fantasy_base_name", p.name))
                round_picks.append((team_name, p))

        print_fantasy_draft_round_summary(round_num, round_picks)

    user_team = make_fantasy_team_factory(user_team_name, drafted_rosters[user_team_name], user_controlled=True)()

    print("\n=== DRAFT COMPLETE ===")
    print("\nYour Final Roster:")
    for p in user_team.roster:
        ovr = fantasy_ovr(p)
        print(f"  - {p.name} ({p.position}) OVR {ovr}")

    input("\nPress Enter to simulate the 82-game fantasy season...")

    standings = run_fantasy_82_game_season(drafted_rosters, user_team_name)
    input("\nPress Enter to start the fantasy playoffs...")
    run_fantasy_playoffs_from_season(standings)


def run_fantasy_draft_playoffs():
    from players_data import build_fantasy_player_pools
    """
    Draft a 16-team playoff field from every player in the simulator.
    User plus 15 AI teams, split into 8 East and 8 West teams, then seeded
    straight into conference playoffs.
    """
    pools = build_fantasy_player_pools(None)
    taken_names: set = set()
    picks_per_team = 8

    print("\n=== FANTASY DRAFT PLAYOFFS ===")
    print("You draft against 15 AI teams, then the field splits into 8 East and 8 West playoff teams.")
    print("The player pool uses every player from every team currently made in the simulator.")
    print("Draft order is snake: you pick first, the 15 AI teams pick, then the order reverses.")

    if GUI_OPTION_PICKER is not None:
        user_conference = GUI_OPTION_PICKER("Choose Conference", "Pick your fantasy playoff conference.", ["Eastern Conference", "Western Conference"]).lower()
    else:
        user_conference = input("Choose your conference, E or W: ").strip().lower()
    if user_conference not in ("w", "west", "western"):
        user_conference = "east"
    else:
        user_conference = "west"

    east_names, west_names = fantasy_random_conference_team_names(user_conference)
    user_team_name = east_names[0] if user_conference == "east" else west_names[0]
    print_fantasy_playoff_team_field(east_names, west_names, user_team_name)

    if user_conference == "east":
        east_names = [user_team_name] + [name for name in east_names if name != user_team_name]
    else:
        west_names = [user_team_name] + [name for name in west_names if name != user_team_name]

    team_order = [user_team_name] + [name for name in east_names + west_names if name != user_team_name]
    drafted_rosters: Dict[str, List[Player]] = {name: [] for name in team_order}

    for round_num in range(1, picks_per_team + 1):
        current_order = team_order if round_num % 2 == 1 else list(reversed(team_order))
        round_picks = []
        print("\n" + "=" * 80)
        print(f"FANTASY PLAYOFF DRAFT ROUND {round_num}")
        print("=" * 80)

        for team_name in current_order:
            if team_name == user_team_name:
                print(f"\n{user_team_name} are on the clock.")
                p = user_pick_from_pool(pools, taken_names)
                user_assign_position(p)
                drafted_rosters[team_name].append(p)
                taken_names.add(getattr(p, "fantasy_base_name", p.name))
                round_picks.append((team_name, p))

                print(f"\nYour roster so far ({len(drafted_rosters[team_name])} players): "
                      f"{', '.join(pl.name for pl in drafted_rosters[team_name])}")
            else:
                p = ai_pick_for_fantasy_team(
                    pools,
                    taken_names,
                    drafted_rosters[team_name],
                    drafted_rosters[user_team_name]
                )
                drafted_rosters[team_name].append(p)
                taken_names.add(getattr(p, "fantasy_base_name", p.name))
                round_picks.append((team_name, p))

        print_fantasy_draft_round_summary(round_num, round_picks)

    user_team = make_fantasy_team_factory(user_team_name, drafted_rosters[user_team_name], user_controlled=True)()

    print("\n=== DRAFT COMPLETE ===")
    print("\nYour Final Roster:")
    for p in user_team.roster:
        print(f"  - {p.name} ({p.position}) OVR {fantasy_ovr(p)}")

    print_fantasy_drafted_team_rosters(drafted_rosters, east_names, west_names, user_team_name)

    east, west = build_fantasy_playoff_entries(drafted_rosters, user_team_name, east_names, west_names)
    print_fantasy_playoff_seedings(east, west)

    input("\nPress Enter to start the fantasy playoffs...")
    run_fantasy_playoffs_from_bracket(east, west)


